window.__STUDY4_LISTEN_CHUNK = window.__STUDY4_LISTEN_CHUNK || {}; window.__STUDY4_LISTEN_CHUNK['u_3'] = {"unitId":"u_3","unitName":"Luyện nghe chính tả theo chủ đề (cơ bản - nâng cao)","items":[{"id":"listening_u3_1","title":"Everyday: recording 1","actTitle":"Luyện tập: Recording 1","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120850/?view=embed","pType":"listen_passage","probTitle":"Everyday: recording 1","audioUrl":"https://s4-media1.study4.com/media/mindset_media/mindset1.mp3","youtubeId":"","subs":[{"time":0,"en":"Hi Jack!","vi":"Chào Jack!"},{"time":2180,"en":"I'm really excited about coming to stay with you at your house on the student exchange trip to Australia next term.","vi":"Mình rất hào hứng khi được đến ở nhà bạn trong chuyến trao đổi sinh viên đến Úc vào học kỳ tới."},{"time":11100,"en":"Me too, Carlos! I know you're going to have a great time at my school and with my family.","vi":"Mình cũng vậy, Carlos! Mình biết bạn sẽ có khoảng thời gian tuyệt vời ở trường và với gia đình mình."},{"time":17040,"en":"Tell me a bit about your family. What do you all like doing?","vi":"Kể cho mình nghe một chút về gia đình bạn đi. Mọi người thích làm gì?"},{"time":22580,"en":"Well, I love playing volleyball and basketball.","vi":"À, mình thích chơi bóng chuyền và bóng rổ."},{"time":27180,"en":"I do volleyball once a week and basketball twice a week.","vi":"Mình chơi bóng chuyền một lần một tuần và bóng rổ hai lần một tuần."},{"time":31660,"en":"I remember you have a brother. What does he do? Is he interested in sport, too?","vi":"Mình nhớ là bạn có một người anh trai. Anh ấy làm gì? Anh ấy có thích thể thao không?"},{"time":38960,"en":"No, not really.","vi":"Không, không hẳn."},{"time":40780,"en":"He prefers staying at home and reading.","vi":"Anh ấy thích ở nhà đọc sách hơn."},{"time":44020,"en":"He's a member of our local gym but he never goes.","vi":"Anh ấy là thành viên của phòng gym địa phương nhưng không bao giờ đến."},{"time":48120,"en":"Oh, that sounds like me! You've got a sister too, haven't you?","vi":"Ồ, nghe giống mình vậy! Bạn cũng có một em gái nữa phải không?"},{"time":54520,"en":"Yes, she's really good at painting and drawing.","vi":"Đúng vậy, em ấy vẽ và tô rất giỏi."},{"time":58860,"en":"Some of her work is hanging up on the walls at home, so you'll be able to see it when you come.","vi":"Một vài tác phẩm của em ấy được treo trên tường ở nhà, bạn sẽ có thể xem chúng khi bạn đến."},{"time":64440,"en":"That would be great. I'd love to see it. What about your parents?","vi":"Tuyệt vời. Mình rất muốn xem. Còn bố mẹ bạn thì sao?"},{"time":70700,"en":"Well, my mum loves growing things.","vi":"À, mẹ mình thích trồng cây."},{"time":75020,"en":"She spends a lot of time outdoors, planting flowers and cutting the grass.","vi":"Mẹ dành nhiều thời gian ở ngoài trời, trồng hoa và cắt cỏ."},{"time":80300,"en":"That sounds interesting. And your dad? What does he like doing?","vi":"Nghe thú vị đấy. Còn bố bạn thì sao? Bố bạn thích làm gì?"},{"time":86360,"en":"Well, he's really good at building and fixing things.","vi":"À, bố mình rất giỏi xây dựng và sửa chữa mọi thứ."},{"time":90960,"en":"If anything gets broken around the house, he fixes it.","vi":"Nếu có thứ gì đó bị hỏng trong nhà, bố mình sẽ sửa nó."},{"time":95080,"en":"He makes new things, too, like furniture.","vi":"Bố cũng làm những thứ mới, như đồ nội thất."},{"time":98480,"en":"Great! And I know your grandma lives with you. What does she like doing?","vi":"Tuyệt! Mình biết bà của bạn sống với bạn. Bà thích làm gì?"},{"time":105320,"en":"Well, we're lucky - she's an amazing cook and makes us all wonderful meals every day.","vi":"Chà, chúng mình thật may mắn - bà là một đầu bếp tuyệt vời và nấu cho chúng mình những bữa ăn ngon mỗi ngày."},{"time":112880,"en":"She already wants to know what you like eating.","vi":"Bà đã muốn biết bạn thích ăn gì rồi đó."},{"time":116220,"en":"Really?","vi":"Thật á?"},{"time":117900,"en":"Well, that gives me an idea for a present for her - a recipe book from where I'm from in the USA.","vi":"À, điều đó cho mình một ý tưởng về món quà cho bà - một cuốn sách công thức nấu ăn từ nơi mình đến ở Mỹ."},{"time":126120,"en":"Perfect!","vi":"Hoàn hảo!"}]}},{"id":"listening_u3_2","title":"Living Spaces: recording 1","actTitle":"Luyện tập: Recording 1","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120851/?view=embed","pType":"listen_passage","probTitle":"Living Spaces: recording 1","audioUrl":"https://s4-media1.study4.com/media/mindset_media/mindset2.mp3","youtubeId":"","subs":[{"time":0,"en":"I'm excited about going to university, but I feel nervous about leaving my home, especially my bedroom.","vi":"Tôi rất hào hứng khi được vào đại học, nhưng tôi cũng lo lắng khi phải rời xa nhà, đặc biệt là phòng ngủ của mình."},{"time":12560,"en":"I like it a lot.","vi":"Tôi rất thích nó."},{"time":15040,"en":"My bed is very comfortable - I've got four big pillows.","vi":"Giường của tôi rất thoải mái - tôi có tới bốn chiếc gối lớn."},{"time":22220,"en":"When I sit on my bed, if I look out of the window I can see the garden.","vi":"Khi tôi ngồi trên giường, nếu nhìn ra ngoài cửa sổ, tôi có thể thấy khu vườn."},{"time":30300,"en":"I often do my homework at my desk and, to help me study, I sometimes turn on the lamp so I can see my notes and my course books better.","vi":"Tôi thường làm bài tập ở bàn học và để giúp việc học tập tốt hơn, thỉnh thoảng tôi bật đèn lên để nhìn rõ hơn các ghi chú và sách giáo trình."},{"time":45420,"en":"When I want to relax, I usually play games on my phone, which I keep in the drawers next to my bed.","vi":"Khi muốn thư giãn, tôi thường chơi game trên điện thoại, cái mà tôi để trong ngăn kéo cạnh giường."},{"time":55740,"en":"I haven't got my own bathroom.","vi":"Tôi không có phòng tắm riêng."},{"time":58520,"en":"I need to go down the hall if I want a shower or bath.","vi":"Tôi cần phải đi xuống hành lang nếu muốn tắm vòi sen hoặc bồn tắm."},{"time":65080,"en":"However, I have got a sink where I brush my teeth every morning before I go to college.","vi":"Tuy nhiên, tôi có một bồn rửa mặt nơi tôi đánh răng mỗi sáng trước khi đến trường."},{"time":74840,"en":"I have two posters: one is above my bed and the other one is next to the TV.","vi":"Tôi có hai tấm áp phích: một ở phía trên giường và một ở cạnh TV."},{"time":85320,"en":"What else?","vi":"Còn gì nữa không nhỉ?"},{"time":87220,"en":"I don't like curtains very much, so I don't have them.","vi":"Tôi không thích rèm cửa lắm nên tôi không có chúng."},{"time":93380,"en":"At the window, I have a blind instead.","vi":"Thay vào đó, ở cửa sổ tôi có một cái mành che."},{"time":98120,"en":"I think it will be strange at first sleeping somewhere new but I'm sure I'll get used to it and I'll make it feel like home.","vi":"Tôi nghĩ ban đầu sẽ lạ lẫm khi ngủ ở một nơi mới, nhưng tôi chắc chắn mình sẽ quen và tôi sẽ làm cho nó có cảm giác như ở nhà."}]}},{"id":"listening_u3_3","title":"Living Spaces: recording 2","actTitle":"Luyện tập: Recording 2","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120852/?view=embed","pType":"listen_passage","probTitle":"Living Spaces: recording 2","audioUrl":"https://s4-media1.study4.com/media/mindset_media/mindset3.mp3","youtubeId":"","subs":[{"time":0,"en":"Good afternoon, Prime Location Agency, Andrew Taylor speaking.","vi":"Chào buổi chiều, đây là Andrew Taylor từ Cơ quan Bất động sản Prime Location."},{"time":7360,"en":"Can I first check your student status?","vi":"Tôi có thể kiểm tra tình trạng sinh viên của bạn trước được không?"},{"time":11560,"en":"Hello, yes, of course.","vi":"Xin chào, vâng, tất nhiên rồi."},{"time":14200,"en":"My name's Giorgio Rossi and I will soon be a student at Brickbat University.","vi":"Tên tôi là Giorgio Rossi và tôi sẽ sớm trở thành sinh viên của Đại học Brickbat."},{"time":22040,"en":"I'm calling today to discuss where to live when I come to the UK to study at the university.","vi":"Hôm nay tôi gọi điện để thảo luận về chỗ ở khi tôi đến Vương quốc Anh học tại trường đại học."},{"time":30900,"en":"Oh, hello, Giorgio.","vi":"Ồ, chào Giorgio."},{"time":32960,"en":"Thank you for your call, I have some questions for you.","vi":"Cảm ơn bạn đã gọi, tôi có một vài câu hỏi dành cho bạn."},{"time":37680,"en":"I hope that you don't mind.","vi":"Tôi hy vọng bạn không phiền."},{"time":39140,"en":"Can you speak English?","vi":"Bạn có nói được tiếng Anh không?"},{"time":42860,"en":"Yes, but I apologise if I make any mistakes.","vi":"Có, nhưng tôi xin lỗi nếu tôi mắc phải sai sót nào."},{"time":48840,"en":"Don't worry. So, what do you want to study?","vi":"Đừng lo lắng. Vậy, bạn muốn học gì?"},{"time":53660,"en":"I'm not sure exactly, but something with engineering.","vi":"Tôi không chắc chắn lắm, nhưng có lẽ là gì đó liên quan đến kỹ thuật."},{"time":59980,"en":"First of all, where do you want to live - in a room on campus or in private accommodation?","vi":"Trước hết, bạn muốn sống ở đâu - trong phòng ký túc xá hay ở nhà riêng?"},{"time":68740,"en":"I'm not sure. Can you give me some advice?","vi":"Tôi không chắc. Bạn có thể cho tôi lời khuyên được không?"},{"time":73240,"en":"Of course!","vi":"Tất nhiên rồi!"},{"time":74760,"en":"Well, tell me a little about your personality and your preferences.","vi":"Vậy, hãy cho tôi biết một chút về tính cách và sở thích của bạn."},{"time":81100,"en":"Are you a sociable person?","vi":"Bạn có phải là một người hòa đồng không?"},{"time":83940,"en":"Oh, yes, I am definitely sociable.","vi":"Ồ, có, tôi chắc chắn là hòa đồng."},{"time":88060,"en":"I live with my parents at the moment.","vi":"Hiện tại tôi đang sống với bố mẹ."},{"time":91880,"en":"We have a big family and there are always lots of visitors.","vi":"Gia đình tôi đông người và luôn có nhiều khách đến thăm."},{"time":97660,"en":"OK, that's great. Do you also like to sometimes have a quiet room to study in private?","vi":"OK, tuyệt vời. Bạn có thích đôi khi có một phòng yên tĩnh để tự học không?"},{"time":106660,"en":"Well, it depends on how I feel.","vi":"Chà, còn tùy thuộc vào tâm trạng của tôi."},{"time":110440,"en":"I sometimes like to be sociable and other times, I prefer to study alone.","vi":"Đôi khi tôi thích hòa đồng, còn những lúc khác, tôi thích học một mình hơn."},{"time":117300,"en":"Can I ask, where exactly the accommodation is?","vi":"Tôi có thể hỏi chỗ ở chính xác ở đâu không?"},{"time":122500,"en":"Well, if you live in a room on campus, it is very convenient for your studies, as you actually live in a building in the university.","vi":"Chà, nếu bạn sống trong một phòng ký túc xá, nó rất thuận tiện cho việc học của bạn, vì bạn thực sự sống trong một tòa nhà của trường đại học."},{"time":134420,"en":"However, it's also noisy.","vi":"Tuy nhiên, nó cũng ồn ào."},{"time":137720,"en":"There are hundreds of other students who also live there, and they often make lots of noise, but if you live in private accommodation you have a quiet life in a different part of the city with maybe one or two other students who are your housemates.","vi":"Có hàng trăm sinh viên khác cũng sống ở đó, và họ thường gây ra nhiều tiếng ồn, nhưng nếu bạn sống ở nhà riêng, bạn sẽ có một cuộc sống yên tĩnh ở một khu vực khác của thành phố với có thể một hoặc hai sinh viên khác là bạn cùng nhà."},{"time":158840,"en":"Although, it often takes a long time to travel to university.","vi":"Mặc dù vậy, thường mất nhiều thời gian để di chuyển đến trường đại học."},{"time":164180,"en":"What do you think?","vi":"Bạn nghĩ sao?"},{"time":165960,"en":"It's a difficult decision.","vi":"Đây là một quyết định khó khăn."},{"time":169140,"en":"I want to make lots of new friends, but I also know that I need to work hard and study.","vi":"Tôi muốn kết bạn với nhiều người mới, nhưng tôi cũng biết rằng tôi cần phải học tập và làm việc chăm chỉ."},{"time":177780,"en":"OK, one final question. Meals. Would you prefer to live somewhere which is catered?","vi":"OK, một câu hỏi cuối cùng. Bữa ăn. Bạn có thích sống ở một nơi có phục vụ ăn uống không?"},{"time":187500,"en":"I'm not sure. What does catered mean?","vi":"Tôi không chắc. Được phục vụ ăn uống nghĩa là gì?"},{"time":192080,"en":"Catered means that all your food is included in the price of the accommodation.","vi":"Phục vụ ăn uống có nghĩa là tất cả thức ăn của bạn đã được bao gồm trong giá chỗ ở."},{"time":199400,"en":"For example, if you decide to live on campus you can usually choose catered accommodation.","vi":"Ví dụ, nếu bạn quyết định sống trong khuôn viên trường, bạn thường có thể chọn chỗ ở có phục vụ ăn uống."},{"time":208000,"en":"That means that, for example, every day, you can go to the canteen for your breakfast, lunch or dinner, and it's always free.","vi":"Điều đó có nghĩa là, ví dụ, mỗi ngày, bạn có thể đến căng tin để ăn sáng, trưa hoặc tối và nó luôn miễn phí."},{"time":219380,"en":"The other option is self-catered accommodation, where you can either cook at home or you can go out for all of your meals.","vi":"Lựa chọn khác là chỗ ở tự phục vụ ăn uống, nơi bạn có thể tự nấu ăn ở nhà hoặc bạn có thể đi ăn ngoài cho tất cả các bữa ăn của mình."},{"time":229480,"en":"However, you always have to pay for your food.","vi":"Tuy nhiên, bạn luôn phải trả tiền cho thức ăn của mình."}]}},{"id":"listening_u3_4","title":"Pastimes and Fun: recording 1","actTitle":"Luyện tập: Recording 1","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120853/?view=embed","pType":"listen_passage","probTitle":"Pastimes and Fun: recording 1","audioUrl":"https://s4-media1.study4.com/media/mindset_media/mindset4.mp3","youtubeId":"","subs":[{"time":0,"en":"Hey, Mark! Are you still interested in coming on a week's adventure holiday with me this summer?","vi":"Chào Mark! Cậu vẫn còn hứng thú đi du lịch mạo hiểm một tuần với tớ vào mùa hè này chứ?"},{"time":7320,"en":"Of course, but can we go in August? I can't do June or July because of college.","vi":"Tất nhiên rồi, nhưng chúng ta có thể đi vào tháng Tám không? Tớ không đi được vào tháng Sáu hoặc tháng Bảy vì bận học ở trường."},{"time":14420,"en":"Yeah, sure!","vi":"Ừ, chắc chắn rồi!"},{"time":15800,"en":"I guess we need to book soon.","vi":"Tớ đoán là chúng ta cần đặt sớm thôi."},{"time":18440,"en":"There's a company called World Trek that my friend told me about.","vi":"Có một công ty tên là World Trek mà bạn tớ đã kể cho tớ."},{"time":23860,"en":"He went on one of their cycling holidays last year, and loved it.","vi":"Năm ngoái cậu ấy đã đi một chuyến du lịch bằng xe đạp của họ và rất thích."},{"time":28980,"en":"There's lots of information on their website.","vi":"Có rất nhiều thông tin trên trang web của họ."},{"time":31520,"en":"Really?","vi":"Thật á?"},{"time":32120,"en":"Yes - they do different kinds of adventure holidays.","vi":"Ừ - họ tổ chức nhiều loại hình du lịch mạo hiểm khác nhau."},{"time":37000,"en":"There's one by the sea with lots of water sports, and another in the forest where you can do hiking and cooking, and you learn how to cook outdoors.","vi":"Có một chương trình gần biển với nhiều môn thể thao dưới nước, và một chương trình khác trong rừng, nơi bạn có thể đi bộ đường dài, nấu ăn và học cách nấu ăn ngoài trời."},{"time":49820,"en":"The one I like best is in the mountains.","vi":"Chương trình tớ thích nhất là ở trên núi."},{"time":53280,"en":"We can do things like climbing and white water rafting.","vi":"Chúng ta có thể làm những việc như leo núi và đi thuyền vượt thác."},{"time":58040,"en":"What do you think?","vi":"Cậu nghĩ sao?"},{"time":59200,"en":"That sounds amazing! Is it expensive?","vi":"Nghe tuyệt vời đấy! Có đắt không?"},{"time":62740,"en":"So so - there's a special offer on at the moment.","vi":"Cũng tàm tạm thôi - hiện tại đang có ưu đãi đặc biệt."},{"time":67060,"en":"Normally the price is six hundred and fifty pounds, but if you book before Friday, it's five hundred pounds.","vi":"Bình thường giá là sáu trăm năm mươi bảng, nhưng nếu bạn đặt trước thứ Sáu, thì giá là năm trăm bảng."},{"time":76440,"en":"The sailing holidays are eight hundred pounds, so it's not bad!","vi":"Các kỳ nghỉ bằng thuyền buồm có giá tám trăm bảng, vì vậy mức giá đó không tệ!"},{"time":82060,"en":"What does that include?","vi":"Giá đó bao gồm những gì?"},{"time":84020,"en":"Transport, accommodation and our guide. We only have to pay for meals and drinks.","vi":"Bao gồm phương tiện di chuyển, chỗ ở và hướng dẫn viên. Chúng ta chỉ phải trả tiền cho các bữa ăn và đồ uống."},{"time":91400,"en":"That's really good, isn't it?","vi":"Thật sự là rất tốt, đúng không?"},{"time":93520,"en":"Let's book tonight!","vi":"Đặt ngay tối nay thôi!"},{"time":95020,"en":"Shall I come to your place this evening around seven?","vi":"Tớ đến nhà cậu tối nay khoảng bảy giờ nhé?"},{"time":98220,"en":"Can you come at eight? I've got a tennis lesson until seven thirty.","vi":"Cậu đến lúc tám giờ được không? Tớ có một buổi học tennis đến bảy giờ rưỡi."},{"time":102980,"en":"Yes, sure. See you then.","vi":"Ừ, chắc chắn rồi. Gặp cậu sau."}]}},{"id":"listening_u3_5","title":"Trips and Vacations: recording 1","actTitle":"Luyện tập: Recording 1","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120854/?view=embed","pType":"listen_passage","probTitle":"Trips and Vacations: recording 1","audioUrl":"https://s4-media1.study4.com/media/mindset_media/mindset5.mp3","youtubeId":"","subs":[{"time":0,"en":"Good afternoon everybody and welcome to the travel show.","vi":"Xin chào buổi chiều tất cả quý vị và chào mừng đến với chương trình du lịch."},{"time":4620,"en":"Today, I'm talking to Anna Cox from Cambridge, who has recently taken part in the Summer Cultural Exchange Programme.","vi":"Hôm nay, tôi sẽ trò chuyện với Anna Cox đến từ Cambridge, người vừa tham gia Chương trình Trao đổi Văn hóa Mùa hè."},{"time":15480,"en":"Good afternoon, Anna!","vi":"Chào buổi chiều, Anna!"},{"time":17140,"en":"Good afternoon!","vi":"Chào buổi chiều!"},{"time":19080,"en":"Anna, where can students go on the Summer Cultural Exchange Programme?","vi":"Anna, sinh viên có thể đến những đâu trong Chương trình Trao đổi Văn hóa Mùa hè?"},{"time":25520,"en":"Well, students can travel to France or Spain on a language exchange, or to the USA on a sports or music exchange.","vi":"À, sinh viên có thể đến Pháp hoặc Tây Ban Nha để trao đổi ngôn ngữ, hoặc đến Mỹ để trao đổi thể thao hoặc âm nhạc."},{"time":37500,"en":"I didn't go to the USA because I'm not very good at sports.","vi":"Tôi đã không đến Mỹ vì tôi không giỏi thể thao lắm."},{"time":42860,"en":"However, I study French and Spanish at school, so I had two options.","vi":"Tuy nhiên, tôi học tiếng Pháp và tiếng Tây Ban Nha ở trường, vì vậy tôi có hai lựa chọn."},{"time":50340,"en":"I've been to France before, so I decided to go to Spain instead.","vi":"Tôi đã từng đến Pháp rồi, nên tôi quyết định đến Tây Ban Nha."}]}},{"id":"listening_u3_6","title":"Trips and Vacations: recording 2","actTitle":"Luyện tập: Recording 2","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120855/?view=embed","pType":"listen_passage","probTitle":"Trips and Vacations: recording 2","audioUrl":"https://s4-media1.study4.com/media/mindset_media/mindset6.mp3","youtubeId":"","subs":[{"time":0,"en":"Where did you stay on your summer cultural exchange programme?","vi":"Bạn đã ở đâu trong chương trình trao đổi văn hóa mùa hè?"},{"time":5400,"en":"I stayed with a host family in a small village just outside the city of Seville.","vi":"Tôi ở với một gia đình bản xứ ở một ngôi làng nhỏ ngay bên ngoài thành phố Seville."},{"time":12680,"en":"Most people in the city live in apartments, but my host family lived in a big house.","vi":"Hầu hết mọi người trong thành phố sống ở căn hộ, nhưng gia đình bản xứ của tôi sống trong một ngôi nhà lớn."},{"time":21240,"en":"The family had a daughter who was my age called Carmen, so we had lots of fun together.","vi":"Gia đình đó có một cô con gái tên là Carmen bằng tuổi tôi, vì vậy chúng tôi đã có rất nhiều niềm vui bên nhau."},{"time":30140,"en":"We also visited Carmen's grandparents who live on a farm in the countryside.","vi":"Chúng tôi cũng đến thăm ông bà của Carmen, những người sống trong một trang trại ở vùng nông thôn."},{"time":37360,"en":"As I love animals, it was a really good experience for me.","vi":"Vì tôi yêu động vật, đó là một trải nghiệm thực sự tốt cho tôi."},{"time":43020,"en":"How wonderful! How long are exchange programmes usually?","vi":"Tuyệt vời! Các chương trình trao đổi thường kéo dài bao lâu?"},{"time":48680,"en":"Well, most of the language exchange programmes last for two weeks but the sports and music exchange programmes last for four weeks.","vi":"À, hầu hết các chương trình trao đổi ngôn ngữ kéo dài hai tuần nhưng các chương trình trao đổi thể thao và âm nhạc kéo dài bốn tuần."},{"time":61620,"en":"If you go on a language exchange programme in August, you can go for three weeks because it's the school holidays.","vi":"Nếu bạn tham gia chương trình trao đổi ngôn ngữ vào tháng 8, bạn có thể đi trong ba tuần vì đó là kỳ nghỉ hè."},{"time":71380,"en":"I went on a language exchange to Spain in July, so I could only stay for two weeks, unfortunately.","vi":"Tôi đã tham gia một chương trình trao đổi ngôn ngữ đến Tây Ban Nha vào tháng 7, vì vậy tôi chỉ có thể ở lại trong hai tuần, rất tiếc."},{"time":80240,"en":"Who can take part in the programme?","vi":"Ai có thể tham gia chương trình?"},{"time":83220,"en":"Well, there are some age requirements for the programme.","vi":"À, có một số yêu cầu về độ tuổi cho chương trình."},{"time":88100,"en":"You must be over the age of fourteen to take part in the language exchange programme and sixteen for the sports and music exchange programme.","vi":"Bạn phải trên mười bốn tuổi để tham gia chương trình trao đổi ngôn ngữ và mười sáu tuổi đối với chương trình trao đổi thể thao và âm nhạc."},{"time":99420,"en":"If you want to take part in the sports and music exchange programme, you have to be on a school sports team or play in the school orchestra.","vi":"Nếu bạn muốn tham gia chương trình trao đổi thể thao và âm nhạc, bạn phải ở trong đội thể thao của trường hoặc chơi trong dàn nhạc của trường."},{"time":110740,"en":"You can only take part in the language exchange programme if you study French or Spanish.","vi":"Bạn chỉ có thể tham gia chương trình trao đổi ngôn ngữ nếu bạn học tiếng Pháp hoặc tiếng Tây Ban Nha."},{"time":116980,"en":"I see - so would you recommend this programme to other students?","vi":"Tôi hiểu - vậy bạn có giới thiệu chương trình này cho các học sinh khác không?"},{"time":122880,"en":"Yes, definitely.","vi":"Có, chắc chắn rồi."},{"time":125160,"en":"I had a great time staying with Carmen and her family.","vi":"Tôi đã có một khoảng thời gian tuyệt vời khi ở với Carmen và gia đình cô ấy."},{"time":129380,"en":"I felt a bit homesick when I first arrived, but they were so friendly and welcoming.","vi":"Tôi cảm thấy hơi nhớ nhà khi mới đến, nhưng họ rất thân thiện và hiếu khách."},{"time":136000,"en":"Carmen spoke really good English, so I was worried that I wouldn't improve my Spanish, but I always tried to speak Spanish with her parents.","vi":"Carmen nói tiếng Anh rất tốt, vì vậy tôi đã lo lắng rằng mình sẽ không cải thiện được tiếng Tây Ban Nha, nhưng tôi luôn cố gắng nói tiếng Tây Ban Nha với bố mẹ cô ấy."},{"time":148480,"en":"My language skills have improved a little bit, but I think that it's better to stay for three weeks because you have more time to practise the language.","vi":"Kỹ năng ngôn ngữ của tôi đã được cải thiện một chút, nhưng tôi nghĩ rằng tốt hơn là nên ở lại trong ba tuần vì bạn có nhiều thời gian hơn để luyện tập ngôn ngữ."},{"time":159900,"en":"The whole programme sounds really interesting, Anna - thank you for telling us about it.","vi":"Toàn bộ chương trình nghe có vẻ rất thú vị, Anna - cảm ơn bạn đã kể cho chúng tôi về nó."}]}},{"id":"listening_u3_7","title":"Meals and Eating: recording 1","actTitle":"Luyện tập: Recording 1","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120856/?view=embed","pType":"listen_passage","probTitle":"Meals and Eating: recording 1","audioUrl":"https://s4-media1.study4.com/media/mindset_media/mindset7.mp3","youtubeId":"","subs":[{"time":0,"en":"Hi, Jane. Oh, hi Mark.","vi":"Chào Jane. Ồ, chào Mark."},{"time":3480,"en":"I'm really looking forward to the food festival.","vi":"Tôi rất mong chờ lễ hội ẩm thực đấy."},{"time":6240,"en":"I love Chinese food and I hope our friends can come.","vi":"Tôi thích đồ ăn Trung Quốc và hy vọng bạn bè chúng ta có thể đến."},{"time":9900,"en":"Well, I'm afraid most of them are busy.","vi":"Chà, tôi e là hầu hết bọn họ đều bận cả."},{"time":13680,"en":"What even Marco? He always says he has nothing to do and that he's interested in trying new food.","vi":"Thậm chí cả Marco cũng không đi được sao? Cậu ấy luôn nói là không có gì để làm và thích thử đồ ăn mới mà."},{"time":21360,"en":"Mohammed says Marco has no money.","vi":"Mohammed bảo là Marco không có tiền."},{"time":24140,"en":"Mohammed can't go because he is helping his flatmate decorate his room.","vi":"Mohammed không đi được vì đang giúp bạn cùng phòng trang trí phòng."},{"time":29720,"en":"But the festival is free!","vi":"Nhưng lễ hội miễn phí mà!"},{"time":31800,"en":"Yes, but we have to go there on the underground and I'm sure he'll want to buy some food when he's there.","vi":"Ừ, nhưng chúng ta phải đi tàu điện ngầm đến đó và tôi chắc là cậu ấy sẽ muốn mua đồ ăn khi đến đó."},{"time":38500,"en":"Well, I don't have much money either, perhaps Pierre could lend him some.","vi":"Chà, tôi cũng không có nhiều tiền, có lẽ Pierre có thể cho cậu ấy vay một ít."},{"time":44180,"en":"He's got a job and he is Marco's best friend.","vi":"Cậu ấy có việc làm và là bạn thân của Marco mà."},{"time":48020,"en":"Oh, Pierre can't come either.","vi":"Ồ, Pierre cũng không đến được."},{"time":51460,"en":"Really? Is he at work? All he thinks about is work!","vi":"Thật á? Cậu ấy đang làm việc à? Lúc nào cũng chỉ nghĩ đến công việc!"},{"time":56040,"en":"No, his parents are coming from France and he's going to show them around London … you know, Big Ben, Tower Bridge ...","vi":"Không, bố mẹ cậu ấy đến từ Pháp và cậu ấy sẽ đưa họ đi tham quan London… cậu biết đấy, Big Ben, Cầu Tháp..."},{"time":65380,"en":"OK, what about Hang Yie? Her mother owns a Chinese restaurant. She must be interested.","vi":"OK, còn Hang Yie thì sao? Mẹ cô ấy sở hữu một nhà hàng Trung Quốc. Chắc chắn cô ấy sẽ thích thú đấy."},{"time":73200,"en":"She is, but she's going to help with the cooking for her family's party on the day we're going.","vi":"Cô ấy thích đấy, nhưng cô ấy sẽ giúp nấu ăn cho bữa tiệc của gia đình vào ngày chúng ta đi."},{"time":79460,"en":"I don't know about Lucy and Larissa though.","vi":"Tôi không biết về Lucy và Larissa thì sao."},{"time":83500,"en":"Well, I phoned Lucy, but her flatmate said she was on holiday in Italy and won't be back until the week after the festival.","vi":"Tôi đã gọi cho Lucy, nhưng bạn cùng phòng của cô ấy nói rằng cô ấy đang đi nghỉ ở Ý và sẽ không trở lại cho đến tuần sau lễ hội."},{"time":92600,"en":"I didn't even know she was on holiday. And Larissa?","vi":"Tôi thậm chí còn không biết cô ấy đi nghỉ. Còn Larissa thì sao?"},{"time":97240,"en":"She's got a really important exam, so she needs to prepare for it!","vi":"Cô ấy có một kỳ thi thực sự quan trọng, vì vậy cô ấy cần phải chuẩn bị cho nó!"},{"time":102220,"en":"Well, it looks like it's just going to be you and me then.","vi":"Chà, có vẻ như chỉ có tôi và bạn đi thôi."},{"time":106260,"en":"Not to worry.","vi":"Đừng lo lắng."},{"time":107300,"en":"We'll take lots of photos to show everyone!","vi":"Chúng ta sẽ chụp thật nhiều ảnh để cho mọi người cùng xem!"}]}},{"id":"listening_u3_8","title":"Meals and Eating: recording 2","actTitle":"Luyện tập: Recording 2","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120857/?view=embed","pType":"listen_passage","probTitle":"Meals and Eating: recording 2","audioUrl":"https://s4-media1.study4.com/media/mindset_media/mindset8.mp3","youtubeId":"","subs":[{"time":0,"en":"OK, so what do you need to make the dumplings?","vi":"Được rồi, vậy bạn cần những gì để làm bánh chẻo?"},{"time":5840,"en":"First of all, you need to make the cases.","vi":"Trước hết, bạn cần làm vỏ bánh."},{"time":9820,"en":"These are the cases which you'll put the other ingredients in.","vi":"Đây là phần vỏ mà bạn sẽ cho các nguyên liệu khác vào."},{"time":13900,"en":"To make the cases, you need to make the dough.","vi":"Để làm vỏ bánh, bạn cần làm bột."},{"time":18940,"en":"Of course, you need flour for this.","vi":"Tất nhiên, bạn cần bột mì cho việc này."},{"time":22920,"en":"To make 20 cases, you'll need four cups of flour.","vi":"Để làm 20 vỏ bánh, bạn sẽ cần bốn cốc bột mì."},{"time":28320,"en":"Then, mix the flour with two cups of water.","vi":"Sau đó, trộn bột mì với hai cốc nước."},{"time":33100,"en":"Don't forget to add some salt, but only a little to add some taste.","vi":"Đừng quên thêm một ít muối, nhưng chỉ một chút để tăng thêm hương vị."},{"time":39440,"en":"When you've mixed the ingredients, leave the dough for ten minutes in the bowl to make sure it's ready.","vi":"Khi bạn đã trộn các nguyên liệu, hãy để bột trong bát mười phút để đảm bảo bột đã sẵn sàng."},{"time":47500,"en":"You can make the filling to go inside the dough while you wait.","vi":"Bạn có thể làm nhân để cho vào trong bột trong khi chờ đợi."},{"time":52980,"en":"There are two main ingredients in the filling.","vi":"Có hai thành phần chính trong nhân bánh."},{"time":56740,"en":"Firstly, you have the cabbage.","vi":"Thứ nhất, bạn có bắp cải."},{"time":59880,"en":"You need to chop this up finely and add it to another important ingredient, the meat.","vi":"Bạn cần thái nhỏ bắp cải và thêm nó vào một thành phần quan trọng khác, thịt."},{"time":67580,"en":"You can use any meat, but today I'm using lamb.","vi":"Bạn có thể sử dụng bất kỳ loại thịt nào, nhưng hôm nay tôi dùng thịt cừu."},{"time":73160,"en":"Put the meat and cabbage together and mix it by hand.","vi":"Cho thịt và bắp cải vào cùng nhau và trộn bằng tay."},{"time":78640,"en":"When it's mixed well, you can add some other ingredients.","vi":"Khi đã trộn đều, bạn có thể thêm một số thành phần khác."},{"time":83420,"en":"In China, people like to add spring onions to their dumplings and I do too!","vi":"Ở Trung Quốc, mọi người thích thêm hành lá vào bánh chẻo của họ và tôi cũng vậy!"},{"time":90940,"en":"I'd like some seafood today, too, so I'm going to add some shrimps.","vi":"Hôm nay tôi cũng muốn ăn một chút hải sản, vì vậy tôi sẽ thêm một ít tôm."},{"time":96720,"en":"Chop the spring onions and shrimps into small pieces and mix them together with the rest of the filling.","vi":"Băm nhỏ hành lá và tôm thành những miếng nhỏ và trộn chúng với phần còn lại của nhân."},{"time":105660,"en":"To make sure that everything sticks together, add some vegetable oil.","vi":"Để đảm bảo mọi thứ dính vào nhau, hãy thêm một ít dầu thực vật."},{"time":112980,"en":"Now that the mixture is ready, you need to finish the cases.","vi":"Bây giờ hỗn hợp đã sẵn sàng, bạn cần hoàn thành phần vỏ bánh."},{"time":118060,"en":"First, cut the dough into twenty pieces, making sure they're all the same size, and roll them into flat little circular shapes.","vi":"Đầu tiên, cắt bột thành hai mươi miếng, đảm bảo chúng đều có kích thước bằng nhau, và cán chúng thành những hình tròn nhỏ phẳng."},{"time":128780,"en":"Put the mixture into the centre of the cases.","vi":"Cho hỗn hợp nhân vào giữa vỏ bánh."},{"time":134120,"en":"Make sure you don't put too much filling in at this stage otherwise you won't be able to close the cases and all the filling will come out when it's cooking.","vi":"Đảm bảo bạn không cho quá nhiều nhân vào giai đoạn này nếu không bạn sẽ không thể đóng vỏ bánh và tất cả nhân sẽ bị tràn ra ngoài khi nấu."},{"time":147380,"en":"Then, fold them into half-moon shapes.","vi":"Sau đó, gấp chúng thành hình bán nguyệt."},{"time":151800,"en":"Finally, boil the dumplings three times, and there you have it.","vi":"Cuối cùng, luộc bánh chẻo ba lần, và thế là xong."},{"time":157700,"en":"Delicious half-moon dumplings ready to eat.","vi":"Bánh chẻo hình bán nguyệt thơm ngon đã sẵn sàng để ăn."}]}},{"id":"listening_u3_9","title":"Getting Around Town: recording 1","actTitle":"Luyện tập: Recording 1","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120858/?view=embed","pType":"listen_passage","probTitle":"Getting Around Town: recording 1","audioUrl":"https://s4-media1.study4.com/media/mindset_media/mindset9.mp3","youtubeId":"","subs":[{"time":0,"en":"Hello everyone and welcome to this talk about Northfields' Shopping Centre.","vi":"Xin chào mọi người và chào mừng đến với buổi nói chuyện về Trung tâm Mua sắm Northfields."},{"time":6540,"en":"It opens next weekend and I'm very excited to be able to tell you about it tonight.","vi":"Nó sẽ mở cửa vào cuối tuần tới và tôi rất vui khi có thể kể cho bạn nghe về nó tối nay."},{"time":13340,"en":"It's a beautiful building, full of light and colour and a wonderful place to spend time in.","vi":"Đó là một tòa nhà tuyệt đẹp, tràn ngập ánh sáng và màu sắc, và là một nơi tuyệt vời để dành thời gian."},{"time":21000,"en":"It was designed by a prize-winning architect - John Gadzen.","vi":"Nó được thiết kế bởi một kiến trúc sư từng đoạt giải thưởng - John Gadzen."},{"time":26300,"en":"That's G-A-D-Z-E-N. Have a look at his website - he's done some fantastic work.","vi":"Đó là G-A-D-Z-E-N. Hãy xem trang web của anh ấy - anh ấy đã làm một số công việc tuyệt vời."},{"time":35520,"en":"Northfields is just outside town, on Forest Drive.","vi":"Northfields nằm ngay bên ngoài thị trấn, trên đường Forest Drive."},{"time":40800,"en":"If you're coming by car and want to use your sat nav, then the postcode is WT3 5BX.","vi":"Nếu bạn đến bằng ô tô và muốn sử dụng hệ thống định vị vệ tinh, thì mã bưu điện là WT3 5BX."},{"time":51380,"en":"That's the easiest way to do it; it works better than using the address.","vi":"Đó là cách dễ nhất để thực hiện; nó hoạt động tốt hơn là sử dụng địa chỉ."},{"time":56940,"en":"We are open seven days a week, and our opening hours are ten am until six pm every day except Thursday.","vi":"Chúng tôi mở cửa bảy ngày một tuần và giờ mở cửa của chúng tôi là từ mười giờ sáng đến sáu giờ chiều mỗi ngày trừ Thứ Năm."},{"time":66400,"en":"That's when we have late-night shopping until 8:00 pm.","vi":"Đó là khi chúng tôi có chương trình mua sắm muộn đến 8:00 tối."},{"time":71160,"en":"We're planning to open late on Wednesdays too, but that won't happen until we see how popular the centre is.","vi":"Chúng tôi cũng đang lên kế hoạch mở cửa muộn vào các ngày Thứ Tư, nhưng điều đó sẽ không xảy ra cho đến khi chúng tôi thấy trung tâm này phổ biến như thế nào."},{"time":80060,"en":"There are lots of ways to get to us.","vi":"Có rất nhiều cách để đến chỗ chúng tôi."},{"time":83060,"en":"We have a large car park, which at the moment is free to use.","vi":"Chúng tôi có một bãi đậu xe lớn, hiện tại được sử dụng miễn phí."},{"time":88860,"en":"You can also come by bus from the town centre.","vi":"Bạn cũng có thể đến bằng xe buýt từ trung tâm thị trấn."},{"time":93280,"en":"Bus 635 brings you to the entrance.","vi":"Xe buýt 635 sẽ đưa bạn đến lối vào."},{"time":98020,"en":"There's also bus 729, but that stops further away and it's a five-minute walk to the shopping centre.","vi":"Ngoài ra còn có xe buýt 729, nhưng xe này dừng ở xa hơn và bạn phải đi bộ năm phút đến trung tâm mua sắm."},{"time":108260,"en":"And of course, you can use the underground.","vi":"Và tất nhiên, bạn có thể sử dụng tàu điện ngầm."},{"time":111660,"en":"A ticket from town is only £3.50.","vi":"Một vé từ thị trấn chỉ có giá 3,50 bảng."},{"time":116280,"en":"The bus costs £2.00, so the underground is a bit more expensive but much faster.","vi":"Xe buýt có giá 2,00 bảng, vì vậy tàu điện ngầm đắt hơn một chút nhưng nhanh hơn nhiều."},{"time":124980,"en":"From the town centre, it only takes fifteen minutes!","vi":"Từ trung tâm thị trấn, chỉ mất mười lăm phút!"}]}},{"id":"listening_u3_10","title":"Getting Around Town: recording 2","actTitle":"Luyện tập: Recording 2","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120859/?view=embed","pType":"listen_passage","probTitle":"Getting Around Town: recording 2","audioUrl":"https://s4-media1.study4.com/media/mindset_media/mindset10.mp3","youtubeId":"","subs":[{"time":0,"en":"Ok, now let me show you a map of the shopping centre.","vi":"Được rồi, bây giờ tôi sẽ cho bạn xem bản đồ của trung tâm mua sắm."},{"time":6520,"en":"As you can see, there are two floors.","vi":"Như bạn thấy, có hai tầng."},{"time":10580,"en":"On the first floor there's a cinema, where you can see some great movies.","vi":"Ở tầng một có một rạp chiếu phim, nơi bạn có thể xem những bộ phim hay."},{"time":16900,"en":"And opposite that, in a smaller area, there are lots of places to eat and drink.","vi":"Và đối diện rạp chiếu phim, ở một khu vực nhỏ hơn, có rất nhiều nơi để ăn uống."},{"time":24620,"en":"There are fast-food restaurants as well, if you don't have time to sit and eat.","vi":"Cũng có các nhà hàng thức ăn nhanh, nếu bạn không có thời gian ngồi ăn."},{"time":30900,"en":"All the shops are on the ground floor.","vi":"Tất cả các cửa hàng đều ở tầng trệt."},{"time":34500,"en":"The biggest shop is the supermarket.","vi":"Cửa hàng lớn nhất là siêu thị."},{"time":38360,"en":"If you use the car park entrance, it's the last shop on your right.","vi":"Nếu bạn đi từ lối vào bãi đậu xe, thì đó là cửa hàng cuối cùng bên tay phải của bạn."},{"time":43960,"en":"Then, all the way over on the other side of the building, is the second biggest shop - Green's department store.","vi":"Sau đó, ở phía bên kia của tòa nhà, là cửa hàng lớn thứ hai - cửa hàng bách hóa Green's."},{"time":52820,"en":"You can get almost anything in there, including gifts, things for the kitchen, and furniture.","vi":"Bạn có thể mua hầu hết mọi thứ ở đó, bao gồm quà tặng, đồ dùng cho nhà bếp và đồ nội thất."},{"time":61760,"en":"Also on the ground floor is a pharmacy selling medicine, and health and beauty products.","vi":"Ngoài ra, ở tầng trệt còn có một hiệu thuốc bán thuốc, và các sản phẩm chăm sóc sức khỏe và sắc đẹp."},{"time":69960,"en":"You'll find it between the men's and women's clothes shop and the cafe.","vi":"Bạn sẽ thấy nó nằm giữa cửa hàng quần áo nam nữ và quán cà phê."},{"time":76120,"en":"Male and female toilets are also on this floor, which is on the same side as the cafe.","vi":"Nhà vệ sinh nam và nữ cũng ở trên tầng này, nằm cùng phía với quán cà phê."},{"time":84460,"en":"There's also a great book store selling everything you might need for school.","vi":"Ngoài ra còn có một hiệu sách tuyệt vời bán mọi thứ bạn có thể cần cho trường học."},{"time":90680,"en":"If you're coming from the car park entrance, that's the second shop on your right, next to the sports shop.","vi":"Nếu bạn đi từ lối vào bãi đậu xe, thì đó là cửa hàng thứ hai bên tay phải của bạn, cạnh cửa hàng thể thao."},{"time":98340,"en":"Oh, and if you need a mobile phone, that's the smallest shop in the shopping centre - between the bank and the shoe shop.","vi":"Ồ, và nếu bạn cần một chiếc điện thoại di động, thì đó là cửa hàng nhỏ nhất trong trung tâm mua sắm - nằm giữa ngân hàng và cửa hàng giày."},{"time":107520,"en":"You can get all the latest mobile phones there.","vi":"Bạn có thể mua tất cả các điện thoại di động mới nhất ở đó."},{"time":111020,"en":"So I hope you'll all visit Northfields' soon and that you'll have a great time here!","vi":"Vì vậy, tôi hy vọng tất cả các bạn sẽ sớm ghé thăm Northfields và có một khoảng thời gian tuyệt vời ở đây!"}]}},{"id":"listening_u3_11","title":"Careers and Learning: recording 1","actTitle":"Luyện tập: Recording 1","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120860/?view=embed","pType":"listen_passage","probTitle":"Careers and Learning: recording 1","audioUrl":"https://s4-media1.study4.com/media/mindset_media/mindset11.mp3","youtubeId":"","subs":[{"time":0,"en":"Good evening!","vi":"Chào buổi tối!"},{"time":1800,"en":"Hello, my name's Jack Riley.","vi":"Xin chào, tôi là Jack Riley."},{"time":6000,"en":"I worked in a restaurant when I was younger, but now I'm a famous chef.","vi":"Khi còn trẻ, tôi từng làm việc trong một nhà hàng, nhưng giờ tôi là một đầu bếp nổi tiếng."},{"time":13060,"en":"You can listen to my cooking show on Mondays at half past seven.","vi":"Bạn có thể nghe chương trình nấu ăn của tôi vào các ngày thứ Hai lúc bảy rưỡi."},{"time":19820,"en":"This Wednesday, you can see me on the TV show Before They Were Famous.","vi":"Thứ Tư tuần này, bạn có thể thấy tôi trên chương trình TV 'Trước Khi Họ Nổi Tiếng'."},{"time":27160,"en":"I'm going to tell you about my life before I became a TV chef.","vi":"Tôi sẽ kể cho bạn nghe về cuộc đời mình trước khi trở thành một đầu bếp truyền hình."},{"time":33680,"en":"You can see the programme on channel three and they will show it at eight o'clock.","vi":"Bạn có thể xem chương trình trên kênh số ba và họ sẽ chiếu nó vào lúc tám giờ."},{"time":39060,"en":"People often ask me how I became so successful, and I tell them that it wasn't always that way.","vi":"Mọi người thường hỏi tôi làm thế nào tôi trở nên thành công như vậy, và tôi nói với họ rằng không phải lúc nào cũng như vậy."},{"time":50300,"en":"Most of my friends left school when they were eighteen and went to university, but I left school when I was sixteen.","vi":"Hầu hết bạn bè của tôi rời trường khi họ mười tám tuổi và vào đại học, nhưng tôi đã bỏ học khi mười sáu tuổi."},{"time":60600,"en":"At school, I was a really bad student.","vi":"Ở trường, tôi là một học sinh rất tệ."},{"time":65100,"en":"I only passed my exams in History and French.","vi":"Tôi chỉ đậu kỳ thi môn Lịch sử và tiếng Pháp."},{"time":69620,"en":"I couldn't understand maths easily and I couldn't write very well, so I failed my exams in both maths and English.","vi":"Tôi không thể hiểu toán một cách dễ dàng và tôi không thể viết tốt, vì vậy tôi đã trượt kỳ thi cả môn toán và tiếng Anh."},{"time":80980,"en":"I always enjoyed trying different foods, especially on holidays in Spain with my family, but I first discovered my love of cooking when I got a summer job working in the kitchen in an Italian restaurant near my home.","vi":"Tôi luôn thích thử các món ăn khác nhau, đặc biệt là trong những kỳ nghỉ ở Tây Ban Nha với gia đình, nhưng tôi lần đầu tiên khám phá ra niềm yêu thích nấu ăn khi tôi nhận được một công việc mùa hè làm việc trong bếp ở một nhà hàng Ý gần nhà."},{"time":100640,"en":"The chefs there could make these amazing dishes out of really simple ingredients.","vi":"Các đầu bếp ở đó có thể tạo ra những món ăn tuyệt vời từ những nguyên liệu thực sự đơn giản."},{"time":107720,"en":"I wanted to be like them, but I lived in a small village near Cambridge and it wasn't possible to train to be a chef there.","vi":"Tôi muốn được như họ, nhưng tôi sống trong một ngôi làng nhỏ gần Cambridge và không thể đào tạo để trở thành một đầu bếp ở đó."},{"time":118300,"en":"I applied for jobs in Rome, but I couldn't speak Italian so in the end, I decided to move to London and train to be a chef.","vi":"Tôi đã nộp đơn xin việc ở Rome, nhưng tôi không thể nói tiếng Ý, vì vậy cuối cùng, tôi quyết định chuyển đến London và học để trở thành một đầu bếp."},{"time":128740,"en":"Today, my career is more successful than I could have ever imagined.","vi":"Ngày nay, sự nghiệp của tôi thành công hơn những gì tôi có thể tưởng tượng."},{"time":136800,"en":"I first appeared on TV in The Food Show in 2005, and I started presenting my radio show, Dinner with Jack in 2006.","vi":"Tôi lần đầu tiên xuất hiện trên TV trong 'The Food Show' năm 2005, và tôi bắt đầu dẫn chương trình radio của mình, 'Bữa tối với Jack' vào năm 2006."},{"time":150260,"en":"I wrote my first bestselling cookbook, Jack's Best Dishes in 2004.","vi":"Tôi đã viết cuốn sách dạy nấu ăn bán chạy nhất đầu tiên của mình, 'Những món ăn ngon nhất của Jack' vào năm 2004."},{"time":157960,"en":"And I worked as head chef at two top London restaurants, The Olive Tree in 2001, and The Lemon Grove between 2002 and 2005.","vi":"Và tôi đã làm bếp trưởng tại hai nhà hàng hàng đầu ở London, 'The Olive Tree' vào năm 2001, và 'The Lemon Grove' từ năm 2002 đến năm 2005."},{"time":173100,"en":"I'm married with two beautiful children - and my third child will be born in December!","vi":"Tôi đã kết hôn và có hai đứa con xinh đẹp - và đứa con thứ ba của tôi sẽ chào đời vào tháng 12!"},{"time":181240,"en":"When I was 16, I could only cook soup from a tin and I couldn't write a sentence without making lots of mistakes.","vi":"Khi tôi 16 tuổi, tôi chỉ có thể nấu súp từ hộp và tôi không thể viết một câu mà không mắc nhiều lỗi."},{"time":190520,"en":"Now, I can cook over 100 dishes and write books.","vi":"Bây giờ, tôi có thể nấu hơn 100 món ăn và viết sách."},{"time":196900,"en":"I can't work for really long hours any more like I did at The Lemon Grove.","vi":"Tôi không thể làm việc nhiều giờ như tôi đã từng làm ở 'The Lemon Grove' nữa."},{"time":202400,"en":"That was the hardest I have ever worked in my life!","vi":"Đó là khoảng thời gian tôi làm việc vất vả nhất trong cuộc đời!"},{"time":207260,"en":"And I still can't do maths!","vi":"Và tôi vẫn không thể làm toán!"}]}},{"id":"listening_u3_12","title":"Staying Healthy: recording 1","actTitle":"Luyện tập: Recording 1","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120861/?view=embed","pType":"listen_passage","probTitle":"Staying Healthy: recording 1","audioUrl":"https://s4-media1.study4.com/media/mindset_media/mindset12.mp3","youtubeId":"","subs":[{"time":0,"en":"Hello, Tom.","vi":"Chào Tom."},{"time":1680,"en":"Hi, Tom. Where are you going?","vi":"Chào Tom. Bạn đang đi đâu vậy?"},{"time":4140,"en":"Hi, Sarah. Hi, Samantha. I'm going to the sports centre.","vi":"Chào Sarah. Chào Samantha. Tôi đang đến trung tâm thể thao."},{"time":8860,"en":"Oh, great. I'm thinking of joining the gym there.","vi":"Ồ, tuyệt. Tôi đang định đăng ký tập gym ở đó."},{"time":12660,"en":"Really? Why don't you come with me and get some Information about it?","vi":"Thật á? Sao bạn không đi cùng tôi để lấy thêm thông tin về nó?"},{"time":18300,"en":"Ok, thanks. Did you join the gym?","vi":"Ok, cảm ơn. Bạn đã đăng ký tập gym chưa?"},{"time":22300,"en":"Yes, I did.","vi":"Rồi, tôi đăng ký rồi."},{"time":23980,"en":"It's got really great equipment - all very modern and new.","vi":"Ở đó có trang thiết bị rất tuyệt vời - tất cả đều rất hiện đại và mới."},{"time":29320,"en":"However, it is a little bit expensive, almost forty pounds a month, and that's with a student discount...","vi":"Tuy nhiên, nó hơi đắt một chút, gần bốn mươi bảng một tháng, và đó là đã có giảm giá cho sinh viên..."},{"time":38420,"en":"But I've been every day since I joined.","vi":"Nhưng tôi đã đến đó mỗi ngày kể từ khi đăng ký."},{"time":41380,"en":"£40 a month! That is expensive. However, if you think it's a good gym, maybe I'll try it.","vi":"40 bảng một tháng! Đắt thật. Tuy nhiên, nếu bạn nghĩ đó là một phòng tập tốt, có lẽ tôi sẽ thử."},{"time":51240,"en":"Well, I think £40 a month is way too much.","vi":"Chà, tôi nghĩ 40 bảng một tháng là quá nhiều."},{"time":55180,"en":"I don't know why people spend so much money on a gym membership, when they can exercise in the park for free.","vi":"Tôi không hiểu tại sao mọi người lại chi quá nhiều tiền cho thẻ thành viên phòng tập, trong khi họ có thể tập thể dục miễn phí ở công viên."},{"time":62940,"en":"I've tried running in the park, but it was really boring!","vi":"Tôi đã thử chạy bộ ở công viên, nhưng nó thực sự rất chán!"},{"time":66940,"en":"I prefer to exercise with friends because it encourages me to work harder.","vi":"Tôi thích tập thể dục với bạn bè hơn vì nó khuyến khích tôi tập luyện chăm chỉ hơn."},{"time":73840,"en":"I prefer to do exercise with friends as well - it's much more fun than exercising alone.","vi":"Tôi cũng thích tập thể dục với bạn bè - nó vui hơn nhiều so với tập một mình."},{"time":80040,"en":"But it's not just running.","vi":"Nhưng không chỉ có chạy bộ."},{"time":82280,"en":"They have group exercise classes there in the park in the morning.","vi":"Họ có các lớp tập thể dục nhóm ở công viên vào buổi sáng."},{"time":86720,"en":"Exercising outside is better because you get lots of fresh air.","vi":"Tập thể dục ngoài trời tốt hơn vì bạn có được nhiều không khí trong lành."},{"time":92000,"en":"And you can exercise with a personal trainer, too.","vi":"Và bạn cũng có thể tập thể dục với huấn luyện viên cá nhân."},{"time":95760,"en":"That sounds good. I think I'd like to have a personal trainer. How much does one cost?","vi":"Nghe hay đó. Tôi nghĩ tôi muốn có một huấn luyện viên cá nhân. Một giờ bao nhiêu tiền?"},{"time":102400,"en":"I pay £20 an hour.","vi":"Tôi trả 20 bảng một giờ."},{"time":104480,"en":"£20 an hour! Doesn't that work out to be more expensive than joining the gym?","vi":"20 bảng một giờ! Chẳng phải cái đó còn đắt hơn cả đăng ký tập gym sao?"},{"time":110780,"en":"It is expensive, but I think that it's worth the money.","vi":"Đắt thật, nhưng tôi nghĩ nó đáng đồng tiền."},{"time":114880,"en":"You can find out which type of exercise is best for you, and you can get some really useful advice on diet, too.","vi":"Bạn có thể tìm ra loại bài tập nào tốt nhất cho bạn, và bạn cũng có thể nhận được một số lời khuyên thực sự hữu ích về chế độ ăn uống."},{"time":123220,"en":"That does sound useful.","vi":"Nghe có vẻ hữu ích đó."},{"time":125360,"en":"I need some advice on my diet - it's not great at the moment.","vi":"Tôi cần một số lời khuyên về chế độ ăn uống của mình - nó không được tốt lắm vào lúc này."},{"time":129540,"en":"And I know that a healthy diet helps you get fit.","vi":"Và tôi biết rằng một chế độ ăn uống lành mạnh giúp bạn khỏe mạnh."},{"time":133280,"en":"I can give you the email address of my personal trainer if you want.","vi":"Tôi có thể cho bạn địa chỉ email của huấn luyện viên cá nhân của tôi nếu bạn muốn."},{"time":137660,"en":"That's great! Thanks Samantha.","vi":"Tuyệt vời! Cảm ơn Samantha."},{"time":140520,"en":"What about the gym? Do you think you'll join it?","vi":"Thế còn phòng tập thì sao? Bạn có nghĩ bạn sẽ đăng ký không?"},{"time":144100,"en":"Yes - I think I'm going to try both.","vi":"Có - Tôi nghĩ tôi sẽ thử cả hai."}]}},{"id":"listening_u3_13","title":"Staying Healthy: recording 2","actTitle":"Luyện tập: Recording 2","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120862/?view=embed","pType":"listen_passage","probTitle":"Staying Healthy: recording 2","audioUrl":"https://s4-media1.study4.com/media/mindset_media/mindset13.mp3","youtubeId":"","subs":[{"time":0,"en":"Jim","vi":"Jim"},{"time":1900,"en":"When I need to relax, I usually read a book.","vi":"Khi cần thư giãn, tôi thường đọc sách."},{"time":6200,"en":"I believe that reading can also change your mood.","vi":"Tôi tin rằng đọc sách cũng có thể thay đổi tâm trạng của bạn."},{"time":10060,"en":"For example, a good novel can make you forget about all of your worries and a funny story can make you feel happy.","vi":"Ví dụ, một cuốn tiểu thuyết hay có thể khiến bạn quên đi mọi lo lắng và một câu chuyện hài hước có thể khiến bạn cảm thấy vui vẻ."},{"time":18940,"en":"If you're feeling sad, you shouldn't read a sad story though, as this will make you feel worse.","vi":"Nếu bạn đang cảm thấy buồn, bạn không nên đọc một câu chuyện buồn, vì điều này sẽ khiến bạn cảm thấy tồi tệ hơn."},{"time":27220,"en":"Elena","vi":"Elena"},{"time":28920,"en":"For me, doing yoga is the best way to relax.","vi":"Đối với tôi, tập yoga là cách tốt nhất để thư giãn."},{"time":33400,"en":"You don't even have to spend a long time doing it to feel the benefits - even five minutes of breathing exercises can make a difference.","vi":"Bạn thậm chí không cần phải dành nhiều thời gian để cảm nhận được lợi ích - ngay cả năm phút tập thở cũng có thể tạo ra sự khác biệt."},{"time":44240,"en":"Doing yoga will help you breathe deeply, which is the fastest way to feel more relaxed.","vi":"Tập yoga sẽ giúp bạn thở sâu, đây là cách nhanh nhất để cảm thấy thư thái hơn."},{"time":50940,"en":"You can do yoga classes in many different places.","vi":"Bạn có thể tham gia các lớp học yoga ở nhiều địa điểm khác nhau."},{"time":55260,"en":"It isn't expensive either!","vi":"Nó cũng không hề đắt đỏ!"},{"time":58560,"en":"Many sports centres offer yoga classes at a low price.","vi":"Nhiều trung tâm thể thao cung cấp các lớp học yoga với giá thấp."},{"time":63520,"en":"You have to find a good teacher though - that's really important.","vi":"Tuy nhiên, bạn phải tìm một giáo viên giỏi - điều đó thực sự quan trọng."},{"time":67480,"en":"Kate","vi":"Kate"},{"time":71620,"en":"I think that doing regular exercise is the best way to relax.","vi":"Tôi nghĩ rằng tập thể dục thường xuyên là cách tốt nhất để thư giãn."},{"time":76340,"en":"It's good for the body and also for the mind.","vi":"Nó tốt cho cơ thể và cả tâm trí."},{"time":80280,"en":"After a short run or work out we feel more relaxed and happier.","vi":"Sau một lần chạy bộ ngắn hoặc tập luyện, chúng ta cảm thấy thư thái và hạnh phúc hơn."},{"time":85880,"en":"Often a person's reason for not doing regular exercise is they don't have enough time.","vi":"Thông thường, lý do một người không tập thể dục thường xuyên là họ không có đủ thời gian."},{"time":91680,"en":"However, you can always find ways to do more exercise, like walking instead of getting the bus or driving.","vi":"Tuy nhiên, bạn luôn có thể tìm cách để tập thể dục nhiều hơn, chẳng hạn như đi bộ thay vì đi xe buýt hoặc lái xe."},{"time":101360,"en":"Mike","vi":"Mike"},{"time":103140,"en":"When I am feeling stressed at work, I go straight outdoors for a walk in the park.","vi":"Khi tôi cảm thấy căng thẳng ở nơi làm việc, tôi đi thẳng ra ngoài đi dạo trong công viên."},{"time":109000,"en":"Breathing fresh air and looking at nature helps me to deal with my problems.","vi":"Hít thở không khí trong lành và ngắm nhìn thiên nhiên giúp tôi giải quyết các vấn đề của mình."},{"time":114360,"en":"Being active for just twenty minutes outside is enough to make you feel healthier, but the longer you spend, the better.","vi":"Vận động ngoài trời chỉ cần hai mươi phút là đủ để bạn cảm thấy khỏe mạnh hơn, nhưng bạn càng dành nhiều thời gian, càng tốt."},{"time":123100,"en":"I try to spend half an hour every day exercising during my lunch break.","vi":"Tôi cố gắng dành nửa giờ mỗi ngày để tập thể dục trong giờ nghỉ trưa."},{"time":128660,"en":"I can't spend the whole hour outside because I don't always have time.","vi":"Tôi không thể dành cả tiếng đồng hồ ở bên ngoài vì không phải lúc nào tôi cũng có thời gian."},{"time":133820,"en":"Everyone should give it a try.","vi":"Mọi người nên thử."},{"time":137540,"en":"Mark","vi":"Mark"},{"time":139200,"en":"When I want to relax, the first thing I do is make myself a cup of tea.","vi":"Khi tôi muốn thư giãn, điều đầu tiên tôi làm là pha cho mình một tách trà."},{"time":145040,"en":"I think green tea makes me feel calmer than black tea, but all types of tea can make you feel less stressed.","vi":"Tôi nghĩ rằng trà xanh khiến tôi cảm thấy bình tĩnh hơn trà đen, nhưng tất cả các loại trà đều có thể giúp bạn giảm căng thẳng."},{"time":153620,"en":"A recent study found that people who drink tea during stressful times are much more relaxed than those who don't.","vi":"Một nghiên cứu gần đây cho thấy rằng những người uống trà trong thời gian căng thẳng thư giãn hơn nhiều so với những người không uống."},{"time":162440,"en":"You shouldn't drink tea at night though or you may find it difficult to sleep.","vi":"Tuy nhiên, bạn không nên uống trà vào ban đêm nếu không bạn có thể thấy khó ngủ."}]}},{"id":"listening_u3_14","title":"Words and Communication: recording 1","actTitle":"Luyện tập: Recording 1","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120863/?view=embed","pType":"listen_passage","probTitle":"Words and Communication: recording 1","audioUrl":"https://s4-media1.study4.com/media/mindset_media/mindset14.mp3","youtubeId":"","subs":[{"time":0,"en":"Oliver, we need to discuss about how to start our project.","vi":"Oliver, chúng ta cần thảo luận về cách bắt đầu dự án của mình."},{"time":5780,"en":"Remember that our teacher wants us to write the report on two things.","vi":"Nhớ rằng giáo viên muốn chúng ta viết báo cáo về hai điều."},{"time":10940,"en":"One, how many students in college already speak more than one language...","vi":"Một là, có bao nhiêu sinh viên trong trường đã nói được nhiều hơn một ngôn ngữ..."},{"time":16500,"en":"... yes, and two, what level their English is.","vi":"... đúng vậy, và hai là, trình độ tiếng Anh của họ ở mức nào."},{"time":20900,"en":"It's a big project so I think we're going to have to speak to a lot of people.","vi":"Đây là một dự án lớn vì vậy tôi nghĩ chúng ta sẽ phải nói chuyện với rất nhiều người."},{"time":26240,"en":"Yes, I know!","vi":"Ừ, tôi biết!"},{"time":28120,"en":"Do you really think it'll be possible to speak to everyone?","vi":"Bạn có thực sự nghĩ rằng có thể nói chuyện với tất cả mọi người không?"},{"time":32180,"en":"I'm not sure.","vi":"Tôi không chắc."},{"time":33900,"en":"There are over two hundred students in total.","vi":"Tổng cộng có hơn hai trăm sinh viên."},{"time":37060,"en":"I know, but I guess only half of them speak just a single language.","vi":"Tôi biết, nhưng tôi đoán chỉ một nửa trong số họ chỉ nói một ngôn ngữ."},{"time":42800,"en":"That's still a lot.","vi":"Như vậy vẫn là nhiều."},{"time":44820,"en":"I don't think we have enough time to go around and have a chat with the whole college.","vi":"Tôi không nghĩ chúng ta có đủ thời gian để đi xung quanh và trò chuyện với cả trường đâu."},{"time":50240,"en":"How are we going to show the results?","vi":"Chúng ta sẽ trình bày kết quả như thế nào?"},{"time":52360,"en":"I think it'll be a problem if we only include numbers. We need more than that.","vi":"Tôi nghĩ sẽ có vấn đề nếu chúng ta chỉ đưa ra các con số. Chúng ta cần nhiều hơn thế."},{"time":58840,"en":"Yes, I agree.","vi":"Ừ, tôi đồng ý."},{"time":60720,"en":"Maybe including some graphs or tables is a good idea.","vi":"Có lẽ đưa vào một vài biểu đồ hoặc bảng là một ý kiến hay."},{"time":65760,"en":"Let me think... First, we need to find out how many students we have here in the college in total.","vi":"Để tôi nghĩ... Đầu tiên, chúng ta cần tìm hiểu xem tổng cộng có bao nhiêu sinh viên ở trường mình."},{"time":74240,"en":"Then we can work out how many of them speak two or more languages.","vi":"Sau đó, chúng ta có thể tính xem có bao nhiêu người trong số họ nói được hai hoặc nhiều ngôn ngữ hơn."},{"time":79560,"en":"Can I make a suggestion?","vi":"Tôi có thể đưa ra một gợi ý được không?"},{"time":81820,"en":"I think we can ask for that information from the college office first.","vi":"Tôi nghĩ chúng ta có thể hỏi thông tin đó từ văn phòng trường trước."},{"time":87620,"en":"I remember that, on my first day here, I put information about my second language on the registration form.","vi":"Tôi nhớ rằng, vào ngày đầu tiên đến đây, tôi đã điền thông tin về ngôn ngữ thứ hai của mình vào mẫu đăng ký."},{"time":95720,"en":"So, I think it's the same for everyone.","vi":"Vì vậy, tôi nghĩ mọi người cũng vậy."},{"time":98320,"en":"That's a good idea.","vi":"Đó là một ý kiến hay."},{"time":99860,"en":"That'll save us some time.","vi":"Điều đó sẽ giúp chúng ta tiết kiệm được chút thời gian."},{"time":102060,"en":"I'll make an appointment to go and speak to somebody there after class.","vi":"Tôi sẽ đặt một cuộc hẹn để đến đó nói chuyện với ai đó sau giờ học."},{"time":106660,"en":"Who do I need to see?","vi":"Tôi cần gặp ai?"},{"time":108700,"en":"Is it Miss Wainwright?","vi":"Có phải là cô Wainwright không?"},{"time":110480,"en":"No, she works in the student services room. You need to see Miss Smith. She's in the college office.","vi":"Không, cô ấy làm việc ở phòng dịch vụ sinh viên. Bạn cần gặp cô Smith. Cô ấy ở văn phòng trường."},{"time":118820,"en":"Can you remind me where that is? Is it next door to the IT services offices where Mr Black works?","vi":"Bạn có thể nhắc tôi văn phòng đó ở đâu không? Có phải nó ở ngay cạnh văn phòng dịch vụ CNTT nơi ông Black làm việc không?"},{"time":126880,"en":"No, Mr Black is in the student administration office so you need to go to the floor above.","vi":"Không, ông Black ở văn phòng quản lý sinh viên, vì vậy bạn cần lên tầng trên."},{"time":134520,"en":"Oh, OK. I know where that is now.","vi":"Ồ, được rồi. Bây giờ tôi biết chỗ đó rồi."},{"time":137780,"en":"Great. OK, I'm going to have lunch. Do you want to join me?","vi":"Tuyệt. Được rồi, tôi đi ăn trưa đây. Bạn muốn đi cùng tôi không?"},{"time":142660,"en":"No, sorry, I can't.","vi":"Không, xin lỗi, tôi không thể."},{"time":144780,"en":"I need to study for my maths test.","vi":"Tôi cần học cho bài kiểm tra toán."},{"time":147360,"en":"Enjoy your lunch.","vi":"Ăn trưa ngon miệng nhé."},{"time":148900,"en":"I'm going to the library.","vi":"Tôi đến thư viện đây."},{"time":150260,"en":"Bye!","vi":"Tạm biệt!"}]}},{"id":"listening_u3_15","title":"Science and Technology: recording 1","actTitle":"Luyện tập: Recording 1","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120864/?view=embed","pType":"listen_passage","probTitle":"Science and Technology: recording 1","audioUrl":"https://s4-media1.study4.com/media/mindset_media/mindset15.mp3","youtubeId":"","subs":[{"time":0,"en":"Good morning, I'm here today to talk about the design and the success of smartphones.","vi":"Chào buổi sáng, hôm nay tôi ở đây để nói về thiết kế và sự thành công của điện thoại thông minh."},{"time":7880,"en":"They are convenient, and they allow us to keep control of our lives.","vi":"Chúng rất tiện lợi và cho phép chúng ta kiểm soát cuộc sống của mình."},{"time":13540,"en":"One important reason why I think smartphones are so successful is because of their simple, clean design.","vi":"Một lý do quan trọng khiến tôi nghĩ điện thoại thông minh thành công đến vậy là vì thiết kế đơn giản và gọn gàng của chúng."},{"time":22680,"en":"Of course, there are many different brands, but let's look at a common example on this picture.","vi":"Tất nhiên, có rất nhiều thương hiệu khác nhau, nhưng hãy xem một ví dụ phổ biến trên bức ảnh này."},{"time":30500,"en":"First of all, on the front of the phone, we have the glass touch screen, also known as the display.","vi":"Trước hết, ở mặt trước của điện thoại, chúng ta có màn hình cảm ứng bằng kính, còn được gọi là màn hình hiển thị."},{"time":38600,"en":"It's very easy, you only need to press your finger on this when you want to use an app.","vi":"Rất dễ dàng, bạn chỉ cần ấn ngón tay vào đây khi muốn sử dụng ứng dụng."},{"time":45800,"en":"Next, on the top right side of the smartphone, is the power button.","vi":"Tiếp theo, ở phía trên bên phải của điện thoại thông minh là nút nguồn."},{"time":51800,"en":"You use this to turn the phone on or off again.","vi":"Bạn sử dụng nút này để bật hoặc tắt lại điện thoại."},{"time":56640,"en":"At the bottom, there is a USB input. This is where you plug in and charge your phone.","vi":"Ở phía dưới, có một cổng USB. Đây là nơi bạn cắm và sạc điện thoại."},{"time":66240,"en":"You can also connect to a laptop and upload your files and photos from your phone.","vi":"Bạn cũng có thể kết nối với máy tính xách tay và tải lên các tập tin và ảnh từ điện thoại của mình."},{"time":72780,"en":"You will see just above this is the microphone.","vi":"Bạn sẽ thấy ngay phía trên đó là micro."},{"time":77620,"en":"Whenever you make a call, you speak into this.","vi":"Bất cứ khi nào bạn gọi điện, bạn sẽ nói vào micro này."},{"time":81780,"en":"At the opposite end of the touch screen, you can see the power bar, which you can look at to check the battery.","vi":"Ở đầu đối diện của màn hình cảm ứng, bạn có thể thấy thanh pin, bạn có thể nhìn vào đó để kiểm tra pin."},{"time":90720,"en":"If the bar is low, you will need to plug it in and charge it again soon.","vi":"Nếu thanh pin thấp, bạn sẽ cần cắm sạc lại sớm."},{"time":97360,"en":"Around the phone on the outside, keeping all of this in place is the case - sometimes made from plastic, but now more often made of metal.","vi":"Bao quanh điện thoại ở bên ngoài, giữ tất cả những thứ này cố định là vỏ - đôi khi được làm từ nhựa, nhưng bây giờ thường được làm bằng kim loại hơn."},{"time":109540,"en":"Many people think that the reason for the case is so that they can have a different design and colour and make it more personal.","vi":"Nhiều người nghĩ rằng lý do cho việc có vỏ là để họ có thể có một thiết kế và màu sắc khác nhau và làm cho nó mang tính cá nhân hơn."},{"time":118360,"en":"Actually, every phone needs a good, strong case to protect the phone from breaking.","vi":"Thực tế, mọi điện thoại đều cần một chiếc ốp lưng tốt và chắc chắn để bảo vệ điện thoại khỏi bị vỡ."}]}},{"id":"listening_u3_16","title":"Science and Technology: recording 2","actTitle":"Luyện tập: Recording 2","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120865/?view=embed","pType":"listen_passage","probTitle":"Science and Technology: recording 2","audioUrl":"https://s4-media1.study4.com/media/mindset_media/mindset16.mp3","youtubeId":"","subs":[{"time":0,"en":"Smartphones are becoming more popular every day, all around the world.","vi":"Điện thoại thông minh ngày càng trở nên phổ biến trên toàn thế giới."},{"time":6680,"en":"In 2010, 38 percent of the world's population owned a smartphone.","vi":"Vào năm 2010, 38% dân số thế giới sở hữu điện thoại thông minh."},{"time":13560,"en":"Most of these people were from developed areas of the world, like North America and Europe.","vi":"Phần lớn những người này đến từ các khu vực phát triển của thế giới, như Bắc Mỹ và Châu Âu."},{"time":20960,"en":"Five years later, that figure was a lot higher.","vi":"Năm năm sau, con số đó đã cao hơn rất nhiều."},{"time":25240,"en":"In 2015, 62 percent of all people had one.","vi":"Vào năm 2015, 62% tổng số người sở hữu một chiếc."},{"time":31820,"en":"And, in the future, these amazing little devices will probably be even more popular.","vi":"Và trong tương lai, những thiết bị nhỏ bé tuyệt vời này có lẽ sẽ còn phổ biến hơn nữa."},{"time":39580,"en":"So popular that, by 2020, 78 percent of the population will own one, and by 2025 many scientists believe that this number will be even higher still.","vi":"Phổ biến đến mức, vào năm 2020, 78% dân số sẽ sở hữu một chiếc, và đến năm 2025 nhiều nhà khoa học tin rằng con số này sẽ còn cao hơn nữa."},{"time":54220,"en":"Not as high as 100%, but close.","vi":"Không cao đến 100%, nhưng gần như vậy."},{"time":58460,"en":"This is mostly because, in the less developed parts of the world, people will be richer than they are now.","vi":"Điều này chủ yếu là do, ở những khu vực kém phát triển hơn của thế giới, mọi người sẽ giàu có hơn so với hiện tại."},{"time":66580,"en":"So, in that year, when 86 percent will own one, what will smartphones look like?","vi":"Vậy, vào năm đó, khi 86% dân số sở hữu một chiếc, điện thoại thông minh sẽ trông như thế nào?"},{"time":74780,"en":"Will they look the same as they do now?","vi":"Chúng có trông giống như bây giờ không?"},{"time":78020,"en":"I'm afraid I can't say for sure, but I do know that they won't look the same as the one in the picture that we're looking at today.","vi":"Tôi e rằng tôi không thể nói chắc chắn, nhưng tôi biết rằng chúng sẽ không giống như chiếc trong bức ảnh mà chúng ta đang xem ngày hôm nay."}]}},{"id":"listening_u3_17","title":"Science and Technology: recording 3","actTitle":"Luyện tập: Recording 3","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120866/?view=embed","pType":"listen_passage","probTitle":"Science and Technology: recording 3","audioUrl":"https://s4-media1.study4.com/media/mindset_media/mindset17.mp3","youtubeId":"","subs":[{"time":0,"en":"It has a silver case, and the screen is bigger than most other smartphones.","vi":"Nó có vỏ màu bạc và màn hình lớn hơn hầu hết các điện thoại thông minh khác."},{"time":9200,"en":"The display is also really clear.","vi":"Màn hình hiển thị cũng thực sự rõ nét."},{"time":12960,"en":"It's really light, and thin, it's got a lot of memory, and the battery lasts for a very long time.","vi":"Nó thực sự nhẹ và mỏng, có dung lượng bộ nhớ lớn và pin dùng được rất lâu."},{"time":23860,"en":"It's very expensive, so before I buy it, I'm going to visit a mobile phone shop first, so I can try all the new features.","vi":"Nó rất đắt, vì vậy trước khi mua, tôi sẽ đến thăm một cửa hàng điện thoại di động trước để có thể thử tất cả các tính năng mới."},{"time":37260,"en":"But I'm definitely going to get it online in the end.","vi":"Nhưng cuối cùng chắc chắn tôi sẽ mua nó trực tuyến."},{"time":42080,"en":"I'm sure it will be cheaper.","vi":"Tôi chắc chắn nó sẽ rẻ hơn."},{"time":47360,"en":"The phone I have now, the Plus 5, is the latest model - it came out last year.","vi":"Điện thoại tôi đang dùng bây giờ, Plus 5, là mẫu mới nhất - nó ra mắt vào năm ngoái."},{"time":55920,"en":"But I think it will start to be really slow and seem out of date soon.","vi":"Nhưng tôi nghĩ nó sẽ bắt đầu chạy rất chậm và có vẻ lỗi thời sớm thôi."},{"time":62820,"en":"The Plus 6 is even faster, and it's better for playing games and streaming things online, so that's why I'm going to get it as soon as I can.I'm not sure if it will help me with everything.","vi":"Plus 6 thậm chí còn nhanh hơn và nó tốt hơn cho việc chơi game và xem trực tuyến, đó là lý do tại sao tôi sẽ mua nó càng sớm càng tốt. Tôi không chắc nó sẽ giúp tôi được mọi thứ."},{"time":82540,"en":"It won't do my homework for me if I swipe the screen, for example.","vi":"Ví dụ, nó sẽ không làm bài tập về nhà cho tôi nếu tôi vuốt màn hình."},{"time":89280,"en":"But I think it will be helpful for some things.","vi":"Nhưng tôi nghĩ nó sẽ hữu ích cho một số việc."},{"time":94080,"en":"There's an app for writing a study plan, so I'm going to download that, anyway.","vi":"Có một ứng dụng để viết kế hoạch học tập, vì vậy dù sao thì tôi cũng sẽ tải xuống."}]}},{"id":"listening_u3_18","title":"Family and Friends: recording 1","actTitle":"Luyện tập: Recording 1","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120867/?view=embed","pType":"listen_passage","probTitle":"Family and Friends: recording 1","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset_1.mp3","youtubeId":"","subs":[{"time":0,"en":"Good afternoon, can I help you?","vi":"Chào buổi chiều, tôi có thể giúp gì cho bạn?"},{"time":3660,"en":"Yes, I'm looking for a gift for my sister.","vi":"Vâng, tôi đang tìm một món quà cho em gái tôi."},{"time":7540,"en":"She's going to be 18 next week.","vi":"Em ấy sẽ tròn 18 tuổi vào tuần tới."},{"time":9900,"en":"So I thought a piece of jewellery would be nice.","vi":"Vì vậy, tôi nghĩ một món đồ trang sức sẽ rất tuyệt."},{"time":13680,"en":"Good idea! Do you have anything particular in mind - a necklace, perhaps?","vi":"Ý kiến hay! Bạn có đang nghĩ đến món đồ cụ thể nào không - ví dụ như một chiếc vòng cổ?"},{"time":19440,"en":"Mm, she has so many necklaces. I was thinking of a pair of earrings, possibly.","vi":"Mm, em ấy có rất nhiều vòng cổ rồi. Tôi đang nghĩ đến một đôi bông tai thì hơn."},{"time":25800,"en":"Does she have a favourite colour?","vi":"Em ấy có thích màu nào không?"},{"time":27420,"en":"Mm, she likes blue ...","vi":"Mm, em ấy thích màu xanh lam..."},{"time":29460,"en":"What about this pair? They have some beautiful little blue stones.","vi":"Vậy đôi này thì sao? Chúng có những viên đá nhỏ màu xanh lam rất đẹp."},{"time":34160,"en":"Mm ... They're quite nice, I suppose.","vi":"Mm... Tôi nghĩ chúng khá đẹp."},{"time":36880,"en":"They're silver, and they're handmade, so you won't find anything like them anywhere else.","vi":"Chúng được làm bằng bạc và được làm thủ công, nên bạn sẽ không tìm thấy món đồ nào giống như vậy ở bất cứ đâu."},{"time":42540,"en":"Oh, really? So, how much are they?","vi":"Ồ, vậy à? Vậy chúng có giá bao nhiêu?"},{"time":46340,"en":"Well, they were £30, but actually we've got a sale on at the moment, so they're a little cheaper - only £20.","vi":"À, chúng có giá £30, nhưng hiện tại chúng tôi đang có chương trình giảm giá, nên chúng rẻ hơn một chút - chỉ £20 thôi."},{"time":55000,"en":"So you can save £10!","vi":"Vậy là bạn tiết kiệm được £10!"},{"time":57160,"en":"Great. I'll take them.","vi":"Tuyệt vời. Tôi sẽ lấy chúng."},{"time":59200,"en":"And would you like me to gift wrap them for you?","vi":"Bạn có muốn tôi gói quà chúng cho bạn không?"},{"time":61900,"en":"How much do you charge for that?","vi":"Bạn tính phí bao nhiêu cho việc đó?"},{"time":64120,"en":"For £4 we give you a pretty box and your own choice of wrapping paper.","vi":"Với £4, chúng tôi sẽ cung cấp cho bạn một chiếc hộp xinh xắn và bạn có thể tự chọn giấy gói quà."},{"time":69700,"en":"Or for £5 you can have our luxury wrapping service, which includes a silver box and silver ribbon.","vi":"Hoặc với £5, bạn có thể sử dụng dịch vụ gói quà cao cấp của chúng tôi, bao gồm một hộp bạc và ruy băng bạc."},{"time":76520,"en":"And if you would like a card to write your own personal message, that will be £2 extra.","vi":"Và nếu bạn muốn có một tấm thiệp để viết lời nhắn cá nhân của riêng bạn, thì sẽ thêm £2."},{"time":82140,"en":"Well, it's a special birthday so I'll take the luxury option. But I already have a card, thank you.","vi":"Chà, đây là một ngày sinh nhật đặc biệt nên tôi sẽ chọn gói cao cấp. Nhưng tôi đã có thiệp rồi, cảm ơn."},{"time":90240,"en":"That's fine. I'll do that for you now. And how would you like to pay - cash or card?","vi":"Được thôi. Tôi sẽ làm việc đó cho bạn ngay bây giờ. Bạn muốn thanh toán bằng tiền mặt hay thẻ?"}]}},{"id":"listening_u3_19","title":"Family and Friends: recording 2","actTitle":"Luyện tập: Recording 2","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120868/?view=embed","pType":"listen_passage","probTitle":"Family and Friends: recording 2","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset_2.mp3","youtubeId":"","subs":[{"time":0,"en":"Hi there, Nam! You aren't still working on your history assignment, are you?","vi":"Chào Nam! Cậu vẫn chưa làm xong bài tập lịch sử à?"},{"time":6380,"en":"Hi, Victor!","vi":"Chào Victor!"},{"time":8180,"en":"No, I'm taking a break.","vi":"Không, tớ đang nghỉ một lát."},{"time":10700,"en":"I'm looking at some photos, actually - a family celebration.","vi":"Thực ra tớ đang xem mấy tấm ảnh, ảnh chụp một buổi lễ kỷ niệm của gia đình."},{"time":15720,"en":"Do you want to see them?","vi":"Cậu có muốn xem không?"},{"time":18600,"en":"So, who's the cute baby in this picture here?","vi":"Vậy, em bé dễ thương trong bức ảnh này là ai vậy?"},{"time":23780,"en":"She's my niece - my brother's daughter.","vi":"Đó là cháu gái tớ - con gái của anh trai tớ."},{"time":27500,"en":"Her name's Tae-Hee.","vi":"Tên cháu là Tae-Hee."},{"time":29740,"en":"She's one year old in this picture.","vi":"Trong ảnh này cháu được một tuổi."},{"time":32600,"en":"It's a very important birthday in Korea - we call it 'Dol' or Doljanchi.","vi":"Đó là một ngày sinh nhật rất quan trọng ở Hàn Quốc - chúng tôi gọi nó là 'Dol' hoặc Doljanchi."},{"time":39780,"en":"It's a very special celebration - in fact, I think it's probably more important than a wedding or a graduation!","vi":"Đó là một lễ kỷ niệm rất đặc biệt - thực tế, tớ nghĩ nó có lẽ còn quan trọng hơn cả đám cưới hoặc lễ tốt nghiệp!"},{"time":48380,"en":"And we invite all our family and friends and sometimes our neighbours.","vi":"Và chúng tôi mời tất cả gia đình, bạn bè và đôi khi cả hàng xóm."},{"time":54020,"en":"Here's a picture of the restaurant where we celebrated Tae-Hee's big day.","vi":"Đây là ảnh nhà hàng nơi chúng tôi tổ chức ngày trọng đại của Tae-Hee."},{"time":59140,"en":"What a lovely place - and a beautiful garden, too.","vi":"Một nơi đáng yêu thật - và cả một khu vườn xinh đẹp nữa."},{"time":63540,"en":"Yes, it's a perfect location for taking photographs. Can you see me just there next to the trees?","vi":"Ừ, đó là một địa điểm hoàn hảo để chụp ảnh. Cậu có thấy tớ ở ngay đó cạnh mấy cái cây không?"},{"time":72120,"en":"Ah yes, I like your hat!","vi":"À ừ, tớ thích cái mũ của cậu!"},{"time":76040,"en":"And I like the red and silver hat Tae-Hee's wearing too.","vi":"Và tớ cũng thích cái mũ màu đỏ và bạc mà Tae-Hee đang đội nữa."},{"time":80320,"en":"It's really pretty.","vi":"Nó thật sự rất đẹp."},{"time":81920,"en":"Yes, it's a traditional hat for a girl.","vi":"Ừ, đó là một chiếc mũ truyền thống dành cho bé gái."},{"time":85480,"en":"Baby boys wear a different one - all black.","vi":"Bé trai thì đội một cái khác - toàn màu đen."},{"time":89720,"en":"It looks very serious!","vi":"Trông có vẻ nghiêm túc quá!"},{"time":91820,"en":"That's a bit boring.","vi":"Hơi chán nhỉ."},{"time":93600,"en":"Black and silver would be more interesting.","vi":"Màu đen và bạc sẽ thú vị hơn."},{"time":97840,"en":"What's Tae-Hee wearing round her skirt?","vi":"Tae-Hee đang đeo cái gì quanh váy vậy?"},{"time":101680,"en":"That's a little purse.","vi":"Đó là một cái ví nhỏ."},{"time":103700,"en":"Boy babies wear this too.","vi":"Bé trai cũng đeo cái này."},{"time":105980,"en":"It's made of silk and it means good luck in our culture.","vi":"Nó được làm từ lụa và nó có nghĩa là may mắn trong văn hóa của chúng tôi."},{"time":111480,"en":"And she's wearing a belt too.","vi":"Và cháu bé cũng đang đeo một cái thắt lưng nữa."},{"time":114620,"en":"Look - do you see?","vi":"Nhìn kìa - cậu thấy không?"},{"time":116960,"en":"The belt means she will have a long life!","vi":"Cái thắt lưng có nghĩa là cháu sẽ sống lâu!"},{"time":121640,"en":"And what's this on the table there? It's very colourful. It's rice cakes.","vi":"Và cái này trên bàn là gì vậy? Nó rất nhiều màu sắc. Đó là bánh gạo."},{"time":127940,"en":"I've never seen anything like that before. It looks like a rainbow!","vi":"Tớ chưa từng thấy cái gì như vậy trước đây. Nó trông như cầu vồng vậy!"},{"time":133240,"en":"We always eat rice cakes at a baby's party.","vi":"Chúng tôi luôn ăn bánh gạo trong tiệc của em bé."},{"time":136940,"en":"There are usually 12 different types of them on the table.","vi":"Thường có 12 loại bánh khác nhau trên bàn."},{"time":141460,"en":"Look - this rice cake is completely orange in colour and this one here is bright green!","vi":"Nhìn này - cái bánh gạo này hoàn toàn có màu cam và cái này thì màu xanh lá cây tươi sáng!"},{"time":149880,"en":"It looks like a vegetable!","vi":"Trông như rau củ vậy!"},{"time":152620,"en":"Now, look, this is me with my brother's wife, Mi-Cha. We get on really well together.","vi":"Giờ thì nhìn này, đây là tớ với vợ của anh trai tớ, Mi-Cha. Chúng tớ rất hợp nhau."},{"time":160600,"en":"What are you holding?","vi":"Cậu đang cầm gì vậy?"},{"time":162680,"en":"Oh, it's a little bag.","vi":"Ồ, là một cái túi nhỏ."},{"time":165420,"en":"All the guests get a gift bag at the end of the party.","vi":"Tất cả khách đều nhận được một túi quà khi kết thúc bữa tiệc."},{"time":169800,"en":"And inside there's a present from the baby's parents.","vi":"Và bên trong có một món quà từ bố mẹ của em bé."},{"time":174360,"en":"It's really fun to open it because you don't know what you'll get.","vi":"Mở nó rất vui vì cậu không biết mình sẽ nhận được gì."},{"time":179000,"en":"So it could be a candle, or some chocolates.","vi":"Vậy nên nó có thể là một cây nến, hoặc một ít sôcôla."},{"time":183960,"en":"Guess what I got?","vi":"Đoán xem tớ nhận được gì?"},{"time":185820,"en":"You can see it in this next photo.","vi":"Cậu có thể thấy nó trong bức ảnh tiếp theo này."},{"time":189440,"en":"It looks like a box of tea. But shouldn't it be the other way round - the baby gets the presents?","vi":"Trông như một hộp trà. Nhưng lẽ ra phải ngược lại chứ - em bé phải là người nhận quà chứ?"},{"time":197060,"en":"Well, the baby receives money from the guests, so in a way you're right!","vi":"À, em bé nhận được tiền từ khách, vậy thì theo một cách nào đó cậu nói đúng!"},{"time":203900,"en":"And actually, I've got my present right here.","vi":"Và thực ra, tớ có món quà của tớ ngay đây."},{"time":208000,"en":"So, why don't we open the box right now and have a cup of tea?","vi":"Vậy, tại sao chúng ta không mở hộp ngay bây giờ và uống một tách trà nhỉ?"},{"time":213320,"en":"Then we can try to finish our assignments.","vi":"Sau đó chúng ta có thể cố gắng hoàn thành bài tập của mình."},{"time":216900,"en":"Sounds good to me!","vi":"Nghe hay đấy!"}]}},{"id":"listening_u3_20","title":"Buildings and Places: recording 1","actTitle":"Luyện tập: Recording 1","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120869/?view=embed","pType":"listen_passage","probTitle":"Buildings and Places: recording 1","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset_3.mp3","youtubeId":"","subs":[{"time":0,"en":"Good morning, how can I help you?","vi":"Chào buổi sáng, tôi có thể giúp gì cho bạn?"},{"time":3840,"en":"Hello, I'd like some information about your facilities.","vi":"Chào bạn, tôi muốn biết thêm thông tin về các tiện nghi của các bạn."},{"time":8080,"en":"OK, well we have a swimming pool, squash courts, a gym and we have a couple of outdoor tennis courts too.","vi":"Được thôi, chúng tôi có một hồ bơi, sân chơi squash, một phòng gym và chúng tôi cũng có một vài sân tennis ngoài trời."},{"time":15420,"en":"You may have seen them on the left as you came in.","vi":"Bạn có thể đã thấy chúng ở bên trái khi bạn đi vào."},{"time":18020,"en":"Now, our website tells you how you can become a member and how much the yearly fee is.","vi":"Trang web của chúng tôi sẽ cho bạn biết cách bạn có thể trở thành thành viên và phí hàng năm là bao nhiêu."},{"time":23660,"en":"Do you want to make a note of the address?","vi":"Bạn có muốn ghi lại địa chỉ không?"},{"time":26520,"en":"Oh, yes please. I'll just put it on my phone now.","vi":"Ồ, có chứ. Tôi sẽ nhập nó vào điện thoại của tôi ngay bây giờ."},{"time":30400,"en":"OK, it's W W W dot getactive dot com. That's G-E-T-A-C-T-I-V-E dot com.","vi":"Được rồi, đó là W W W chấm getactive chấm com. Đó là G-E-T-A-C-T-I-V-E chấm com."},{"time":42780,"en":"'Get active' - is that all one word?","vi":"'Get active' - là một từ duy nhất phải không?"},{"time":45880,"en":"Yes, that's right.","vi":"Đúng vậy."},{"time":47300,"en":"OK, I've got that. Thanks very much for your help.","vi":"OK, tôi đã ghi lại rồi. Cảm ơn bạn rất nhiều vì sự giúp đỡ."}]}},{"id":"listening_u3_21","title":"Buildings and Places: recording 2","actTitle":"Luyện tập: Recording 2","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120870/?view=embed","pType":"listen_passage","probTitle":"Buildings and Places: recording 2","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset_4.mp3","youtubeId":"","subs":[{"time":0,"en":"Good afternoon, can I help you?","vi":"Chào buổi chiều, tôi có thể giúp gì cho quý khách?"},{"time":3000,"en":"I'd like to open a new account, please.","vi":"Tôi muốn mở một tài khoản mới."},{"time":5560,"en":"Certainly - now, is it a basic account you're looking to open or a savings account?","vi":"Chắc chắn rồi. Quý khách muốn mở tài khoản cơ bản hay tài khoản tiết kiệm ạ?"},{"time":11060,"en":"A savings account.","vi":"Tài khoản tiết kiệm."},{"time":12540,"en":"Right, we can complete your application online.","vi":"Vâng, chúng tôi có thể hoàn tất thủ tục đăng ký trực tuyến cho quý khách."},{"time":15760,"en":"I'll just get the form up on screen now.","vi":"Tôi sẽ mở mẫu đơn trên màn hình ngay bây giờ."},{"time":18420,"en":"It won't take long.","vi":"Sẽ không mất nhiều thời gian đâu ạ."},{"time":20780,"en":"So, I just need a few personal details.","vi":"Vậy, tôi chỉ cần một vài thông tin cá nhân."},{"time":23880,"en":"Can you give me your full name, please?","vi":"Quý khách vui lòng cho biết họ tên đầy đủ được không ạ?"},{"time":26560,"en":"James Clarke.","vi":"James Clarke."},{"time":28360,"en":"Is that Clark with an `e' or without?","vi":"Clarke có chữ 'e' ở cuối hay không ạ?"},{"time":31440,"en":"It's got an `e' at the end. C-L-A-R-K-E.","vi":"Có chữ 'e' ở cuối. C-L-A-R-K-E."},{"time":34980,"en":"And where do you live? What's your address?","vi":"Địa chỉ nhà của quý khách ở đâu ạ?"},{"time":38900,"en":"2 Waddington Road.","vi":"Số 2, đường Waddington."},{"time":40820,"en":"Can you spell that for me?","vi":"Quý khách có thể đánh vần giúp tôi được không ạ?"},{"time":42900,"en":"That's W-A-D-D-I-N-G-T-O-N Road.","vi":"Là W-A-D-D-I-N-G-T-O-N Road."},{"time":49680,"en":"Is that Waddington with a double D, did you say? That's right.","vi":"Waddington có phải là hai chữ D không ạ? Đúng vậy."},{"time":54140,"en":"OK, so I just need a little more information about ...","vi":"Được rồi, tôi chỉ cần thêm một chút thông tin về..."}]}},{"id":"listening_u3_22","title":"Buildings and Places: recording 3","actTitle":"Luyện tập: Recording 3","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120871/?view=embed","pType":"listen_passage","probTitle":"Buildings and Places: recording 3","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset_5.mp3","youtubeId":"","subs":[{"time":0,"en":"Hi, Leila! Where are you? We need to leave for the party soon.","vi":"Chào Leila! Bạn đang ở đâu vậy? Chúng ta cần phải đi dự tiệc sớm thôi."},{"time":10880,"en":"I'm on my way home - I'm still waiting for the bus.","vi":"Tớ đang trên đường về nhà đây - vẫn còn đang đợi xe buýt."},{"time":14780,"en":"I was going to get a taxi back but I've just checked my phone and there's a bus due in about 15 minutes - 7.50 pm to be exact.","vi":"Tớ định bắt taxi về nhưng vừa kiểm tra điện thoại thì thấy có một chuyến xe buýt sắp đến trong khoảng 15 phút nữa - chính xác là 7:50 tối."},{"time":23280,"en":"And it seems to be running on time.","vi":"Và có vẻ như xe đang chạy đúng giờ."},{"time":25580,"en":"It left the railway station a couple of minutes ago, so it's not too far away.","vi":"Xe vừa rời khỏi nhà ga vài phút trước, nên chắc không còn xa nữa đâu."},{"time":30320,"en":"Do you want me to pick you up? I've got the car, so it's no problem. Where's the bus stop exactly?","vi":"Bạn có muốn tớ đến đón không? Tớ có xe hơi nên không vấn đề gì. Trạm xe buýt chính xác ở đâu vậy?"},{"time":37320,"en":"It's the one on Blythe Road.","vi":"Ở trên đường Blythe."},{"time":39660,"en":"Blythe Road? I'm just checking it on my phone. Is that B-L-Y-T-H?","vi":"Đường Blythe? Tớ đang kiểm tra trên điện thoại đây. Có phải là B-L-Y-T-H không?"},{"time":48200,"en":"There's an e at the end of Blythe.","vi":"Có chữ 'e' ở cuối chữ Blythe."},{"time":50560,"en":"Got it. OK, I won't be long.","vi":"Hiểu rồi. OK, tớ đến ngay."},{"time":53560,"en":"Actually, David - no need to pick me up.","vi":"Thực ra, David - không cần đến đón tớ đâu."},{"time":56240,"en":"The traffic lights have just changed and I can see the bus coming now.","vi":"Đèn giao thông vừa chuyển và tớ thấy xe buýt đang đến rồi."},{"time":59600,"en":"I'd better go - I'll see you at home in a few minutes.","vi":"Tớ phải đi đây - gặp cậu ở nhà trong vài phút nữa."}]}},{"id":"listening_u3_23","title":"Buildings and Places: recording 4","actTitle":"Luyện tập: Recording 4","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120872/?view=embed","pType":"listen_passage","probTitle":"Buildings and Places: recording 4","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset_6.mp3","youtubeId":"","subs":[{"time":0,"en":"Hi there, Alicia!","vi":"Chào bạn, Alicia!"},{"time":2320,"en":"How was your weekend?","vi":"Cuối tuần của bạn thế nào?"},{"time":3980,"en":"You were on a sailing course down at the harbour, weren't you?","vi":"Bạn đã tham gia một khóa học chèo thuyền ở bến cảng, đúng không?"},{"time":7040,"en":"That's right - I really enjoyed breathing in all that fresh sea air.","vi":"Đúng vậy - Tôi thực sự thích hít thở không khí biển trong lành."},{"time":11540,"en":"It was only two days but the time flew by!","vi":"Chỉ có hai ngày thôi mà thời gian trôi nhanh quá!"},{"time":15820,"en":"The instructor began by teaching us safety rules, which was necessary, but not very exciting.","vi":"Người hướng dẫn bắt đầu bằng cách dạy chúng tôi các quy tắc an toàn, điều này là cần thiết, nhưng không thú vị lắm."},{"time":22960,"en":"But then on the first morning we learnt how to open the sails and I even learnt how to turn the boat.","vi":"Nhưng sau đó vào buổi sáng đầu tiên, chúng tôi đã học cách mở cánh buồm và tôi thậm chí còn học được cách điều khiển thuyền."},{"time":30240,"en":"The water wasn't as calm as it looked, I can tell you - I lost my balance a few times!","vi":"Nước không tĩnh lặng như vẻ ngoài của nó đâu, tôi nói thật đấy - Tôi đã mất thăng bằng vài lần!"},{"time":36460,"en":"Sounds like you had a lot of fun. I'd love to learn to sail.","vi":"Nghe có vẻ bạn đã có rất nhiều niềm vui. Tôi rất muốn học chèo thuyền."},{"time":40380,"en":"Well, there are plenty of courses and I think they run them once a month - so just let me check the website here.","vi":"À, có rất nhiều khóa học và tôi nghĩ họ tổ chức chúng mỗi tháng một lần - để tôi kiểm tra trang web ở đây."},{"time":49140,"en":"OK, so this was my course here - see -4th and 5th of August.","vi":"OK, đây là khóa học của tôi này - xem này - ngày 4 và 5 tháng 8."},{"time":55940,"en":"Now you could sign up for the next one, at the beginning of September.","vi":"Bây giờ bạn có thể đăng ký khóa tiếp theo, vào đầu tháng 9."},{"time":60860,"en":"And it looks like there are still some spaces available.","vi":"Và có vẻ như vẫn còn một vài chỗ trống."},{"time":64060,"en":"So, the next one starts on 1st of September? I think I could do that.","vi":"Vậy, khóa tiếp theo bắt đầu vào ngày 1 tháng 9? Tôi nghĩ là tôi có thể tham gia."},{"time":69120,"en":"Well, let me give you the name of the course leader so that you","vi":"Được rồi, để tôi cho bạn tên của người phụ trách khóa học để bạn"},{"time":72680,"en":"can give him a call. He's a really experienced sailor ... OK, it's Jon Galloway.","vi":"có thể gọi cho anh ấy. Anh ấy là một người chèo thuyền rất giàu kinh nghiệm ... OK, là Jon Galloway."},{"time":78820,"en":"Is that the usual spelling of John?","vi":"Đó có phải là cách viết thông thường của John không?"},{"time":81160,"en":"No, there's no 'H' - he's just J-O-N.","vi":"Không, không có chữ 'H' - anh ấy chỉ viết là J-O-N."},{"time":85340,"en":"OK, got you. And did you say his surname's Galloway? Can you spell that for me?","vi":"OK, tôi hiểu rồi. Và bạn nói họ của anh ấy là Galloway phải không? Bạn có thể đánh vần nó cho tôi được không?"},{"time":91460,"en":"Yes - Galloway - that's G-A-L-L-O-W-A-Y. And I've got his number too. Why don't you give him a ring?","vi":"Vâng - Galloway - đó là G-A-L-L-O-W-A-Y. Và tôi cũng có số của anh ấy. Sao bạn không gọi cho anh ấy?"}]}},{"id":"listening_u3_24","title":"Buildings and Places: recording 5","actTitle":"Luyện tập: Recording 5","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120873/?view=embed","pType":"listen_passage","probTitle":"Buildings and Places: recording 5","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset_7.mp3","youtubeId":"","subs":[{"time":0,"en":"So, how's your very first week at university going, Rita?","vi":"Rita, tuần đầu tiên của bạn ở trường đại học thế nào rồi?"},{"time":5400,"en":"It's Orientation Week for all you new students, isn't it?","vi":"Đây là Tuần lễ Định hướng cho tất cả sinh viên mới phải không?"},{"time":9380,"en":"Yes, that's right - Orientation Week.","vi":"Vâng, đúng vậy - Tuần lễ Định hướng."},{"time":13080,"en":"Yes, it's great fun - there are so many different events going on to help us make friends and find our way around the university.","vi":"Vâng, rất vui - có rất nhiều sự kiện khác nhau diễn ra để giúp chúng tôi kết bạn và tìm đường trong trường đại học."},{"time":21600,"en":"And to get around the city, come to that!","vi":"Và để đi lại trong thành phố nữa chứ!"},{"time":24760,"en":"But you'll remember all that, Jon.","vi":"Nhưng Jon, bạn sẽ nhớ tất cả những điều đó thôi."},{"time":26980,"en":"You were a new student once!","vi":"Bạn cũng từng là sinh viên mới mà!"},{"time":28920,"en":"That's true.","vi":"Đúng vậy."},{"time":30280,"en":"I remember I went on a walking tour of the city on my first day.","vi":"Tôi nhớ là tôi đã tham gia một chuyến đi bộ quanh thành phố vào ngày đầu tiên."},{"time":35080,"en":"And I think some students did a bus tour.","vi":"Và tôi nghĩ một số sinh viên đã đi tour bằng xe buýt."},{"time":38440,"en":"Well, I did a bike tour - I was sent an email about it and I decided to sign up.","vi":"Chà, tôi đã đi tour bằng xe đạp - tôi đã nhận được một email về nó và tôi quyết định đăng ký."},{"time":45360,"en":"There were only eight places and there were seven other names on the list already, so I got the very last place.","vi":"Chỉ có tám chỗ và đã có bảy tên khác trong danh sách rồi, vì vậy tôi đã có được chỗ cuối cùng."},{"time":52080,"en":"I didn't know you had a bike.","vi":"Tôi không biết bạn có xe đạp."},{"time":53960,"en":"I don't have a bike but that didn't matter.","vi":"Tôi không có xe đạp nhưng điều đó không thành vấn đề."},{"time":56860,"en":"We all hired them - from a little cycle hire shop on Barkway Street.","vi":"Tất cả chúng tôi đã thuê xe - từ một cửa hàng cho thuê xe đạp nhỏ trên đường Barkway."},{"time":61780,"en":"You probably know the place.","vi":"Chắc hẳn bạn biết chỗ đó."},{"time":63980,"en":"Barclay Street?","vi":"Đường Barclay à?"},{"time":65880,"en":"Do you mean the 'Barclay Street' on campus?","vi":"Ý bạn là 'Đường Barclay' trong khuôn viên trường à?"},{"time":68760,"en":"No, it's Barkway Street - B-A-R-K-W-A-Y.","vi":"Không, là đường Barkway - B-A-R-K-W-A-Y."},{"time":75880,"en":"Number 22 Barkway Street, to be exact.","vi":"Chính xác là số 22 đường Barkway."},{"time":79300,"en":"It was great - we could choose a traditional bike or an electric one.","vi":"Tuyệt lắm - chúng tôi có thể chọn xe đạp truyền thống hoặc xe đạp điện."},{"time":83940,"en":"So I take it you went electric!","vi":"Vậy tôi đoán bạn đã chọn xe điện!"},{"time":87480,"en":"Yes, of course I did!","vi":"Vâng, tất nhiên là tôi chọn xe điện rồi!"},{"time":89860,"en":"Well, think about it - why ride a traditional bike when you can get around the city much faster on an electric one!","vi":"Thì cứ nghĩ mà xem - tại sao lại đi xe đạp truyền thống khi bạn có thể đi quanh thành phố nhanh hơn nhiều bằng xe đạp điện!"},{"time":96740,"en":"And because there was a group of us, it wasn't too expensive.","vi":"Và vì có một nhóm chúng tôi, nên nó không quá đắt."},{"time":101800,"en":"In fact the cycle hire was only a $120 for the whole group.","vi":"Trên thực tế, tiền thuê xe đạp chỉ có 120 đô la cho cả nhóm."},{"time":106540,"en":"So the cost was only $15 per person and that was for three whole hours!","vi":"Vì vậy, chi phí chỉ là 15 đô la mỗi người và đó là cho ba tiếng đồng hồ!"},{"time":111880,"en":"Did you say $50?","vi":"Bạn nói 50 đô la à?"},{"time":113680,"en":"No, $15.","vi":"Không, 15 đô la."},{"time":115820,"en":"So I thought it was really quite cheap.","vi":"Vì vậy, tôi nghĩ nó thực sự khá rẻ."},{"time":118660,"en":"And I didn't have to bring along a helmet to wear either.","vi":"Và tôi cũng không phải mang theo mũ bảo hiểm để đội."},{"time":121520,"en":"That was included - and we also got a lock, so it was easy to park our bikes safely when we wanted to stop and take a break!","vi":"Mũ đã được bao gồm - và chúng tôi cũng có một ổ khóa, vì vậy rất dễ dàng để đỗ xe đạp an toàn khi chúng tôi muốn dừng lại và nghỉ ngơi!"},{"time":130080,"en":"Sounds good.","vi":"Nghe hay đấy."},{"time":131340,"en":"Have you got the website address of the place you got your bike from?","vi":"Bạn có địa chỉ trang web của nơi bạn thuê xe đạp không?"},{"time":135060,"en":"I quite like the idea of doing a bike tour.","vi":"Tôi khá thích ý tưởng đi tour bằng xe đạp."},{"time":138540,"en":"Yes - it's a really easy one to remember. It's tradelectric.com","vi":"Có, rất dễ nhớ. Đó là tradelectric.com"},{"time":144260,"en":"Can you say that again?","vi":"Bạn có thể nói lại được không?"},{"time":146080,"en":"tradelectric - T-R-A-D-E-L-E-C-T-R-I-C all one word dot com. Thanks, Rita.","vi":"tradelectric - T-R-A-D-E-L-E-C-T-R-I-C, tất cả là một từ, chấm com. Cảm ơn, Rita."},{"time":156760,"en":"No problem.","vi":"Không có gì."},{"time":158880,"en":"Hey, maybe we can do a bike tour together.","vi":"Này, có lẽ chúng ta có thể cùng nhau đi tour bằng xe đạp."},{"time":163120,"en":"I'd love to cycle as far as the harbour next time.","vi":"Lần tới tôi rất muốn đạp xe đến tận bến cảng."},{"time":166000,"en":"Great! That's a date then!","vi":"Tuyệt vời! Vậy là có hẹn nhé!"}]}},{"id":"listening_u3_25","title":"School and Jobs: recording 1","actTitle":"Luyện tập: Recording 1","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120874/?view=embed","pType":"listen_passage","probTitle":"School and Jobs: recording 1","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset_8.mp3","youtubeId":"","subs":[{"time":0,"en":"Come on in. It's Anna, isn't it?","vi":"Mời vào. Bạn là Anna, đúng không?"},{"time":2880,"en":"Yes, that's right. Anna Scott.","vi":"Vâng, đúng vậy. Anna Scott."},{"time":5680,"en":"Ah yes.","vi":"À vâng."},{"time":6460,"en":"Take a seat, Anna.","vi":"Mời ngồi, Anna."},{"time":8380,"en":"First of all, we're delighted that you'll be joining us as a store assistant at the beginning of next week.","vi":"Trước hết, chúng tôi rất vui vì bạn sẽ gia nhập với chúng tôi với vai trò trợ lý cửa hàng vào đầu tuần tới."},{"time":13840,"en":"Thanks very much.","vi":"Cảm ơn rất nhiều."},{"time":15340,"en":"I'm really looking forward to the challenge.","vi":"Tôi thực sự mong chờ thử thách này."},{"time":17860,"en":"That's good to know.","vi":"Thật tốt khi biết điều đó."},{"time":19380,"en":"Now, we know you've just finished a course in Information Technology, so we've decided to put you in the computing and phones section of our department store.","vi":"Chúng tôi biết bạn vừa hoàn thành khóa học về Công nghệ Thông tin, vì vậy chúng tôi đã quyết định bố trí bạn vào khu vực máy tính và điện thoại của cửa hàng chúng tôi."},{"time":29720,"en":"That's great.","vi":"Tuyệt vời."},{"time":31060,"en":"Now, that's next to the radios and audio equipment, isn't it?","vi":"Khu đó nằm cạnh khu vực radio và thiết bị âm thanh, đúng không?"},{"time":35200,"en":"That's right.","vi":"Đúng vậy."},{"time":36400,"en":"All our radios and audio are in a part of the store we used to call the 'Sound Station'.","vi":"Tất cả radio và thiết bị âm thanh của chúng tôi đều nằm trong khu vực mà chúng tôi từng gọi là 'Trạm Âm Thanh'."},{"time":42380,"en":"But as I've just said, you'll be based in the computing and phones section.","vi":"Nhưng như tôi vừa nói, bạn sẽ làm việc tại khu vực máy tính và điện thoại."},{"time":47620,"en":"Now we've recently made this area of our store much bigger so that we can sell a much wider range of computer equipment, such as smart watches.","vi":"Gần đây chúng tôi đã mở rộng khu vực này của cửa hàng để có thể bán nhiều loại thiết bị máy tính hơn, chẳng hạn như đồng hồ thông minh."},{"time":56760,"en":"Mm. Smart watches.","vi":"Ừm. Đồng hồ thông minh."},{"time":59040,"en":"Yes, we really want to attract a younger group of customers.","vi":"Đúng vậy, chúng tôi thực sự muốn thu hút nhóm khách hàng trẻ tuổi hơn."},{"time":62960,"en":"And we haven't just given this whole area a completely new look - we've re-named it too!","vi":"Chúng tôi không chỉ mang đến cho toàn bộ khu vực này một diện mạo hoàn toàn mới - chúng tôi còn đổi tên nó nữa!"},{"time":68180,"en":"Re-named it?","vi":"Đổi tên nó?"},{"time":69620,"en":"Yes. From next week it's going to be known as 'Moving Images'.","vi":"Vâng. Từ tuần tới, nó sẽ được gọi là 'Moving Images' (Hình ảnh động)."},{"time":74000,"en":"'Moving Images'? Cool! I like it.","vi":"'Moving Images'? Hay đó! Tôi thích nó."},{"time":77920,"en":"Now, do you have any questions before we move on?","vi":"Bạn có câu hỏi nào trước khi chúng ta tiếp tục không?"}]}},{"id":"listening_u3_26","title":"School and Jobs: recording 2","actTitle":"Luyện tập: Recording 2","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120875/?view=embed","pType":"listen_passage","probTitle":"School and Jobs: recording 2","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset_9.mp3","youtubeId":"","subs":[{"time":0,"en":"Now can I just check the details of the course?","vi":"Bây giờ tôi có thể kiểm tra lại thông tin chi tiết về khóa học được không?"},{"time":3800,"en":"Sure, go ahead.","vi":"Chắc chắn rồi, cứ tự nhiên."},{"time":5440,"en":"Now it says on the leaflet ... um, let me find it ... OK, got it!","vi":"Để xem tờ rơi ghi gì nào...ờm, để tôi tìm...OK, thấy rồi!"},{"time":12160,"en":"Right, so it's called Food Photography, and I've got here that it begins at nine thirty.","vi":"Được rồi, vậy là khóa học có tên là Nhiếp ảnh ẩm thực, và tôi thấy ở đây là nó bắt đầu lúc chín giờ ba mươi."},{"time":19260,"en":"That's right - it's an early start.","vi":"Đúng vậy - là một sự khởi đầu sớm."},{"time":22040,"en":"It begins at half past nine and it goes on until four thirty.","vi":"Nó bắt đầu lúc chín giờ rưỡi và kéo dài đến bốn giờ rưỡi."},{"time":27160,"en":"Most of our weekend courses are quite short and so they're over in a couple of hours - this course is longer.","vi":"Hầu hết các khóa học cuối tuần của chúng tôi khá ngắn và kết thúc sau vài giờ - khóa học này thì dài hơn."},{"time":34600,"en":"According to the information I've got up here on screen, it's seven hours long.","vi":"Theo thông tin tôi có trên màn hình, khóa học dài bảy tiếng."},{"time":39740,"en":"Oh, I'm glad it lasts for more than a few hours.","vi":"Ồ, tôi rất vui vì nó kéo dài hơn vài tiếng."},{"time":43360,"en":"I don't think I'd be able to learn how to take good pictures in less than seven hours.","vi":"Tôi không nghĩ mình có thể học cách chụp ảnh đẹp trong vòng chưa đến bảy tiếng."},{"time":48500,"en":"Now, I'll just give you a bit more information about the course itself.","vi":"Bây giờ, tôi sẽ cung cấp cho bạn thêm một chút thông tin về bản thân khóa học."},{"time":53380,"en":"Basically, you'll learn how to take good photos of food using a digital camera.","vi":"Về cơ bản, bạn sẽ học cách chụp ảnh đồ ăn đẹp bằng máy ảnh kỹ thuật số."},{"time":59580,"en":"So it'll train you in the basics of using a range of camera angles.","vi":"Vì vậy, nó sẽ huấn luyện bạn những điều cơ bản về sử dụng các góc máy khác nhau."},{"time":63460,"en":"Camera angles?","vi":"Góc máy ảnh?"},{"time":65540,"en":"Yes, you'll learn how to photograph food using close-up shots, wide-angle shots and shots taken from above, that sort of thing.","vi":"Đúng vậy, bạn sẽ học cách chụp ảnh đồ ăn bằng cách sử dụng các bức ảnh cận cảnh, ảnh góc rộng và ảnh chụp từ trên cao, những thứ kiểu như vậy."},{"time":74900,"en":"What about learning to edit pictures on my computer? Will that be covered too?","vi":"Vậy còn việc học chỉnh sửa ảnh trên máy tính của tôi thì sao? Nó có được đề cập đến không?"},{"time":79800,"en":"No, I'm afraid not.","vi":"Không, tôi e là không."},{"time":81820,"en":"The purpose of the workshop is to teach you how to take good photos in the first place.","vi":"Mục đích của buổi workshop là dạy bạn cách chụp ảnh đẹp ngay từ đầu."},{"time":86860,"en":"It's a really hands-on session - in fact, you'll spend some of the day on location in a local hotel.","vi":"Đây là một buổi học thực hành thực tế - trên thực tế, bạn sẽ dành một phần thời gian trong ngày tại một địa điểm ở một khách sạn địa phương."},{"time":94120,"en":"It's just round the corner from the college - the Lincoln Hotel - so you'll have the opportunity to practise taking photographs using real dishes!","vi":"Nó chỉ cách trường một đoạn ngắn - Khách sạn Lincoln - vì vậy bạn sẽ có cơ hội thực hành chụp ảnh bằng các món ăn thật!"},{"time":103080,"en":"That's great - a practical course is exactly what I'm looking for!","vi":"Tuyệt vời - một khóa học thực hành chính xác là những gì tôi đang tìm kiếm!"},{"time":107960,"en":"Now just a few more things.","vi":"Bây giờ chỉ còn một vài điều nữa."},{"time":110500,"en":"The full fee for the course is $55 and that includes a light lunch and refreshments at the hotel.","vi":"Toàn bộ học phí cho khóa học là 55 đô la và bao gồm một bữa trưa nhẹ và đồ ăn thức uống tại khách sạn."},{"time":118240,"en":"Oh, that's really good.","vi":"Ồ, điều đó thực sự tốt."},{"time":120480,"en":"That means I don't have to worry about bringing along my own drinks and snacks on the day.","vi":"Điều đó có nghĩa là tôi không phải lo lắng về việc mang theo đồ uống và đồ ăn nhẹ của riêng mình vào ngày hôm đó."},{"time":125100,"en":"That would probably cost me at least $10.","vi":"Điều đó có lẽ sẽ tốn của tôi ít nhất 10 đô la."},{"time":128400,"en":"OK, I think that's everything, so I'll just take your details so that we can confirm your place on the course.","vi":"OK, tôi nghĩ đó là tất cả, vì vậy tôi sẽ lấy thông tin chi tiết của bạn để chúng tôi có thể xác nhận vị trí của bạn trong khóa học."}]}},{"id":"listening_u3_27","title":"Eating and Drinking: recording 1","actTitle":"Luyện tập: Recording 1","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120876/?view=embed","pType":"listen_passage","probTitle":"Eating and Drinking: recording 1","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset_10.mp3","youtubeId":"","subs":[{"time":0,"en":"In this new series of 'Talk of the Town' we'll be looking at the different restaurants in and around Ogdenville and getting some tips and recommendations from our resident food critic, Chris Griffin.","vi":"Trong loạt chương trình mới 'Chuyện phố phường' này, chúng ta sẽ khám phá các nhà hàng khác nhau ở trong và xung quanh Ogdenville, đồng thời nhận được một vài lời khuyên và gợi ý từ nhà phê bình ẩm thực thường trú của chúng ta, Chris Griffin."},{"time":13980,"en":"So Chris, where have you been this week?","vi":"Vậy Chris, tuần này anh đã đi đâu?"},{"time":16940,"en":"Well, one restaurant that I really enjoyed is Adam's.","vi":"Chà, một nhà hàng mà tôi rất thích là Adam's."},{"time":20440,"en":"It's on the Town Square.","vi":"Nó nằm ở quảng trường thị trấn."},{"time":22200,"en":"I ordered a steak au poivre and it was perfect.","vi":"Tôi đã gọi món bít tết tiêu và nó thật hoàn hảo."},{"time":25380,"en":"What's that?","vi":"Món đó là gì vậy?"},{"time":26480,"en":"It's a steak in peppercorns - it's quite a typical French dish.","vi":"Đó là món bít tết rắc tiêu - một món ăn khá điển hình của Pháp."},{"time":30560,"en":"So, is it a French restaurant or a steakhouse?","vi":"Vậy, đó là một nhà hàng Pháp hay một quán bít tết?"},{"time":34080,"en":"Well, the chef is French, but it serves food from all over the world.","vi":"Chà, đầu bếp là người Pháp, nhưng nhà hàng phục vụ các món ăn từ khắp nơi trên thế giới."},{"time":38420,"en":"It has a wide variety of dishes.","vi":"Nó có rất nhiều món ăn đa dạng."},{"time":41180,"en":"One word of warning though, it gets really busy at weekends, so you should check they have places before you go.","vi":"Tuy nhiên, có một điều cần lưu ý là, vào cuối tuần quán rất đông khách, vì vậy bạn nên kiểm tra xem họ còn chỗ trước khi đến."},{"time":48480,"en":"Have you got any other recommendations for us this week, Chris?","vi":"Anh có bất kỳ gợi ý nào khác cho chúng tôi trong tuần này không, Chris?"},{"time":51940,"en":"Oh, yes.","vi":"Ồ, có chứ."},{"time":52900,"en":"I can really recommend the Duke on Smith Street.","vi":"Tôi thực sự có thể giới thiệu Duke trên đường Smith."},{"time":56380,"en":"I had lobster and it was really tasty.","vi":"Tôi đã ăn tôm hùm và nó thực sự rất ngon."},{"time":59560,"en":"It also has a few vegetarian dishes, but it's the fish dishes that make it famous in the town.","vi":"Nó cũng có một vài món chay, nhưng chính các món cá đã làm nên sự nổi tiếng của nó trong thị trấn."},{"time":66100,"en":"The food isn't that low-cost though, so you might want to save going here for a special treat.","vi":"Tuy nhiên, đồ ăn ở đó không hề rẻ, vì vậy bạn có thể muốn để dành đến đây cho một dịp đặc biệt."},{"time":72200,"en":"What about people who are on a budget? Have you got any suggestions for them?","vi":"Còn những người có ngân sách eo hẹp thì sao? Anh có gợi ý nào cho họ không?"},{"time":77580,"en":"Yes, I have.","vi":"Có, tôi có."},{"time":78880,"en":"The Tower in Market Street is a fashionable restaurant where people can get a good meal at a reasonable price.","vi":"The Tower trên đường Market là một nhà hàng hợp thời trang, nơi mọi người có thể có một bữa ăn ngon với giá cả hợp lý."},{"time":86120,"en":"I had a pizza, but it isn't a fast food restaurant, it specialises in all different types of food from Italy.","vi":"Tôi đã ăn pizza, nhưng nó không phải là một nhà hàng thức ăn nhanh, nó chuyên về tất cả các loại thực phẩm khác nhau từ Ý."},{"time":93980,"en":"I've heard that the lasagne is especially good.","vi":"Tôi nghe nói rằng món lasagne ở đó đặc biệt ngon."},{"time":96940,"en":"Thanks, Chris. You certainly have given us all food for thought.","vi":"Cảm ơn, Chris. Anh chắc chắn đã cho chúng tôi rất nhiều điều đáng để suy ngẫm về ẩm thực."}]}},{"id":"listening_u3_28","title":"Eating and Drinking: recording 2","actTitle":"Luyện tập: Recording 2","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120877/?view=embed","pType":"listen_passage","probTitle":"Eating and Drinking: recording 2","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset_11.mp3","youtubeId":"","subs":[{"time":0,"en":"I suppose one thing that everybody knows about Japanese, Chinese and Korean cooking is that they all use chopsticks rather than knives and forks like people in the West.","vi":"Tôi cho rằng một điều mà mọi người đều biết về ẩm thực Nhật Bản, Trung Quốc và Hàn Quốc là họ đều sử dụng đũa thay vì dao và nĩa như người phương Tây."},{"time":11320,"en":"The chopsticks that people use in the different countries are quite different though.","vi":"Tuy nhiên, đũa mà mọi người sử dụng ở các quốc gia khác nhau lại khá khác nhau."},{"time":16340,"en":"In China the chopsticks tend to be made of wood and are round at the end, whereas in Korea they're made of stainless steel and are rough at the end.","vi":"Ở Trung Quốc, đũa thường được làm bằng gỗ và có đầu tròn, trong khi ở Hàn Quốc, chúng được làm bằng thép không gỉ và có đầu nhám."},{"time":25540,"en":"This is because in the past the emperor would","vi":"Điều này là do trong quá khứ, hoàng đế sẽ"},{"time":28620,"en":"use silver chopsticks, as they changed colour if there was any poison in the dish.","vi":"sử dụng đũa bạc, vì chúng sẽ đổi màu nếu có bất kỳ chất độc nào trong món ăn."},{"time":34240,"en":"They can be quite tricky to use, but in Korea people use a spoon to eat their rice.","vi":"Chúng có thể khá khó sử dụng, nhưng ở Hàn Quốc, mọi người dùng thìa để ăn cơm."},{"time":40280,"en":"In Japan they use a variety of things to make chopsticks.","vi":"Ở Nhật Bản, họ sử dụng nhiều loại vật liệu để làm đũa."},{"time":43900,"en":"Wood and plastic are the most popular now, but you can find bone, metal and even ivory ones.","vi":"Gỗ và nhựa là phổ biến nhất hiện nay, nhưng bạn có thể tìm thấy đũa làm bằng xương, kim loại và thậm chí cả ngà voi."},{"time":50920,"en":"If we look at the food of the different countries, it's very difficult to talk about China in general terms because it has many different cuisines.","vi":"Nếu chúng ta xem xét ẩm thực của các quốc gia khác nhau, thì rất khó để nói về Trung Quốc một cách chung chung vì nó có nhiều nền ẩm thực khác nhau."},{"time":59420,"en":"So it might be better if we look at Korean and Japanese food a little more.","vi":"Vì vậy, có lẽ tốt hơn nếu chúng ta xem xét kỹ hơn một chút về ẩm thực Hàn Quốc và Nhật Bản."},{"time":64200,"en":"It's well known that Koreans tend to like spicier food and red peppers can be found in a wide number of dishes.","vi":"Ai cũng biết rằng người Hàn Quốc có xu hướng thích đồ ăn cay hơn và ớt đỏ có thể được tìm thấy trong rất nhiều món ăn."},{"time":71520,"en":"I suppose that everybody thinks of sushi when they think of Japanese food, but you can also find a lot of influences from all over Asia and even Europe, for example tempura, which came to Japan from Portugal.","vi":"Tôi cho rằng mọi người đều nghĩ đến sushi khi họ nghĩ về món ăn Nhật Bản, nhưng bạn cũng có thể tìm thấy rất nhiều ảnh hưởng từ khắp châu Á và thậm chí cả châu Âu, ví dụ như tempura, món ăn đến Nhật Bản từ Bồ Đào Nha."},{"time":85600,"en":"Those aren't present in Chinese and Korean food.","vi":"Những món đó không có trong ẩm thực Trung Quốc và Hàn Quốc."},{"time":88220,"en":"Traditionally, in both Japan and in Korea meat plays less of an important role than in Europe, perhaps because it's so expensive due to the lack of space for keeping animals.","vi":"Theo truyền thống, ở cả Nhật Bản và Hàn Quốc, thịt đóng vai trò ít quan trọng hơn so với ở châu Âu, có lẽ vì nó rất đắt do thiếu không gian để nuôi động vật."},{"time":100100,"en":"That said, both the Japanese and Koreans enjoy meat.","vi":"Tuy nhiên, cả người Nhật và người Hàn Quốc đều thích thịt."},{"time":104540,"en":"Barbecues of all types are popular in Korea and beef forms the basis of many special meals in both of the countries.","vi":"Các loại hình thịt nướng rất phổ biến ở Hàn Quốc và thịt bò là cơ sở của nhiều bữa ăn đặc biệt ở cả hai nước."},{"time":112480,"en":"Now moving back to Chinese cuisine ...","vi":"Bây giờ chúng ta quay trở lại với ẩm thực Trung Quốc ..."}]}},{"id":"listening_u3_29","title":"Eating and Drinking: recording 3","actTitle":"Luyện tập: Recording 3","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120878/?view=embed","pType":"listen_passage","probTitle":"Eating and Drinking: recording 3","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset_12.mp3","youtubeId":"","subs":[{"time":0,"en":"Today in the studio I am pleased to have with me the famous chef, Graham Shepherd.","vi":"Hôm nay tại trường quay, tôi rất vui được giới thiệu bếp trưởng nổi tiếng Graham Shepherd."},{"time":6280,"en":"Graham has just come back from Beijing in China, where he was making a TV programme on the food you can try in this historic city.","vi":"Graham vừa trở về từ Bắc Kinh, Trung Quốc, nơi ông đang thực hiện một chương trình truyền hình về những món ăn bạn có thể thử ở thành phố cổ kính này."},{"time":15820,"en":"So, Graham, what can you tell us about your trip?","vi":"Vậy, Graham, anh có thể kể cho chúng tôi nghe về chuyến đi của anh được không?"},{"time":19460,"en":"Was it how you expected it to be?","vi":"Chuyến đi có như anh mong đợi không?"},{"time":21140,"en":"It was quite surprising really.","vi":"Thực sự khá bất ngờ."},{"time":23800,"en":"I suppose that most people think of Beijing duck when they think of Beijing and I did try some of this tasty traditional dish, but with so many people from all over the country living in Beijing there really are a lot of different foods from all regions of the country.","vi":"Tôi cho rằng hầu hết mọi người nghĩ đến vịt quay Bắc Kinh khi nghĩ về Bắc Kinh và tôi đã thử món ăn truyền thống ngon miệng này, nhưng với rất nhiều người từ khắp đất nước sống ở Bắc Kinh, thực sự có rất nhiều món ăn khác nhau từ khắp các vùng miền của đất nước."},{"time":38480,"en":"One dish that I really enjoyed and I didn't expect to find was kebabs.","vi":"Một món ăn mà tôi thực sự thích và tôi không ngờ lại tìm thấy là món kebab."},{"time":42640,"en":"These tasty snacks are originally from north-west China, but they're very popular street food in Beijing.","vi":"Những món ăn nhẹ ngon miệng này có nguồn gốc từ tây bắc Trung Quốc, nhưng chúng là món ăn đường phố rất phổ biến ở Bắc Kinh."},{"time":49540,"en":"They're especially popular as a tasty snack at lunchtime for school pupils.","vi":"Chúng đặc biệt phổ biến như một món ăn nhẹ ngon miệng vào bữa trưa cho học sinh."},{"time":53900,"en":"They have less meat and more vegetables than we are used to, so they're a bit healthier.","vi":"Chúng có ít thịt và nhiều rau hơn so với chúng ta thường ăn, vì vậy chúng tốt cho sức khỏe hơn một chút."},{"time":58840,"en":"I'm sure that most people have tried kebabs, but did you try anything that might be unusual for our listeners?","vi":"Tôi chắc rằng hầu hết mọi người đã thử kebab, nhưng anh có thử món gì khác thường cho khán giả của chúng tôi không?"},{"time":65720,"en":"Oh, yes.","vi":"Ồ, có chứ."},{"time":66720,"en":"One of the things that I had was jellyfish.","vi":"Một trong những thứ tôi đã ăn là sứa."},{"time":69500,"en":"It added a nice texture to the dish, but I thought it didn't taste of much.","vi":"Nó tạo thêm một kết cấu thú vị cho món ăn, nhưng tôi nghĩ nó không có nhiều hương vị."},{"time":74040,"en":"One dish that did have a strong taste was hotpot.","vi":"Một món ăn có hương vị đậm đà là lẩu."},{"time":77220,"en":"The dish I had was made in the Sichuan style, so it was very spicy.","vi":"Món tôi ăn được chế biến theo kiểu Tứ Xuyên, vì vậy nó rất cay."},{"time":82580,"en":"What I found interesting was that the hotpot was put on a hotplate in the centre of the table, and we were given a dish of raw food and we chose what we wanted and put it into the pot ourselves, and got it out when it was ready.","vi":"Điều tôi thấy thú vị là nồi lẩu được đặt trên một bếp điện ở giữa bàn, và chúng tôi được phát một đĩa thức ăn sống và chúng tôi chọn những gì mình muốn, tự cho vào nồi và gắp ra khi chín."},{"time":95120,"en":"It was great fun and very sociable.","vi":"Thật là thú vị và rất dễ hòa đồng."},{"time":97720,"en":"And very tasty!","vi":"Và rất ngon!"},{"time":99500,"en":"I'm sure that you tried some of the dishes that we all know and love too.","vi":"Tôi chắc rằng anh cũng đã thử một số món ăn mà tất cả chúng ta đều biết và yêu thích."},{"time":103520,"en":"Can you tell us something interesting about them?","vi":"Anh có thể kể cho chúng tôi nghe điều gì thú vị về chúng không?"},{"time":106160,"en":"Of course, everybody knows about noodles and dumplings, but I doubt many people know how many different types there are!","vi":"Tất nhiên, mọi người đều biết về mì và sủi cảo, nhưng tôi nghi ngờ có nhiều người biết có bao nhiêu loại khác nhau!"},{"time":112900,"en":"One of the highlights for me was learning how to make fresh noodles with a chef from Northern China.","vi":"Một trong những điểm nổi bật đối với tôi là học cách làm mì tươi với một đầu bếp từ miền Bắc Trung Quốc."},{"time":118240,"en":"The recipe of egg, salt and wheat flour is quite simple, but to make the noodles by hand you need to be quite a skilful chef.","vi":"Công thức gồm trứng, muối và bột mì khá đơn giản, nhưng để làm mì bằng tay, bạn cần phải là một đầu bếp khéo léo."},{"time":126120,"en":"Something which is much simpler to make are dumplings.","vi":"Một thứ dễ làm hơn nhiều là sủi cảo."},{"time":129100,"en":"The basic ingredients are flour and water, but the beauty of this dish is that it's very flexible.","vi":"Các thành phần cơ bản là bột mì và nước, nhưng vẻ đẹp của món ăn này là nó rất linh hoạt."},{"time":134780,"en":"You can fill them with whatever you like.","vi":"Bạn có thể nhồi chúng với bất cứ thứ gì bạn thích."},{"time":137120,"en":"I especially enjoyed one with raw prawns, but all sorts of meat and vegetables can be put in them.","vi":"Tôi đặc biệt thích một loại có tôm sống, nhưng tất cả các loại thịt và rau đều có thể cho vào chúng."},{"time":142360,"en":"Thanks Graham, that's really interesting, but unfortunately we've run out of time.","vi":"Cảm ơn Graham, điều đó thực sự thú vị, nhưng tiếc là chúng ta đã hết thời gian."},{"time":147800,"en":"If you'd like to know more about Graham's adventures, the series will be starting on Thursday at 7 o'clock on Channel 9.","vi":"Nếu bạn muốn biết thêm về những cuộc phiêu lưu của Graham, loạt phim sẽ bắt đầu vào Thứ Năm lúc 7 giờ trên Kênh 9."}]}},{"id":"listening_u3_30","title":"Shopping and Spending: recording 1","actTitle":"Luyện tập: Recording 1","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120879/?view=embed","pType":"listen_passage","probTitle":"Shopping and Spending: recording 1","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset_13.mp3","youtubeId":"","subs":[{"time":0,"en":"Recording 1","vi":"Bản ghi âm 1"},{"time":2900,"en":"And now for the local news ... A new branch of Sports World, the Danish sporting goods company, is opening on Saturday.","vi":"Và bây giờ là phần tin tức địa phương... Một chi nhánh mới của Sports World, công ty kinh doanh đồ thể thao của Đan Mạch, sẽ khai trương vào thứ Bảy."},{"time":11840,"en":"Most of you will be familiar with the branch in the south of Grinstead that opened two years ago and which has enjoyed a lot of success.","vi":"Hầu hết các bạn sẽ quen thuộc với chi nhánh ở phía nam Grinstead đã mở cửa hai năm trước và đã đạt được rất nhiều thành công."},{"time":20260,"en":"There was talk of them opening a new store in the Meadows Shopping Centre in the north of the town, but they have finally decided to open in the east, near the football stadium.","vi":"Đã có thông tin về việc họ mở một cửa hàng mới ở Trung tâm mua sắm Meadows ở phía bắc của thị trấn, nhưng cuối cùng họ đã quyết định mở ở phía đông, gần sân vận động bóng đá."},{"time":31300,"en":"As a special treat for fans, Grinstead Town's Danish striker Jesper Nielsen will be opening the store ahead of their home match at the weekend.","vi":"Như một món quà đặc biệt dành cho người hâm mộ, tiền đạo người Đan Mạch Jesper Nielsen của Grinstead Town sẽ khai trương cửa hàng trước trận đấu trên sân nhà vào cuối tuần."},{"time":42360,"en":"Recording 2","vi":"Bản ghi âm 2"},{"time":44860,"en":"That's the end of our tour of the city, so you now have a couple of hours to spend exploring the city centre.","vi":"Đó là kết thúc chuyến tham quan thành phố của chúng ta, vì vậy bây giờ bạn có một vài giờ để khám phá trung tâm thành phố."},{"time":52060,"en":"If you want to buy souvenirs, you might find them cheaper near the hotel.","vi":"Nếu bạn muốn mua quà lưu niệm, bạn có thể tìm thấy chúng rẻ hơn gần khách sạn."},{"time":57080,"en":"However, if you're feeling a bit tired, there are plenty of tea shops nearby and they also sell boxes of tea that make really good presents.","vi":"Tuy nhiên, nếu bạn cảm thấy hơi mệt mỏi, có rất nhiều quán trà gần đó và họ cũng bán các hộp trà làm quà tặng rất tốt."},{"time":66800,"en":"A word of warning, you'll find a lot of cheap electronic stores offering cameras at really low prices.","vi":"Một lời cảnh báo, bạn sẽ tìm thấy rất nhiều cửa hàng điện tử giá rẻ cung cấp máy ảnh với giá thực sự thấp."},{"time":74240,"en":"They might seem good quality, but we've had a lot of complaints from tourists who have bought them, only to find they break after about a week.","vi":"Chúng có vẻ chất lượng tốt, nhưng chúng tôi đã nhận được rất nhiều phàn nàn từ du khách đã mua chúng, chỉ để thấy chúng bị hỏng sau khoảng một tuần."},{"time":84180,"en":"Recording 3","vi":"Bản ghi âm 3"},{"time":86680,"en":"Thank you for calling the Eastgate Shopping Centre.","vi":"Cảm ơn bạn đã gọi đến Trung tâm mua sắm Eastgate."},{"time":89680,"en":"The centre is currently closed.","vi":"Trung tâm hiện đang đóng cửa."},{"time":91940,"en":"Our opening days and times are as follows ... Monday to Saturday we are open from nine o'clock until six o'clock and on Sunday, our doors open at eleven o'clock and we close at five o'clock.","vi":"Giờ mở cửa của chúng tôi như sau... Thứ Hai đến Thứ Bảy chúng tôi mở cửa từ chín giờ đến sáu giờ và vào Chủ Nhật, chúng tôi mở cửa lúc mười một giờ và đóng cửa lúc năm giờ."},{"time":106560,"en":"Recording 4","vi":"Bản ghi âm 4"},{"time":109080,"en":"When I first opened the shop three years ago, we mainly sold shirts and jackets that I had designed, and these proved very popular.","vi":"Khi tôi mới mở cửa hàng ba năm trước, chúng tôi chủ yếu bán áo sơ mi và áo khoác do tôi thiết kế, và chúng rất được ưa chuộng."},{"time":117280,"en":"However, we added more products as the business started to grow.","vi":"Tuy nhiên, chúng tôi đã thêm nhiều sản phẩm hơn khi doanh nghiệp bắt đầu phát triển."},{"time":121400,"en":"We also started selling online.","vi":"Chúng tôi cũng bắt đầu bán hàng trực tuyến."},{"time":123600,"en":"The jackets and shirts are still really popular, especially online, but in the shop itself, we sell trousers more than any other item.","vi":"Áo khoác và áo sơ mi vẫn rất phổ biến, đặc biệt là trực tuyến, nhưng trong cửa hàng, chúng tôi bán quần dài nhiều hơn bất kỳ mặt hàng nào khác."}]}},{"id":"listening_u3_31","title":"Shopping and Spending: recording 2","actTitle":"Luyện tập: Recording 2","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120880/?view=embed","pType":"listen_passage","probTitle":"Shopping and Spending: recording 2","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset_14.mp3","youtubeId":"","subs":[{"time":0,"en":"Hello everyone.","vi":"Xin chào mọi người."},{"time":2340,"en":"So can you all hear me and see me?","vi":"Mọi người có nghe và thấy tôi rõ không ạ?"},{"time":5280,"en":"OK, my name's David Edwards and I'm your tour leader for your shopping tour today.","vi":"Được rồi, tôi là David Edwards và tôi là trưởng đoàn cho chuyến tham quan mua sắm của các bạn hôm nay."},{"time":12420,"en":"Now, as you can see, we're parked just in front of the main theatre.","vi":"Như các bạn thấy, chúng ta đang đậu ngay trước nhà hát chính."},{"time":16680,"en":"If any of you would like tickets for tonight's performance, we can arrange that for you.","vi":"Nếu ai muốn mua vé xem buổi biểu diễn tối nay, chúng tôi có thể sắp xếp giúp bạn."},{"time":21580,"en":"We're just round the corner from the railway station.","vi":"Chúng ta chỉ cách ga tàu hỏa một góc phố."},{"time":25340,"en":"If you want to come on our Historic Buildings tour tomorrow, the coach will leave from just outside the station.","vi":"Nếu bạn muốn tham gia tour tham quan Các Tòa Nhà Lịch Sử vào ngày mai, xe buýt sẽ khởi hành ngay bên ngoài nhà ga."},{"time":32880,"en":"And if you want to go for a drink at the end of our tour today, there are plenty of cafés just behind the station.","vi":"Và nếu bạn muốn đi uống nước vào cuối chuyến tham quan hôm nay, có rất nhiều quán cà phê ngay phía sau nhà ga."},{"time":40940,"en":"We're still waiting for a few people, but while we wait I can tell you a little about the theatre.","vi":"Chúng ta vẫn đang chờ một vài người, nhưng trong khi chờ đợi, tôi có thể kể cho bạn nghe một chút về nhà hát."},{"time":47460,"en":"Although the building is very modern, in fact a theatre has existed on this site for over 200 years.","vi":"Mặc dù tòa nhà rất hiện đại, nhưng thực tế là một nhà hát đã tồn tại trên địa điểm này hơn 200 năm."},{"time":55520,"en":"The original theatre used to be very popular because of the musicals it put on.","vi":"Nhà hát ban đầu rất nổi tiếng vì các vở nhạc kịch mà nó trình diễn."},{"time":60240,"en":"However, it had to be rebuilt after a fire.","vi":"Tuy nhiên, nó đã phải xây dựng lại sau một trận hỏa hoạn."},{"time":64140,"en":"Some people love the striking modern design, others hate it.","vi":"Một số người thích thiết kế hiện đại nổi bật, những người khác lại ghét nó."},{"time":69240,"en":"These days, its popularity is mainly due to the fact that it attracts a lot of well-known performers.","vi":"Ngày nay, sự nổi tiếng của nó chủ yếu là do nó thu hút rất nhiều nghệ sĩ biểu diễn nổi tiếng."},{"time":76700,"en":"Now, in a few minutes' time - at 9.30 - we'll be starting our tour.","vi":"Bây giờ, trong vài phút nữa - vào lúc 9:30 - chúng ta sẽ bắt đầu chuyến tham quan."},{"time":83340,"en":"First we're going to make our way down to Market Place, which is one of the most famous squares in the city - that should take us about ten minutes.","vi":"Đầu tiên, chúng ta sẽ đi đến Market Place, một trong những quảng trường nổi tiếng nhất trong thành phố - sẽ mất khoảng mười phút."},{"time":92780,"en":"There's not too much traffic on the roads, so we should get there at quarter to ten at the latest.","vi":"Không có quá nhiều xe cộ trên đường, vì vậy chúng ta sẽ đến đó muộn nhất là 9:45."},{"time":99640,"en":"Market Place was the city's old food market.","vi":"Market Place là chợ thực phẩm cũ của thành phố."},{"time":102460,"en":"People used to come in from the countryside to sell their fresh fruit and vegetables.","vi":"Người dân từ vùng quê thường đến đây để bán trái cây và rau quả tươi."},{"time":108400,"en":"Remember that these were the days before supermarkets!","vi":"Hãy nhớ rằng đó là những ngày trước khi có siêu thị!"},{"time":112840,"en":"You won't find any food here now though.","vi":"Tuy nhiên, bây giờ bạn sẽ không tìm thấy bất kỳ thực phẩm nào ở đây."},{"time":115480,"en":"It's now a craft market and I think you'll find lots to interest you - especially if you want to take presents home.","vi":"Bây giờ nó là một chợ thủ công và tôi nghĩ bạn sẽ tìm thấy rất nhiều điều thú vị - đặc biệt nếu bạn muốn mua quà về nhà."},{"time":123640,"en":"You'll see all kinds of things like hand-painted local pottery and leather goods.","vi":"Bạn sẽ thấy tất cả các loại đồ vật như đồ gốm địa phương vẽ tay và đồ da."},{"time":129360,"en":"Personally, I suggest that you visit the jewellery stalls.","vi":"Cá nhân tôi khuyên bạn nên ghé thăm các gian hàng trang sức."},{"time":134480,"en":"You really won't find anything like it anywhere else!","vi":"Bạn thực sự sẽ không tìm thấy bất cứ thứ gì tương tự ở bất kỳ nơi nào khác!"},{"time":138100,"en":"But if you're looking for clothes, I'm afraid you'll be disappointed.","vi":"Nhưng nếu bạn đang tìm kiếm quần áo, tôi e rằng bạn sẽ thất vọng."},{"time":143100,"en":"Wait for this afternoon's visit.","vi":"Hãy đợi đến buổi chiều nay."},{"time":146020,"en":"We'll stop at Market Place for an hour and a half and then continue the tour with a visit to the Regional Food Centre.","vi":"Chúng ta sẽ dừng lại ở Market Place trong một tiếng rưỡi và sau đó tiếp tục chuyến tham quan với chuyến thăm Trung Tâm Thực Phẩm Vùng."},{"time":154400,"en":"Here you can find over 50 types of local cheeses!","vi":"Tại đây bạn có thể tìm thấy hơn 50 loại phô mai địa phương!"},{"time":159020,"en":"There is also fresh fruit juice on sale - orange juice, peach juice, pomegranate juice, produced in the villages of the region, and local jam too.","vi":"Ngoài ra còn có bán nước ép trái cây tươi - nước cam, nước đào, nước lựu, được sản xuất tại các ngôi làng trong vùng, và cả mứt địa phương."},{"time":169960,"en":"You're welcome to buy things to take home with you, but the real reason for our visit is lunch.","vi":"Bạn có thể mua đồ mang về nhà, nhưng lý do chính cho chuyến thăm của chúng ta là bữa trưa."},{"time":175700,"en":"The idea is that you buy food and drink from the stalls and take it to eat in the lovely open-air dining area.","vi":"Ý tưởng là bạn mua đồ ăn và thức uống từ các gian hàng và mang đến ăn ở khu vực ăn uống ngoài trời xinh xắn."},{"time":184200,"en":"And finally, in the afternoon we will be visiting the Fashion Fair in the exhibition centre on the outskirts of the city.","vi":"Và cuối cùng, vào buổi chiều, chúng ta sẽ tham quan Hội chợ Thời trang trong trung tâm triển lãm ở ngoại ô thành phố."},{"time":191940,"en":"This is a huge venue, so try not to get lost.","vi":"Đây là một địa điểm rất lớn, vì vậy hãy cố gắng không bị lạc."},{"time":196800,"en":"There is a whole hall devoted just to footwear - every kind of shoes and boots you can imagine.","vi":"Có cả một hội trường dành riêng cho giày dép - tất cả các loại giày và bốt mà bạn có thể tưởng tượng."},{"time":205040,"en":"You can easily find it because it has a green roof.","vi":"Bạn có thể dễ dàng tìm thấy nó vì nó có mái màu xanh lá cây."},{"time":208500,"en":"Just don't go through the blue doors at the entrance of the centre - you have to pay for that part of the exhibition.","vi":"Chỉ cần không đi qua các cửa màu xanh lam ở lối vào trung tâm - bạn phải trả tiền cho phần đó của triển lãm."},{"time":215040,"en":"And if all that shopping has exhausted you, there's a café where you can rest your weary feet!","vi":"Và nếu tất cả việc mua sắm đó đã khiến bạn kiệt sức, thì có một quán cà phê, nơi bạn có thể nghỉ ngơi đôi chân mệt mỏi của mình!"},{"time":221700,"en":"That's in the building with a red sign.","vi":"Đó là trong tòa nhà có biển báo màu đỏ."},{"time":225080,"en":"But don't worry, I'll remind you all about that later.","vi":"Nhưng đừng lo, tôi sẽ nhắc lại cho bạn về điều đó sau."},{"time":229500,"en":"Right, everyone's here now, so, if you've all got your shopping bags, let's go!","vi":"Được rồi, mọi người đã đến đông đủ, vậy, nếu tất cả các bạn đã có túi mua sắm, thì chúng ta đi thôi!"}]}},{"id":"listening_u3_32","title":"Free Time: recording 1","actTitle":"Luyện tập: Recording 1","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120881/?view=embed","pType":"listen_passage","probTitle":"Free Time: recording 1","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset_15.mp3","youtubeId":"","subs":[{"time":0,"en":"First of all, welcome to our activity summer camp.","vi":"Lời đầu tiên, xin chào mừng đến với trại hè hoạt động của chúng tôi."},{"time":4600,"en":"I hope you enjoy all the activities we have on offer.","vi":"Tôi hy vọng bạn sẽ thích tất cả các hoạt động mà chúng tôi cung cấp."},{"time":8260,"en":"We start our tour at the outdoor theatre here, where we hold many of our evening activities.","vi":"Chúng ta bắt đầu chuyến tham quan tại nhà hát ngoài trời ở đây, nơi chúng tôi tổ chức nhiều hoạt động buổi tối."},{"time":15160,"en":"From here you can see our various water sport activities.","vi":"Từ đây bạn có thể thấy các hoạt động thể thao dưới nước khác nhau của chúng tôi."},{"time":19620,"en":"Directly in front of the campsite, on the edge of the lake, we have the kayaking centre.","vi":"Ngay phía trước khu cắm trại, trên mép hồ, chúng ta có trung tâm chèo thuyền kayak."},{"time":25900,"en":"And then in front of the beach, we have an area reserved for diving.","vi":"Và sau đó, phía trước bãi biển, chúng tôi có một khu vực dành riêng cho lặn."},{"time":30920,"en":"Swimming isn't permitted here.","vi":"Bơi lội không được phép ở đây."},{"time":33660,"en":"If you like racket sports, just behind the beach you can practise badminton in the large building.","vi":"Nếu bạn thích các môn thể thao dùng vợt, ngay phía sau bãi biển bạn có thể tập cầu lông trong tòa nhà lớn."},{"time":40420,"en":"That's quite popular in the evenings.","vi":"Hoạt động này khá phổ biến vào buổi tối."},{"time":43480,"en":"We also have some outdoor tennis courts.","vi":"Chúng tôi cũng có một vài sân tennis ngoài trời."},{"time":46640,"en":"We used to have basketball in the building too, but now you can play it on the court behind the building.","vi":"Trước đây chúng tôi cũng có bóng rổ trong tòa nhà, nhưng bây giờ bạn có thể chơi nó trên sân phía sau tòa nhà."},{"time":53560,"en":"And if these activities make you hungry, the path from there takes you straight to the café and dining hall.","vi":"Và nếu những hoạt động này khiến bạn đói, con đường từ đó sẽ dẫn bạn thẳng đến quán cà phê và nhà ăn."},{"time":60820,"en":"However, we'll continue our walk along the lake shore and I'd like to draw your attention to two other areas.","vi":"Tuy nhiên, chúng ta sẽ tiếp tục đi bộ dọc theo bờ hồ và tôi muốn bạn chú ý đến hai khu vực khác."},{"time":68620,"en":"One is this part of the lake, which is perfect for swimming, but, for safety reasons, only when an instructor is present.","vi":"Một là khu vực này của hồ, rất lý tưởng để bơi lội, nhưng vì lý do an toàn, chỉ khi có người hướng dẫn ở đó."},{"time":77780,"en":"Unfortunately we can't offer sailing as an option here this year.","vi":"Rất tiếc là chúng tôi không thể cung cấp tùy chọn chèo thuyền buồm ở đây trong năm nay."},{"time":83220,"en":"And I also want to point out, just across the lake, a track for cycling.","vi":"Và tôi cũng muốn chỉ ra rằng, ngay bên kia hồ, có một đường đua dành cho xe đạp."},{"time":89260,"en":"Some people in the past have also gone running on the track, but there were a few accidents because there isn't enough space for runners and cyclists, so now running isn't allowed.","vi":"Một số người trong quá khứ cũng đã chạy trên đường đua, nhưng đã có một vài tai nạn vì không có đủ không gian cho người chạy và người đi xe đạp, vì vậy bây giờ chạy bộ không được phép."},{"time":102180,"en":"So now let's take this path here, towards the tennis courts.","vi":"Vậy bây giờ chúng ta hãy đi theo con đường này ở đây, về phía sân tennis."},{"time":107060,"en":"On our left, you can see there's a football field.","vi":"Ở bên trái của chúng ta, bạn có thể thấy có một sân bóng đá."},{"time":110820,"en":"Gary's our coach and he'll be organising tournaments during the week.","vi":"Gary là huấn luyện viên của chúng tôi và anh ấy sẽ tổ chức các giải đấu trong tuần."},{"time":115260,"en":"He'll arrive tomorrow, because he's taking part in a rugby game today.","vi":"Anh ấy sẽ đến vào ngày mai, vì hôm nay anh ấy tham gia một trận đấu bóng bầu dục."},{"time":120200,"en":"And now if we walk up to the right of the tennis courts, we can see the archery field, surrounded by trees.","vi":"Và bây giờ nếu chúng ta đi bộ lên phía bên phải của sân tennis, chúng ta có thể thấy sân bắn cung, được bao quanh bởi cây cối."},{"time":127840,"en":"And in the building just to the right of this, you can hire equipment for the archery and buy snacks and drinks.","vi":"Và trong tòa nhà ngay phía bên phải của sân này, bạn có thể thuê thiết bị cho môn bắn cung và mua đồ ăn nhẹ và đồ uống."},{"time":135560,"en":"It also has some table tennis tables, so you can go there and have a game if the weather turns bad.","vi":"Nó cũng có một số bàn bóng bàn, vì vậy bạn có thể đến đó và chơi một trận nếu thời tiết trở nên xấu."}]}},{"id":"listening_u3_33","title":"Free Time: recording 2","actTitle":"Luyện tập: Recording 2","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120882/?view=embed","pType":"listen_passage","probTitle":"Free Time: recording 2","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset_16.mp3","youtubeId":"","subs":[{"time":0,"en":"Good morning.","vi":"Chào buổi sáng."},{"time":1840,"en":"I'd like to thank the council for agreeing to this meeting and for welcoming us here today to explain to you our plans for Pine Woods Centre.","vi":"Tôi xin cảm ơn hội đồng đã đồng ý cuộc họp này và chào mừng chúng tôi đến đây hôm nay để trình bày với quý vị về kế hoạch của chúng tôi cho Trung tâm Pine Woods."},{"time":11600,"en":"Our aim is to make Pine Woods a place where people of all ages can come and enjoy their free time.","vi":"Mục tiêu của chúng tôi là biến Pine Woods thành một nơi mà mọi người ở mọi lứa tuổi có thể đến và tận hưởng thời gian rảnh rỗi của mình."},{"time":19220,"en":"The centre will feature our Tree Tops Challenge - only for the brave and fearless!","vi":"Trung tâm sẽ có Trò chơi Mạo hiểm trên Ngọn cây của chúng tôi - chỉ dành cho những người dũng cảm và không sợ hãi!"},{"time":25220,"en":"For the less brave, and for families with children, there will be adventure playgrounds, indoor and outdoor, and a feeding area for farm animals and we will also offer cycle trails through the woods.","vi":"Đối với những người ít dũng cảm hơn và các gia đình có trẻ em, sẽ có sân chơi mạo hiểm trong nhà và ngoài trời, khu vực cho động vật trang trại ăn và chúng tôi cũng sẽ cung cấp các tuyến đường đạp xe xuyên rừng."},{"time":39360,"en":"I'll give you an overview of Pine Woods first and then tell you more about each area in more detail.","vi":"Đầu tiên, tôi sẽ cung cấp cho quý vị tổng quan về Pine Woods, sau đó sẽ trình bày chi tiết hơn về từng khu vực."},{"time":47260,"en":"This first slide shows the overall layout of the centre and where all the activities will be situated.","vi":"Slide đầu tiên này cho thấy bố cục tổng thể của trung tâm và vị trí của tất cả các hoạt động."},{"time":55280,"en":"As you can see from the map, the entrance to this attraction will be on the south side.","vi":"Như quý vị có thể thấy từ bản đồ, lối vào của điểm tham quan này sẽ ở phía nam."},{"time":61620,"en":"As visitors enter from the car park, they will walk along this path leading them to the café and gift shop.","vi":"Khi du khách vào từ bãi đậu xe, họ sẽ đi dọc theo con đường này dẫn đến quán cà phê và cửa hàng quà tặng."},{"time":68700,"en":"The gift shop will be where tickets are on sale and therefore needs to be near the entrance.","vi":"Cửa hàng quà tặng sẽ là nơi bán vé và do đó cần phải ở gần lối vào."},{"time":74880,"en":"So this building here on the right will be the café and the building on the left will be the gift shop.","vi":"Vì vậy, tòa nhà ở bên phải này sẽ là quán cà phê và tòa nhà ở bên trái sẽ là cửa hàng quà tặng."},{"time":81520,"en":"There will also be a picnic field behind the café for the warmer months.","vi":"Ngoài ra, sẽ có một khu dã ngoại phía sau quán cà phê cho những tháng ấm áp."},{"time":86580,"en":"It's the area just to the right of the café as you look at the map.","vi":"Đó là khu vực ngay bên phải quán cà phê khi bạn nhìn vào bản đồ."},{"time":91300,"en":"And in the bottom right-hand corner of the picnic field we're planning to have a barbecue area, where people can hire a barbecue and bring their own food to cook.","vi":"Và ở góc dưới cùng bên phải của khu dã ngoại, chúng tôi dự định sẽ có một khu vực nướng thịt, nơi mọi người có thể thuê vỉ nướng và mang thức ăn của riêng mình đến để nấu."},{"time":101320,"en":"It'll be great for parties.","vi":"Nó sẽ rất tuyệt cho các bữa tiệc."},{"time":103740,"en":"In summer we plan to have bands performing here in the evenings.","vi":"Vào mùa hè, chúng tôi dự định sẽ có các ban nhạc biểu diễn ở đây vào buổi tối."},{"time":108480,"en":"To the west of the gift shop is where the Tree Tops Challenge will take place.","vi":"Phía tây của cửa hàng quà tặng là nơi Trò chơi Mạo hiểm trên Ngọn cây sẽ diễn ra."},{"time":113500,"en":"There's a path here winding through the forest, and up in the trees there will be all sorts of high-level adventure apparatus - rope swings, awesome rope bridges and tunnels, and zip wires where you can fly way above the forest floor.","vi":"Có một con đường ở đây uốn lượn qua khu rừng, và trên cây sẽ có đủ loại thiết bị mạo hiểm trên cao - xích đu dây, cầu dây và đường hầm tuyệt vời, và dây zip nơi bạn có thể bay cao trên mặt đất rừng."},{"time":128760,"en":"This adventure experience will only be open to those aged 15 and over.","vi":"Trải nghiệm mạo hiểm này sẽ chỉ mở cửa cho những người từ 15 tuổi trở lên."},{"time":135520,"en":"Beyond the Tree Tops Challenge there will be an adventure playground.","vi":"Ngoài Trò chơi Mạo hiểm trên Ngọn cây sẽ có một sân chơi mạo hiểm."},{"time":139120,"en":"To get to it, you go along this path from the entrance until you reach the crossroads, then you turn left.","vi":"Để đến đó, bạn đi dọc theo con đường này từ lối vào cho đến khi bạn đến ngã tư, sau đó bạn rẽ trái."},{"time":147180,"en":"The young children's playground will have a fence around it, making it safer and keeping them away from the lake.","vi":"Sân chơi dành cho trẻ nhỏ sẽ có hàng rào xung quanh, làm cho nó an toàn hơn và giữ chúng tránh xa hồ nước."},{"time":154380,"en":"The indoor play area, only for the very young, will be on the east side of the farm, near the café and just inside the picnic area.","vi":"Khu vui chơi trong nhà, chỉ dành cho trẻ rất nhỏ, sẽ ở phía đông của trang trại, gần quán cà phê và ngay bên trong khu dã ngoại."},{"time":164000,"en":"And finally, let's turn our attention back to this area here, where the paths meet and form a crossroads.","vi":"Và cuối cùng, hãy quay lại khu vực này, nơi các con đường gặp nhau và tạo thành một ngã tư."},{"time":171300,"en":"This path leading to the east end of the farm will take our visitors to the area which houses the farm animals.","vi":"Con đường này dẫn đến phía đông của trang trại sẽ đưa du khách của chúng ta đến khu vực nuôi động vật trang trại."},{"time":178200,"en":"Children will be able to watch the animals being fed and cared for, and in some instances they will be able to feed the animals themselves.","vi":"Trẻ em sẽ có thể xem động vật được cho ăn và chăm sóc, và trong một số trường hợp, chúng sẽ có thể tự cho động vật ăn."},{"time":187800,"en":"The sheep will be in this first area on the right here, directly opposite the pigs, and the goats will go at the very end there.","vi":"Cừu sẽ ở khu vực đầu tiên bên phải này, đối diện trực tiếp với lợn, và dê sẽ ở cuối cùng."},{"time":196200,"en":"We haven't quite decided on the other areas yet.","vi":"Chúng tôi vẫn chưa quyết định về các khu vực khác."},{"time":199800,"en":"So those are our plans.","vi":"Vì vậy, đó là kế hoạch của chúng tôi."},{"time":201820,"en":"We hope they will be approved, and we look forward to welcoming you back in the not too distant future to see the final result.","vi":"Chúng tôi hy vọng chúng sẽ được phê duyệt và chúng tôi mong muốn được chào đón quý vị trở lại trong tương lai không xa để xem kết quả cuối cùng."}]}},{"id":"listening_u3_34","title":"Celebrities and Media: recording 1","actTitle":"Luyện tập: Recording 1","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120883/?view=embed","pType":"listen_passage","probTitle":"Celebrities and Media: recording 1","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset_17.mp3","youtubeId":"","subs":[{"time":0,"en":"Justin Bieber's rise to fame is an interesting story.","vi":"Hành trình nổi tiếng của Justin Bieber là một câu chuyện thú vị."},{"time":4860,"en":"He was interested in music from a very early age and he taught himself how to play a whole selection of musical instruments, which I think is rare in youngsters these days.","vi":"Anh ấy đã có hứng thú với âm nhạc từ khi còn rất nhỏ và tự học chơi rất nhiều loại nhạc cụ, điều mà tôi nghĩ là hiếm thấy ở giới trẻ ngày nay."},{"time":15540,"en":"Like a lot of teenagers who want to be pop stars, he learnt the guitar.","vi":"Giống như nhiều thiếu niên muốn trở thành ngôi sao nhạc pop, anh ấy đã học guitar."},{"time":21280,"en":"But, whereas very few of those teenagers put in the effort needed to be successful, Bieber, on the other hand, not only learnt how to play the piano as well, but also mastered the drums and even the trumpet!","vi":"Nhưng, trong khi rất ít những thiếu niên đó nỗ lực để thành công, thì Bieber, mặt khác, không chỉ học chơi piano mà còn thành thạo cả trống và thậm chí cả kèn trumpet!"},{"time":35100,"en":"One day he hopes to learn the violin.","vi":"Một ngày nào đó anh ấy hy vọng sẽ học violin."},{"time":37820,"en":"He was clearly gifted, and his mother used to arrange for him to take part in local competitions.","vi":"Rõ ràng là anh ấy có năng khiếu, và mẹ anh ấy thường sắp xếp cho anh ấy tham gia các cuộc thi địa phương."},{"time":44320,"en":"He came second in one, and his mother posted his performance on YouTube.","vi":"Anh ấy đã về nhì trong một cuộc thi, và mẹ anh ấy đã đăng màn trình diễn của anh ấy lên YouTube."},{"time":49300,"en":"She kept posting other clips of him singing, and soon these attracted a number of fans who started following him, though at this point he still hadn't found fame.","vi":"Cô ấy tiếp tục đăng những đoạn clip khác về anh ấy hát, và chẳng mấy chốc chúng đã thu hút được một số người hâm mộ bắt đầu theo dõi anh ấy, mặc dù tại thời điểm này anh ấy vẫn chưa nổi tiếng."},{"time":59680,"en":"His big break came when a music executive came across these videos by accident when he was looking for a performance by a different artist.","vi":"Bước ngoặt lớn của anh ấy đến khi một giám đốc âm nhạc tình cờ xem được những video này khi đang tìm kiếm màn trình diễn của một nghệ sĩ khác."},{"time":68860,"en":"He immediately recognised Bieber's talent and gave the teenager a contract with his recording company.","vi":"Ông ấy ngay lập tức nhận ra tài năng của Bieber và trao cho chàng thiếu niên một hợp đồng với công ty thu âm của mình."},{"time":75540,"en":"His first record was a worldwide hit.","vi":"Đĩa nhạc đầu tiên của anh ấy đã trở thành một hit toàn cầu."},{"time":78500,"en":"He shot to fame in just two years and is now a global superstar, one of the most well-known performers the world has ever seen.","vi":"Anh ấy đã nhanh chóng nổi tiếng chỉ trong hai năm và giờ là một siêu sao toàn cầu, một trong những nghệ sĩ biểu diễn nổi tiếng nhất thế giới từng thấy."}]}},{"id":"listening_u3_35","title":"Celebrities and Media: recording 2","actTitle":"Luyện tập: Recording 2","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120884/?view=embed","pType":"listen_passage","probTitle":"Celebrities and Media: recording 2","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset_18.mp3","youtubeId":"","subs":[{"time":0,"en":"So, you've been a famous singer for over three decades now.","vi":"Vậy, bạn đã là một ca sĩ nổi tiếng trong hơn ba thập kỷ rồi."},{"time":4800,"en":"What advice would you give to someone wanting to become famous?","vi":"Bạn sẽ đưa ra lời khuyên gì cho một người muốn trở nên nổi tiếng?"},{"time":8600,"en":"Well, my first piece of advice is - don't try and become famous.","vi":"Chà, lời khuyên đầu tiên của tôi là - đừng cố gắng để trở nên nổi tiếng."},{"time":14700,"en":"Instead focus on being good at something.","vi":"Thay vào đó, hãy tập trung vào việc giỏi một cái gì đó."},{"time":17800,"en":"Choose something you enjoy and then work hard at doing well in that area.","vi":"Chọn một thứ bạn thích và sau đó làm việc chăm chỉ để làm tốt trong lĩnh vực đó."},{"time":23860,"en":"What did you do to become such a successful singer?","vi":"Bạn đã làm gì để trở thành một ca sĩ thành công như vậy?"},{"time":27080,"en":"Well, a good way to be the best is to learn from the experts.","vi":"Chà, một cách tốt để trở thành người giỏi nhất là học hỏi từ các chuyên gia."},{"time":32000,"en":"Find people you admire in your area of interest.","vi":"Tìm những người bạn ngưỡng mộ trong lĩnh vực bạn quan tâm."},{"time":35260,"en":"Try to get as close to them as possible.","vi":"Cố gắng tiếp cận họ càng gần càng tốt."},{"time":38160,"en":"Observe them carefully.","vi":"Quan sát họ cẩn thận."},{"time":40260,"en":"If possible, talk to them.","vi":"Nếu có thể, hãy nói chuyện với họ."},{"time":42980,"en":"Ask lots of questions.","vi":"Đặt nhiều câu hỏi."},{"time":45440,"en":"Don't copy them, but try to learn from them.","vi":"Đừng sao chép họ, nhưng hãy cố gắng học hỏi từ họ."},{"time":48880,"en":"And don't be afraid to experiment, try something new.","vi":"Và đừng sợ thử nghiệm, hãy thử một cái gì đó mới."},{"time":53680,"en":"Being the best is one thing, but how did you get yourself known?","vi":"Trở thành người giỏi nhất là một chuyện, nhưng làm thế nào bạn được mọi người biết đến?"},{"time":57980,"en":"Getting yourself known is indeed another skill you must work on.","vi":"Để được mọi người biết đến thực sự là một kỹ năng khác mà bạn phải trau dồi."},{"time":62780,"en":"One thing is for sure, nobody is going to come to you.","vi":"Một điều chắc chắn là, sẽ không ai đến với bạn cả."},{"time":67000,"en":"You have to make opportunities for yourself.","vi":"Bạn phải tự tạo cơ hội cho chính mình."},{"time":70600,"en":"You have a product to sell","vi":"Bạn có một sản phẩm để bán"},{"time":72480,"en":"and the product is you.","vi":"và sản phẩm đó chính là bạn."},{"time":74820,"en":"It's much easier to do that these days, especially with the internet around.","vi":"Ngày nay làm điều đó dễ dàng hơn nhiều, đặc biệt là với sự trợ giúp của internet."},{"time":79960,"en":"Many people use social media for this.","vi":"Nhiều người sử dụng mạng xã hội cho việc này."},{"time":82820,"en":"Any other piece of advice?","vi":"Bạn có lời khuyên nào khác không?"},{"time":84460,"en":"Yes, the last thing I would say is, if you want to be really successful in something, you will most likely experience a certain amount of failure.","vi":"Có, điều cuối cùng tôi muốn nói là, nếu bạn muốn thực sự thành công trong một lĩnh vực nào đó, rất có thể bạn sẽ trải qua một số thất bại nhất định."},{"time":93780,"en":"People who fail at some point often say that the experience has been a great lesson and helped them on the road","vi":"Những người thất bại vào một thời điểm nào đó thường nói rằng kinh nghiệm đó là một bài học lớn và giúp họ trên con đường"},{"time":101400,"en":"to success.","vi":"dẫn đến thành công."},{"time":102520,"en":"Try to learn from these moments instead of being frightened of them.","vi":"Hãy cố gắng học hỏi từ những khoảnh khắc này thay vì sợ hãi chúng."},{"time":107440,"en":"In fact, some of the most successful people have often failed countless times before reaching their end goal.","vi":"Trên thực tế, một số người thành công nhất thường đã thất bại vô số lần trước khi đạt được mục tiêu cuối cùng của họ."},{"time":115100,"en":"What makes them successful, is that they kept on trying regardless.","vi":"Điều khiến họ thành công là họ vẫn tiếp tục cố gắng bất chấp mọi thứ."}]}},{"id":"listening_u3_36","title":"Celebrities and Media: recording 3","actTitle":"Luyện tập: Recording 3","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120885/?view=embed","pType":"listen_passage","probTitle":"Celebrities and Media: recording 3","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset_19.mp3","youtubeId":"","subs":[{"time":0,"en":"So welcome to Film-makers' Club.","vi":"Chào mừng đến với Câu lạc bộ Nhà làm phim."},{"time":3180,"en":"I hope you're excited at the thought of making a film and that you're bursting with great ideas.","vi":"Tôi hy vọng các bạn hào hứng với ý tưởng làm phim và tràn đầy những ý tưởng tuyệt vời."},{"time":8540,"en":"I've put you all into groups, so here's what you're going to do.","vi":"Tôi đã chia tất cả các bạn thành các nhóm, và đây là những gì các bạn sẽ làm."},{"time":12500,"en":"Now you might think the first thing that you need to do is to come up with an idea for a story, but even before that you need to think about what type of film you want to make.","vi":"Có lẽ bạn nghĩ điều đầu tiên cần làm là nghĩ ra một ý tưởng cho câu chuyện, nhưng trước đó, bạn cần nghĩ về thể loại phim mà bạn muốn làm."},{"time":23240,"en":"Remember that a film is really a story in pictures.","vi":"Hãy nhớ rằng, phim thực chất là một câu chuyện bằng hình ảnh."},{"time":26600,"en":"There are lots of ways of telling a story.","vi":"Có rất nhiều cách để kể một câu chuyện."},{"time":28520,"en":"So choose a style of film that suits the talents of the group.","vi":"Vì vậy, hãy chọn một phong cách phim phù hợp với tài năng của nhóm."},{"time":33020,"en":"If you have talented artists, but no good writers, or actors, you might want to make your film in the style of a cartoon or some other kind of animation.","vi":"Nếu bạn có những nghệ sĩ tài năng, nhưng không có nhà văn hay diễn viên giỏi, bạn có thể muốn làm phim theo phong cách hoạt hình hoặc một loại hình animation nào đó."},{"time":43180,"en":"Last year a group made an excellent film using Lego bricks.","vi":"Năm ngoái, một nhóm đã làm một bộ phim xuất sắc bằng cách sử dụng các viên gạch Lego."},{"time":47200,"en":"So having decided that, you can start to think of your idea for the story.","vi":"Vì vậy, sau khi quyết định điều đó, bạn có thể bắt đầu nghĩ về ý tưởng cho câu chuyện của mình."},{"time":52460,"en":"Think about the movies you like to watch.","vi":"Hãy nghĩ về những bộ phim bạn thích xem."},{"time":55400,"en":"What is it that makes them interesting?","vi":"Điều gì làm cho chúng thú vị?"},{"time":57500,"en":"Is it the characters, the plot?","vi":"Là nhân vật hay cốt truyện?"},{"time":59860,"en":"As regards plot, my advice is - don't be too ambitious, don't make it complicated.","vi":"Về cốt truyện, lời khuyên của tôi là - đừng quá tham vọng, đừng làm cho nó phức tạp."},{"time":66140,"en":"Keep it simple - the simplest ideas are often the ones that work the best.","vi":"Hãy giữ cho nó đơn giản - những ý tưởng đơn giản nhất thường là những ý tưởng hiệu quả nhất."},{"time":72060,"en":"Initially you just need to find the basic concept.","vi":"Ban đầu, bạn chỉ cần tìm ra khái niệm cơ bản."},{"time":76260,"en":"You can fill in the details later.","vi":"Bạn có thể điền vào các chi tiết sau."},{"time":78600,"en":"It's a good idea to keep a notebook in your pocket and carry it everywhere.","vi":"Bạn nên mang theo một cuốn sổ nhỏ trong túi và mang nó đi khắp mọi nơi."},{"time":83480,"en":"You never know when a great idea will suddenly come to you!","vi":"Bạn không bao giờ biết khi nào một ý tưởng tuyệt vời sẽ bất ngờ đến với bạn!"},{"time":87020,"en":"And the more ideas, the better, in my opinion.","vi":"Và theo tôi, càng nhiều ý tưởng càng tốt."},{"time":90440,"en":"The next stage is to write the screenplay - for this you need to divide the story up into a series of scenes.","vi":"Giai đoạn tiếp theo là viết kịch bản - để làm điều này, bạn cần chia câu chuyện thành một loạt các cảnh."},{"time":97600,"en":"For each scene, the screenplay should begin with a short description of where it takes place and the time of day, that is day or night.","vi":"Đối với mỗi cảnh, kịch bản nên bắt đầu bằng một mô tả ngắn gọn về địa điểm diễn ra và thời gian trong ngày, tức là ngày hay đêm."},{"time":105960,"en":"Then the rest consists of the script - the lines the actors will speak, and it should also describe the camera movements, and give directions to the actors about how they should move.","vi":"Phần còn lại bao gồm kịch bản - những dòng thoại mà diễn viên sẽ nói, và nó cũng nên mô tả các chuyển động của máy quay, và đưa ra chỉ dẫn cho diễn viên về cách họ nên di chuyển."},{"time":117660,"en":"Before you can start filming, you need to prepare a storyboard of your film to help everyone involved imagine the scene clearly and to understand what you are trying to achieve.","vi":"Trước khi bạn có thể bắt đầu quay phim, bạn cần chuẩn bị một bảng phân cảnh cho bộ phim của mình để giúp mọi người liên quan hình dung rõ ràng cảnh quay và hiểu những gì bạn đang cố gắng đạt được."},{"time":128680,"en":"This is similar to a comic-book version of your film, but without speech balloons.","vi":"Nó tương tự như một phiên bản truyện tranh của bộ phim của bạn, nhưng không có bong bóng thoại."},{"time":134220,"en":"And at this point you need to appoint a director.","vi":"Và tại thời điểm này, bạn cần chỉ định một đạo diễn."},{"time":137640,"en":"This is a major role and it's vital that he or she is a good communicator, as they are the key link between the actors and the rest of the team.","vi":"Đây là một vai trò quan trọng và điều quan trọng là người đó phải là một người giao tiếp tốt, vì họ là mối liên kết chính giữa các diễn viên và phần còn lại của nhóm."},{"time":147320,"en":"This person will have responsibility for the creative side of the project.","vi":"Người này sẽ chịu trách nhiệm về khía cạnh sáng tạo của dự án."},{"time":151700,"en":"He or she will have the final say in the choice of the main actors and in directing the action of the film.","vi":"Người đó sẽ có tiếng nói cuối cùng trong việc lựa chọn các diễn viên chính và trong việc chỉ đạo hành động của bộ phim."},{"time":159480,"en":"That brings me to the next stage - casting your film - finding the actors.","vi":"Điều đó đưa tôi đến giai đoạn tiếp theo - tuyển diễn viên cho bộ phim của bạn - tìm diễn viên."},{"time":165400,"en":"Don't just rely on your friends.","vi":"Đừng chỉ dựa vào bạn bè của bạn."},{"time":167560,"en":"Be creative!","vi":"Hãy sáng tạo!"},{"time":168500,"en":"Perhaps you could advertise on social media.","vi":"Có lẽ bạn có thể quảng cáo trên phương tiện truyền thông xã hội."},{"time":171880,"en":"Or if your film needs a doctor, perhaps you could ask one from the local hospital if they could spare a couple of hours for you?","vi":"Hoặc nếu bộ phim của bạn cần một bác sĩ, có lẽ bạn có thể hỏi một người từ bệnh viện địa phương xem họ có thể dành ra một vài giờ cho bạn không?"},{"time":179300,"en":"And then before filming finally starts, you will need to assign other jobs, such as director of photography - in your case this will be the person who operates the camera; someone in charge of sound and music, and someone in charge of costumes and props (including furniture and any other objects needed) and also someone to look after hair and make-up.","vi":"Và sau đó, trước khi quá trình quay phim thực sự bắt đầu, bạn sẽ cần phân công các công việc khác, chẳng hạn như đạo diễn hình ảnh - trong trường hợp của bạn, đây sẽ là người điều khiển máy quay; người phụ trách âm thanh và âm nhạc, và người phụ trách trang phục và đạo cụ (bao gồm đồ nội thất và bất kỳ đồ vật cần thiết nào khác) và cả người chăm sóc tóc và trang điểm."},{"time":202440,"en":"But we'll look at these roles in more detail in our next session.","vi":"Nhưng chúng ta sẽ xem xét các vai trò này chi tiết hơn trong buổi tiếp theo."}]}},{"id":"listening_u3_37","title":"Nature and Wildlife: recording 1","actTitle":"Luyện tập: Recording 1","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120886/?view=embed","pType":"listen_passage","probTitle":"Nature and Wildlife: recording 1","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset_20.mp3","youtubeId":"","subs":[{"time":0,"en":"Hello everyone.","vi":"Xin chào mọi người."},{"time":1,"en":"Today I'm going to talk about a project I've done about the mountain gorilla.","vi":"Hôm nay tôi sẽ nói về một dự án tôi đã thực hiện về loài khỉ đột núi."},{"time":7140,"en":"I think it's a truly fascinating animal.","vi":"Tôi nghĩ đây là một loài động vật thực sự hấp dẫn."},{"time":10380,"en":"They originate in Africa - Central Africa, in fact.","vi":"Chúng có nguồn gốc từ Châu Phi - thực tế là Trung Phi."},{"time":15100,"en":"So now I'm going to talk a little about where they live.","vi":"Vậy bây giờ tôi sẽ nói một chút về nơi chúng sống."},{"time":18660,"en":"As you can probably guess, and as you can see in this first photo, their name reflects the environment they live in - tropical mountain forests.","vi":"Như bạn có thể đoán, và như bạn có thể thấy trong bức ảnh đầu tiên này, tên của chúng phản ánh môi trường sống của chúng - rừng núi nhiệt đới."},{"time":29040,"en":"Now just like all other apes, they build nests out of leaves.","vi":"Bây giờ giống như tất cả các loài vượn khác, chúng xây tổ bằng lá cây."},{"time":33820,"en":"But they don't make their nests high up as other species do - mountain gorillas make them on the ground instead.","vi":"Nhưng chúng không làm tổ trên cao như các loài khác - khỉ đột núi thay vào đó lại làm tổ trên mặt đất."},{"time":40560,"en":"And they sleep wherever they end their day and they rarely sleep in the same bed twice!","vi":"Và chúng ngủ bất cứ nơi nào chúng kết thúc một ngày của mình và hiếm khi ngủ lại ở cùng một chỗ hai lần!"},{"time":45920,"en":"So, I'll move on to talk about the physical features of the mountain gorilla.","vi":"Vậy, tôi sẽ chuyển sang nói về các đặc điểm thể chất của khỉ đột núi."},{"time":50460,"en":"In other words, what it looks like.","vi":"Nói cách khác, nó trông như thế nào."},{"time":53180,"en":"So here are some more photographs on screen for you all to have a look at.","vi":"Vậy đây là một vài bức ảnh nữa trên màn hình để tất cả các bạn xem qua."},{"time":58280,"en":"This gorilla here on the left is a male gorilla.","vi":"Con khỉ đột ở bên trái này là một con đực."},{"time":62080,"en":"We know that he's an older male gorilla because of the colour of his coat.","vi":"Chúng ta biết rằng nó là một con đực lớn tuổi vì màu lông của nó."},{"time":66460,"en":"As you can see, his coat is grey.","vi":"Như bạn có thể thấy, lông của nó màu xám."},{"time":69560,"en":"He's called a silverback.","vi":"Nó được gọi là lưng bạc."},{"time":72560,"en":"Younger male gorillas are called blackbacks.","vi":"Những con khỉ đột đực trẻ hơn được gọi là lưng đen."},{"time":76200,"en":"And there's an obvious reason for that!","vi":"Và có một lý do hiển nhiên cho điều đó!"},{"time":78740,"en":"Yes, a young adult male has a black coat.","vi":"Đúng vậy, một con đực trưởng thành trẻ tuổi có bộ lông màu đen."},{"time":83100,"en":"As he gets older, his coat turns from black to grey.","vi":"Khi nó già đi, bộ lông của nó chuyển từ đen sang xám."},{"time":87660,"en":"Next, I'm going to tell you a little about the diet of the mountain gorilla.","vi":"Tiếp theo, tôi sẽ kể cho bạn nghe một chút về chế độ ăn của khỉ đột núi."},{"time":91500,"en":"Interestingly, mountain gorillas are herbivores.","vi":"Điều thú vị là, khỉ đột núi là động vật ăn cỏ."},{"time":95520,"en":"In other words, they survive on a diet of plants.","vi":"Nói cách khác, chúng sống sót nhờ chế độ ăn thực vật."},{"time":99440,"en":"As you can see from this next picture, this gorilla is eating leaves.","vi":"Như bạn có thể thấy từ bức ảnh tiếp theo này, con khỉ đột này đang ăn lá cây."},{"time":104600,"en":"They also eat fruit and flowers.","vi":"Chúng cũng ăn trái cây và hoa."},{"time":107140,"en":"They occasionally eat insects too, but only when they're very hungry!","vi":"Thỉnh thoảng chúng cũng ăn côn trùng, nhưng chỉ khi chúng rất đói!"},{"time":112700,"en":"And it might interest you to know that mountain gorillas very rarely drink water, even though they live in a very warm climate.","vi":"Và bạn có thể thấy thú vị khi biết rằng khỉ đột núi rất hiếm khi uống nước, mặc dù chúng sống trong một vùng khí hậu rất ấm áp."},{"time":120140,"en":"It appears they get all the water they need from plants.","vi":"Có vẻ như chúng lấy tất cả lượng nước cần thiết từ thực vật."},{"time":124700,"en":"I'd like to conclude by talking about some of the threats that mountain gorillas face.","vi":"Tôi muốn kết luận bằng cách nói về một số mối đe dọa mà khỉ đột núi phải đối mặt."},{"time":130240,"en":"They are in serious danger of disappearing from our world altogether.","vi":"Chúng đang gặp nguy cơ nghiêm trọng biến mất hoàn toàn khỏi thế giới của chúng ta."},{"time":134900,"en":"Let's have a look at two reasons why they're in such danger.","vi":"Hãy xem xét hai lý do tại sao chúng lại gặp nguy hiểm như vậy."},{"time":138340,"en":"And both of these reasons are connected to human activity.","vi":"Và cả hai lý do này đều liên quan đến hoạt động của con người."},{"time":142600,"en":"Firstly, people are damaging the mountain forests where these gorillas live.","vi":"Thứ nhất, con người đang phá hoại các khu rừng trên núi, nơi những con khỉ đột này sinh sống."},{"time":147380,"en":"They're cutting down the trees to build farms and towns.","vi":"Họ đang chặt cây để xây dựng trang trại và thị trấn."},{"time":151220,"en":"Mountain gorillas live in close family groups and this means that it's difficult for them to get enough to eat in the small areas they now have to live in.","vi":"Khỉ đột núi sống theo nhóm gia đình thân thiết và điều này có nghĩa là chúng khó có đủ thức ăn trong những khu vực nhỏ mà chúng phải sống hiện nay."},{"time":160060,"en":"Secondly, gorillas are also suffering as a result of hunting.","vi":"Thứ hai, khỉ đột cũng đang phải chịu đựng do săn bắn."},{"time":164940,"en":"Sadly, some people find and kill them to sell.","vi":"Đáng buồn thay, một số người tìm và giết chúng để bán."},{"time":168860,"en":"So it's a very sad situation indeed for these beautiful animals.","vi":"Vì vậy, đây thực sự là một tình huống rất đáng buồn cho những con vật xinh đẹp này."}]}},{"id":"listening_u3_38","title":"Nature and Wildlife: recording 2","actTitle":"Luyện tập: Recording 2","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120887/?view=embed","pType":"listen_passage","probTitle":"Nature and Wildlife: recording 2","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset_21.mp3","youtubeId":"","subs":[{"time":0,"en":"Good morning, everyone.","vi":"Chào buổi sáng mọi người."},{"time":2820,"en":"In today's lecture I want to talk to you about a very unpopular animal here in Britain.","vi":"Trong bài giảng hôm nay, tôi muốn nói với các bạn về một loài động vật rất không được ưa chuộng ở Anh."},{"time":8580,"en":"In fact, you could say that it's one of our least loved animals!","vi":"Thực tế, bạn có thể nói rằng nó là một trong những loài động vật ít được yêu thích nhất của chúng ta!"},{"time":13180,"en":"It's called the American bullfrog and yes, it does in fact come from America - the east of America, to be exact - and it was brought to Britain in the early 19th century, so you could say that it's been here for quite a longtime.","vi":"Nó được gọi là ếch ương Mỹ và đúng vậy, nó thực sự đến từ Mỹ - chính xác là miền đông nước Mỹ - và nó đã được đưa đến Anh vào đầu thế kỷ 19, vì vậy bạn có thể nói rằng nó đã ở đây khá lâu rồi."},{"time":28960,"en":"It wasn't brought here on purpose - it actually arrived in a big container of aquatic plants.","vi":"Nó không được đưa đến đây một cách có chủ ý - nó thực sự đã đến trong một thùng lớn đựng cây thủy sinh."},{"time":34880,"en":"In other words, it was accidentally introduced into Britain.","vi":"Nói cách khác, nó đã vô tình du nhập vào Anh."},{"time":38940,"en":"Now, I'll tell you a little about its appearance.","vi":"Bây giờ, tôi sẽ nói với bạn một chút về ngoại hình của nó."},{"time":41740,"en":"The American bullfrog is a very large - and ugly - species of frog.","vi":"Ếch ương Mỹ là một loài ếch rất lớn - và xấu xí."},{"time":47320,"en":"And when I say it's large, I mean large.","vi":"Và khi tôi nói nó lớn, ý tôi là rất lớn."},{"time":51060,"en":"Interestingly, female American bullfrogs are usually much larger than the males.","vi":"Điều thú vị là, ếch ương Mỹ cái thường lớn hơn nhiều so với con đực."},{"time":56440,"en":"In fact, they can weigh up to 750 grams, whereas the males only go up to about 600 grams.","vi":"Trên thực tế, chúng có thể nặng tới 750 gram, trong khi con đực chỉ nặng khoảng 600 gram."},{"time":63980,"en":"Take a look at its head - it's really broad and flat, isn't it?","vi":"Hãy nhìn vào đầu của nó - nó thực sự rộng và phẳng, phải không?"},{"time":69340,"en":"And you can see its mouth - just here - that's quite large too.","vi":"Và bạn có thể thấy miệng của nó - ngay đây - cũng khá lớn."},{"time":74580,"en":"Now, both the male and the female American bullfrogs have green or brown bodies and have dark spots on the top.","vi":"Cả ếch ương Mỹ đực và cái đều có thân màu xanh lục hoặc nâu và có những đốm đen trên lưng."},{"time":83220,"en":"But there's one important difference between them - the male's throat is yellow but the female has a white one instead.","vi":"Nhưng có một điểm khác biệt quan trọng giữa chúng - cổ họng của con đực có màu vàng nhưng con cái lại có màu trắng."},{"time":91640,"en":"And the other difference is their eardrums, here just behind their eyes.","vi":"Và sự khác biệt còn lại là màng nhĩ của chúng, ở ngay sau mắt."},{"time":96860,"en":"Those of the male are much larger than the female's.","vi":"Màng nhĩ của con đực lớn hơn nhiều so với con cái."},{"time":100960,"en":"So, let's move on to why we so dislike the American bullfrog.","vi":"Vậy, chúng ta hãy chuyển sang lý do tại sao chúng ta lại không thích ếch ương Mỹ đến vậy."},{"time":105720,"en":"Well, this is because it has threatened our own native species of frogs.","vi":"Chà, điều này là do nó đã đe dọa các loài ếch bản địa của chúng ta."},{"time":110600,"en":"Firstly, it breeds very quickly indeed.","vi":"Thứ nhất, nó sinh sản rất nhanh."},{"time":113800,"en":"For example, female bullfrogs can lay up to 25,000 eggs every single season.","vi":"Ví dụ, ếch ương cái có thể đẻ tới 25.000 trứng mỗi mùa."},{"time":120600,"en":"And secondly, the American bullfrog is very greedy.","vi":"Và thứ hai, ếch ương Mỹ rất tham ăn."},{"time":124720,"en":"In fact, they eat just about anything they can put into their mouths!","vi":"Trên thực tế, chúng ăn bất cứ thứ gì chúng có thể cho vào miệng!"},{"time":129600,"en":"As well as other frogs, they eat insects, fish and have even been known to eat birds and snakes!","vi":"Cùng với các loài ếch khác, chúng ăn côn trùng, cá và thậm chí được biết là ăn cả chim và rắn!"},{"time":136780,"en":"So, in other words, they eat the food sources of our own native species.","vi":"Nói cách khác, chúng ăn các nguồn thức ăn của các loài bản địa của chúng ta."},{"time":142340,"en":"Thirdly, they carry a disease that is dangerous to other frogs.","vi":"Thứ ba, chúng mang một căn bệnh nguy hiểm cho các loài ếch khác."},{"time":146940,"en":"And finally, they don't just damage our natural world, they cause financial damage too.","vi":"Và cuối cùng, chúng không chỉ gây hại cho thế giới tự nhiên của chúng ta, chúng còn gây ra thiệt hại về tài chính."},{"time":153080,"en":"Around £100,000 has been spent monitoring the American bullfrog in the wild.","vi":"Khoảng 100.000 bảng Anh đã được chi để theo dõi ếch ương Mỹ trong tự nhiên."},{"time":158920,"en":"So, as scientists, we can learn a lesson from this about the dangers of introducing any living species into a new environment.","vi":"Vì vậy, với tư cách là các nhà khoa học, chúng ta có thể rút ra một bài học từ điều này về sự nguy hiểm của việc đưa bất kỳ loài sinh vật nào vào một môi trường mới."}]}},{"id":"listening_u3_39","title":"Nature and Wildlife: recording 3","actTitle":"Luyện tập: Recording 3","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120888/?view=embed","pType":"listen_passage","probTitle":"Nature and Wildlife: recording 3","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset_22.mp3","youtubeId":"","subs":[{"time":0,"en":"OK everyone, I think we're ready to make a start.","vi":"Được rồi mọi người, tôi nghĩ chúng ta đã sẵn sàng để bắt đầu."},{"time":4600,"en":"Now, when you think of a dangerous animal, what do you think of?","vi":"Bây giờ, khi bạn nghĩ về một con vật nguy hiểm, bạn nghĩ đến con gì?"},{"time":8960,"en":"A tiger perhaps?","vi":"Có lẽ là một con hổ?"},{"time":10560,"en":"Or maybe a leopard?","vi":"Hoặc có thể là một con báo?"},{"time":12560,"en":"Most people think that all dangerous animals live on land, but in fact, some of the most dangerous animals on the planet live in our seas and oceans.","vi":"Hầu hết mọi người nghĩ rằng tất cả các loài động vật nguy hiểm đều sống trên cạn, nhưng trên thực tế, một số loài động vật nguy hiểm nhất trên hành tinh lại sống ở biển cả và đại dương của chúng ta."},{"time":22980,"en":"I'm going to talk today about one of these - the box jellyfish.","vi":"Hôm nay tôi sẽ nói về một trong số đó - loài sứa hộp."},{"time":28480,"en":"There are different types of box jellyfish, and they are found in warm coastal seas anywhere from the Indian Ocean to as far north as Japan, but the most dangerous ones are found in the oceans around Australia.","vi":"Có nhiều loại sứa hộp khác nhau, và chúng được tìm thấy ở các vùng biển ven biển ấm áp từ Ấn Độ Dương đến tận phía bắc Nhật Bản, nhưng những loại nguy hiểm nhất được tìm thấy ở các đại dương xung quanh Úc."},{"time":42780,"en":"OK, so now let's examine what these box jellyfish look like.","vi":"Được rồi, bây giờ chúng ta hãy xem xét những con sứa hộp này trông như thế nào."},{"time":47600,"en":"There are no prizes for guessing why it's called a box jellyfish!","vi":"Không cần phải đoán xem tại sao nó lại được gọi là sứa hộp!"},{"time":51240,"en":"You can see that it's shaped like a box or a cube, with four sides and rounded corners.","vi":"Bạn có thể thấy rằng nó có hình dạng như một cái hộp hoặc một khối lập phương, với bốn mặt và các góc tròn."},{"time":58000,"en":"And you can also see that its body is light blue.","vi":"Và bạn cũng có thể thấy rằng cơ thể của nó có màu xanh nhạt."},{"time":62000,"en":"So, let's take a look at the tentacles of the box jellyfish more closely.","vi":"Vậy, hãy xem xét kỹ hơn các xúc tu của sứa hộp."},{"time":67160,"en":"It's got 15 of these growing from each of the four corners of the box.","vi":"Nó có 15 xúc tu mọc ra từ mỗi góc của hộp."},{"time":72380,"en":"Now, you may be surprised to learn that these tentacles can grow to a length of three metres!","vi":"Bây giờ, bạn có thể ngạc nhiên khi biết rằng những xúc tu này có thể phát triển đến chiều dài ba mét!"},{"time":79280,"en":"And another surprising thing is its large number of eyes, that's six eyes on each of its four sides, so 24 altogether.","vi":"Và một điều đáng ngạc nhiên nữa là số lượng mắt lớn của nó, sáu mắt trên mỗi mặt trong bốn mặt, tổng cộng là 24 mắt."},{"time":89220,"en":"So now let's move on to talk about the sting of a box jellyfish.","vi":"Vậy bây giờ chúng ta hãy chuyển sang nói về vết đốt của sứa hộp."},{"time":94120,"en":"What is it?","vi":"Nó là gì?"},{"time":95400,"en":"Well, a jellyfish has a lot of tentacles, and each tentacle has thousands of cells which can produce a poison.","vi":"Chà, một con sứa có rất nhiều xúc tu, và mỗi xúc tu có hàng ngàn tế bào có thể tạo ra chất độc."},{"time":103680,"en":"If the tentacles come into contact with a fish, or a person, they stick to their skin.","vi":"Nếu xúc tu tiếp xúc với cá hoặc người, chúng sẽ dính vào da của họ."},{"time":110300,"en":"If the tentacles are very long, they are in contact with a lot of the body, giving a bad sting which hurts terribly.","vi":"Nếu các xúc tu rất dài, chúng sẽ tiếp xúc với phần lớn cơ thể, gây ra vết đốt tồi tệ gây đau đớn khủng khiếp."},{"time":118140,"en":"This can be dangerous to the victim.","vi":"Điều này có thể gây nguy hiểm cho nạn nhân."},{"time":121060,"en":"There are two ways that people can die as the result of a jellyfish sting.","vi":"Có hai cách mà mọi người có thể chết do bị sứa đốt."},{"time":125520,"en":"Firstly, a very severe sting can cause a person to have a heart attack.","vi":"Thứ nhất, một vết đốt rất nghiêm trọng có thể khiến một người bị đau tim."},{"time":130580,"en":"This can happen within minutes.","vi":"Điều này có thể xảy ra trong vòng vài phút."},{"time":133160,"en":"Secondly, sometimes a swimmer goes into shock and can't make it back to the beach because they are in such extreme pain.","vi":"Thứ hai, đôi khi một người bơi bị sốc và không thể quay trở lại bãi biển vì họ quá đau đớn."},{"time":141400,"en":"If they're in the water alone, they'll die.","vi":"Nếu họ ở một mình dưới nước, họ sẽ chết."},{"time":145340,"en":"And now I'd like to conclude with advice on how to help someone who has been stung by a box jellyfish.","vi":"Và bây giờ tôi muốn kết thúc bằng lời khuyên về cách giúp đỡ một người bị sứa hộp đốt."},{"time":151960,"en":"If they have had a heart attack, of course the most important thing is to try to revive them first of all.","vi":"Nếu họ bị đau tim, tất nhiên điều quan trọng nhất là cố gắng hồi sức cho họ trước hết."},{"time":157920,"en":"And then, the best thing to help is vinegar.","vi":"Và sau đó, điều tốt nhất để giúp đỡ là giấm."},{"time":160900,"en":"Yes, the same vinegar you use when you're cooking!","vi":"Đúng vậy, loại giấm bạn dùng khi nấu ăn!"},{"time":164620,"en":"Many Australian beaches keep bottles of it near the jellyfish warning signs.","vi":"Nhiều bãi biển ở Úc giữ các chai giấm gần các biển báo cảnh báo sứa."},{"time":169400,"en":"You should pour a bottle over the tentacles for 30 seconds, and then the tentacles can be removed.","vi":"Bạn nên đổ một chai lên các xúc tu trong 30 giây, và sau đó có thể loại bỏ các xúc tu."},{"time":176400,"en":"However, if you get stung and don't have any vinegar, you should pour seawater on the skin.","vi":"Tuy nhiên, nếu bạn bị đốt và không có giấm, bạn nên dội nước biển lên da."},{"time":182320,"en":"This will help to ease the pain before you can get further medical help.","vi":"Điều này sẽ giúp giảm bớt cơn đau trước khi bạn có thể nhận được sự trợ giúp y tế thêm."}]}},{"id":"listening_u3_40","title":"Cities and Structures: recording 1","actTitle":"Luyện tập: Recording 1","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120889/?view=embed","pType":"listen_passage","probTitle":"Cities and Structures: recording 1","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset2_1.mp3","youtubeId":"","subs":[{"time":0,"en":"Morgan's Estate Agents. How can I help you?","vi":"Văn phòng bất động sản Morgan. Tôi có thể giúp gì cho bạn?"},{"time":7920,"en":"Hello. I'm calling about a property that you have for sale - in Churchill Road.","vi":"Chào bạn. Tôi gọi để hỏi về một bất động sản đang được rao bán trên đường Churchill."},{"time":13280,"en":"Sorry. Did you say Church Mill Road?","vi":"Xin lỗi. Ý bạn là đường Church Mill phải không?"},{"time":16160,"en":"No. Churchill Road - C-H-U-R-C-H-I-L-L.","vi":"Không. Đường Churchill - C-H-U-R-C-H-I-L-L."},{"time":23120,"en":"Oh, right.","vi":"À, ra vậy."},{"time":24500,"en":"We have two for sale in Churchill Road - a three-bedroom property and a two-bedroom one.","vi":"Chúng tôi có hai bất động sản đang bán trên đường Churchill - một căn ba phòng ngủ và một căn hai phòng ngủ."},{"time":30340,"en":"Can you tell me which one you're calling about?","vi":"Bạn gọi để hỏi về căn nào trong số đó?"},{"time":33720,"en":"It's the three-bedroom one.","vi":"Là căn ba phòng ngủ."},{"time":35280,"en":"Oh, yes. Would you like to arrange a viewing?","vi":"À, vâng. Bạn có muốn sắp xếp xem nhà không?"},{"time":38480,"en":"Yes, but first of all, I'd like to check some details.","vi":"Có, nhưng trước hết, tôi muốn kiểm tra một vài chi tiết."},{"time":42840,"en":"Certainly. What would you like to know?","vi":"Chắc chắn rồi. Bạn muốn biết điều gì?"},{"time":45680,"en":"First, how many lounges has it got?","vi":"Đầu tiên, nó có bao nhiêu phòng khách?"},{"time":48840,"en":"There are two. There's a small one at the front and a larger one at the back, leading to a sun-room.","vi":"Có hai. Một phòng nhỏ ở phía trước và một phòng lớn hơn ở phía sau, dẫn đến phòng tắm nắng."},{"time":55520,"en":"A sun-room? That's nice to know.","vi":"Phòng tắm nắng? Thật tuyệt khi biết điều đó."},{"time":58580,"en":"Yes.","vi":"Vâng."},{"time":58940,"en":"It's perfect to sit in on those chilly or rainy days as it's got its own heating.","vi":"Nó hoàn hảo để ngồi vào những ngày lạnh hoặc mưa vì nó có hệ thống sưởi riêng."},{"time":64620,"en":"And you can get to the garden through the sun-room door.","vi":"Và bạn có thể ra vườn qua cửa phòng tắm nắng."},{"time":67420,"en":"Lovely.","vi":"Tuyệt vời."},{"time":69020,"en":"I've always liked the idea of outdoor space with a lawn.","vi":"Tôi luôn thích ý tưởng về không gian ngoài trời với bãi cỏ."},{"time":74000,"en":"I do a bit of gardening myself.","vi":"Tôi cũng tự mình làm vườn một chút."},{"time":76180,"en":"What about the kitchen?","vi":"Còn về nhà bếp thì sao?"},{"time":78200,"en":"It's fully-fitted - so it includes a cooker and a dishwasher and all the other things you'd expect in a kitchen.","vi":"Nó được trang bị đầy đủ - vì vậy nó bao gồm bếp nấu, máy rửa bát và tất cả những thứ khác mà bạn mong đợi trong một nhà bếp."},{"time":84840,"en":"You can also get to the outside space through the kitchen door.","vi":"Bạn cũng có thể ra không gian bên ngoài qua cửa bếp."},{"time":88160,"en":"That sounds great, not having to buy a cooker and dishwasher.","vi":"Nghe thật tuyệt, không phải mua bếp và máy rửa bát."},{"time":92380,"en":"Yes, it would be perfect for you. I should add that there's a garage and a short driveway.","vi":"Vâng, nó sẽ rất phù hợp với bạn. Tôi nên nói thêm rằng có một gara và một đường lái xe ngắn."},{"time":98560,"en":"Oh, that's very useful. My husband usually drives to work, but I mostly use public transport.","vi":"Ồ, điều đó rất hữu ích. Chồng tôi thường lái xe đi làm, nhưng tôi chủ yếu sử dụng phương tiện giao thông công cộng."},{"time":105460,"en":"Well, regarding transport, it's only five minutes from Edgely Station and there are regular buses to the town centre, so it's very well connected.","vi":"Về giao thông, nó chỉ cách ga Edgely năm phút và có xe buýt thường xuyên đến trung tâm thị trấn, vì vậy nó rất thuận tiện."},{"time":114720,"en":"That's excellent!","vi":"Tuyệt vời!"},{"time":115840,"en":"So, would you like to arrange a viewing?","vi":"Vậy, bạn có muốn sắp xếp xem nhà không?"},{"time":119400,"en":"I'm free tomorrow morning. Is 11 o'clock OK?","vi":"Tôi rảnh vào sáng mai. 11 giờ được không?"},{"time":124660,"en":"Oh, no, I'm sorry. I'm busy then.","vi":"Ồ, không, tôi xin lỗi. Lúc đó tôi bận."},{"time":127240,"en":"How about one o'clock then, or one forty-five?","vi":"Vậy thì khoảng một giờ hoặc một giờ bốn mươi lăm thì sao?"},{"time":130800,"en":"Estateagent: One o'clock would be best for me.","vi":"Người môi giới: Một giờ sẽ tốt nhất cho tôi."},{"time":133880,"en":"OK, great. Let's meet then. Oh, my name is Caroline Prendergast. My number is 07945 872310.","vi":"OK, tuyệt vời. Vậy hẹn gặp bạn lúc đó. Ồ, tên tôi là Caroline Prendergast. Số của tôi là 07945 872310."},{"time":148040,"en":"I'm Peter Eliot.","vi":"Tôi là Peter Eliot."},{"time":149800,"en":"Is that with two Ts?","vi":"Có hai chữ T không?"},{"time":151940,"en":"No, one: E-L-I-O-T. My number is 07863 905073.","vi":"Không, một chữ thôi: E-L-I-O-T. Số của tôi là 07863 905073."},{"time":161200,"en":"That's 07863 905073.","vi":"Đó là 07863 905073."},{"time":166560,"en":"I look forward to seeing you then.","vi":"Tôi mong được gặp bạn lúc đó."},{"time":168340,"en":"OK. Goodbye.","vi":"OK. Tạm biệt."},{"time":169860,"en":"Goodbye.","vi":"Tạm biệt."}]}},{"id":"listening_u3_41","title":"Cities and Structures: recording 2","actTitle":"Luyện tập: Recording 2","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120890/?view=embed","pType":"listen_passage","probTitle":"Cities and Structures: recording 2","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset2_2.mp3","youtubeId":"","subs":[{"time":0,"en":"Conversation 1","vi":"Đoạn hội thoại 1"},{"time":2980,"en":"How much is that altogether?","vi":"Tổng cộng là bao nhiêu tiền?"},{"time":5500,"en":"That's £53.72, please.","vi":"Tổng cộng là 53,72 bảng Anh, thưa quý khách."},{"time":8700,"en":"Sorry, did you say £43.72?","vi":"Xin lỗi, bạn nói là 43,72 bảng Anh phải không?"},{"time":12940,"en":"No, £53.72.","vi":"Không, 53,72 bảng Anh."},{"time":15420,"en":"Conversation 2","vi":"Đoạn hội thoại 2"},{"time":19780,"en":"So how far is it to Paris?","vi":"Vậy từ đây đến Paris bao xa?"},{"time":22080,"en":"I've just checked. It's 472 km.","vi":"Tôi vừa kiểm tra xong. Là 472 km."},{"time":26260,"en":"472 km? That's a long way. Are you sure you want to drive?","vi":"472 km? Đường dài đấy. Anh chắc là muốn lái xe đi à?"},{"time":31960,"en":"Conversation 3","vi":"Đoạn hội thoại 3"},{"time":36220,"en":"Someone left a message for you, MrHenry. He wants to call him on 01897 625730.","vi":"Có người để lại tin nhắn cho ông, ông Henry. Anh ấy muốn gọi cho ông theo số 01897 625730."},{"time":44900,"en":"Sorry, I didn't get all that. Did you say 01857 629730? No, it's 01897625730.","vi":"Xin lỗi, tôi nghe không rõ. Bạn nói là 01857 629730 phải không? Không, là 01897 625730."},{"time":62060,"en":"Conversation 4","vi":"Đoạn hội thoại 4"},{"time":64420,"en":"So how big is the football field?","vi":"Vậy sân bóng đá rộng bao nhiêu?"},{"time":67060,"en":"It's 110 m by 55 m.","vi":"Nó dài 110 mét và rộng 55 mét."},{"time":71000,"en":"110 m long and 55 m wide? That's quite big.","vi":"Dài 110 mét và rộng 55 mét? Khá lớn đấy."},{"time":76540,"en":"Conversation 5","vi":"Đoạn hội thoại 5"},{"time":79980,"en":"Can I book a place on the course on Saturday, please?","vi":"Tôi có thể đặt một chỗ trong khóa học vào thứ Bảy được không?"},{"time":84600,"en":"Certainly madam. What's your membership number? It's B1074.","vi":"Chắc chắn rồi thưa bà. Số thành viên của bà là gì? Là B1074."},{"time":90200,"en":"Sorry, did you say D1074?","vi":"Xin lỗi, bạn nói là D1074 phải không?"},{"time":92620,"en":"No, B1074.","vi":"Không, B1074."},{"time":95540,"en":"Oh, OK, thank you.","vi":"Ồ, được rồi, cảm ơn bạn."}]}},{"id":"listening_u3_42","title":"Cities and Structures: recording 3","actTitle":"Luyện tập: Recording 3","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120891/?view=embed","pType":"listen_passage","probTitle":"Cities and Structures: recording 3","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset2_3.mp3","youtubeId":"","subs":[{"time":0,"en":"Hello. I'm Peter Eliot. You must be Ms Prendergast. Yes, that's right.","vi":"Xin chào. Tôi là Peter Eliot. Chắc hẳn đây là cô Prendergast. Vâng, đúng vậy."},{"time":6840,"en":"So, this is the property.","vi":"Vậy, đây là bất động sản này."},{"time":9020,"en":"Oh, I just wanted to check one thing-the price. If I remember rightly, it's £340,000.","vi":"Ồ, tôi chỉ muốn kiểm tra một điều - giá cả. Nếu tôi nhớ không nhầm thì là 340.000 bảng."},{"time":16920,"en":"Actually, it's £350,000 at the moment, but we can discuss that later if you like it.","vi":"Thực ra, hiện tại là 350.000 bảng, nhưng chúng ta có thể thảo luận về điều đó sau nếu anh thích nó."},{"time":23960,"en":"As you can see, the front garden is very well kept.","vi":"Như anh thấy, khu vườn phía trước được chăm sóc rất kỹ lưỡng."},{"time":27660,"en":"Yes. The owners have taken very good care of it.","vi":"Vâng. Chủ nhà đã chăm sóc nó rất tốt."},{"time":31680,"en":"Shall we go in? Follow me. Here's the hall and the front lounge to the left.","vi":"Chúng ta vào trong nhé? Đi theo tôi. Đây là hành lang và phòng khách phía trước bên trái."},{"time":43140,"en":"Hmm, yes. It's very nice. What are the dimensions?","vi":"Hmm, vâng. Rất đẹp. Kích thước là bao nhiêu?"},{"time":48820,"en":"It's 4.3 m by 3.28 m. That's very spacious for a smaller lounge.","vi":"Là 4,3 m nhân 3,28 m. Như vậy là rất rộng rãi so với một phòng khách nhỏ."},{"time":55880,"en":"Hmm, yes. 4.3 m long and 3.28 m wide. Can we go through to the second lounge?","vi":"Hmm, vâng. Dài 4,3 m và rộng 3,28 m. Chúng ta có thể đi qua phòng khách thứ hai không?"},{"time":68640,"en":"Certainly. If you'd like to follow me.","vi":"Chắc chắn rồi. Mời anh đi theo tôi."},{"time":73520,"en":"Oh, it's lovely. What's the size of this room?","vi":"Ôi, thật đáng yêu. Kích thước của căn phòng này là bao nhiêu?"},{"time":77580,"en":"Er, let's see ... the second lounge ... er ... it's 6.5 m x 4.25 m. And you can see the sun-room at the back and the garden.","vi":"Ờ, để xem nào... phòng khách thứ hai... ờ... là 6,5 m x 4,25 m. Và anh có thể thấy phòng tắm nắng ở phía sau và khu vườn."},{"time":90460,"en":"Can we go and have a look?","vi":"Chúng ta có thể đi xem được không?"},{"time":91980,"en":"Of course.","vi":"Đương nhiên rồi."},{"time":92940,"en":"As you can see, there's enough room here for some plants and two sofas.","vi":"Như anh thấy, có đủ chỗ ở đây cho một vài chậu cây và hai chiếc ghế sofa."},{"time":100580,"en":"You could even put a dining suite here.","vi":"Anh thậm chí có thể đặt một bộ bàn ăn ở đây."},{"time":103120,"en":"That would be perfect for cooler days.","vi":"Sẽ thật hoàn hảo cho những ngày mát mẻ."},{"time":106300,"en":"I love it!","vi":"Tôi thích nó!"},{"time":107600,"en":"And as you can see, there's a patio and a large lawn with flowers round the edges.","vi":"Và như anh thấy, có một hàng hiên và một bãi cỏ lớn với hoa xung quanh các mép."},{"time":113000,"en":"What are the dimensions of the garden?","vi":"Kích thước của khu vườn là bao nhiêu?"},{"time":115500,"en":"It's 30 m long and 10 m wide.","vi":"Dài 30 m và rộng 10 m."},{"time":119460,"en":"30 m by 10 m? That's a good size for a family. It would be lovely in summer.","vi":"30 m nhân 10 m? Đó là một kích thước tốt cho một gia đình. Sẽ rất tuyệt vào mùa hè."},{"time":127280,"en":"Of course. Walk this way. Would you like to look upstairs?","vi":"Đương nhiên rồi. Đi lối này. Anh có muốn xem tầng trên không?"},{"time":130500,"en":"Yes, OK.","vi":"Vâng, được."},{"time":133560,"en":"Here's the main bedroom.","vi":"Đây là phòng ngủ chính."},{"time":134940,"en":"It's 4.91 m x 3.95 m - perfect for a large double bed.","vi":"Là 4,91 m x 3,95 m - hoàn hảo cho một chiếc giường đôi lớn."},{"time":142760,"en":"Oh, sorry, that's 4.91 m long and 3.95 m wide.","vi":"Ồ, xin lỗi, dài 4,91 m và rộng 3,95 m."},{"time":149120,"en":"And there's an en-suite bathroom here, though it only has a shower unit and not a big bath like the main bathroom.","vi":"Và có một phòng tắm riêng ở đây, mặc dù nó chỉ có vòi sen chứ không có bồn tắm lớn như phòng tắm chính."},{"time":157180,"en":"That would come in very useful when we all get up to get ready for school or work.","vi":"Điều đó sẽ rất hữu ích khi tất cả chúng ta thức dậy để chuẩn bị đi học hoặc đi làm."},{"time":161920,"en":"Yes, that's a real positive.","vi":"Vâng, đó là một điểm cộng thực sự."},{"time":164740,"en":"Here's The second bedroom.","vi":"Đây là phòng ngủ thứ hai."},{"time":167380,"en":"It's 4.2 m x 3.55 m - ideal for children to share.","vi":"Là 4,2 m x 3,55 m - lý tưởng cho trẻ em ở chung."},{"time":175440,"en":"4.2 m long and 3.55 m wide? OK, that's good. Yes, it's got plenty of room to play in.","vi":"Dài 4,2 m và rộng 3,55 m? OK, tốt đấy. Vâng, có rất nhiều không gian để chơi."},{"time":188960,"en":"And here's the last bedroom, which is 3.25 m x 2.5 m. It would be ideal for a child.","vi":"Và đây là phòng ngủ cuối cùng, có kích thước 3,25 m x 2,5 m. Nó sẽ lý tưởng cho một đứa trẻ."},{"time":198160,"en":"Yes, it would be fine for my older daughter.","vi":"Vâng, nó sẽ phù hợp với con gái lớn của tôi."},{"time":201640,"en":"The bathroom is just over here. It's got a large bath as well as a shower fitting.","vi":"Phòng tắm ở ngay đằng kia. Nó có một bồn tắm lớn cũng như vòi sen."},{"time":208380,"en":"Great! It's just what we need.","vi":"Tuyệt vời! Đúng là thứ chúng ta cần."},{"time":211580,"en":"So, would you like to put in an offer?","vi":"Vậy, anh có muốn đưa ra một lời đề nghị không?"},{"time":214560,"en":"Yes, please.","vi":"Vâng, làm ơn."},{"time":215960,"en":"This is the best property I've seen so far.","vi":"Đây là bất động sản tốt nhất tôi từng thấy cho đến nay."},{"time":219420,"en":"I don't think I'll find a more suitable one.","vi":"Tôi không nghĩ mình sẽ tìm được một cái nào phù hợp hơn."},{"time":221620,"en":"Wonderful! If you'd like to come back to the office, I can take your details and arrange everything.","vi":"Tuyệt vời! Nếu anh muốn quay lại văn phòng, tôi có thể lấy thông tin của anh và sắp xếp mọi thứ."}]}},{"id":"listening_u3_43","title":"Cities and Structures: recording 4","actTitle":"Luyện tập: Recording 4","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120892/?view=embed","pType":"listen_passage","probTitle":"Cities and Structures: recording 4","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset2_4.mp3","youtubeId":"","subs":[{"time":0,"en":"So, Ms Prendergast, let me take your details. I'll just enter your name. How do you spell it?","vi":"Vậy, thưa cô Prendergast, để tôi lấy thông tin của cô. Tôi sẽ nhập tên của cô. Cô đánh vần như thế nào ạ?"},{"time":7460,"en":"P-R-E-N-D-E-R-G-A-S-T.","vi":"P-R-E-N-D-E-R-G-A-S-T."},{"time":15680,"en":"OK, that's it.","vi":"OK, xong rồi ạ."},{"time":17580,"en":"And what's your present address?","vi":"Địa chỉ hiện tại của cô là gì ạ?"},{"time":20120,"en":"52, Lanchester Road.","vi":"Số 52, đường Lanchester."},{"time":23460,"en":"That's L-A-N-C-H-E-S-T-E-R.","vi":"Đó là L-A-N-C-H-E-S-T-E-R."},{"time":29780,"en":"It's in the Riverside part of town.","vi":"Nó ở khu Riverside của thị trấn."},{"time":33420,"en":"The postcode is KE7 8UD.","vi":"Mã bưu điện là KE7 8UD."},{"time":39940,"en":"And your home phone number?","vi":"Số điện thoại nhà của cô là gì ạ?"},{"time":41860,"en":"01594 398210.","vi":"01594 398210."},{"time":48560,"en":"And I've got your mobile number: 07945 872310.","vi":"Và tôi có số điện thoại di động của cô: 07945 872310."},{"time":56740,"en":"Yes, that's right.","vi":"Vâng, đúng rồi ạ."},{"time":57940,"en":"OK. Now the house is on the market for £350,000, but I know that the owners would be happy to accept a close offer as it's been on for a few months.","vi":"OK. Hiện tại ngôi nhà đang được rao bán với giá 350.000 bảng, nhưng tôi biết chủ nhà sẽ vui vẻ chấp nhận một mức giá gần với giá đó vì nó đã được rao bán vài tháng rồi."},{"time":69780,"en":"What would your first offer be?","vi":"Mức giá đầu tiên cô muốn trả là bao nhiêu ạ?"},{"time":72220,"en":"I think £340,000 would be fair.","vi":"Tôi nghĩ 340.000 bảng sẽ là hợp lý."},{"time":76780,"en":"OK.","vi":"OK."},{"time":77540,"en":"I'll put that offer to them and we'll see what they say.","vi":"Tôi sẽ đưa ra mức giá đó cho họ và chúng ta xem họ nói gì."},{"time":81240,"en":"Now, usually buyers have a mortgage arranged with a bank - a loan to buy the house - so that we can quickly complete the sale.","vi":"Thông thường, người mua sẽ có một khoản thế chấp được sắp xếp với ngân hàng - một khoản vay để mua nhà - để chúng ta có thể nhanh chóng hoàn tất việc bán."},{"time":89580,"en":"Do you have one arranged yet?","vi":"Cô đã thu xếp được khoản vay nào chưa ạ?"},{"time":91940,"en":"We've spoken to our bank and they're happy to offer us what we need, up to £300,000.","vi":"Chúng tôi đã nói chuyện với ngân hàng của mình và họ sẵn lòng cung cấp cho chúng tôi những gì chúng tôi cần, lên đến 300.000 bảng."},{"time":100140,"en":"We also have a 15% deposit in our bank account - about £52,000 - so that won't be a problem.","vi":"Chúng tôi cũng có khoản tiền đặt cọc 15% trong tài khoản ngân hàng của mình - khoảng 52.000 bảng Anh - vì vậy điều đó sẽ không thành vấn đề."},{"time":109920,"en":"And is anyone buying your house?","vi":"Và có ai mua nhà của cô không ạ?"},{"time":112380,"en":"Will the sellers of this property need to wait for you to sell yours?","vi":"Người bán bất động sản này có cần đợi cô bán nhà của mình không?"},{"time":116580,"en":"No.","vi":"Không ạ."},{"time":117140,"en":"We sold it a couple of months ago and we're staying with relatives, so we're ready to move in as soon as the sale is completed.","vi":"Chúng tôi đã bán nó vài tháng trước và chúng tôi đang ở với người thân, vì vậy chúng tôi sẵn sàng chuyển vào ngay sau khi việc bán hoàn tất."},{"time":125840,"en":"So, when do you think you can get an answer on the offer?","vi":"Vậy, khi nào cô nghĩ mình có thể nhận được câu trả lời về mức giá?"},{"time":129620,"en":"I should be able to get one tomorrow.","vi":"Tôi sẽ có thể nhận được vào ngày mai."},{"time":132020,"en":"Then, if they agree, we can do things quite quickly.","vi":"Vậy thì, nếu họ đồng ý, chúng ta có thể tiến hành mọi việc khá nhanh chóng."},{"time":136020,"en":"Your bank will do the survey - you know, send someone to check the house is in good condition and at the right price - and, if that's OK, we can then prepare the contracts for you and the seller to sign.","vi":"Ngân hàng của cô sẽ thực hiện việc khảo sát - cô biết đấy, gửi người đến kiểm tra xem ngôi nhà có ở trong tình trạng tốt và với mức giá phù hợp hay không - và nếu mọi thứ ổn thỏa, chúng ta có thể chuẩn bị hợp đồng để cô và người bán ký."},{"time":149700,"en":"How long do you think the sale will take after that?","vi":"Cô nghĩ việc bán sẽ mất bao lâu sau đó?"},{"time":152820,"en":"Well, it's difficult to say.","vi":"Chà, thật khó để nói."},{"time":154620,"en":"If things go well, we should complete it in about two months at the most.","vi":"Nếu mọi việc suôn sẻ, chúng ta sẽ hoàn thành nó trong khoảng tối đa hai tháng."},{"time":159660,"en":"Most sales take about two months.","vi":"Hầu hết các giao dịch mua bán mất khoảng hai tháng."},{"time":162000,"en":"However, if there are any problems, it could take longer, but we hope it won't be more than three months.","vi":"Tuy nhiên, nếu có bất kỳ vấn đề gì, có thể mất nhiều thời gian hơn, nhưng chúng tôi hy vọng sẽ không quá ba tháng."},{"time":169140,"en":"For example, part of the house, like the roof, might be in bad condition and might need some work.","vi":"Ví dụ: một phần của ngôi nhà, như mái nhà, có thể ở trong tình trạng tồi tệ và có thể cần sửa chữa."},{"time":175560,"en":"Or there might be plans for a new road in the local area.","vi":"Hoặc có thể có kế hoạch xây dựng một con đường mới trong khu vực địa phương."},{"time":179440,"en":"Anything like that can delay the sale, but most of our sales go through quickly.","vi":"Bất cứ điều gì như vậy đều có thể trì hoãn việc bán, nhưng hầu hết các giao dịch mua bán của chúng tôi đều diễn ra nhanh chóng."},{"time":184440,"en":"Oh, I hope nothing like that happens!","vi":"Ồ, tôi hy vọng không có điều gì như vậy xảy ra!"},{"time":187180,"en":"We're really looking forward to moving in soon.","vi":"Chúng tôi thực sự mong muốn được chuyển vào sớm."},{"time":189940,"en":"It's not easy living a long time with relatives, and my husband has a long journey to get to work, but those aren't the things I'm really worried about.","vi":"Việc sống lâu dài với người thân không hề dễ dàng, và chồng tôi phải đi làm xa, nhưng đó không phải là những điều tôi thực sự lo lắng."},{"time":201560,"en":"If we can move in before the end of the summer, it'll be much easier for the children to go to their new school.","vi":"Nếu chúng tôi có thể chuyển vào trước khi kết thúc mùa hè, lũ trẻ sẽ dễ dàng hơn nhiều khi đến trường mới."},{"time":209180,"en":"That's why I hope we can complete everything on time.","vi":"Đó là lý do tại sao tôi hy vọng chúng ta có thể hoàn thành mọi thứ đúng thời hạn."},{"time":212640,"en":"Don't worry.","vi":"Đừng lo lắng."},{"time":213640,"en":"I don't see any problems with this sale, so I'm quite sure you'll be in the house by then.","vi":"Tôi không thấy bất kỳ vấn đề gì với việc bán này, vì vậy tôi khá chắc chắn rằng cô sẽ ở trong nhà vào thời điểm đó."},{"time":219200,"en":"So, just to go over things again: talk to the sellers tomorrow.","vi":"Vậy, để xem lại mọi thứ một lần nữa: hãy nói chuyện với người bán vào ngày mai."},{"time":223740,"en":"If they accept your offer then we can continue.","vi":"Nếu họ chấp nhận mức giá của cô thì chúng ta có thể tiếp tục."},{"time":226580,"en":"If they don't, you'll need to put in a higher one quickly, but we should be able to agree by the end of the week.","vi":"Nếu họ không chấp nhận, cô sẽ cần nhanh chóng đưa ra mức giá cao hơn, nhưng chúng ta sẽ có thể đạt được thỏa thuận vào cuối tuần."},{"time":233800,"en":"Then you ask your bank to send someone to check the house.","vi":"Sau đó, cô yêu cầu ngân hàng của mình cử người đến kiểm tra ngôi nhà."},{"time":237560,"en":"If that's all OK, the next step is to prepare the contracts for you and the seller to sign, and we should complete the sale soon after that.","vi":"Nếu mọi thứ đều ổn, bước tiếp theo là chuẩn bị hợp đồng để cô và người bán ký, và chúng ta sẽ hoàn tất việc bán ngay sau đó."},{"time":246840,"en":"Wonderful! I'll look forward to your call tomorrow. Bye.","vi":"Tuyệt vời! Tôi sẽ chờ cuộc gọi của anh vào ngày mai. Tạm biệt."},{"time":251580,"en":"Bye.","vi":"Tạm biệt."}]}},{"id":"listening_u3_44","title":"Relaxing and Playing: recording 1","actTitle":"Luyện tập: Recording 1","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120893/?view=embed","pType":"listen_passage","probTitle":"Relaxing and Playing: recording 1","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset2_5.mp3","youtubeId":"","subs":[{"time":0,"en":"Hi.","vi":"Chào bạn."},{"time":1220,"en":"This is Jeff here.","vi":"Jeff đây."},{"time":2580,"en":"I'm calling you all about the inter-college sports competition at the South Hinton Sports Centre next week.","vi":"Tôi gọi cho các bạn về cuộc thi đấu thể thao giữa các trường đại học tại Trung tâm Thể thao South Hinton vào tuần tới."},{"time":8760,"en":"I'm really sorry but there's been a change of plan.","vi":"Tôi rất tiếc phải thông báo rằng đã có sự thay đổi trong kế hoạch."},{"time":11920,"en":"We can't have the competition at the centre because of the flooding last week after all the rain.","vi":"Chúng ta không thể tổ chức cuộc thi tại trung tâm như dự kiến vì trận lụt tuần trước sau những ngày mưa lớn."},{"time":16860,"en":"It damaged a lot of our equipment and also the floors in some of the rooms.","vi":"Nó đã làm hỏng rất nhiều thiết bị của chúng tôi và cả sàn nhà ở một số phòng."},{"time":21540,"en":"Luckily, I contacted the North Hinton Sports Centre and they've kindly agreed to let us use their centre and their equipment for the competition, so I'm phoning to give you directions on how to get there and instructions about what to do there to prepare.","vi":"May mắn thay, tôi đã liên hệ với Trung tâm Thể thao North Hinton và họ đã đồng ý cho chúng ta sử dụng trung tâm và thiết bị của họ cho cuộc thi, vì vậy tôi gọi điện để chỉ đường cho các bạn đến đó và hướng dẫn những việc cần làm để chuẩn bị."},{"time":35820,"en":"You'll need to meet the others there next Tuesday at about nine o'clock to get the centre ready.","vi":"Các bạn cần gặp những người khác ở đó vào khoảng chín giờ sáng thứ Ba tới để chuẩn bị trung tâm."},{"time":41440,"en":"OK, as I'm not sure if you know how to get to North Hinton, I'll give you directions avoiding the town centre, because it can be quite busy in the morning.","vi":"Được rồi, vì tôi không chắc các bạn có biết đường đến North Hinton không, nên tôi sẽ chỉ đường đi tránh trung tâm thị trấn, vì buổi sáng ở đó khá đông đúc."},{"time":50420,"en":"First, come out of our sports centre into Lily Road.","vi":"Đầu tiên, đi ra khỏi trung tâm thể thao của chúng ta vào đường Lily."},{"time":53860,"en":"Turn left and go about two hundred metres and you come to a roundabout.","vi":"Rẽ trái và đi khoảng hai trăm mét, bạn sẽ đến một vòng xuyến."},{"time":59600,"en":"You see a sign to Hinton saying turn left, but that takes you into the centre of town, so don't take that one.","vi":"Bạn sẽ thấy một biển báo chỉ đường đến Hinton nói rẽ trái, nhưng đường đó sẽ đưa bạn vào trung tâm thị trấn, vì vậy đừng đi theo hướng đó."},{"time":66980,"en":"Go straight over that roundabout and you come to a crossroads.","vi":"Đi thẳng qua vòng xuyến đó và bạn sẽ đến một ngã tư."},{"time":70580,"en":"The left turn here also takes you into the centre, so don't take that one either.","vi":"Rẽ trái ở đây cũng sẽ đưa bạn vào trung tâm, vì vậy cũng đừng đi theo hướng đó."},{"time":75240,"en":"Carry on for about a kilometre.","vi":"Tiếp tục đi khoảng một ki-lô-mét."},{"time":78140,"en":"The road goes up onto a flyover over the motorway to Longchester.","vi":"Đường sẽ đi lên một cầu vượt qua đường cao tốc đến Longchester."},{"time":82700,"en":"After the flyover, you come to the junction with Bramley Road.","vi":"Sau cầu vượt, bạn sẽ đến ngã ba giao với đường Bramley."},{"time":86980,"en":"This is where you go left, because that takes you round the town to the sports centre.","vi":"Đây là nơi bạn rẽ trái, vì đường đó sẽ đưa bạn vòng quanh thị trấn đến trung tâm thể thao."},{"time":91360,"en":"Carry on for about five hundred metres.","vi":"Tiếp tục đi khoảng năm trăm mét."},{"time":94980,"en":"Then you go left round a bend and just after the bend you see a petrol station on the left.","vi":"Sau đó bạn rẽ trái vòng qua một khúc cua và ngay sau khúc cua bạn sẽ thấy một trạm xăng ở bên trái."},{"time":101180,"en":"The turning for Hinton is just after that at the traffic lights, so make sure you lookout for it.","vi":"Lối rẽ vào Hinton nằm ngay sau đó ở chỗ đèn giao thông, vì vậy hãy chú ý tìm nó."},{"time":106580,"en":"Turn right into West Road and carry on.","vi":"Rẽ phải vào đường West và tiếp tục đi."},{"time":110940,"en":"The sports centre is on Green Lane, which is just past the Woodland Hotel on the right.","vi":"Trung tâm thể thao nằm trên đường Green Lane, ngay sau Khách sạn Woodland ở bên phải."},{"time":116560,"en":"You can't miss it.","vi":"Bạn không thể bỏ lỡ nó đâu."},{"time":118100,"en":"There's a car park there so you shouldn't have a problem parking.","vi":"Ở đó có bãi đậu xe nên bạn sẽ không gặp vấn đề gì khi đỗ xe."},{"time":121080,"en":"Please don't be late as we have a lot to do.","vi":"Xin vui lòng đừng đến muộn vì chúng ta có rất nhiều việc phải làm."}]}},{"id":"listening_u3_45","title":"Relaxing and Playing: recording 2","actTitle":"Luyện tập: Recording 2","youtubeId":"","htmlContent":"","problem":{"probUrl":"https://study4.com/problems/120894/?view=embed","pType":"listen_passage","probTitle":"Relaxing and Playing: recording 2","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset2_6.mp3","youtubeId":"","subs":[{"time":0,"en":"Now, about the equipment.","vi":"Bây giờ, về phần thiết bị."},{"time":2400,"en":"For the badminton in the Dean Room, there are two nets in the storeroom to set up and you know what to do so it shouldn't take you long.","vi":"Đối với môn cầu lông ở Phòng Dean, có hai lưới trong kho để lắp đặt và bạn biết phải làm gì nên sẽ không mất nhiều thời gian đâu."},{"time":10100,"en":"The players will bring their own racquets with them, but there are some spare ones, so take them into the badminton room as well, just in case.","vi":"Người chơi sẽ tự mang theo vợt của họ, nhưng có một vài cái dự phòng, nên cứ mang chúng vào phòng cầu lông luôn cho chắc."},{"time":18360,"en":"There are also a couple of boxes of shuttlecocks if we need them.","vi":"Cũng có một vài hộp cầu lông nếu chúng ta cần dùng đến."},{"time":22600,"en":"For the basketball in the afternoon, you only need to bring in the balls because the nets are always up and ready, so you can do that between the sports events.","vi":"Đối với môn bóng rổ vào buổi chiều, bạn chỉ cần mang bóng vào thôi vì lưới luôn được giăng sẵn rồi, bạn có thể làm việc đó giữa các sự kiện thể thao."},{"time":31460,"en":"In the Carsley Room, you'll have to get the gymnastics equipment in place in the morning.","vi":"Ở Phòng Carsley, bạn sẽ phải chuẩn bị sẵn thiết bị thể dục dụng cụ vào buổi sáng."},{"time":36160,"en":"That means bringing in the vaulting horse and putting it in the middle.","vi":"Điều đó có nghĩa là mang ngựa nhảy vào và đặt nó ở giữa phòng."},{"time":39620,"en":"Put one mat in front and another behind the horse, and have some other mats ready for the floor exercises.","vi":"Đặt một tấm thảm phía trước và một tấm phía sau ngựa, và chuẩn bị sẵn một vài tấm thảm khác cho các bài tập trên sàn."},{"time":46580,"en":"Then on the side, set up the bars for the gymnastics.","vi":"Sau đó ở bên cạnh, dựng xà để tập thể dục dụng cụ."},{"time":50180,"en":"There are two sets of bars: one for the men and one for the women.","vi":"Có hai bộ xà: một cho nam và một cho nữ."},{"time":54660,"en":"The other equipment, such as the rings and pommel horse, are already in there, so you don't need to worry about those.","vi":"Các thiết bị khác, chẳng hạn như vòng treo và ngựa gỗ có tay cầm, đã ở đó rồi, nên bạn không cần phải lo về chúng."},{"time":61700,"en":"It's also a good idea to bring in the tables and nets for the table tennis at the same time.","vi":"Cũng nên mang bàn và lưới cho môn bóng bàn vào cùng lúc."},{"time":67140,"en":"There's enough room to leave them folded while the gymnastics is going on, but you'll be able to set them up more quickly later.","vi":"Có đủ chỗ để chúng gấp lại trong khi đang diễn ra môn thể dục dụng cụ, nhưng bạn sẽ có thể lắp chúng nhanh hơn sau đó."},{"time":74460,"en":"The players should bring their own bats with them, but there's a box of bats there, so bring those in as well as we might need them.","vi":"Người chơi nên tự mang theo vợt bóng bàn của họ, nhưng có một hộp vợt ở đó, nên cứ mang chúng vào luôn vì có thể chúng ta sẽ cần."},{"time":82960,"en":"For weightlifting, get someone to help you bring in the barbells and the other weights so that you don't try to carry too much.","vi":"Đối với môn cử tạ, hãy nhờ ai đó giúp bạn mang tạ đòn và các loại tạ khác để bạn khỏi phải cố mang quá nhiều."},{"time":89780,"en":"The bench for the bench press should be in there already, so check that it is when you arrive, but you'll need to bring in the stand with the chalk for the lifters to put on their hands.","vi":"Ghế cho bài tập đẩy tạ nằm phải ở đó rồi, nên hãy kiểm tra xem nó có ở đó khi bạn đến, nhưng bạn sẽ cần mang giá đựng phấn để người nâng tạ bôi lên tay."},{"time":100040,"en":"I'll be there at about ten o' clock as I have an appointment first thing, so you should be ready by then.","vi":"Tôi sẽ đến đó vào khoảng mười giờ vì tôi có một cuộc hẹn vào việc đầu tiên, vì vậy bạn nên chuẩn bị sẵn sàng trước lúc đó."},{"time":106340,"en":"We can check everything together and then get ready to welcome the contestants and the spectators.","vi":"Chúng ta có thể cùng nhau kiểm tra mọi thứ và sau đó chuẩn bị sẵn sàng để chào đón các thí sinh và khán giả."},{"time":111840,"en":"I hope everything goes well, and I'm sure we can do it!","vi":"Tôi hy vọng mọi thứ diễn ra tốt đẹp, và tôi chắc chắn rằng chúng ta có thể làm được!"},{"time":114640,"en":"Call me if you need any extra information.","vi":"Gọi cho tôi nếu bạn cần thêm bất kỳ thông tin nào."}]}},{"id":"listening_u3_46","title":"News and Media: recording 1","actTitle":"News and Media: recording 1","youtubeId":"","htmlContent":"","problem":{"pType":"listen_passage","probTitle":"News and Media: recording 1","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset2_7.mp3","subs":[{"time":0,"en":"Hello Simon.","vi":"Chào Simon."},{"time":2080,"en":"Hi Maria.","vi":"Chào Maria."},{"time":3180,"en":"OK. What topic do you think we should choose for the project we're starting next week?","vi":"Được rồi. Bạn nghĩ chúng ta nên chọn chủ đề gì cho dự án mà chúng ta sẽ bắt đầu vào tuần tới?"},{"time":8320,"en":"I think we need to make sure that it's going to last over the next few months so that we can complete the project.","vi":"Tôi nghĩ chúng ta cần đảm bảo rằng nó sẽ kéo dài trong vài tháng tới để chúng ta có thể hoàn thành dự án."},{"time":14720,"en":"Well, there are several possibilities.","vi":"Chà, có một vài khả năng."},{"time":17520,"en":"Have you heard of the Pluto expedition?","vi":"Bạn đã nghe về cuộc thám hiểm sao Diêm Vương chưa?"},{"time":20260,"en":"The spacecraft is about to arrive there and it's going to send back pictures that we've never seen before.","vi":"Tàu vũ trụ sắp đến đó và nó sẽ gửi lại những bức ảnh mà chúng ta chưa từng thấy trước đây."},{"time":26380,"en":"It should be really interesting.","vi":"Nó chắc sẽ rất thú vị."},{"time":28560,"en":"That sounds like a good idea. What do you think, Dr Thornton?","vi":"Nghe có vẻ là một ý kiến hay. Bạn nghĩ sao, Tiến sĩ Thornton?"},{"time":32580,"en":"Well, I'm not so sure about that one.","vi":"Chà, tôi không chắc lắm về cái đó."},{"time":35580,"en":"I mean, it's already been going for ten years and I think we should look at something which is planned for the future but hasn't started yet.","vi":"Ý tôi là, nó đã diễn ra trong mười năm rồi và tôi nghĩ chúng ta nên xem xét một cái gì đó được lên kế hoạch cho tương lai nhưng chưa bắt đầu."},{"time":44820,"en":"It would give you a better chance to study it in depth and do far more analysis for your monthly update reports.","vi":"Nó sẽ cho bạn cơ hội tốt hơn để nghiên cứu sâu hơn và phân tích nhiều hơn cho các báo cáo cập nhật hàng tháng của bạn."},{"time":52100,"en":"I don't think that's a problem. There'll be a lot of coverage on the news over the next few weeks.","vi":"Tôi không nghĩ đó là một vấn đề. Sẽ có rất nhiều thông tin về nó trên tin tức trong vài tuần tới."},{"time":57740,"en":"Hmm ... that's true ... but we really need something to last for a few months.","vi":"Hmm ... đúng vậy ... nhưng chúng ta thực sự cần một cái gì đó kéo dài trong vài tháng."},{"time":63560,"en":"On second thoughts, maybe Dr Thornton's right.","vi":"Nghĩ lại thì, có lẽ Tiến sĩ Thornton đúng."},{"time":66920,"en":"Perhaps we should look at something which hasn't started yet.","vi":"Có lẽ chúng ta nên xem xét một cái gì đó chưa bắt đầu."},{"time":70480,"en":"Isn't there something I heard about a new Mars expedition?","vi":"Có phải tôi đã nghe về một cuộc thám hiểm sao Hỏa mới không?"},{"time":73940,"en":"I think there's a group of people out in America somewhere who are preparing for a trip to Mars.","vi":"Tôi nghĩ có một nhóm người ở đâu đó ở Mỹ đang chuẩn bị cho một chuyến đi tới sao Hỏa."},{"time":79520,"en":"Yes. It was in the news last week. They've built a sort of camp","vi":"Đúng vậy. Nó đã có trên tin tức tuần trước. Họ đã xây dựng một loại trại"},{"time":84360,"en":"in the desert in Arizona. There are ten people living there for six","vi":"ở sa mạc Arizona. Có mười người sống ở đó trong sáu"},{"time":88460,"en":"months, just like they would be together on the trip to Mars and after they arrive there.","vi":"tháng, giống như họ sẽ ở cùng nhau trong chuyến đi tới sao Hỏa và sau khi họ đến đó."},{"time":93740,"en":"That'd be ideal.","vi":"Điều đó thật lý tưởng."},{"time":95560,"en":"Six months is just right for you.","vi":"Sáu tháng là vừa đủ cho bạn."},{"time":98100,"en":"You could follow their progress and how the project develops.","vi":"Bạn có thể theo dõi tiến trình của họ và cách dự án phát triển."},{"time":102280,"en":"From what I know, the Pluto project is already a success, but with the Mars one you can assess how successful it is as it progresses and you can write it up for your final report.","vi":"Theo những gì tôi biết, dự án sao Diêm Vương đã thành công, nhưng với dự án sao Hỏa, bạn có thể đánh giá mức độ thành công của nó khi nó tiến triển và bạn có thể viết nó cho báo cáo cuối cùng của mình."},{"time":114600,"en":"Hmm ... yeah ...that sounds promising.","vi":"Hmm ... yeah ... nghe có vẻ đầy hứa hẹn."},{"time":117880,"en":"OK, but before we decide, I'd just like to mention one more.","vi":"Được rồi, nhưng trước khi chúng ta quyết định, tôi chỉ muốn đề cập đến một điều nữa."},{"time":122500,"en":"I heard that the Chinese are planning an expedition to the moon.","vi":"Tôi nghe nói rằng người Trung Quốc đang lên kế hoạch cho một cuộc thám hiểm lên mặt trăng."},{"time":126120,"en":"What?","vi":"Cái gì?"},{"time":127320,"en":"Another man or woman on the moon?","vi":"Lại một người đàn ông hay phụ nữ khác trên mặt trăng sao?"},{"time":129740,"en":"That's already been done.","vi":"Điều đó đã được thực hiện rồi."},{"time":130780,"en":"I don't think the moon's particularly interesting these days.","vi":"Tôi không nghĩ mặt trăng đặc biệt thú vị vào thời điểm này."},{"time":135640,"en":"Simon has a point.","vi":"Simon nói có lý."},{"time":138160,"en":"I mean, the Chinese are coming up now and they've got some new ideas.","vi":"Ý tôi là, người Trung Quốc đang trỗi dậy và họ có một số ý tưởng mới."},{"time":143480,"en":"I don't think they're sending","vi":"Tôi không nghĩ họ đang gửi"},{"time":144940,"en":"any astronauts.","vi":"bất kỳ phi hành gia nào."},{"time":146400,"en":"I think it's just an expedition with robots and machines to find the best place to start a colony.","vi":"Tôi nghĩ đó chỉ là một cuộc thám hiểm với robot và máy móc để tìm địa điểm tốt nhất để bắt đầu một thuộc địa."},{"time":153080,"en":"Yes, but I don't think that's particularly interesting.","vi":"Vâng, nhưng tôi không nghĩ điều đó đặc biệt thú vị."},{"time":156660,"en":"I mean, no one has ever seen Pluto close up and no one has tried to go to Mars, so I think they'd be more interesting expeditions to do.","vi":"Ý tôi là, chưa ai từng nhìn thấy sao Diêm Vương cận cảnh và chưa ai cố gắng lên sao Hỏa, vì vậy tôi nghĩ đó sẽ là những cuộc thám hiểm thú vị hơn để thực hiện."},{"time":165760,"en":"You have a point. Perhaps it would be better to focus on one of the other two.","vi":"Bạn có lý. Có lẽ tốt hơn là nên tập trung vào một trong hai cái còn lại."},{"time":170860,"en":"OK, if you ask me, I'd prefer to see how a group of people get along living together in a difficult situation, like they'll be doing in Arizona in preparation for their trip.","vi":"Được rồi, nếu bạn hỏi tôi, tôi thích xem một nhóm người hòa thuận sống cùng nhau trong một tình huống khó khăn như họ sẽ làm ở Arizona để chuẩn bị cho chuyến đi của họ như thế nào."},{"time":183300,"en":"I think you'd get far more out of that, but the final decision is yours.","vi":"Tôi nghĩ bạn sẽ học được nhiều hơn từ điều đó, nhưng quyết định cuối cùng là của bạn."},{"time":188380,"en":"What do you think?","vi":"Bạn nghĩ sao?"},{"time":189640,"en":"I agree. I'd prefer to go for that one.","vi":"Tôi đồng ý. Tôi muốn chọn cái đó hơn."},{"time":192620,"en":"So that's agreed then. Good. Let's make a start.","vi":"Vậy là đã thống nhất rồi. Tốt. Hãy bắt đầu thôi."},{"time":196740,"en":"Excellent.","vi":"Tuyệt vời."},{"time":197460,"en":"I'll make a note of that.","vi":"Tôi sẽ ghi chú lại điều đó."},{"time":199480,"en":"We'll meet again next Wednesday and you can give me your project outline.","vi":"Chúng ta sẽ gặp lại nhau vào thứ Tư tới và bạn có thể cho tôi xem phác thảo dự án của bạn."},{"time":204800,"en":"I'm looking forward to seeing it.","vi":"Tôi rất mong được xem nó."}],"probUrl":"https://study4.com/problems/120895/?view=embed"}},{"id":"listening_u3_47","title":"News and Media: recording 2","actTitle":"News and Media: recording 2","youtubeId":"","htmlContent":"","problem":{"pType":"listen_passage","probTitle":"News and Media: recording 2","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset2_8.mp3","subs":[{"time":0,"en":"So, now that the project has ended, we need to review it and I can help you plan your final assignments.","vi":"Vậy là dự án đã kết thúc, chúng ta cần xem xét lại và tôi có thể giúp các bạn lên kế hoạch cho các bài tập cuối cùng."},{"time":8200,"en":"Yes.","vi":"Vâng."},{"time":9000,"en":"I never thought that of the ten who started, only six would finish in the end, and it was really hard for them to get through the whole programme.","vi":"Tôi không ngờ rằng trong số mười người bắt đầu, cuối cùng chỉ có sáu người hoàn thành, và việc vượt qua toàn bộ chương trình thực sự rất khó khăn đối với họ."},{"time":17400,"en":"So, what have we learnt?","vi":"Vậy, chúng ta đã học được gì?"},{"time":19820,"en":"Well, I've got lots of data on the environmental systems and life support, and that's the key focus of my project report, especially considering the events last week, when the whole system came close to failing.","vi":"Chà, tôi có rất nhiều dữ liệu về hệ thống môi trường và hỗ trợ sự sống, và đó là trọng tâm chính trong báo cáo dự án của tôi, đặc biệt là khi xem xét các sự kiện tuần trước, khi toàn bộ hệ thống gần như bị lỗi."},{"time":34500,"en":"Right.","vi":"Đúng vậy."},{"time":35460,"en":"When the life support system went offline for four hours, they had to really race to fix it.","vi":"Khi hệ thống hỗ trợ sự sống ngừng hoạt động trong bốn giờ, họ đã phải chạy đua để sửa chữa nó."},{"time":41900,"en":"If that happened on a real trip, it'd be a disaster!","vi":"Nếu điều đó xảy ra trong một chuyến đi thực tế, thì đó sẽ là một thảm họa!"},{"time":45620,"en":"They could all die.","vi":"Tất cả bọn họ có thể chết."},{"time":47220,"en":"I know.","vi":"Tôi biết."},{"time":48360,"en":"It's good that they weren't actually in danger in this project, but I agree, in a real situation people could have been killed.","vi":"Thật tốt là họ không thực sự gặp nguy hiểm trong dự án này, nhưng tôi đồng ý, trong một tình huống thực tế, mọi người có thể đã thiệt mạng."},{"time":56840,"en":"Who would've thought that it'd be on the front page and the first item on the evening bulletin?","vi":"Ai có thể ngờ rằng nó sẽ nằm trên trang nhất và là mục đầu tiên trong bản tin tối?"},{"time":62200,"en":"It shows how much interest there's been in the project.","vi":"Điều đó cho thấy dự án này đã nhận được sự quan tâm lớn như thế nào."},{"time":65520,"en":"Anyway, I'm hoping to use the data to design a new system if it's not too difficult.","vi":"Dù sao thì, tôi hy vọng sẽ sử dụng dữ liệu này để thiết kế một hệ thống mới nếu nó không quá khó khăn."},{"time":71080,"en":"That would be challenging but fascinating at the same time.","vi":"Điều đó sẽ đầy thách thức nhưng đồng thời cũng rất hấp dẫn."},{"time":75160,"en":"I think you'll do well with that, Simon.","vi":"Tôi nghĩ bạn sẽ làm tốt việc đó, Simon."},{"time":77220,"en":"Personally, I'd love to focus on the particularly interesting and useful data on the health of the participants.","vi":"Cá nhân tôi, tôi rất muốn tập trung vào dữ liệu đặc biệt thú vị và hữu ích về sức khỏe của những người tham gia."},{"time":85220,"en":"I think it'd be worthwhile writing about the physical effects of the project, you know, howthey kept healthy in the long term, even though they became ill sometimes, but also about the psychological effects of living in an enclosed group like that.","vi":"Tôi nghĩ rằng việc viết về những ảnh hưởng vật lý của dự án sẽ rất đáng giá, bạn biết đấy, làm thế nào họ giữ được sức khỏe về lâu dài, ngay cả khi đôi khi họ bị ốm, mà còn về những ảnh hưởng tâm lý của việc sống trong một nhóm khép kín như vậy."},{"time":102020,"en":"It'd be interesting to see if any of them will have any long-term health changes.","vi":"Sẽ rất thú vị để xem liệu ai trong số họ có bất kỳ thay đổi sức khỏe lâu dài nào không."},{"time":106760,"en":"Would either of you like to take that on?","vi":"Ai trong số các bạn có muốn đảm nhận việc đó không?"},{"time":109480,"en":"Well, I'm not sure if I could take that on as well as producing an assessment of the life support issues.","vi":"Chà, tôi không chắc liệu tôi có thể đảm nhận việc đó cũng như đưa ra đánh giá về các vấn đề hỗ trợ sự sống hay không."},{"time":115740,"en":"I feel that those are more significant in view of the current developments in technology to support this kind of expedition.","vi":"Tôi cảm thấy rằng những điều đó quan trọng hơn khi xem xét những phát triển hiện tại trong công nghệ để hỗ trợ loại thám hiểm này."},{"time":122300,"en":"I've already looked at the latest reports in the popular science magazines, though there are some fascinating articles due in the next Journal of Space Studies.","vi":"Tôi đã xem các báo cáo mới nhất trên các tạp chí khoa học phổ biến, mặc dù có một số bài báo hấp dẫn sẽ xuất hiện trong Tạp chí Nghiên cứu Không gian tiếp theo."},{"time":131600,"en":"Maybe I could beat them to it!","vi":"Có lẽ tôi có thể vượt mặt họ!"},{"time":133520,"en":"That'd be a great idea, Simon - to write an article - but for me, the main thing is the efficiency of the crew and how well they managed to perform their duties.","vi":"Đó sẽ là một ý tưởng tuyệt vời, Simon - viết một bài báo - nhưng đối với tôi, điều chính là hiệu quả của phi hành đoàn và mức độ họ quản lý để thực hiện nhiệm vụ của mình tốt như thế nào."},{"time":144120,"en":"I'm focusing specifically on their abilities to work under the stresses of living in an enclosed environment.","vi":"Tôi đang tập trung đặc biệt vào khả năng làm việc của họ dưới áp lực của cuộc sống trong một môi trường khép kín."},{"time":151280,"en":"I'm going to analyse how well they managed to maintain their effectiveness over time.","vi":"Tôi sẽ phân tích xem họ đã xoay sở để duy trì hiệu quả của mình theo thời gian tốt như thế nào."},{"time":156400,"en":"That's interesting.","vi":"Điều đó thật thú vị."},{"time":157340,"en":"Maybe you could include a section on the psychological effects of long-term isolation.","vi":"Có lẽ bạn có thể bao gồm một phần về những ảnh hưởng tâm lý của việc cô lập lâu dài."},{"time":163160,"en":"Remember the incident early in the project?","vi":"Bạn còn nhớ sự cố vào đầu dự án không?"},{"time":166200,"en":"It'd be very interesting to follow that up with the latest developments and results.","vi":"Sẽ rất thú vị để theo dõi điều đó với những phát triển và kết quả mới nhất."},{"time":171400,"en":"I can give you some of the latest research on the subject from other studies for you to compare.","vi":"Tôi có thể cung cấp cho bạn một số nghiên cứu mới nhất về chủ đề này từ các nghiên cứu khác để bạn so sánh."},{"time":176680,"en":"I think it would significantly enhance your research and findings.","vi":"Tôi nghĩ nó sẽ nâng cao đáng kể nghiên cứu và những phát hiện của bạn."},{"time":180660,"en":"OK. That sounds like a good idea.","vi":"Được rồi. Nghe có vẻ là một ý kiến hay."},{"time":183460,"en":"It shouldn't be too difficult to develop a wider theme to include the psychological studies.","vi":"Không quá khó để phát triển một chủ đề rộng hơn để bao gồm các nghiên cứu tâm lý."},{"time":188760,"en":"I'll work out a structure for next week.","vi":"Tôi sẽ xây dựng một cấu trúc cho tuần tới."},{"time":190880,"en":"That's great, Maria.","vi":"Tuyệt vời, Maria."},{"time":192220,"en":"We can meet again next Wednesday and I can help you structure it.","vi":"Chúng ta có thể gặp lại nhau vào thứ Tư tới và tôi có thể giúp bạn cấu trúc nó."},{"time":197020,"en":"And what about you, Simon?","vi":"Còn bạn thì sao, Simon?"},{"time":199260,"en":"Do you think you have enough?","vi":"Bạn có nghĩ bạn có đủ chưa?"},{"time":201320,"en":"Yes, thanks, DrThornton.","vi":"Vâng, cảm ơn Tiến sĩ Thornton."},{"time":203500,"en":"I've got plenty to think about, especially as the study of life support was the main aim of the whole project.","vi":"Tôi có rất nhiều điều để suy nghĩ, đặc biệt là vì việc nghiên cứu về hỗ trợ sự sống là mục tiêu chính của toàn bộ dự án."},{"time":210440,"en":"I could include some observations about the effects on the physical and mental health of the participants, as it's relevant.","vi":"Tôi có thể bao gồm một số quan sát về những ảnh hưởng đến sức khỏe thể chất và tinh thần của những người tham gia, vì nó có liên quan."},{"time":217860,"en":"That's fine, then. Is there anything else you want to discuss?","vi":"Vậy thì tốt. Các bạn có muốn thảo luận thêm gì nữa không?"},{"time":222380,"en":"One thing I'm really surprised about is that they managed to complete the project without any extra costs.","vi":"Một điều tôi thực sự ngạc nhiên là họ đã hoàn thành dự án mà không tốn thêm bất kỳ chi phí nào."},{"time":229100,"en":"Everyone was expecting it to go over the original $10 million.","vi":"Mọi người đều mong đợi nó vượt quá 10 triệu đô la ban đầu."},{"time":233440,"en":"I personally thought that it might even go up to something like $12 million.","vi":"Cá nhân tôi nghĩ rằng nó thậm chí có thể lên tới khoảng 12 triệu đô la."},{"time":237880,"en":"Well, actually, it says here that the final cost was $9.5 million, so they saved half a million in the end.","vi":"Chà, thực ra, ở đây nói rằng chi phí cuối cùng là 9,5 triệu đô la, vì vậy cuối cùng họ đã tiết kiệm được nửa triệu đô la."},{"time":247180,"en":"They could give that to us to fund our projects! Is there anything about future developments?","vi":"Họ có thể đưa số tiền đó cho chúng ta để tài trợ cho các dự án của chúng ta! Có gì về những phát triển trong tương lai không?"},{"time":253240,"en":"Well, I heard that they're going to share their research results with government and private organisations.","vi":"Chà, tôi nghe nói rằng họ sẽ chia sẻ kết quả nghiên cứu của họ với các tổ chức chính phủ và tư nhân."},{"time":260120,"en":"There are a few other organisations planning trips to Mars that would love to study the results.","vi":"Có một vài tổ chức khác đang lên kế hoạch cho các chuyến đi lên sao Hỏa, những tổ chức này rất muốn nghiên cứu kết quả."},{"time":266300,"en":"I'm not sure the government is planning anything, but they'd be interested anyway.","vi":"Tôi không chắc chính phủ có đang lên kế hoạch cho bất cứ điều gì không, nhưng dù sao thì họ cũng sẽ quan tâm."},{"time":271240,"en":"What about a follow-up? Are they planning another project?","vi":"Còn về việc tiếp tục thì sao? Họ có đang lên kế hoạch cho một dự án khác không?"},{"time":274900,"en":"Well, depending on the results from this one, they're going to decide whether to have another one that will last a year.","vi":"Chà, tùy thuộc vào kết quả từ dự án này, họ sẽ quyết định xem có nên có một dự án khác kéo dài một năm hay không."},{"time":281840,"en":"Obviously, they'll have to find some more participants.","vi":"Rõ ràng, họ sẽ phải tìm thêm một số người tham gia."},{"time":285200,"en":"Would either of you be interested in taking part?","vi":"Ai trong số các bạn có hứng thú tham gia không?"},{"time":288640,"en":"It depends.","vi":"Tùy thuộc."},{"time":290700,"en":"I wouldn't say no, but I'd have to think a longtime about it.","vi":"Tôi sẽ không từ chối, nhưng tôi sẽ phải suy nghĩ rất lâu về điều đó."},{"time":295320,"en":"I don't know if I'd want to be cut off for so long.","vi":"Tôi không biết liệu tôi có muốn bị cô lập quá lâu như vậy không."},{"time":298080,"en":"I think you should bear it in mind.","vi":"Tôi nghĩ bạn nên ghi nhớ điều đó."},{"time":300340,"en":"It would be so interesting to see how staying in a situation like that for a year affects physical and mental health.","vi":"Sẽ rất thú vị để xem việc ở trong một tình huống như vậy trong một năm ảnh hưởng đến sức khỏe thể chất và tinh thần như thế nào."},{"time":308340,"en":"I'd love to follow your progress myself.","vi":"Tôi rất muốn tự mình theo dõi tiến trình của bạn."},{"time":311400,"en":"I might even volunteer!","vi":"Tôi thậm chí có thể tình nguyện!"},{"time":313400,"en":"What about you, Simon?","vi":"Còn bạn thì sao, Simon?"},{"time":315420,"en":"Oh, you wouldn't catch me inside one of those places!","vi":"Ồ, bạn sẽ không bắt gặp tôi bên trong một trong những nơi đó đâu!"},{"time":319240,"en":"I'll be happy to follow what goes on and see how the whole system works over a year, but definitely from the outside, not the inside ...","vi":"Tôi rất vui được theo dõi những gì đang diễn ra và xem toàn bộ hệ thống hoạt động như thế nào trong một năm, nhưng chắc chắn là từ bên ngoài, không phải bên trong..."},{"time":328860,"en":"I wouldn't mind working for the company, though.","vi":"Mặc dù vậy, tôi không ngại làm việc cho công ty."},{"time":331400,"en":"It'd be great to study it and get paid at the same time!","vi":"Sẽ thật tuyệt nếu được nghiên cứu nó và được trả tiền cùng một lúc!"},{"time":335000,"en":"Well, thank you, both of you.","vi":"Chà, cảm ơn cả hai bạn."},{"time":337140,"en":"You've produced excellent results and I'm looking forward to seeing your final submissions.","vi":"Các bạn đã tạo ra những kết quả xuất sắc và tôi rất mong được xem những bài nộp cuối cùng của các bạn."}],"probUrl":"https://study4.com/problems/120896/?view=embed"}},{"id":"listening_u3_48","title":"Travel and Transportation: recording 1","actTitle":"Travel and Transportation: recording 1","youtubeId":"","htmlContent":"","problem":{"pType":"listen_passage","probTitle":"Travel and Transportation: recording 1","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset2_9.mp3","subs":[{"time":0,"en":"So where are the worst affected places in town?","vi":"Vậy những khu vực nào trong thị trấn bị ảnh hưởng nặng nề nhất?"},{"time":4400,"en":"I would say one of the worst is by the Arts Centre.","vi":"Tôi nghĩ một trong những nơi tệ nhất là khu vực gần Trung tâm Nghệ thuật."},{"time":7580,"en":"I'm not sure about that. Statistics show that the worst place is by the town hall.","vi":"Tôi không chắc về điều đó. Số liệu thống kê cho thấy nơi tệ nhất là khu vực gần tòa thị chính."},{"time":13440,"en":"Well, as most of the traffic comes in from the east of town, that would be the Arts Centre.","vi":"Chà, vì hầu hết xe cộ đi vào từ phía đông thị trấn, nên đó sẽ là Trung tâm Nghệ thuật."},{"time":18400,"en":"The town hall is further over.","vi":"Tòa thị chính nằm ở xa hơn."},{"time":20320,"en":"Actually, Robert, that's not quite right.","vi":"Thực ra, Robert, điều đó không hoàn toàn đúng."},{"time":22660,"en":"The traffic gets quite bad along East Road, further out of town.","vi":"Giao thông trở nên khá tệ dọc theo Đường East, xa hơn ra khỏi thị trấn."},{"time":27080,"en":"It's been getting worse over the last year or so, especially by the Starview Cinema.","vi":"Nó ngày càng tệ hơn trong khoảng một năm trở lại đây, đặc biệt là khu vực gần Rạp chiếu phim Starview."},{"time":32780,"en":"The Starview?","vi":"Starview ư?"},{"time":33880,"en":"Yes, haven't you ever been there?","vi":"Phải, bạn chưa từng đến đó à?"},{"time":35720,"en":"No, I haven't. I thought it was by the main roundabout.","vi":"Chưa, tôi chưa từng. Tôi cứ tưởng nó ở gần bùng binh chính."},{"time":38840,"en":"Well, in actual fact, it's by the junction of East Road and Station Road.","vi":"Thực tế là, nó ở gần ngã tư Đường East và Đường Station."},{"time":43340,"en":"That's where the traffic has been getting really bad, especially in the mornings.","vi":"Đó là nơi giao thông trở nên thực sự tệ, đặc biệt là vào buổi sáng."},{"time":47860,"en":"It's especially bad for the buses coming from the station as they can't turn right into East Road to get to the centre.","vi":"Đặc biệt tệ cho xe buýt đi từ nhà ga vì chúng không thể rẽ phải vào Đường East để đến trung tâm."},{"time":54680,"en":"OK. So that's the first bad spot, then.","vi":"OK. Vậy đó là điểm tệ đầu tiên."},{"time":57580,"en":"Yes.","vi":"Đúng vậy."},{"time":58440,"en":"Sometimes the traffic backs up for almost a kilometre, and in the evening, when everyone is trying to get home, it gets bad all the way back to the main roundabout.","vi":"Đôi khi giao thông ùn tắc gần một kilomet, và vào buổi tối, khi mọi người cố gắng về nhà, nó trở nên tệ đến tận bùng binh chính."},{"time":68420,"en":"It's bad in the morning and the afternoon as the traffic also comes in from the north and the south.","vi":"Trời tệ vào buổi sáng và buổi chiều vì giao thông cũng đến từ phía bắc và phía nam."},{"time":74620,"en":"Remember, there's Liverton to the north and Scotsfield to the south and a lot of people commute to both places for work.","vi":"Hãy nhớ rằng, có Liverton ở phía bắc và Scotsfield ở phía nam và rất nhiều người đi làm ở cả hai nơi."},{"time":81720,"en":"That's true.","vi":"Đúng vậy."},{"time":82980,"en":"I live a few kilometres down the Scotsfield Road and I have a lot of trouble coming in during the morning rush hour.","vi":"Tôi sống cách Đường Scotsfield vài kilomet và tôi gặp rất nhiều khó khăn khi vào thị trấn vào giờ cao điểm buổi sáng."},{"time":89420,"en":"It's especially bad just by the Arts Centre where the road comes into the roundabout.","vi":"Đặc biệt tệ ở ngay Trung tâm Nghệ thuật, nơi con đường dẫn vào bùng binh."},{"time":94400,"en":"The buses have a lot of trouble getting through that as well.","vi":"Xe buýt cũng gặp rất nhiều khó khăn khi đi qua đó."},{"time":97440,"en":"OK ... so those are the two main hotspots, the Starview and the Arts Centre.","vi":"OK ... vậy đó là hai điểm nóng chính, Starview và Trung tâm Nghệ thuật."},{"time":104000,"en":"I've marked them on the map.","vi":"Tôi đã đánh dấu chúng trên bản đồ."},{"time":105580,"en":"And that leaves the town hall.","vi":"Và còn lại tòa thị chính."},{"time":107120,"en":"Hmm ... yes.","vi":"Hmm ... đúng vậy."},{"time":108620,"en":"I mean, the whole area around Central Park is bad, but you're right, the town hall side of Central Park is the worst in the area.","vi":"Ý tôi là, toàn bộ khu vực xung quanh Công viên Trung tâm đều tệ, nhưng bạn nói đúng, phía tòa thị chính của Công viên Trung tâm là tệ nhất trong khu vực."},{"time":116940,"en":"It's bad enough right by the shopping centre on the other side of Central Park, but it's particularly bad on the town hall side, with all the heavy lorries coming into the centre from the industrial estate on the west side of town.","vi":"Đã đủ tệ ở ngay trung tâm mua sắm ở phía bên kia của Công viên Trung tâm, nhưng đặc biệt tệ ở phía tòa thị chính, với tất cả những xe tải nặng đi vào trung tâm từ khu công nghiệp ở phía tây thị trấn."},{"time":130160,"en":"They usually make their deliveries in the morning rush hour.","vi":"Họ thường giao hàng vào giờ cao điểm buổi sáng."},{"time":133380,"en":"So you're saying that if we stopped them from coming in early to the area by Central Park where the town hall is, that would make the traffic a lot lighter?","vi":"Vậy bạn nói rằng nếu chúng ta ngăn họ đến sớm khu vực gần Công viên Trung tâm, nơi có tòa thị chính, thì giao thông sẽ thông thoáng hơn nhiều?"},{"time":140940,"en":"I'm sure it would.","vi":"Tôi chắc chắn là vậy."},{"time":142540,"en":"Now that we've established where the worst places are, let's have a look at the proposals.","vi":"Bây giờ chúng ta đã xác định được những nơi tệ nhất, hãy xem xét các đề xuất."}],"probUrl":"https://study4.com/problems/120897/?view=embed"}},{"id":"listening_u3_49","title":"Travel and Transportation: recording 2","actTitle":"Travel and Transportation: recording 2","youtubeId":"","htmlContent":"","problem":{"pType":"listen_passage","probTitle":"Travel and Transportation: recording 2","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset2_10.mp3","subs":[{"time":0,"en":"The first proposal is to introduce bus and cycle lanes on the roads coming into each of the trouble spots, but I'm not really sure that that will solve the problem by itself.","vi":"Đề xuất đầu tiên là đưa làn xe buýt và xe đạp vào các con đường dẫn đến từng điểm nóng giao thông, nhưng tôi không chắc chắn rằng điều đó sẽ tự giải quyết được vấn đề."},{"time":10860,"en":"What do you mean? I think it's a really good idea. I think it would help a lot.","vi":"Ý bạn là gì? Tôi nghĩ đó là một ý tưởng thực sự tốt. Tôi nghĩ nó sẽ giúp ích rất nhiều."},{"time":15140,"en":"On the face of it, yes, but in actual fact it can make things worse.","vi":"겉으로는 그렇겠지만 실제로 nó có thể làm cho mọi thứ tồi tệ hơn."},{"time":20120,"en":"There've been a few studies of towns and cities where they've put schemes like that into operation and one serious problem is that car traffic tends to go off into the areas around town where people live, and that causes more traffic in places where there haven't been problems before.","vi":"Đã có một vài nghiên cứu về các thị trấn và thành phố nơi họ đưa những kế hoạch như vậy vào hoạt động và một vấn đề nghiêm trọng là giao thông xe hơi có xu hướng đi vào các khu vực xung quanh thị trấn nơi mọi người sinh sống, và điều đó gây ra nhiều giao thông hơn ở những nơi chưa từng có vấn đề trước đây."},{"time":37080,"en":"Drivers think they can find emptier roads in residential areas and it just sends the problem there instead.","vi":"Các tài xế nghĩ rằng họ có thể tìm thấy những con đường vắng vẻ hơn trong khu dân cư và nó chỉ đẩy vấn đề đến đó mà thôi."},{"time":43080,"en":"Hmm ... I hadn't thought about that. What about the second one, a park and ride scheme?","vi":"Hmm ... Tôi đã không nghĩ về điều đó. Còn đề xuất thứ hai thì sao, một kế hoạch đỗ xe và đi xe buýt (park and ride)?"},{"time":48620,"en":"Well, we build car parks on the edge of town where the main roads come in.","vi":"Chà, chúng ta xây dựng các bãi đậu xe ở rìa thị trấn nơi các con đường chính đi vào."},{"time":53920,"en":"When cars come into town from further out, they can park there cheaply and take special buses into the town centre.","vi":"Khi xe hơi đi vào thị trấn từ xa hơn, họ có thể đậu xe ở đó với giá rẻ và đi xe buýt đặc biệt vào trung tâm thị trấn."},{"time":61400,"en":"It's been quite popular in a few other towns around the country.","vi":"Nó khá phổ biến ở một vài thị trấn khác trên khắp đất nước."},{"time":64840,"en":"In some places, yes, but not in all.","vi":"Ở một số nơi thì có, nhưng không phải ở tất cả."},{"time":67200,"en":"I've had a look at some of those schemes.","vi":"Tôi đã xem xét một số kế hoạch đó."},{"time":69840,"en":"The main problem is lack of take-up.","vi":"Vấn đề chính là thiếu sự hưởng ứng."},{"time":72140,"en":"Drivers just don't use them.","vi":"Các tài xế chỉ là không sử dụng chúng."},{"time":73860,"en":"A lot of these car parks stay empty for a long time and the buses are often less than half-full.","vi":"Rất nhiều bãi đậu xe này vẫn trống trong một thời gian dài và xe buýt thường không đầy một nửa."},{"time":79800,"en":"It's not always a good use of public money, especially when drivers avoid using the services and prefer to come into town and pay higher parking fees.","vi":"Đó không phải lúc nào cũng là một cách sử dụng tốt tiền công, đặc biệt là khi các tài xế tránh sử dụng các dịch vụ và thích đi vào thị trấn và trả phí đậu xe cao hơn."},{"time":88380,"en":"You've got a point there.","vi":"Bạn nói có lý đấy."},{"time":89860,"en":"We need to bear that in mind.","vi":"Chúng ta cần ghi nhớ điều đó."},{"time":91720,"en":"Do you think either of the other proposals would work?","vi":"Bạn có nghĩ rằng một trong hai đề xuất khác sẽ hiệu quả không?"},{"time":94880,"en":"I think the pedestrian area is a very interesting proposal.","vi":"Tôi nghĩ khu vực dành cho người đi bộ là một đề xuất rất thú vị."},{"time":98640,"en":"We could turn the whole of the centre, including the shopping areas, into a pedestrian zone and put in a one-way system round it.","vi":"Chúng ta có thể biến toàn bộ trung tâm, bao gồm cả khu mua sắm, thành khu vực dành cho người đi bộ và thiết lập hệ thống một chiều xung quanh nó."},{"time":106620,"en":"I'm not convinced that would work.","vi":"Tôi không tin rằng điều đó sẽ hiệu quả."},{"time":108520,"en":"You'd move all the traffic further out of the centre and cause more problems.","vi":"Bạn sẽ đẩy tất cả giao thông ra xa trung tâm hơn và gây ra nhiều vấn đề hơn."},{"time":112380,"en":"But the biggest problem would actually be with the shops themselves.","vi":"Nhưng vấn đề lớn nhất thực sự sẽ là với chính các cửa hàng."},{"time":116280,"en":"It's fine to stop traffic around the shopping areas, but there would be huge problems with deliveries.","vi":"Việc ngăn chặn giao thông xung quanh khu mua sắm thì tốt thôi, nhưng sẽ có những vấn đề lớn với việc giao hàng."},{"time":121420,"en":"Some shops could go out of business if they have difficulty getting lorries in with their goods.","vi":"Một số cửa hàng có thể phá sản nếu họ gặp khó khăn trong việc đưa xe tải chở hàng của họ vào."},{"time":126040,"en":"Right. I'll note that as well. The last one is a new tram system.","vi":"Được rồi. Tôi sẽ ghi chú điều đó. Cái cuối cùng là một hệ thống xe điện mới."},{"time":132060,"en":"We'll have to lay down a new line through the centre of town and also from north to south.","vi":"Chúng ta sẽ phải đặt một tuyến đường mới xuyên qua trung tâm thị trấn và cả từ bắc xuống nam."},{"time":137620,"en":"It's quite a popular solution to traffic problems.","vi":"Đó là một giải pháp khá phổ biến cho các vấn đề giao thông."},{"time":140720,"en":"That may be so, but the main problem with that kind of project is the expense.","vi":"Có thể là như vậy, nhưng vấn đề chính với loại dự án đó là chi phí."},{"time":145540,"en":"The initial financial requirements would be huge and so would the maintenance expenses.","vi":"Các yêu cầu tài chính ban đầu sẽ rất lớn và chi phí bảo trì cũng vậy."},{"time":150200,"en":"It might well be far more than the council is prepared to spend on a solution.","vi":"Nó có thể vượt quá xa số tiền mà hội đồng sẵn sàng chi cho một giải pháp."},{"time":155000,"en":"I'll note that as well. Which brings us to the next point, the question of cost ...","vi":"Tôi cũng sẽ ghi chú điều đó. Điều đó đưa chúng ta đến điểm tiếp theo, câu hỏi về chi phí ..."}],"probUrl":"https://study4.com/problems/120898/?view=embed"}},{"id":"listening_u3_50","title":"Travel and Transportation: recording 3","actTitle":"Travel and Transportation: recording 3","youtubeId":"","htmlContent":"","problem":{"pType":"listen_passage","probTitle":"Travel and Transportation: recording 3","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset2_11.mp3","subs":[{"time":0,"en":"I've got the details on the cost of each of these projects.","vi":"Tôi đã có thông tin chi tiết về chi phí của từng dự án này."},{"time":4580,"en":"The tram system comes out as the costliest.","vi":"Hệ thống xe điện là tốn kém nhất."},{"time":7500,"en":"It would cost over £20 million just to prepare the route and to lay the lines down, including widening the roads.","vi":"Sẽ tốn hơn 20 triệu bảng chỉ để chuẩn bị tuyến đường và lắp đặt đường ray, bao gồm cả việc mở rộng đường."},{"time":16500,"en":"Then there's the cost of buying the trams themselves and organising the system.","vi":"Sau đó là chi phí mua xe điện và tổ chức hệ thống."},{"time":21160,"en":"And what does it all come to?","vi":"Vậy tổng cộng là bao nhiêu?"},{"time":22980,"en":"No less than £30 million in the end.","vi":"Không dưới 30 triệu bảng."},{"time":27180,"en":"At least that's what they need to try to keep the costs down to.","vi":"Ít nhất đó là những gì họ cần để cố gắng giữ chi phí ở mức thấp nhất."},{"time":30500,"en":"£30 million? That does seem a lot. I thought it was closer to","vi":"30 triệu bảng? Có vẻ nhiều đấy. Tôi nghĩ nó gần với"},{"time":34980,"en":"£25 million, but clearly it isn't. And what about the cheapest?","vi":"25 triệu bảng, nhưng rõ ràng là không phải. Vậy còn cái nào rẻ nhất?"},{"time":40000,"en":"Well, it seems that it'd be either the bus and cycle lanes plan or the park and ride scheme.","vi":"Chà, có vẻ như đó là kế hoạch làn đường dành cho xe buýt và xe đạp hoặc dự án đỗ xe và đi xe buýt."},{"time":46260,"en":"At the moment, it looks like the bus and cycle lanes might be the least expensive overall.","vi":"Hiện tại, có vẻ như làn đường dành cho xe buýt và xe đạp có thể là ít tốn kém nhất."},{"time":52140,"en":"The changes wouldn't be so large.","vi":"Những thay đổi sẽ không quá lớn."},{"time":54540,"en":"They estimate around £8 million to set up the signs, paint the roads and so on, and at least another £2 million or so to make the changes.","vi":"Họ ước tính khoảng 8 triệu bảng để thiết lập biển báo, sơn đường, v.v., và ít nhất khoảng 2 triệu bảng nữa để thực hiện các thay đổi."},{"time":64720,"en":"So you're saying it's around £10 million?","vi":"Vậy ý bạn là khoảng 10 triệu bảng?"},{"time":68080,"en":"That seems quite reasonable.","vi":"Có vẻ khá hợp lý."},{"time":69920,"en":"What about the park and ride scheme?","vi":"Vậy còn dự án đỗ xe và đi xe buýt thì sao?"},{"time":72300,"en":"Well, there are sites which have been identified for development to build the car parks, and as they're not in the centre, it won't cost too much to buy them, probably around £5 million.","vi":"Chà, có những địa điểm đã được xác định để phát triển xây dựng bãi đỗ xe, và vì chúng không ở trung tâm nên việc mua chúng sẽ không tốn quá nhiều, có lẽ khoảng 5 triệu bảng."},{"time":83720,"en":"Then they'd just need to lay out the car parks and put in bus shelters, which should be around £6 or £7 million and then get the buses.","vi":"Sau đó, họ chỉ cần bố trí các bãi đỗ xe và đặt nhà chờ xe buýt, sẽ vào khoảng 6 hoặc 7 triệu bảng, sau đó thuê xe buýt."},{"time":93200,"en":"If they rent them, they could keep the costs down to around £3 million.","vi":"Nếu họ thuê chúng, họ có thể giữ chi phí ở mức khoảng 3 triệu bảng."},{"time":98020,"en":"So, if I'm right, that comes to around £15 million for the park and ride in total.","vi":"Vậy, nếu tôi đúng, tổng cộng sẽ vào khoảng 15 triệu bảng cho việc đỗ xe và đi xe buýt."},{"time":103280,"en":"And then there's the pedestrian and one-way system.","vi":"Và sau đó là hệ thống dành cho người đi bộ và đường một chiều."},{"time":106320,"en":"How does that work out?","vi":"Cái đó thì sao?"},{"time":107700,"en":"That's the second highest.","vi":"Đó là cái tốn kém thứ hai."},{"time":109620,"en":"We'd have to re-route all the traffic while the works are done, then change the roads along the routes to make it safer for cyclists, which is around £12 million.","vi":"Chúng ta sẽ phải định tuyến lại tất cả giao thông trong khi công việc được thực hiện, sau đó thay đổi các con đường dọc theo các tuyến đường để làm cho nó an toàn hơn cho người đi xe đạp, khoảng 12 triệu bảng."},{"time":121180,"en":"Then there are the new signs and so on, which comes to about £5 million and also the road painting and maintenance, at around £8 million.","vi":"Sau đó là các biển báo mới, v.v., vào khoảng 5 triệu bảng và cả việc sơn và bảo trì đường, vào khoảng 8 triệu bảng."},{"time":132320,"en":"So that's around £23 million. We might be able to manage that.","vi":"Vậy là khoảng 23 triệu bảng. Chúng ta có thể xoay sở được."},{"time":136620,"en":"Actually, that's £25 million, Robert.","vi":"Thực ra là 25 triệu bảng, Robert."},{"time":140240,"en":"So it is! My mistake. Maths was never my strong point!","vi":"Đúng vậy! Lỗi của tôi. Toán học chưa bao giờ là điểm mạnh của tôi!"}],"probUrl":"https://study4.com/problems/120899/?view=embed"}},{"id":"listening_u3_51","title":"Travel and Transportation: recording 4","actTitle":"Travel and Transportation: recording 4","youtubeId":"","htmlContent":"","problem":{"pType":"listen_passage","probTitle":"Travel and Transportation: recording 4","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset2_12.mp3","subs":[{"time":0,"en":"So we've discussed the negative aspects and costs of these proposals, but now I'd like to look at the real benefits which we think each proposal will bring.","vi":"Vậy là chúng ta đã thảo luận về các khía cạnh tiêu cực và chi phí của những đề xuất này, nhưng bây giờ tôi muốn xem xét những lợi ích thực sự mà chúng ta nghĩ rằng mỗi đề xuất sẽ mang lại."},{"time":10780,"en":"Well, I really think that one of the most important benefits is better public transport.","vi":"Chà, tôi thực sự nghĩ rằng một trong những lợi ích quan trọng nhất là giao thông công cộng tốt hơn."},{"time":16480,"en":"The most important thing is to get more people out of their cars and onto public transport.","vi":"Điều quan trọng nhất là đưa được nhiều người ra khỏi xe hơi của họ và sử dụng giao thông công cộng."},{"time":21120,"en":"Well, three of the proposals would help with that - park and ride, bus and cycle-only routes and the new tram transport system.","vi":"Chà, ba trong số các đề xuất sẽ giúp ích cho việc đó - bãi đỗ xe trung chuyển, các tuyến đường dành riêng cho xe buýt và xe đạp, và hệ thống giao thông bằng xe điện mới."},{"time":28800,"en":"Which do you think would be the best out of those three?","vi":"Bạn nghĩ cái nào sẽ là tốt nhất trong ba cái đó?"},{"time":31880,"en":"I think the bus and cycle routes would be great for town centre transport, but they might push car traffic further out and make it more difficult for buses outside the centre.","vi":"Tôi nghĩ các tuyến đường dành cho xe buýt và xe đạp sẽ rất tốt cho giao thông trung tâm thị trấn, nhưng chúng có thể đẩy giao thông xe hơi ra xa hơn và gây khó khăn hơn cho xe buýt bên ngoài trung tâm."},{"time":41940,"en":"That leads me to think that the tram system would actually improve public transport the most, even though it's the most expensive, as there will be a new form of transport in the centre, without affecting other parts of town.","vi":"Điều đó khiến tôi nghĩ rằng hệ thống xe điện thực sự sẽ cải thiện giao thông công cộng nhiều nhất, mặc dù nó đắt nhất, vì sẽ có một hình thức giao thông mới ở trung tâm, mà không ảnh hưởng đến các khu vực khác của thị trấn."},{"time":53780,"en":"I think you have a good point there.","vi":"Tôi nghĩ bạn có lý đấy."},{"time":56200,"en":"I agree that in the long term it would be the best thing.","vi":"Tôi đồng ý rằng về lâu dài đó sẽ là điều tốt nhất."},{"time":59640,"en":"Do you think that proposal would also increase the number of visitors in town?","vi":"Bạn có nghĩ rằng đề xuất đó cũng sẽ làm tăng số lượng du khách trong thị trấn không?"},{"time":64040,"en":"Well, of course.","vi":"Chà, tất nhiên rồi."},{"time":65520,"en":"Any of the solutions would do that, but I'm not sure if the tram system would be the best.","vi":"Bất kỳ giải pháp nào cũng sẽ làm được điều đó, nhưng tôi không chắc liệu hệ thống xe điện có phải là tốt nhất không."},{"time":70520,"en":"What do you think?","vi":"Bạn nghĩ sao?"},{"time":71420,"en":"I think the park and ride would be better than the tram system for that.","vi":"Tôi nghĩ rằng bãi đỗ xe trung chuyển sẽ tốt hơn hệ thống xe điện cho việc đó."},{"time":75180,"en":"The trams would help people who are already in town, but a park and ride would bring more of them in from outside.","vi":"Xe điện sẽ giúp những người đã ở trong thị trấn, nhưng bãi đỗ xe trung chuyển sẽ đưa nhiều người từ bên ngoài vào hơn."},{"time":82420,"en":"So you think the park and ride would bring most visitors in?","vi":"Vậy bạn nghĩ bãi đỗ xe trung chuyển sẽ thu hút nhiều du khách nhất?"},{"time":85620,"en":"Actually, I think if people know that they can get around the centre more easily, do their shopping and so on, they would come in more.","vi":"Thực ra, tôi nghĩ nếu mọi người biết rằng họ có thể đi lại quanh trung tâm dễ dàng hơn, mua sắm, v.v., thì họ sẽ đến nhiều hơn."},{"time":93620,"en":"So perhaps the pedestrian area and one-way system would be best in that respect.","vi":"Vậy có lẽ khu vực dành cho người đi bộ và hệ thống một chiều sẽ là tốt nhất về mặt đó."},{"time":98940,"en":"True.","vi":"Đúng vậy."},{"time":100300,"en":"I've seen other town centres become really busy when they've put in pedestrian areas, so that's clearly the best way of bringing visitors in.","vi":"Tôi đã thấy các trung tâm thị trấn khác trở nên thực sự nhộn nhịp khi họ xây dựng các khu vực dành cho người đi bộ, vì vậy đó rõ ràng là cách tốt nhất để thu hút du khách."},{"time":107360,"en":"So we agree on that, then.","vi":"Vậy là chúng ta đồng ý về điều đó rồi."},{"time":109140,"en":"And I think that people's health will improve as well as they will be walking around the pedestrian area, rather than driving around town.","vi":"Và tôi nghĩ rằng sức khỏe của mọi người cũng sẽ được cải thiện khi họ đi bộ xung quanh khu vực dành cho người đi bộ, thay vì lái xe quanh thị trấn."},{"time":117000,"en":"Up to a point, yes, but I'm sure you'd agree that encouraging people who do more cycling would help their health far more.","vi":"Đến một mức độ nào đó thì đúng, nhưng tôi chắc chắn bạn sẽ đồng ý rằng việc khuyến khích mọi người đạp xe nhiều hơn sẽ giúp ích cho sức khỏe của họ hơn nhiều."},{"time":123920,"en":"Of course.","vi":"Đương nhiên."},{"time":124840,"en":"Creating bus and cycle-only routes would be the best way of getting people to exercise.","vi":"Việc tạo ra các tuyến đường dành riêng cho xe buýt và xe đạp sẽ là cách tốt nhất để mọi người tập thể dục."},{"time":129700,"en":"It would also help reduce pollution, so even the people who don't cycle will breathe cleaner air.","vi":"Nó cũng sẽ giúp giảm ô nhiễm, vì vậy ngay cả những người không đạp xe cũng sẽ hít thở không khí trong lành hơn."},{"time":136180,"en":"And we agree that producing less pollution is a really important part of this scheme, though I think that the park and ride would be better at doing that than the bus and cycle-only routes.","vi":"Và chúng ta đồng ý rằng việc giảm ô nhiễm là một phần thực sự quan trọng của kế hoạch này, mặc dù tôi nghĩ rằng bãi đỗ xe trung chuyển sẽ làm tốt hơn việc đó so với các tuyến đường dành riêng cho xe buýt và xe đạp."},{"time":145860,"en":"I'm not sure.","vi":"Tôi không chắc."},{"time":147220,"en":"Lots of people would need to use the park and ride to help reduce pollution.","vi":"Rất nhiều người sẽ cần phải sử dụng bãi đỗ xe trung chuyển để giúp giảm ô nhiễm."},{"time":151280,"en":"Bus and cycle-only routes keep cars out of the centre.","vi":"Các tuyến đường dành riêng cho xe buýt và xe đạp giữ xe hơi ở bên ngoài trung tâm."},{"time":154440,"en":"Yes, but if people are encouraged to use the park and ride more, it would produce the best results.","vi":"Đúng vậy, nhưng nếu mọi người được khuyến khích sử dụng bãi đỗ xe trung chuyển nhiều hơn, nó sẽ mang lại kết quả tốt nhất."},{"time":159960,"en":"There would be far fewer cars in the centre and the air would be much cleaner.","vi":"Sẽ có ít xe hơi hơn nhiều ở trung tâm và không khí sẽ trong lành hơn nhiều."},{"time":164120,"en":"Yes, that's true, but that's a lot of work for the council.","vi":"Đúng vậy, nhưng đó là rất nhiều việc cho hội đồng."},{"time":168500,"en":"OK, we'll agree on a park and ride, then.","vi":"OK, vậy chúng ta sẽ đồng ý về bãi đỗ xe trung chuyển."},{"time":170960,"en":"What about safety?","vi":"Vậy còn sự an toàn thì sao?"},{"time":173280,"en":"I'd say the bus and cycle routes would be best from that point of view.","vi":"Tôi muốn nói rằng các tuyến đường dành riêng cho xe buýt và xe đạp sẽ là tốt nhất từ quan điểm đó."},{"time":177120,"en":"Probably. I think I agree with you on that.","vi":"Có lẽ vậy. Tôi nghĩ tôi đồng ý với bạn về điều đó."},{"time":179920,"en":"OK then, so we agree on safety.","vi":"OK vậy, chúng ta đồng ý về sự an toàn."},{"time":182720,"en":"Actually, no.","vi":"Thực ra là không."},{"time":184280,"en":"When I think about it, you have to take pedestrians into account as well.","vi":"Khi tôi nghĩ về nó, bạn cũng phải tính đến người đi bộ."},{"time":187940,"en":"It's safer for cyclists when there are no cars around, but I'm not sure that it's safer for pedestrians.","vi":"Sẽ an toàn hơn cho người đi xe đạp khi không có ô tô xung quanh, nhưng tôi không chắc liệu nó có an toàn hơn cho người đi bộ hay không."},{"time":194360,"en":"They still have to avoid cyclists, who don't always pay attention to pedestrians, so I really think the pedestrian area and one-way system would be safer for them.","vi":"Họ vẫn phải tránh người đi xe đạp, những người không phải lúc nào cũng chú ý đến người đi bộ, vì vậy tôi thực sự nghĩ rằng khu vực dành cho người đi bộ và hệ thống một chiều sẽ an toàn hơn cho họ."},{"time":204180,"en":"Cyclists won't be allowed in the pedestrian areas, so there will only be people walking.","vi":"Người đi xe đạp sẽ không được phép vào khu vực dành cho người đi bộ, vì vậy sẽ chỉ có người đi bộ."},{"time":209460,"en":"Yes, you have a point there. Shall we change that then?","vi":"Ừ, bạn nói có lý. Vậy chúng ta đổi ý nhé?"},{"time":213200,"en":"OK. I'm glad you agree. So, that's all done then. We have all our recommendations!","vi":"OK. Tôi rất vui vì bạn đồng ý. Vậy là xong hết rồi. Chúng ta đã có tất cả các đề xuất của mình!"}],"probUrl":"https://study4.com/problems/120900/?view=embed"}},{"id":"listening_u3_52","title":"Companies and Careers: recording 1","actTitle":"Companies and Careers: recording 1","youtubeId":"","htmlContent":"","problem":{"pType":"listen_passage","probTitle":"Companies and Careers: recording 1","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset2_13.mp3","subs":[{"time":0,"en":"In last week's lecture I talked about employment and aspects related to it, including contracts, income tax and so on.","vi":"Trong bài giảng tuần trước, tôi đã nói về việc làm và các khía cạnh liên quan, bao gồm hợp đồng, thuế thu nhập, v.v."},{"time":8880,"en":"However, people are increasingly looking at other forms of earning a living by working for themselves and being in greater control of their working lives.","vi":"Tuy nhiên, ngày càng có nhiều người tìm kiếm các hình thức kiếm sống khác bằng cách tự làm chủ và kiểm soát cuộc sống làm việc của mình nhiều hơn."},{"time":17240,"en":"Today Dr Korpis and I are going to talk about three different ways in which people can work for themselves.","vi":"Hôm nay, Tiến sĩ Korpis và tôi sẽ nói về ba cách khác nhau để mọi người có thể tự làm chủ."},{"time":24620,"en":"They can set up a company, set up a partnership, or they can work as a sole trader.","vi":"Họ có thể thành lập một công ty, thành lập một công ty hợp danh, hoặc họ có thể làm việc với tư cách là một người kinh doanh cá thể."},{"time":31060,"en":"There are important legal and financial matters to take into consideration when choosing one of these structures as a way of doing business in the UK.","vi":"Có những vấn đề pháp lý và tài chính quan trọng cần xem xét khi lựa chọn một trong các hình thức này như một cách để kinh doanh ở Vương quốc Anh."},{"time":40680,"en":"First, I just want to outline the main differences between these three types of business structure, which are to do with tax and registration.","vi":"Đầu tiên, tôi chỉ muốn phác thảo những khác biệt chính giữa ba loại hình cơ cấu kinh doanh này, liên quan đến thuế và đăng ký."},{"time":49420,"en":"Regarding registration, those wanting to set up a limited liability company have to legally register the company with Companies House, the government department responsible for businesses.","vi":"Về đăng ký, những người muốn thành lập công ty trách nhiệm hữu hạn phải đăng ký hợp pháp công ty với Companies House, cơ quan chính phủ chịu trách nhiệm về các doanh nghiệp."},{"time":61260,"en":"'Limited liability' means that, if the business fails and the owners owe a lot of money, they only lose the money and goods which are in the business, and not their own personal money and goods.","vi":"\"Trách nhiệm hữu hạn\" có nghĩa là, nếu doanh nghiệp thất bại và chủ sở hữu nợ rất nhiều tiền, họ chỉ mất số tiền và hàng hóa có trong doanh nghiệp, chứ không phải tiền và hàng hóa cá nhân của họ."},{"time":74260,"en":"This is because the owners of the company are separate from the company itself.","vi":"Điều này là do chủ sở hữu của công ty tách biệt với chính công ty."},{"time":79080,"en":"On the other hand, a sole trader doesn't need to set up a company; he or she can simply start working without any legal registration.","vi":"Mặt khác, một người kinh doanh cá thể không cần thành lập công ty; người đó có thể chỉ cần bắt đầu làm việc mà không cần đăng ký pháp lý."},{"time":87000,"en":"A partnership can be limited or unlimited.","vi":"Công ty hợp danh có thể là hữu hạn hoặc vô hạn."},{"time":91320,"en":"An unlimited partnership is just like a sole trader, but with two or more partners.","vi":"Một công ty hợp danh vô hạn giống như một người kinh doanh cá thể, nhưng có hai hoặc nhiều đối tác hơn."},{"time":96980,"en":"In this situation, each partner shares expenses and also income.","vi":"Trong tình huống này, mỗi đối tác chia sẻ chi phí và cả thu nhập."},{"time":102520,"en":"A limited liability partnership, or LLP for short, is like a limited company, because it must be legally registered in the same way.","vi":"Một công ty hợp danh trách nhiệm hữu hạn, hay LLP, giống như một công ty trách nhiệm hữu hạn, vì nó phải được đăng ký hợp pháp theo cùng một cách."},{"time":112040,"en":"So just to summarise: with limited liability companies and limited liability partnerships, the owners and the company are separate in legal terms, but with simple partnerships and sole traders, the business and the owner are not legally separate.","vi":"Tóm lại: với các công ty trách nhiệm hữu hạn và công ty hợp danh trách nhiệm hữu hạn, chủ sở hữu và công ty tách biệt về mặt pháp lý, nhưng với các công ty hợp danh đơn giản và người kinh doanh cá thể, doanh nghiệp và chủ sở hữu không tách biệt về mặt pháp lý."},{"time":129500,"en":"The other main difference is to do with money - both with finding money to start your business, and with paying tax.","vi":"Sự khác biệt chính còn lại là về tiền bạc - cả về việc tìm tiền để bắt đầu kinh doanh và về việc nộp thuế."},{"time":136700,"en":"For example, it might be difficult to borrow money from the bank if you're a sole trader, but easier if you have a limited company, as banks trust companies more.","vi":"Ví dụ: có thể khó vay tiền từ ngân hàng nếu bạn là một người kinh doanh cá thể, nhưng dễ dàng hơn nếu bạn có một công ty trách nhiệm hữu hạn, vì các ngân hàng tin tưởng các công ty hơn."},{"time":147420,"en":"Regarding tax, limited companies pay corporation tax, which, unlike income tax, is a tax on business profits, not personal earnings.","vi":"Về thuế, các công ty trách nhiệm hữu hạn nộp thuế doanh nghiệp, không giống như thuế thu nhập, là thuế đánh trên lợi nhuận kinh doanh, không phải thu nhập cá nhân."},{"time":157860,"en":"This is more favourable for companies, as corporation tax is usually less than income tax.","vi":"Điều này có lợi hơn cho các công ty, vì thuế doanh nghiệp thường ít hơn thuế thu nhập."},{"time":164660,"en":"On the other hand, with sole traders and partnerships, whether simple partnerships or limited liability partnerships, the owners must pay income tax, which may be higher than corporation tax.","vi":"Mặt khác, với những người kinh doanh cá thể và công ty hợp danh, cho dù là công ty hợp danh đơn giản hay công ty hợp danh trách nhiệm hữu hạn, chủ sở hữu phải nộp thuế thu nhập, có thể cao hơn thuế doanh nghiệp."}],"probUrl":"https://study4.com/problems/120901/?view=embed"}},{"id":"listening_u3_53","title":"Companies and Careers: recording 2","actTitle":"Companies and Careers: recording 2","youtubeId":"","htmlContent":"","problem":{"pType":"listen_passage","probTitle":"Companies and Careers: recording 2","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset2_14.mp3","subs":[{"time":0,"en":"Thank you, Dr Lethbridge, for your introduction.","vi":"Cảm ơn Tiến sĩ Lethbridge vì lời giới thiệu của ông."},{"time":3660,"en":"I'd now like to move on to the details of each type of business structure and discuss the advantages and disadvantages of each, starting with the sole trader.","vi":"Bây giờ tôi muốn đi vào chi tiết của từng loại hình cơ cấu kinh doanh và thảo luận về ưu và nhược điểm của từng loại, bắt đầu với doanh nghiệp tư nhân."},{"time":14040,"en":"This is simply a person who runs a business alone.","vi":"Đây đơn giản là một người điều hành doanh nghiệp một mình."},{"time":17520,"en":"On the practical side, there's no need to register with Companies House, which means the sole trader is not legally the same as a registered company.","vi":"Về mặt thực tế, không cần đăng ký với Companies House, điều này có nghĩa là doanh nghiệp tư nhân không phải là pháp nhân giống như một công ty đã đăng ký."},{"time":27180,"en":"The trader can simply choose any name and start trading without paying any fees.","vi":"Người kinh doanh có thể chọn bất kỳ tên nào và bắt đầu giao dịch mà không phải trả bất kỳ khoản phí nào."},{"time":32560,"en":"There's no need to register an office, so the trader can even work from home.","vi":"Không cần đăng ký văn phòng, vì vậy người kinh doanh thậm chí có thể làm việc tại nhà."},{"time":38040,"en":"There are also no legal requirements to submit financial accounts to Companies House.","vi":"Cũng không có yêu cầu pháp lý nào về việc nộp báo cáo tài chính cho Companies House."},{"time":43880,"en":"As a result, this is the simplest and most straightforward way to start out in business and work for yourself.","vi":"Do đó, đây là cách đơn giản và dễ dàng nhất để bắt đầu kinh doanh và làm việc cho chính mình."},{"time":51220,"en":"Another benefit of being a sole trader is that you are your own boss.","vi":"Một lợi ích khác của việc là một doanh nghiệp tư nhân là bạn là ông chủ của chính mình."},{"time":56000,"en":"You don't have to answer to anybody else, you make your own decisions and you don't have to share your earnings with a partner.","vi":"Bạn không phải trả lời bất kỳ ai khác, bạn tự đưa ra quyết định của mình và bạn không phải chia sẻ thu nhập của mình với đối tác."},{"time":63300,"en":"However, it doesn't mean that you have to do everything alone.","vi":"Tuy nhiên, điều đó không có nghĩa là bạn phải làm mọi thứ một mình."},{"time":67000,"en":"You can also employ or give contracts to other people to do work for you, though, of course, you need to be aware of regulations regarding employing others.","vi":"Bạn cũng có thể thuê hoặc ký hợp đồng với người khác để làm việc cho bạn, mặc dù, tất nhiên, bạn cần phải biết về các quy định liên quan đến việc thuê người khác."},{"time":77200,"en":"So these are the desirable aspects of being a sole trader, but there are other matters which need careful consideration.","vi":"Vậy đây là những khía cạnh đáng mong muốn của việc trở thành một doanh nghiệp tư nhân, nhưng có những vấn đề khác cần xem xét cẩn thận."},{"time":85540,"en":"When you're in employment, you are taxed at source, which means your employer takes your tax from your earnings every month and sends it to the tax office, so you don't need to worry about it.","vi":"Khi bạn làm công ăn lương, bạn bị đánh thuế tại nguồn, có nghĩa là chủ của bạn sẽ lấy thuế từ thu nhập của bạn mỗi tháng và gửi đến cơ quan thuế, vì vậy bạn không cần phải lo lắng về điều đó."},{"time":96340,"en":"However, as a sole trader, you are self-employed, which means you are responsible for what you earn, what you spend and the tax that you must pay.","vi":"Tuy nhiên, với tư cách là một doanh nghiệp tư nhân, bạn là người tự làm chủ, có nghĩa là bạn chịu trách nhiệm về những gì bạn kiếm được, những gì bạn chi tiêu và thuế mà bạn phải trả."},{"time":106040,"en":"This means you have to complete an annual tax return.","vi":"Điều này có nghĩa là bạn phải hoàn thành tờ khai thuế hàng năm."},{"time":109760,"en":"This is a document which you send to the tax office once a year showing what you earn from your business and what you spend in running your business.","vi":"Đây là một tài liệu mà bạn gửi cho cơ quan thuế mỗi năm một lần, cho biết những gì bạn kiếm được từ doanh nghiệp của mình và những gì bạn chi tiêu để điều hành doanh nghiệp của mình."},{"time":118200,"en":"On the positive side, you're only taxed on your earnings after expenses, such as transport, electricity, office equipment and so on.","vi":"Về mặt tích cực, bạn chỉ bị đánh thuế trên thu nhập của mình sau các chi phí, chẳng hạn như vận chuyển, điện, thiết bị văn phòng, v.v."},{"time":126820,"en":"So, if you work from home, you can save tax by declaring some of your use of electricity as necessary for your business.","vi":"Vì vậy, nếu bạn làm việc tại nhà, bạn có thể tiết kiệm thuế bằng cách khai báo một phần việc sử dụng điện của bạn là cần thiết cho doanh nghiệp của bạn."},{"time":134960,"en":"Another consideration is that if you earn over a certain amount, you pay a higher rate of income tax, which is higher than the corporation tax rates that companies pay.","vi":"Một cân nhắc khác là nếu bạn kiếm được trên một số tiền nhất định, bạn sẽ phải trả mức thuế thu nhập cao hơn, cao hơn mức thuế doanh nghiệp mà các công ty phải trả."},{"time":145960,"en":"You'll also have ‘unlimited liability', which means that if you can't pay your business debts, you may lose your house and car to pay for them, as you are your business.","vi":"Bạn cũng sẽ có ‘trách nhiệm vô hạn', có nghĩa là nếu bạn không thể trả các khoản nợ kinh doanh của mình, bạn có thể mất nhà và xe để trả cho chúng, vì bạn là doanh nghiệp của bạn."},{"time":158540,"en":"Finally, many sole traders find it difficult to take holidays and breaks from the business and find that they spend far more time working than employed people.","vi":"Cuối cùng, nhiều doanh nghiệp tư nhân cảm thấy khó khăn trong việc nghỉ lễ và nghỉ ngơi khỏi công việc kinh doanh và thấy rằng họ dành nhiều thời gian làm việc hơn những người làm công ăn lương."},{"time":168760,"en":"The typical traders associated with this type of business structure are skilled manual workers, such as builders, plumbers and electricians, or professions in which people usually work alone, such as photographers and writers.","vi":"Những người buôn bán điển hình liên quan đến loại hình cơ cấu kinh doanh này là công nhân thủ công lành nghề, chẳng hạn như thợ xây, thợ sửa ống nước và thợ điện, hoặc các ngành nghề mà mọi người thường làm việc một mình, chẳng hạn như nhiếp ảnh gia và nhà văn."},{"time":182980,"en":"However, increasingly these days, with the reduction in long-term employment and job security, sole traders are coming from other professions, such as computer programming and even teaching, especially tutoring.","vi":"Tuy nhiên, ngày nay, với việc giảm việc làm dài hạn và bảo đảm công việc, các doanh nghiệp tư nhân đang đến từ các ngành nghề khác, chẳng hạn như lập trình máy tính và thậm chí cả giảng dạy, đặc biệt là dạy kèm."},{"time":197700,"en":"Certainly, being a sole trader is a very useful way of starting out in business by yourself.","vi":"Chắc chắn, trở thành một doanh nghiệp tư nhân là một cách rất hữu ích để tự mình bắt đầu kinh doanh."}],"probUrl":"https://study4.com/problems/120902/?view=embed"}},{"id":"listening_u3_54","title":"Companies and Careers: recording 3","actTitle":"Companies and Careers: recording 3","youtubeId":"","htmlContent":"","problem":{"pType":"listen_passage","probTitle":"Companies and Careers: recording 3","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset2_15.mp3","subs":[{"time":0,"en":"Thank you, Dr Korpis.","vi":"Cảm ơn Tiến sĩ Korpis."},{"time":2480,"en":"The next form of business structure that I would like to discuss is the partnership.","vi":"Loại hình cấu trúc kinh doanh tiếp theo mà tôi muốn thảo luận là hình thức hợp danh."},{"time":7700,"en":"There are two kinds of partnership - a simple partnership and a limited liability partnership, or LLP.","vi":"Có hai loại hình hợp danh - hợp danh thông thường và hợp danh trách nhiệm hữu hạn, hay còn gọi là LLP."},{"time":15860,"en":"I'll talk about each of these in turn.","vi":"Tôi sẽ lần lượt nói về từng loại hình này."},{"time":18440,"en":"Forming a simple partnership is straightforward, like becoming a sole trader, except that you have to agree to work with someone else.","vi":"Việc thành lập một hợp danh thông thường khá đơn giản, giống như trở thành một chủ doanh nghiệp tư nhân, ngoại trừ việc bạn phải đồng ý làm việc với người khác."},{"time":25520,"en":"A partnership could be between a husband and wife, or two members of the same family or close friends.","vi":"Hình thức hợp danh có thể là giữa vợ và chồng, hoặc hai thành viên trong cùng một gia đình hoặc bạn bè thân thiết."},{"time":32600,"en":"For example, a couple might run a catering business, or two car mechanics might leave employed work to set up a partnership together repairing cars.","vi":"Ví dụ, một cặp vợ chồng có thể điều hành một doanh nghiệp dịch vụ ăn uống, hoặc hai thợ sửa xe có thể nghỉ việc để cùng nhau thành lập một hợp danh sửa chữa ô tô."},{"time":42220,"en":"One obvious advantage of this is that if one partner is sick or on holiday, the other partner can carry on the business, and another is that it can be easier for a partnership to borrow money from a bank than it can for a sole trader.","vi":"Một lợi thế rõ ràng của hình thức này là nếu một đối tác bị ốm hoặc đi nghỉ, đối tác còn lại có thể tiếp tục công việc kinh doanh, và một lợi thế khác là việc hợp danh vay tiền từ ngân hàng có thể dễ dàng hơn so với một chủ doanh nghiệp tư nhân."},{"time":56800,"en":"Of course, partners usually have an informal agreement to work together, but it's always better to have a formal arrangement to avoid disagreements.","vi":"Tất nhiên, các đối tác thường có một thỏa thuận không chính thức để làm việc cùng nhau, nhưng tốt hơn hết là nên có một thỏa thuận chính thức để tránh bất đồng."},{"time":65940,"en":"As with sole traders, each partner must be registered with the tax office as self-employed and must send in a tax return once a year.","vi":"Giống như các chủ doanh nghiệp tư nhân, mỗi đối tác phải đăng ký với cơ quan thuế với tư cách là người tự kinh doanh và phải gửi tờ khai thuế mỗi năm một lần."},{"time":75400,"en":"In addition, as the partnership is unlimited, all members are responsible for debt, so you and your partners may lose your personal possessions to pay debts if the business fails.","vi":"Ngoài ra, vì hợp danh là vô hạn, tất cả các thành viên đều chịu trách nhiệm về nợ, vì vậy bạn và các đối tác của bạn có thể mất tài sản cá nhân để trả nợ nếu doanh nghiệp thất bại."},{"time":87000,"en":"The other structure for a partnership is the limited liability partnership, or LLP.","vi":"Cấu trúc khác cho hợp danh là hợp danh trách nhiệm hữu hạn, hay LLP."},{"time":93340,"en":"This is similar to a simple partnership as the partners share the income and expenses and also have to pay their own taxes to the tax office, but there are important differences.","vi":"Hình thức này tương tự như hợp danh thông thường vì các đối tác chia sẻ thu nhập và chi phí và cũng phải tự nộp thuế cho cơ quan thuế, nhưng có những khác biệt quan trọng."},{"time":105260,"en":"On the one hand, sole traders and simple partnerships don't have to legally register their businesses.","vi":"Một mặt, các chủ doanh nghiệp tư nhân và hợp danh thông thường không phải đăng ký kinh doanh hợp pháp."},{"time":111920,"en":"On the other hand, LLPs have to be legally registered with Companies House.","vi":"Mặt khác, LLP phải được đăng ký hợp pháp với Companies House (Cơ quan đăng ký doanh nghiệp)."},{"time":117200,"en":"This means that at least two of the members are legally responsible for the partnership.","vi":"Điều này có nghĩa là ít nhất hai thành viên chịu trách nhiệm pháp lý cho hợp danh."},{"time":122880,"en":"They have to make sure that they send accounts to Companies House, as well as to the tax office.","vi":"Họ phải đảm bảo rằng họ gửi báo cáo tài chính cho Companies House, cũng như cho cơ quan thuế."},{"time":129420,"en":"They also need to send in an annual return, which is a documentshowingthe name, address and members of the partnership and any changes.","vi":"Họ cũng cần phải gửi tờ khai hàng năm, là một tài liệu thể hiện tên, địa chỉ và các thành viên của hợp danh và bất kỳ thay đổi nào."},{"time":138160,"en":"If they don't do this, they may go to prison, so it's important to understand exactly what setting up an LLP means.","vi":"Nếu họ không làm điều này, họ có thể phải ngồi tù, vì vậy điều quan trọng là phải hiểu chính xác ý nghĩa của việc thành lập LLP."},{"time":146200,"en":"So why should partners enter into a limited liability partnership?","vi":"Vậy tại sao các đối tác nên tham gia vào một hợp danh trách nhiệm hữu hạn?"},{"time":150980,"en":"Usually, an LLP suits certain types of professionals who provide services, such as accountants, lawyers, consultants and financial service providers.","vi":"Thông thường, LLP phù hợp với một số loại hình chuyên gia cung cấp dịch vụ, chẳng hạn như kế toán viên, luật sư, nhà tư vấn và nhà cung cấp dịch vụ tài chính."},{"time":162580,"en":"Another reason may be that partners want to do business with larger organisations who would prefer to give contracts to a registered company or partnership.","vi":"Một lý do khác có thể là các đối tác muốn kinh doanh với các tổ chức lớn hơn, những tổ chức thích giao hợp đồng cho một công ty hoặc hợp danh đã đăng ký hơn."},{"time":172220,"en":"In any event, an LLP offers the flexibility of being in a simple partnership, but also gives the partners protection so that they lose only the money that they have put into the partnership if it fails.","vi":"Trong mọi trường hợp, LLP mang lại sự linh hoạt của việc tham gia vào một hợp danh thông thường, nhưng cũng mang lại cho các đối tác sự bảo vệ để họ chỉ mất số tiền mà họ đã đầu tư vào hợp danh nếu nó thất bại."},{"time":185220,"en":"However, if the partners earn a lot of money, they will still pay more tax than the owner of a limited liability company.","vi":"Tuy nhiên, nếu các đối tác kiếm được nhiều tiền, họ vẫn sẽ phải trả nhiều thuế hơn so với chủ sở hữu của một công ty trách nhiệm hữu hạn."}],"probUrl":"https://study4.com/problems/120903/?view=embed"}},{"id":"listening_u3_55","title":"Companies and Careers: recording 4","actTitle":"Companies and Careers: recording 4","youtubeId":"","htmlContent":"","problem":{"pType":"listen_passage","probTitle":"Companies and Careers: recording 4","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset2_16.mp3","subs":[{"time":0,"en":"Thank you, Dr Lethbridge.","vi":"Cảm ơn tiến sĩ Lethbridge."},{"time":2860,"en":"The last form of business I'd like to talk about is the limited liability company.","vi":"Loại hình kinh doanh cuối cùng mà tôi muốn nói đến là công ty trách nhiệm hữu hạn."},{"time":8100,"en":"The owners of a limited liability company are called 'members' or`shareholders' as they own shares in the company.","vi":"Những người sở hữu một công ty trách nhiệm hữu hạn được gọi là 'thành viên' hoặc 'cổ đông' vì họ sở hữu cổ phần trong công ty."},{"time":15240,"en":"A 'share' is a divided-up unit or part of the company.","vi":"'Cổ phần' là một đơn vị hoặc phần được chia nhỏ của công ty."},{"time":19520,"en":"All businesses run the risk of failing or going bankrupt.","vi":"Tất cả các doanh nghiệp đều có nguy cơ thất bại hoặc phá sản."},{"time":23520,"en":"If a business goes bankrupt, it has to close because it owes money and is not able to pay the money back.","vi":"Nếu một doanh nghiệp phá sản, nó phải đóng cửa vì nợ tiền và không thể trả lại số tiền đó."},{"time":30320,"en":"As I mentioned before, setting up a limited liability company, like an LLP, means that if the company fails or goes bankrupt, the business owners lose only what they have put into the business and not their own personal goods and property.","vi":"Như tôi đã đề cập trước đó, việc thành lập một công ty trách nhiệm hữu hạn, giống như một LLP, có nghĩa là nếu công ty thất bại hoặc phá sản, chủ sở hữu doanh nghiệp chỉ mất những gì họ đã đầu tư vào doanh nghiệp chứ không phải hàng hóa và tài sản cá nhân của họ."},{"time":45260,"en":"This is the idea of liability - how much a business owes in debt if it can no longer operate and has to close.","vi":"Đây là ý tưởng về trách nhiệm pháp lý - một doanh nghiệp nợ bao nhiêu khi không còn khả năng hoạt động và phải đóng cửa."},{"time":52880,"en":"For example, if a sole trader goes bankrupt, he or she may need to sell his or her own house and possessions in order to pay any debts, because the business is not separate from the owner.","vi":"Ví dụ: nếu một chủ doanh nghiệp cá thể phá sản, người đó có thể cần phải bán nhà và tài sản cá nhân của mình để trả bất kỳ khoản nợ nào, vì doanh nghiệp không tách biệt với chủ sở hữu."},{"time":65640,"en":"With LLPs and limited liability companies, the owners and the businesses are separate, so property and goods owned by the business can be sold to pay debts, but not property and goods personally owned by the members or company shareholders.","vi":"Với LLPs và các công ty trách nhiệm hữu hạn, chủ sở hữu và doanh nghiệp là riêng biệt, do đó tài sản và hàng hóa thuộc sở hữu của doanh nghiệp có thể được bán để trả nợ, nhưng không phải tài sản và hàng hóa thuộc sở hữu cá nhân của các thành viên hoặc cổ đông của công ty."},{"time":82300,"en":"Just as with LLPs, limited liability companies (or 'limited companies' for short) must be legally registered with Companies House.","vi":"Cũng giống như LLPs, các công ty trách nhiệm hữu hạn (hoặc 'công ty trách nhiệm hữu hạn' viết tắt) phải được đăng ký hợp pháp với Companies House."},{"time":92300,"en":"This means they must have a registered address, where all the company documents and records must be kept.","vi":"Điều này có nghĩa là họ phải có một địa chỉ đăng ký, nơi tất cả các tài liệu và hồ sơ của công ty phải được lưu giữ."},{"time":99120,"en":"As with LLPs, accounts and annual returns must be submitted every year so that anyone can have a look at the company's finances before doing business with it.","vi":"Như với LLPs, tài khoản và báo cáo thường niên phải được nộp hàng năm để bất kỳ ai cũng có thể xem xét tình hình tài chính của công ty trước khi làm ăn với công ty."},{"time":109820,"en":"The level of administration is higher than with other business structures and you need to have a managing director and at least one shareholder.","vi":"Mức độ quản lý hành chính cao hơn so với các cơ cấu kinh doanh khác và bạn cần phải có một giám đốc điều hành và ít nhất một cổ đông."},{"time":119360,"en":"In terms of paying tax, the company has to pay corporation tax on its profits, which is far less than income tax on large amounts, especially over around £50,000.","vi":"Về việc nộp thuế, công ty phải nộp thuế doanh nghiệp trên lợi nhuận, mức thuế này thấp hơn nhiều so với thuế thu nhập đối với các khoản tiền lớn, đặc biệt là trên 50.000 bảng Anh."},{"time":131020,"en":"However, you also have to pay income tax on any money you take as a salary from your company.","vi":"Tuy nhiên, bạn cũng phải trả thuế thu nhập trên bất kỳ khoản tiền nào bạn nhận làm lương từ công ty của mình."},{"time":138260,"en":"As with the other business structures, the company tax assessment must be submitted to the tax office, but for corporation tax rather than income tax.","vi":"Như với các cơ cấu kinh doanh khác, tờ khai thuế của công ty phải được nộp cho cơ quan thuế, nhưng là thuế doanh nghiệp thay vì thuế thu nhập."},{"time":148720,"en":"The shareholders also have to submit their own personal tax assessments separately.","vi":"Các cổ đông cũng phải nộp tờ khai thuế cá nhân của riêng họ một cách riêng biệt."},{"time":154560,"en":"As we've already mentioned, the company owners must also submit accounts to Companies House.","vi":"Như chúng tôi đã đề cập, chủ sở hữu công ty cũng phải nộp báo cáo tài chính cho Companies House."},{"time":160420,"en":"This can all be quite complicated, so it's a good idea to get professional help and advice from an accountant.","vi":"Tất cả những điều này có thể khá phức tạp, vì vậy tốt nhất là bạn nên tìm kiếm sự giúp đỡ và tư vấn chuyên nghiệp từ một kế toán viên."},{"time":167740,"en":"It's important to remember that running a limited company is more complex than being a sole trader, so it's important to do careful research and consider your situation before deciding which type of business to run.","vi":"Điều quan trọng cần nhớ là việc điều hành một công ty trách nhiệm hữu hạn phức tạp hơn là một chủ doanh nghiệp cá thể, vì vậy điều quan trọng là phải nghiên cứu cẩn thận và xem xét tình hình của bạn trước khi quyết định loại hình kinh doanh nào sẽ điều hành."},{"time":181800,"en":"In any case, you could start as a sole trader and, if business is doing well, turn your business into a limited company at a later date.","vi":"Trong mọi trường hợp, bạn có thể bắt đầu với tư cách là một chủ doanh nghiệp cá thể và nếu công việc kinh doanh tốt, hãy chuyển doanh nghiệp của bạn thành một công ty trách nhiệm hữu hạn vào một ngày sau đó."}],"probUrl":"https://study4.com/problems/120904/?view=embed"}},{"id":"listening_u3_56","title":"Companies and Careers: recording 5","actTitle":"Companies and Careers: recording 5","youtubeId":"","htmlContent":"","problem":{"pType":"listen_passage","probTitle":"Companies and Careers: recording 5","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset2_17.mp3","subs":[{"time":0,"en":"So, let me summarise the differences and similarities between each business structure.","vi":"Vậy, hãy để tôi tóm tắt những điểm khác biệt và tương đồng giữa các loại hình doanh nghiệp."},{"time":6980,"en":"On the one hand, it's fairly simple and inexpensive to set up as a sole trader.","vi":"Một mặt, việc thành lập một doanh nghiệp tư nhân khá đơn giản và không tốn kém."},{"time":12720,"en":"You don't have to worry about lots of administration and financial organisation, and you can keep total control of your business and decision-making.","vi":"Bạn không phải lo lắng về nhiều thủ tục hành chính và tổ chức tài chính, đồng thời bạn có thể kiểm soát hoàn toàn doanh nghiệp và việc ra quyết định."},{"time":21700,"en":"On the other hand, you may end up paying more in tax than you would as a limited company, you are personally responsible for your debts and losses, and it might be more difficult to get valuable contracts if your business does not have limited liability.","vi":"Mặt khác, bạn có thể phải trả nhiều thuế hơn so với khi là một công ty trách nhiệm hữu hạn, bạn phải chịu trách nhiệm cá nhân về các khoản nợ và thua lỗ, và có thể khó có được các hợp đồng giá trị nếu doanh nghiệp của bạn không có trách nhiệm hữu hạn."},{"time":37420,"en":"With regard to partnerships, there are two kinds: simple partnerships and LLPs.","vi":"Đối với hình thức hợp danh, có hai loại: hợp danh thông thường và hợp danh hữu hạn (LLP)."},{"time":44520,"en":"In comparison with sole traders, partnerships have the benefit of more people to plan and make decisions.","vi":"So với doanh nghiệp tư nhân, hợp danh có lợi thế là có nhiều người hơn để lập kế hoạch và đưa ra quyết định."},{"time":51160,"en":"It's easier to take care of the business when one partner is not able to take an active part, and it can also be easier to borrow money than for a sole trader.","vi":"Việc điều hành doanh nghiệp sẽ dễ dàng hơn khi một thành viên không thể tham gia tích cực, và việc vay tiền cũng có thể dễ dàng hơn so với doanh nghiệp tư nhân."},{"time":60420,"en":"On the negative side, liability is shared among the partners and having more than one owner can make things more complicated when there are disagreements, or if the business needs to be brought to a close.","vi":"Về mặt tiêu cực, trách nhiệm pháp lý được chia sẻ giữa các thành viên hợp danh và việc có nhiều hơn một chủ sở hữu có thể khiến mọi thứ trở nên phức tạp hơn khi có bất đồng, hoặc nếu doanh nghiệp cần phải đóng cửa."},{"time":73060,"en":"One other difference between sole traders and partnerships is that the partners need to trust each other.","vi":"Một điểm khác biệt nữa giữa doanh nghiệp tư nhân và hợp danh là các thành viên hợp danh cần tin tưởng lẫn nhau."},{"time":79240,"en":"If a partnership has serious money problems, one partner may leave the other to deal with the debts.","vi":"Nếu một hợp danh gặp vấn đề nghiêm trọng về tiền bạc, một thành viên có thể bỏ mặc thành viên khác đối mặt với các khoản nợ."},{"time":85080,"en":"Clearly this is not a problem for sole traders.","vi":"Rõ ràng đây không phải là vấn đề đối với các doanh nghiệp tư nhân."},{"time":89060,"en":"One similarity between partnerships and sole traders, though, is to do with tax.","vi":"Tuy nhiên, một điểm tương đồng giữa hợp danh và doanh nghiệp tư nhân là về thuế."},{"time":94560,"en":"The sole trader must submit a yearly income tax assessment to the tax office.","vi":"Doanh nghiệp tư nhân phải nộp tờ khai thuế thu nhập hàng năm cho cơ quan thuế."},{"time":99480,"en":"The same is true of partnerships, as members are treated individually for this purpose.","vi":"Điều tương tự cũng đúng với hợp danh, vì các thành viên được đối xử riêng lẻ cho mục đích này."},{"time":105720,"en":"When we compare simple partnerships with LLPs, we find various differences.","vi":"Khi so sánh hợp danh thông thường với hợp danh hữu hạn (LLP), chúng ta thấy có nhiều điểm khác biệt."},{"time":111380,"en":"For example, LLPs are legally required to submit their accounts and annual returns to Companies House.","vi":"Ví dụ: LLP theo luật định phải nộp báo cáo tài chính và tờ khai hàng năm cho Companies House."},{"time":119340,"en":"This is not something that is required for simple partnerships.","vi":"Đây không phải là điều bắt buộc đối với hợp danh thông thường."},{"time":123400,"en":"Another difference is to do with debt.","vi":"Một điểm khác biệt nữa là về nợ."},{"time":125940,"en":"In an LLP, the partners' personal possessions and property are protected.","vi":"Trong LLP, tài sản cá nhân và tài sản của các thành viên hợp danh được bảo vệ."},{"time":131420,"en":"In a simple partnership, however, like sole traders, the members are personally responsible for any business debts.","vi":"Tuy nhiên, trong hợp danh thông thường, giống như doanh nghiệp tư nhân, các thành viên phải chịu trách nhiệm cá nhân đối với bất kỳ khoản nợ nào của doanh nghiệp."},{"time":139500,"en":"Finally, limited liability companies have two main advantages over simple partnerships and sole traders: this type of structure limits the financial liabilities of the owners to business losses and not personal losses, and it can save money, as corporation tax is generally lower than income tax.","vi":"Cuối cùng, công ty trách nhiệm hữu hạn có hai ưu điểm chính so với hợp danh thông thường và doanh nghiệp tư nhân: loại hình này giới hạn trách nhiệm tài chính của chủ sở hữu đối với các khoản lỗ của doanh nghiệp chứ không phải các khoản lỗ cá nhân, và nó có thể tiết kiệm tiền, vì thuế doanh nghiệp thường thấp hơn thuế thu nhập."},{"time":161080,"en":"On the other hand, there are a lot more administrative and legal requirements.","vi":"Mặt khác, có rất nhiều yêu cầu hành chính và pháp lý khác."},{"time":165480,"en":"Company accounts and an annual return must be sent to Companies House.","vi":"Báo cáo tài chính của công ty và tờ khai hàng năm phải được gửi đến Companies House."},{"time":170760,"en":"Similarly, there is a legal requirement to keep company records at the registered address.","vi":"Tương tự, có một yêu cầu pháp lý là phải lưu giữ hồ sơ công ty tại địa chỉ đã đăng ký."}],"probUrl":"https://study4.com/problems/120905/?view=embed"}},{"id":"listening_u3_57","title":"Companies and Careers: recording 6","actTitle":"Companies and Careers: recording 6","youtubeId":"","htmlContent":"","problem":{"pType":"listen_passage","probTitle":"Companies and Careers: recording 6","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset2_18.mp3","subs":[{"time":0,"en":"To conclude this lecture, I'd like to present three case studies to show the different structures in action.","vi":"Để kết thúc bài giảng này, tôi muốn trình bày ba nghiên cứu điển hình để minh họa các loại hình cơ cấu khác nhau trong thực tế."},{"time":7580,"en":"I'll present each case, briefly discuss the possibilities and recommend the most suitable structure.","vi":"Tôi sẽ trình bày từng trường hợp, thảo luận ngắn gọn về các khả năng và đề xuất cơ cấu phù hợp nhất."},{"time":15640,"en":"First, there's the case of Sanjay and Tanya, a couple who want to set up a catering service delivering food to businesses.","vi":"Đầu tiên, là trường hợp của Sanjay và Tanya, một cặp vợ chồng muốn thành lập dịch vụ cung cấp đồ ăn cho các doanh nghiệp."},{"time":23580,"en":"The idea is to take orders from businesses on a daily basis and prepare food for delivery during the business day.","vi":"Ý tưởng là nhận đơn đặt hàng từ các doanh nghiệp hàng ngày và chuẩn bị đồ ăn để giao trong giờ làm việc."},{"time":30760,"en":"They aim to target businesses in their local area to begin with, and then further afield as they expand.","vi":"Họ nhắm mục tiêu vào các doanh nghiệp trong khu vực địa phương của họ để bắt đầu, và sau đó mở rộng ra xa hơn khi họ phát triển."},{"time":37560,"en":"Their plans include a website to display their daily international menus and to provide an online service for customers to order and check when the food will be delivered.","vi":"Kế hoạch của họ bao gồm một trang web để hiển thị thực đơn quốc tế hàng ngày và cung cấp dịch vụ trực tuyến cho khách hàng đặt hàng và kiểm tra thời gian giao đồ ăn."},{"time":47680,"en":"Clearly, it's not suitable to be sole traders, but they could organise themselves as a partnership or a limited company.","vi":"Rõ ràng, không phù hợp để là chủ sở hữu duy nhất, nhưng họ có thể tổ chức thành một quan hệ đối tác hoặc một công ty trách nhiệm hữu hạn."},{"time":56820,"en":"It depends partly on how much money they can raise and how many people they intend to employ to prepare and deliver the orders.","vi":"Điều này phụ thuộc một phần vào số tiền họ có thể huy động và số lượng người họ dự định雇来 để chuẩn bị và giao đơn đặt hàng."},{"time":65800,"en":"It might be best for them to start as an LLP, so that they can get funding more easily than if they were a simple partnership.","vi":"Có lẽ tốt nhất cho họ là bắt đầu với tư cách là một công ty hợp danh hữu hạn (LLP), để họ có thể nhận được tài trợ dễ dàng hơn so với khi họ là một quan hệ đối tác đơn giản."},{"time":73660,"en":"They could start small and build from there.","vi":"Họ có thể bắt đầu nhỏ và xây dựng từ đó."},{"time":76560,"en":"They could hand out contracts to other companies for some of their services, particularly for the website and delivery, if they intend to prepare the food themselves.","vi":"Họ có thể giao hợp đồng cho các công ty khác cho một số dịch vụ của họ, đặc biệt là cho trang web và giao hàng, nếu họ dự định tự chuẩn bị đồ ăn."},{"time":86740,"en":"Alternatively, they could set up a limited liability company if they expect to grow quickly and want to keep every aspect of their business in-house, employing staff directly.","vi":"Ngoài ra, họ có thể thành lập một công ty trách nhiệm hữu hạn nếu họ dự kiến sẽ phát triển nhanh chóng và muốn giữ mọi khía cạnh的业务 在内部, 雇用员工 直接."},{"time":99480,"en":"However, I would say the LLP model would work better here - giving them more time to focus on growing the business, rather than dealing with a lot of administration from the start.","vi":"Tuy nhiên, tôi nghĩ mô hình LLP sẽ phù hợp hơn ở đây - cho họ thêm thời gian để tập trung vào việc phát triển kinh doanh, thay vì phải đối phó với nhiều thủ tục hành chính ngay từ đầu."},{"time":112480,"en":"Melissa and Jane have an idea for a website design service.","vi":"Melissa và Jane có ý tưởng về một dịch vụ thiết kế trang web."},{"time":117040,"en":"They both studied software engineering at university and so they are both well skilled in their field.","vi":"Cả hai đều học kỹ thuật phần mềm tại trường đại học và vì vậy cả hai đều có kỹ năng tốt trong lĩnh vực của họ."},{"time":123280,"en":"They have both worked as designers for major organisations, so they have a good understanding of what's involved in running such a business.","vi":"Cả hai đều đã làm việc với tư cách là nhà thiết kế cho các tổ chức lớn, vì vậy họ hiểu rõ về những gì liên quan đến việc điều hành một doanh nghiệp như vậy."},{"time":131280,"en":"Melissa has also taken a Master's degree in Business Administration, so she's confident about her skills as a businesswoman.","vi":"Melissa cũng đã取得 được bằng Thạc sĩ Quản trị Kinh doanh, vì vậy cô ấy tự tin về kỹ năng của mình với tư cách là một nữ doanh nhân."},{"time":140360,"en":"They've managed to save over £3,000 to rent office space and £10,000 to buy equipment to run their business.","vi":"Họ đã xoay sở tiết kiệm được hơn 3.000 bảng Anh để thuê văn phòng và 10.000 bảng Anh để mua thiết bị để điều hành công việc kinh doanh của họ."},{"time":148880,"en":"The best option for them would be to register a limited company and start trading straight away as they have a good level of knowledge and experience which will benefit them.","vi":"Lựa chọn tốt nhất cho họ là đăng ký thành lập công ty trách nhiệm hữu hạn và bắt đầu giao dịch ngay lập tức vì họ có kiến thức và kinh nghiệm ở mức độ tốt, điều này sẽ mang lại lợi ích cho họ."},{"time":158820,"en":"They don't intend to employ anyone immediately, but the option is there if they need to in the future.","vi":"Họ không có ý định thuê ai ngay lập tức, nhưng có thể考虑 nếu họ cần trong tương lai."},{"time":165920,"en":"An alternative would be for them to start as a simple partnership and expand from there, seeing how their work grows and then maybe setting up a limited liability company in the future (or they could make their partnership a limited one).","vi":"Một lựa chọn khác là họ bắt đầu với tư cách là một quan hệ đối tác đơn giản và mở rộng từ đó, xem công việc của họ phát triển như thế nào và sau đó có thể thành lập một công ty trách nhiệm hữu hạn trong tương lai (hoặc họ có thể biến quan hệ đối tác của họ thành một quan hệ đối tác hữu hạn)."},{"time":180440,"en":"But if they have confidence in themselves, there's nothing to stop them setting up a limited company immediately.","vi":"Nhưng nếu họ tin tưởng vào bản thân, thì không có gì ngăn cản họ thành lập công ty trách nhiệm hữu hạn ngay lập tức."},{"time":188780,"en":"Barry is a motorbike enthusiast with many years of experience riding bikes.","vi":"Barry là một người đam mê xe mô tô với nhiều năm kinh nghiệm lái xe."},{"time":194600,"en":"He's been working for a courier company delivering letters and parcels for over five years now and thinks that he'd do better if he worked for himself.","vi":"Anh ấy đã làm việc cho một công ty chuyển phát nhanh giao thư và bưu kiện trong hơn năm năm nay và nghĩ rằng anh ấy sẽ làm tốt hơn nếu anh ấy tự làm."},{"time":203580,"en":"The courier company provided him with his work bike and took care of maintenance and repairs, so if he works for himself, he'll have to buy his own bike for work and take care of it himself.","vi":"Công ty chuyển phát nhanh đã cung cấp cho anh ấy chiếc xe đạp làm việc và lo việc bảo trì và sửa chữa, vì vậy nếu anh ấy tự làm, anh ấy sẽ phải mua xe đạp riêng để làm việc và tự chăm sóc nó."},{"time":214820,"en":"This isn't a problem for him as he has three bikes for his own use already.","vi":"Đây không phải là vấn đề đối với anh ta vì anh ta đã có ba chiếc xe đạp để sử dụng riêng."},{"time":219780,"en":"He knows that he can build up regular clients from his","vi":"Anh ấy biết rằng anh ấy có thể xây dựng những khách hàng thường xuyên từ các mối quan hệ của anh ấy,"},{"time":222900,"en":"contacts, but he's not sure if working as a sole trader is the best thing for him, as he's never been self-employed before.","vi":"nhưng anh ấy không chắc liệu làm việc với tư cách là một chủ sở hữu duy nhất có phải là điều tốt nhất cho anh ấy hay không, vì anh ấy chưa bao giờ tự làm chủ trước đây."},{"time":231220,"en":"Another possibility would be to set up a limited company with a family member.","vi":"Một khả năng khác là thành lập một công ty trách nhiệm hữu hạn với một thành viên trong gia đình."},{"time":236020,"en":"This person wouldn't take an active part in the business - they would be known as a 'sleeping partner'.","vi":"Người này sẽ không tham gia tích cực vào công việc kinh doanh - họ sẽ được gọi là 'đối tác im lặng'."},{"time":242080,"en":"Finally, he could also choose to work in a partnership with other riders who are thinking of leaving the company, but he's not sure if that arrangement would last.","vi":"Cuối cùng, anh ấy cũng có thể chọn làm việc trong một quan hệ đối tác với những người lái xe khác đang nghĩ đến việc rời công ty, nhưng anh ấy không chắc liệu sự sắp xếp đó có kéo dài hay không."},{"time":251460,"en":"On balance, the best option for him would be to start off as a sole trader with his own work bike and do that for a year or two to see how well it went, and then make a decision about whether to set up a limited company in the future.","vi":"Nói chung, lựa chọn tốt nhất cho anh ấy là bắt đầu với tư cách là một chủ sở hữu duy nhất với chiếc xe đạp làm việc của riêng mình và làm điều đó trong một hoặc hai năm để xem nó diễn ra tốt như thế nào, và sau đó đưa ra quyết định về việc có nên thành lập một công ty trách nhiệm hữu hạn trong tương lai hay không."}],"probUrl":"https://study4.com/problems/120906/?view=embed"}},{"id":"listening_u3_58","title":"The Environment: recording 1","actTitle":"The Environment: recording 1","youtubeId":"","htmlContent":"","problem":{"pType":"listen_passage","probTitle":"The Environment: recording 1","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset2_19.mp3","subs":[{"time":0,"en":"This week in environmental studies, we're going to look at the latest developments in the energy industry and how they might affect our lives in the future.","vi":"Tuần này trong môn nghiên cứu môi trường, chúng ta sẽ xem xét những phát triển mới nhất trong ngành năng lượng và chúng có thể ảnh hưởng đến cuộc sống của chúng ta như thế nào trong tương lai."},{"time":9940,"en":"As we've already seen, there are basically two types of energy source - renewable and non-renewable.","vi":"Như chúng ta đã thấy, về cơ bản có hai loại nguồn năng lượng - tái tạo và không tái tạo."},{"time":17260,"en":"As you no doubt remember, renewable sources are those which can be used again and again, while non-renewable sources can be used only once and then they're finished.","vi":"Như bạn chắc chắn còn nhớ, nguồn tái tạo là những nguồn có thể được sử dụng nhiều lần, trong khi nguồn không tái tạo chỉ có thể được sử dụng một lần rồi hết."},{"time":28360,"en":"Historically, coal has been the most-used form of non-renewable energy, but it has also been the most polluting.","vi":"Trong lịch sử, than đá là dạng năng lượng không tái tạo được sử dụng nhiều nhất, nhưng nó cũng gây ô nhiễm nhất."},{"time":36800,"en":"It's widely accepted that we need to use less of it to help protect the environment for the future.","vi":"Nhiều người chấp nhận rằng chúng ta cần sử dụng ít than đá hơn để giúp bảo vệ môi trường cho tương lai."},{"time":43600,"en":"The oldest renewable source is wind power, which has been used for centuries to power windmills and other devices, and which has now been developed further, giving us wind turbines which produce electricity.","vi":"Nguồn tái tạo lâu đời nhất là năng lượng gió, đã được sử dụng hàng thế kỷ để cung cấp năng lượng cho cối xay gió và các thiết bị khác, và giờ đây đã được phát triển hơn nữa, cho chúng ta các tuabin gió sản xuất điện."},{"time":57640,"en":"Over the last 200 years or so, petroleum has become the most important non-renewable source, though natural gas is overtaking it as it's far cleaner and less polluting.","vi":"Trong khoảng 200 năm trở lại đây, dầu mỏ đã trở thành nguồn không tái tạo quan trọng nhất, mặc dù khí đốt tự nhiên đang vượt qua nó vì nó sạch hơn và ít gây ô nhiễm hơn nhiều."},{"time":70700,"en":"Hydroelectric power has been in use for many years as a renewable resource, especially with dams on rivers and lakes, but these are expensive to create and maintain, and can affect the local environment in negative ways.","vi":"Thủy điện đã được sử dụng trong nhiều năm như một nguồn tài nguyên tái tạo, đặc biệt là với các đập trên sông và hồ, nhưng chúng tốn kém để xây dựng và duy trì, và có thể ảnh hưởng tiêu cực đến môi trường địa phương."},{"time":86440,"en":"More recently, there've been great developments in two renewable sources: solar power - that is, power produced directly from the sun - and wave power, which comes from the movement of waves at sea, but, of course, these are only effective in areas with a lot of sun or in coastal areas.","vi":"Gần đây, đã có những phát triển lớn trong hai nguồn tái tạo: năng lượng mặt trời - tức là năng lượng được sản xuất trực tiếp từ mặt trời - và năng lượng sóng, đến từ sự chuyển động của sóng trên biển, nhưng tất nhiên, chúng chỉ hiệu quả ở những khu vực có nhiều ánh nắng mặt trời hoặc ở các khu vực ven biển."},{"time":107100,"en":"While there are clear benefits to expanding solar and wave power, one other source has become particularly significant and important, and that is fracking, which is a way of getting natural gas out of the ground.","vi":"Mặc dù có những lợi ích rõ ràng khi mở rộng năng lượng mặt trời và năng lượng sóng, một nguồn khác đã trở nên đặc biệt quan trọng, đó là fracking, một cách để lấy khí đốt tự nhiên ra khỏi lòng đất."},{"time":121280,"en":"So, the main focus of today's lecture is on fracking and why there's been so much discussion and debate about it in the media.","vi":"Vì vậy, trọng tâm chính của bài giảng hôm nay là về fracking và lý do tại sao có rất nhiều thảo luận và tranh luận về nó trên các phương tiện truyền thông."}],"probUrl":"https://study4.com/problems/120907/?view=embed"}},{"id":"listening_u3_59","title":"The Environment: recording 2","actTitle":"The Environment: recording 2","youtubeId":"","htmlContent":"","problem":{"pType":"listen_passage","probTitle":"The Environment: recording 2","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset2_20.mp3","subs":[{"time":0,"en":"So, what exactly is fracking?","vi":"Vậy, chính xác thì fracking là gì?"},{"time":3580,"en":"It's a way of getting gas out of the ground.","vi":"Đó là một cách để lấy khí đốt ra khỏi lòng đất."},{"time":7040,"en":"Both oil and gas are found deep underground, so to get to them a well must be drilled.","vi":"Cả dầu và khí đốt đều được tìm thấy sâu dưới lòng đất, vì vậy để tiếp cận chúng, cần phải khoan một giếng."},{"time":13620,"en":"Normally, when a well is drilled into ground where there's gas, the natural pressure of the gas pushes it to the surface, where it can easily be taken away and stored.","vi":"Thông thường, khi một giếng được khoan vào khu vực có khí đốt, áp suất tự nhiên của khí đốt sẽ đẩy nó lên bề mặt, nơi nó có thể dễ dàng được lấy đi và lưu trữ."},{"time":24480,"en":"However, a lot of gas is found inside a type of rock called 'shale', where there is no natural pressure to push the gas out.","vi":"Tuy nhiên, một lượng lớn khí đốt được tìm thấy bên trong một loại đá gọi là 'đá phiến sét', nơi không có áp suất tự nhiên để đẩy khí đốt ra ngoài."},{"time":34100,"en":"If a well is drilled into shale, the gas will not come out by itself.","vi":"Nếu một giếng được khoan vào đá phiến sét, khí đốt sẽ không tự thoát ra."},{"time":38860,"en":"It needs extra help.","vi":"Nó cần thêm sự hỗ trợ."},{"time":41060,"en":"This is when fracking is an important way of getting the gas out.","vi":"Đây là lúc fracking trở thành một phương pháp quan trọng để lấy khí đốt ra."},{"time":45520,"en":"The fracking process works in this way: first, a well is drilled into the ground ,through the water table (which is the natural level of freshwater).","vi":"Quy trình fracking hoạt động theo cách này: đầu tiên, một giếng được khoan xuống đất, xuyên qua mực nước ngầm (là mức nước ngọt tự nhiên)."},{"time":56320,"en":"When the drill reaches the shale, which is where the gas is, itturnssidewaysth rough 90 degrees and continues horizontally through the shale.","vi":"Khi mũi khoan chạm đến đá phiến sét, nơi có khí đốt, nó sẽ quay ngang một góc 90 độ và tiếp tục đi ngang qua đá phiến sét."},{"time":66340,"en":"So, to put it simply, the drill goes down into the shale, where the gas is, and then turns to the side.","vi":"Vì vậy, nói một cách đơn giản, mũi khoan đi xuống đá phiến sét, nơi có khí đốt, và sau đó quay sang một bên."},{"time":74240,"en":"Then, a mixture of water, sand and various chemicals are sent down into the well.","vi":"Sau đó, một hỗn hợp nước, cát và các hóa chất khác nhau được đưa xuống giếng."},{"time":80760,"en":"The mixture creates pressure in the rock and the rock breaks.","vi":"Hỗn hợp này tạo ra áp suất trong đá và đá bị vỡ ra."},{"time":85300,"en":"These small breaks in the rock are known as 'fissures', and these fissures release the gas from the shale.","vi":"Những vết nứt nhỏ này trong đá được gọi là 'khe nứt', và những khe nứt này giải phóng khí đốt từ đá phiến sét."},{"time":93340,"en":"The pressure of the mixture causes the gas to rise to the surface, where it can be collected and stored.","vi":"Áp suất của hỗn hợp khiến khí đốt nổi lên bề mặt, nơi nó có thể được thu thập và lưu trữ."}],"probUrl":"https://study4.com/problems/120908/?view=embed"}},{"id":"listening_u3_60","title":"The Environment: recording 3","actTitle":"The Environment: recording 3","youtubeId":"","htmlContent":"","problem":{"pType":"listen_passage","probTitle":"The Environment: recording 3","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset2_21.mp3","subs":[{"time":0,"en":"Despite the benefits of fracking which its supporters claim, there are clearly various concerns connected with it.","vi":"Mặc dù những người ủng hộ tuyên bố về lợi ích của việc khai thác dầu khí bằng phương pháp fracking, nhưng rõ ràng có nhiều mối lo ngại liên quan đến nó."},{"time":8120,"en":"Some of these are real, but it's possible that they're not as well founded as opponents of fracking would have us believe.","vi":"Một số trong những lo ngại này là có thật, nhưng có thể chúng không có cơ sở vững chắc như những người phản đối fracking muốn chúng ta tin."},{"time":15580,"en":"So, what exactly are these concerns?","vi":"Vậy, chính xác thì những mối lo ngại này là gì?"},{"time":18980,"en":"Well, we can divide them into three categories: environmental concerns, health concerns, and economic concerns.","vi":"Chà, chúng ta có thể chia chúng thành ba loại: lo ngại về môi trường, lo ngại về sức khỏe và lo ngại về kinh tế."},{"time":27640,"en":"To begin with, let's look at the environmental concerns.","vi":"Để bắt đầu, chúng ta hãy xem xét những lo ngại về môi trường."},{"time":31600,"en":"The first and possibly most significant environmental concern is that, despite producing lower levels of carbon dioxide, shale gas is still a cause of global warming and so it should not be used.","vi":"Mối lo ngại về môi trường đầu tiên và có lẽ quan trọng nhất là, mặc dù sản xuất ra mức độ carbon dioxide thấp hơn, khí đá phiến vẫn là một nguyên nhân gây ra hiện tượng nóng lên toàn cầu và vì vậy không nên được sử dụng."},{"time":45820,"en":"In effect, it simply stops energy producers and governments focusing on the real need to develop renewable sources of energy.","vi":"Trên thực tế, nó chỉ đơn giản là ngăn cản các nhà sản xuất năng lượng và chính phủ tập trung vào nhu cầu thực sự là phát triển các nguồn năng lượng tái tạo."},{"time":54280,"en":"What's more, it's likely that, although countries which produce shale gas will use less coal and oil, the use of coal and oil will still continue to increase in other places, so globally there will be little or no benefit to the environment.","vi":"Hơn nữa, có khả năng là, mặc dù các quốc gia sản xuất khí đá phiến sẽ sử dụng ít than và dầu hơn, nhưng việc sử dụng than và dầu vẫn sẽ tiếp tục tăng ở những nơi khác, vì vậy trên toàn cầu sẽ có ít hoặc không có lợi ích cho môi trường."},{"time":72320,"en":"Another environmental concern is pollution.","vi":"Một mối lo ngại về môi trường khác là ô nhiễm."},{"time":75600,"en":"If the production site is badly maintained, dangerous chemicals can get into water sources and rivers and contaminate the water.","vi":"Nếu khu vực sản xuất không được bảo trì tốt, các hóa chất nguy hiểm có thể xâm nhập vào các nguồn nước và sông ngòi và làm ô nhiễm nước."},{"time":82260,"en":"While there's some evidence of this happening at existing production sites, it isn't clear whether this problem happens everywhere, so more research is needed.","vi":"Mặc dù có một số bằng chứng về việc này xảy ra tại các khu vực sản xuất hiện có, nhưng không rõ liệu vấn đề này có xảy ra ở mọi nơi hay không, vì vậy cần có thêm nghiên cứu."},{"time":93620,"en":"The last environmental concern connected with drilling is that of earthquakes.","vi":"Mối lo ngại về môi trường cuối cùng liên quan đến khoan là động đất."},{"time":99200,"en":"We're more familiar with earthquakes happening in certain areas of the world likeJapan and China, but there's evidence that drilling can disturb the ground in the local area, causing it to move and shake, which in turn damages buildings.","vi":"Chúng ta quen thuộc hơn với động đất xảy ra ở một số khu vực nhất định trên thế giới như Nhật Bản và Trung Quốc, nhưng có bằng chứng cho thấy việc khoan có thể làm xáo trộn mặt đất ở khu vực địa phương, khiến nó di chuyển và rung lắc, từ đó gây hư hại cho các tòa nhà."},{"time":114640,"en":"Usually, these movements aren't serious, but they can cause a lot of worry to the local population, so they need to be considered.","vi":"Thông thường, những chuyển động này không nghiêm trọng, nhưng chúng có thể gây ra nhiều lo lắng cho người dân địa phương, vì vậy chúng cần được xem xét."},{"time":124100,"en":"In fact, very few of these ground movements have definitely been caused by drilling, and it might be that people are worried because of what they hear or read in the media rather than the actual reality of the situation.","vi":"Trên thực tế, rất ít trong số các chuyển động trên mặt đất này chắc chắn là do khoan gây ra, và có thể mọi người lo lắng vì những gì họ nghe hoặc đọc được trên các phương tiện truyền thông hơn là thực tế của tình hình."},{"time":137920,"en":"Now I'd like to turn to the economic concerns.","vi":"Bây giờ tôi muốn chuyển sang những lo ngại về kinh tế."},{"time":141820,"en":"Opponents of fracking say that the economic benefits are not as great as its supporters claim.","vi":"Những người phản đối fracking nói rằng lợi ích kinh tế không lớn như những người ủng hộ tuyên bố."},{"time":148700,"en":"While there's clearly an increase in economic activity in the areas where fracking is carried out, as I discussed earlier, there are often negative effects on agriculture and farming in these areas and there's good evidence that house prices fall, because people aren't willing to move into areas where fracking is taking place or has taken place.","vi":"Mặc dù rõ ràng có sự gia tăng trong hoạt động kinh tế ở các khu vực nơi thực hiện fracking, như tôi đã thảo luận trước đó, thường có những tác động tiêu cực đến nông nghiệp và canh tác ở các khu vực này và có bằng chứng tốt cho thấy giá nhà giảm, vì mọi người không sẵn lòng chuyển đến các khu vực nơi fracking đang diễn ra hoặc đã diễn ra."},{"time":170380,"en":"Another economic concern is that gas production can be very high at the beginning of the fracking process, but it can drop quickly, down to as little as 10% in five years.","vi":"Một mối lo ngại kinh tế khác là sản lượng khí đốt có thể rất cao khi bắt đầu quá trình fracking, nhưng nó có thể giảm nhanh chóng, xuống chỉ còn 10% trong vòng năm năm."},{"time":182640,"en":"This can result in more drilling and greater use of water, which increases the cost of getting the gas out of the ground.","vi":"Điều này có thể dẫn đến việc khoan nhiều hơn và sử dụng nhiều nước hơn, làm tăng chi phí khai thác khí đốt từ lòng đất."},{"time":191140,"en":"The other main economic problem is that the estimated amount of gas in the ground may not be anywhere near as high as fracking supporters claim, so investing huge amounts of money in new wells may not benefit the economy at all.","vi":"Vấn đề kinh tế chính khác là lượng khí đốt ước tính trong lòng đất có thể không cao như những người ủng hộ fracking tuyên bố, vì vậy việc đầu tư một lượng lớn tiền vào các giếng mới có thể không mang lại lợi ích gì cho nền kinh tế."},{"time":208320,"en":"This brings me to the last major concern: health.","vi":"Điều này đưa tôi đến mối quan tâm lớn cuối cùng: sức khỏe."},{"time":212860,"en":"Fracking can bring with it a pollution problem.","vi":"Fracking có thể mang theo vấn đề ô nhiễm."},{"time":215760,"en":"If the well isn't deep enough - less than 600 metres - or if there are problems with drilling, the chemicals can leak into the drinking water supply and cause problems for the local population.","vi":"Nếu giếng không đủ sâu - dưới 600 mét - hoặc nếu có vấn đề với việc khoan, các hóa chất có thể rò rỉ vào nguồn cung cấp nước uống và gây ra vấn đề cho người dân địa phương."},{"time":227740,"en":"There've even been reports of residents opening their water taps and seeing brown water and mud coming out.","vi":"Thậm chí đã có báo cáo về việc cư dân mở vòi nước và thấy nước màu nâu và bùn chảy ra."},{"time":235000,"en":"However, it's not only the water supply which can be affected.","vi":"Tuy nhiên, không chỉ nguồn cung cấp nước có thể bị ảnh hưởng."},{"time":236520,"en":"Pollution can","vi":"Ô nhiễm có thể"},{"time":236980,"en":"also be carried in the air to local towns and affect people with existing medical problems, especially those with breathing difficulties.","vi":"cũng có thể được mang trong không khí đến các thị trấn địa phương và ảnh hưởng đến những người có vấn đề sức khỏe hiện tại, đặc biệt là những người khó thở."},{"time":245940,"en":"There've even been reports of more cases of cancer among people living near production sites, as well as among the workers themselves.","vi":"Thậm chí đã có báo cáo về nhiều trường hợp ung thư hơn ở những người sống gần các khu vực sản xuất, cũng như trong chính những người lao động."},{"time":253960,"en":"Clearly, a lot more research needs to be done on the effects of fracking on health.","vi":"Rõ ràng, cần phải thực hiện nhiều nghiên cứu hơn về ảnh hưởng của fracking đối với sức khỏe."},{"time":261500,"en":"So to summarise, there are significant environmental, economic and health concerns connected with fracking, but we need to carry out a lot more research to see whether these concerns are real.","vi":"Tóm lại, có những lo ngại đáng kể về môi trường, kinh tế và sức khỏe liên quan đến fracking, nhưng chúng ta cần thực hiện nhiều nghiên cứu hơn để xem liệu những lo ngại này có thật hay không."},{"time":275440,"en":"Whether they're real or not, they're having an effect on the fracking industry right now.","vi":"Cho dù chúng có thật hay không, chúng đang có ảnh hưởng đến ngành công nghiệp fracking ngay bây giờ."},{"time":280620,"en":"In many places around the world, local people have protested angrily when they've found out that fracking is planned in their area.","vi":"Ở nhiều nơi trên thế giới, người dân địa phương đã phản đối giận dữ khi họ phát hiện ra rằng fracking được lên kế hoạch ở khu vực của họ."},{"time":289740,"en":"These concerns have also led local, regional and national governments to announce that fracking won't start until they're quite sure that it's safe.","vi":"Những lo ngại này cũng đã khiến các chính phủ địa phương, khu vực và quốc gia tuyên bố rằng fracking sẽ không bắt đầu cho đến khi họ hoàn toàn chắc chắn rằng nó an toàn."},{"time":299260,"en":"This means that they'll prevent any activity connected with fracking until there's enough evidence to assure its safety, especially in areas with higher populations.","vi":"Điều này có nghĩa là họ sẽ ngăn chặn bất kỳ hoạt động nào liên quan đến fracking cho đến khi có đủ bằng chứng để đảm bảo an toàn, đặc biệt là ở các khu vực có dân số cao hơn."},{"time":309720,"en":"In fact, in France, they've decided not to allow fracking anywhere in the country.","vi":"Trên thực tế, ở Pháp, họ đã quyết định không cho phép fracking ở bất kỳ đâu trong nước."},{"time":315640,"en":"We can see that the future is very uncertain, and that is what I'd now like to discuss.","vi":"Chúng ta có thể thấy rằng tương lai rất không chắc chắn, và đó là điều mà bây giờ tôi muốn thảo luận."}],"probUrl":"https://study4.com/problems/120909/?view=embed"}},{"id":"listening_u3_61","title":"The Environment: recording 4","actTitle":"The Environment: recording 4","youtubeId":"","htmlContent":"","problem":{"pType":"listen_passage","probTitle":"The Environment: recording 4","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset2_22.mp3","subs":[{"time":0,"en":"While fracking is being used around the world, we've seen that there are serious concerns about it.","vi":"Mặc dù khai thác đá phiến sét (fracking) đang được sử dụng trên khắp thế giới, chúng ta thấy rằng có những lo ngại nghiêm trọng về nó."},{"time":7280,"en":"What's clear is that fracking isn't the answer to the growing worldwide need for energy as countries increase their consumption.","vi":"Rõ ràng là khai thác đá phiến sét không phải là giải pháp cho nhu cầu năng lượng ngày càng tăng trên toàn thế giới khi các quốc gia tăng mức tiêu thụ."},{"time":15780,"en":"Already, the amount of carbon dioxide in the atmosphere has reached 400 parts per million.","vi":"Hiện tại, lượng carbon dioxide trong khí quyển đã đạt mức 400 phần triệu (ppm)."},{"time":22280,"en":"This may not seem very high, but we have to remember that 200 years ago the level was around 280 parts per million, so it's increased by over a third since then.","vi":"Con số này có vẻ không cao, nhưng chúng ta phải nhớ rằng 200 năm trước, mức này chỉ khoảng 280 phần triệu, vì vậy nó đã tăng hơn một phần ba kể từ đó."},{"time":35080,"en":"As a result, it's estimated that global temperatures have already increased by almost one degree Celsius.","vi":"Do đó, ước tính nhiệt độ toàn cầu đã tăng gần một độ C."},{"time":42660,"en":"This increase changes the climate and affects the weather in many parts of the world.","vi":"Sự gia tăng này làm thay đổi khí hậu và ảnh hưởng đến thời tiết ở nhiều nơi trên thế giới."},{"time":48480,"en":"Many places, such as north-west Europe, are expected to become warmer and wetter, and we've seen winter storms becoming worse in this region.","vi":"Nhiều nơi, chẳng hạn như Tây Bắc châu Âu, dự kiến sẽ trở nên ấm hơn và ẩm ướt hơn, và chúng ta đã thấy các cơn bão mùa đông trở nên tồi tệ hơn ở khu vực này."},{"time":59100,"en":"Other places such as sub-Saharan Africa are expected to become hotter and drier, with deserts growing in area and seriously affecting farmland.","vi":"Những nơi khác như khu vực châu Phi cận Sahara dự kiến sẽ trở nên nóng hơn và khô hơn, với diện tích sa mạc ngày càng tăng và ảnh hưởng nghiêm trọng đến đất nông nghiệp."},{"time":70660,"en":"Ice in the polar regions will melt and sea levels will rise, which will put coastal cities in greater danger of flooding.","vi":"Băng ở các vùng cực sẽ tan chảy và mực nước biển sẽ dâng cao, điều này sẽ khiến các thành phố ven biển gặp nguy cơ ngập lụt lớn hơn."},{"time":78080,"en":"Clearly, we need to reduce, and eventually stop, using non-renewable resources like coal, oil and gas.","vi":"Rõ ràng, chúng ta cần giảm và cuối cùng là ngừng sử dụng các nguồn tài nguyên không tái tạo như than đá, dầu mỏ và khí đốt."},{"time":88380,"en":"It may well be true that fracking can slow down global warming for a while and allow us to develop better renewable resources.","vi":"Có thể đúng là khai thác đá phiến sét có thể làm chậm quá trình nóng lên toàn cầu trong một thời gian và cho phép chúng ta phát triển các nguồn tài nguyên tái tạo tốt hơn."},{"time":97620,"en":"However, these resources, like wind, wave and solar power, are currently far more expensive to develop than shale gas production.","vi":"Tuy nhiên, các nguồn tài nguyên này, như năng lượng gió, sóng và mặt trời, hiện đang tốn kém hơn nhiều để phát triển so với sản xuất khí đá phiến."},{"time":107120,"en":"On top of that, they take a long time to develop and start paying for themselves.","vi":"Thêm vào đó, chúng mất nhiều thời gian để phát triển và bắt đầu tự chi trả cho bản thân."},{"time":112480,"en":"Consumers have to pay higher bills to help the development of cleaner sources, and energy companies don't want to lose customers by asking them to pay more.","vi":"Người tiêu dùng phải trả hóa đơn cao hơn để giúp phát triển các nguồn năng lượng sạch hơn, và các công ty năng lượng không muốn mất khách hàng bằng cách yêu cầu họ trả nhiều tiền hơn."},{"time":122800,"en":"Consequently, it's important for international organisations like the United Nations and national governments to support the development of renewable resources.","vi":"Do đó, điều quan trọng là các tổ chức quốc tế như Liên Hợp Quốc và chính phủ các nước phải hỗ trợ phát triển các nguồn tài nguyên tái tạo."},{"time":134220,"en":"The problem here, of course, is that governments usually think of short-term answers to energy problems and not longer-term ones.","vi":"Vấn đề ở đây, tất nhiên, là các chính phủ thường nghĩ đến các giải pháp ngắn hạn cho các vấn đề năng lượng chứ không phải các giải pháp dài hạn."},{"time":142700,"en":"They're afraid that if they reduce the production and use of gas and oil, their economies will do worse than other economies, so they don't want to take action to increase the use of renewable sources.","vi":"Họ sợ rằng nếu họ giảm sản xuất và sử dụng khí đốt và dầu mỏ, nền kinh tế của họ sẽ hoạt động kém hơn các nền kinh tế khác, vì vậy họ không muốn hành động để tăng cường sử dụng các nguồn tái tạo."},{"time":154660,"en":"As I mentioned earlier, there are many people in different countries, like Canada, the UK and France, who don't support fracking, especially if it's going to take place near where they live.","vi":"Như tôi đã đề cập trước đó, có nhiều người ở các quốc gia khác nhau, như Canada, Vương quốc Anh và Pháp, không ủng hộ việc khai thác đá phiến sét, đặc biệt nếu nó diễn ra gần nơi họ sống."},{"time":166020,"en":"Environmental groups also oppose fracking, not just because they want to protect people living in areas where fracking is planned, but also because they see fracking as part of the old way of doing things, like burning coal, oil and gas and increasing global warming.","vi":"Các nhóm môi trường cũng phản đối khai thác đá phiến sét, không chỉ vì họ muốn bảo vệ những người sống ở những khu vực có kế hoạch khai thác đá phiến sét, mà còn vì họ coi khai thác đá phiến sét là một phần của cách làm cũ, như đốt than, dầu và khí đốt và làm tăng sự nóng lên toàn cầu."},{"time":184360,"en":"They want to see continued action and are trying to persuade governments to develop wind, wave and solar power, as well as other renewable forms of energy, to fight global warming and ensure the supply of energy in the future.","vi":"Họ muốn thấy hành động tiếp tục và đang cố gắng thuyết phục các chính phủ phát triển năng lượng gió, sóng và mặt trời, cũng như các dạng năng lượng tái tạo khác, để chống lại sự nóng lên toàn cầu và đảm bảo nguồn cung cấp năng lượng trong tương lai."},{"time":198880,"en":"Certainly, coal, oil and gas will run out one day, and if we haven't developed other forms of renewable energy, we'll then have serious problems with supplying energy to the growing world population, and the problems of fracking will seem relatively unimportant.","vi":"Chắc chắn, than đá, dầu mỏ và khí đốt sẽ cạn kiệt một ngày nào đó, và nếu chúng ta chưa phát triển các dạng năng lượng tái tạo khác, thì chúng ta sẽ gặp những vấn đề nghiêm trọng trong việc cung cấp năng lượng cho dân số thế giới đang ngày càng tăng, và những vấn đề của việc khai thác đá phiến sét sẽ có vẻ tương đối không quan trọng."}],"probUrl":"https://study4.com/problems/120910/?view=embed"}},{"id":"listening_u3_62","title":"Schools and Studying: recording 1","actTitle":"Schools and Studying: recording 1","youtubeId":"","htmlContent":"","problem":{"pType":"listen_passage","probTitle":"Schools and Studying: recording 1","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset2_23.mp3","subs":[{"time":0,"en":"The British education system is not the same everywhere in the UK.","vi":"Hệ thống giáo dục của Anh không giống nhau ở mọi nơi trên Vương quốc Anh."},{"time":5820,"en":"Scotland has its own system, and while Northern Ireland has the same basic system as England and Wales, there are some differences.","vi":"Scotland có hệ thống riêng, và trong khi Bắc Ireland có hệ thống cơ bản giống như Anh và xứ Wales, vẫn có một số khác biệt."},{"time":14500,"en":"Because of this, I'm going to focus mainly on England and Wales.","vi":"Vì điều này, tôi sẽ tập trung chủ yếu vào Anh và xứ Wales."},{"time":19360,"en":"The system in England and Wales is divided into three main levels: primary, secondary and tertiary.","vi":"Hệ thống ở Anh và xứ Wales được chia thành ba cấp độ chính: tiểu học, trung học và đại học."},{"time":27220,"en":"In the first part of my lecture, I'll talk about the primary and secondary levels up to the age of 16, and in the second part I'll discuss the options between 16 and 18.","vi":"Trong phần đầu của bài giảng, tôi sẽ nói về các cấp tiểu học và trung học đến 16 tuổi, và trong phần thứ hai, tôi sẽ thảo luận về các lựa chọn từ 16 đến 18 tuổi."},{"time":38600,"en":"Then, finally, I'll talk about tertiary, or 'higher' level, education.","vi":"Sau đó, cuối cùng, tôi sẽ nói về giáo dục cấp đại học, hoặc cấp 'cao hơn'."},{"time":44320,"en":"As in most similar countries, education at school is compulsory between the ages of five and 16.","vi":"Như ở hầu hết các quốc gia tương tự, giáo dục ở trường là bắt buộc từ 5 đến 16 tuổi."},{"time":51480,"en":"Pupils can leave school at 16 but they must stay in an approved learning environment until the age of 18.","vi":"Học sinh có thể rời trường lúc 16 tuổi nhưng phải ở trong một môi trường học tập được chấp thuận cho đến 18 tuổi."},{"time":59060,"en":"This can be full-time education, a job or volunteering combined with part-time study, or an apprenticeship, sometimes called a 'traineeship'.","vi":"Điều này có thể là giáo dục toàn thời gian, một công việc hoặc làm tình nguyện kết hợp với học bán thời gian, hoặc một chương trình học nghề, đôi khi được gọi là 'thực tập sinh'."},{"time":68880,"en":"Before the age of five, children can attend nursery, though they don't have to attend any educational institution at all before the age of five.","vi":"Trước 5 tuổi, trẻ em có thể đi nhà trẻ, mặc dù chúng không bắt buộc phải đến bất kỳ cơ sở giáo dục nào trước 5 tuổi."},{"time":78240,"en":"However, when they reach the age of four, they usually start school in an early class called 'Reception', which helps them to adjust to regular schooling.","vi":"Tuy nhiên, khi đến 4 tuổi, trẻ thường bắt đầu đi học ở một lớp sớm gọi là 'Lớp tiếp nhận', giúp trẻ làm quen với việc học chính quy."},{"time":87700,"en":"Primary school runs from the ages of five to 11.","vi":"Trường tiểu học kéo dài từ 5 đến 11 tuổi."},{"time":93260,"en":"The first part of primary school, between the ages of five and seven, is traditionally known as 'infant school' and this is where children learn to manipulate numbers, read and write.","vi":"Phần đầu tiên của trường tiểu học, từ 5 đến 7 tuổi, theo truyền thống được gọi là 'trường mầm non' và đây là nơi trẻ em học cách làm quen với các con số, đọc và viết."},{"time":104960,"en":"Traditional infant schools offer an informal education using child-centred techniques.","vi":"Các trường mầm non truyền thống cung cấp một nền giáo dục không chính thức bằng cách sử dụng các kỹ thuật lấy trẻ làm trung tâm."},{"time":111640,"en":"The second part of primary school, from seven to 11, is known as 'junior school'.","vi":"Phần thứ hai của trường tiểu học, từ 7 đến 11 tuổi, được gọi là 'trường cấp hai'."},{"time":117700,"en":"The education system has undergone various changes in the last 30 years, most notably with the National Curriculum, which was put in place in 1988 to specify a set of core main subjects that all school pupils have to study.","vi":"Hệ thống giáo dục đã trải qua nhiều thay đổi khác nhau trong 30 năm qua, đáng chú ý nhất là Chương trình giảng dạy quốc gia, được đưa ra vào năm 1988 để chỉ định một bộ các môn học chính cốt lõi mà tất cả học sinh phải học."},{"time":133720,"en":"These subjects have to be assessed at four key stages up to the age of 16.","vi":"Các môn học này phải được đánh giá ở bốn giai đoạn chính cho đến 16 tuổi."},{"time":139340,"en":"At certain stages, the children take exams known as 'Standard Assessment Tests', or 'SATS'.","vi":"Ở một số giai đoạn nhất định, trẻ em làm các bài kiểm tra được gọi là 'Bài kiểm tra Đánh giá Tiêu chuẩn', hay 'SATS'."},{"time":146440,"en":"These tests are designed to check the pupils' progress against the national standards, as well as to provide teachers and parents with an assessment of their school's performance.","vi":"Các bài kiểm tra này được thiết kế để kiểm tra sự tiến bộ của học sinh so với các tiêu chuẩn quốc gia, cũng như cung cấp cho giáo viên và phụ huynh đánh giá về hiệu suất của trường."},{"time":156900,"en":"Key Stage 1 assessment comes at the age of seven, when the pupils do their first 'Teacher Assessments'.","vi":"Đánh giá Giai đoạn then chốt 1 diễn ra ở tuổi lên bảy, khi học sinh thực hiện 'Đánh giá của Giáo viên' đầu tiên."},{"time":164020,"en":"Key Stage 2 comes at the age of 11, when the pupils are ready to leave primary school.","vi":"Giai đoạn then chốt 2 diễn ra ở tuổi 11, khi học sinh đã sẵn sàng rời trường tiểu học."},{"time":171100,"en":"Although teachers assess their pupils' progress throughout primary school, at the end of Key Stage 2, unlike in Key Stage 1, pupils have to take SATS.","vi":"Mặc dù giáo viên đánh giá sự tiến bộ của học sinh trong suốt trường tiểu học, nhưng vào cuối Giai đoạn then chốt 2, không giống như Giai đoạn then chốt 1, học sinh phải làm bài kiểm tra SATS."},{"time":181700,"en":"Key Stage 3 is reached after the first three years in secondary school, when the pupils are 14.","vi":"Giai đoạn then chốt 3 đạt được sau ba năm đầu tiên ở trường trung học cơ sở, khi học sinh 14 tuổi."},{"time":189540,"en":"However, this time, the students are assessed directly by the teachers and not by sitting national tests.","vi":"Tuy nhiên, lần này, học sinh được đánh giá trực tiếp bởi giáo viên chứ không phải làm các bài kiểm tra quốc gia."},{"time":197100,"en":"These assessments help teachers, students and parents to decide which subjects the students should choose to prepare for Key Stage 4, when they take exams which will help decide their future career choices.","vi":"Những đánh giá này giúp giáo viên, học sinh và phụ huynh quyết định những môn học nào học sinh nên chọn để chuẩn bị cho Giai đoạn then chốt 4, khi các em làm các bài kiểm tra giúp quyết định lựa chọn nghề nghiệp tương lai."},{"time":210940,"en":"Unlike SATS, these assessments, known as 'General Certificate of Secondary Education' exams, or 'GCSEs', are not primarily designed to assess progress or give schools an official statement of their performance, but to provide students with their own personal qualifications.","vi":"Không giống như SATS, những đánh giá này, được gọi là kỳ thi 'Chứng chỉ Giáo dục Trung học Phổ thông' hoặc 'GCSE', không chủ yếu được thiết kế để đánh giá sự tiến bộ hoặc đưa ra cho các trường một tuyên bố chính thức về hiệu suất của họ, mà là cung cấp cho học sinh trình độ cá nhân của riêng họ."},{"time":230820,"en":"The National Curriculum defined a set of compulsory subjects.","vi":"Chương trình giảng dạy quốc gia quy định một bộ môn học bắt buộc."},{"time":235520,"en":"These are subjects which the law requires all students to study.","vi":"Đây là những môn học mà luật pháp yêu cầu tất cả học sinh phải học."},{"time":239960,"en":"There are also some subjects which pupils and students have to study at different stages.","vi":"Ngoài ra, có một số môn học mà học sinh phải học ở các giai đoạn khác nhau."},{"time":246020,"en":"For example, Modern Foreign Languages start in primary school, and continue up to Key Stage 3, after which they're optional.","vi":"Ví dụ: Ngoại ngữ hiện đại bắt đầu ở trường tiểu học và tiếp tục đến Giai đoạn then chốt 3, sau đó chúng là tùy chọn."},{"time":255520,"en":"In secondary school, students take Citizenship from Key Stage 3.","vi":"Ở trường trung học, học sinh học môn Công dân từ Giai đoạn then chốt 3."},{"time":260720,"en":"When they enter Key Stage 4, pupils are allowed to make more choices.","vi":"Khi bước vào Giai đoạn then chốt 4, học sinh được phép đưa ra nhiều lựa chọn hơn."},{"time":265560,"en":"For example, all learners have to take History and Design and Technology up to the age of 14, but then they can choose whether to continue them or not.","vi":"Ví dụ: tất cả người học phải học Lịch sử và Thiết kế và Công nghệ cho đến 14 tuổi, nhưng sau đó họ có thể chọn tiếp tục học hay không."}],"probUrl":"https://study4.com/problems/120911/?view=embed"}},{"id":"listening_u3_63","title":"Schools and Studying: recording 2","actTitle":"Schools and Studying: recording 2","youtubeId":"","htmlContent":"","problem":{"pType":"listen_passage","probTitle":"Schools and Studying: recording 2","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset2_24.mp3","subs":[{"time":0,"en":"Now I'd like to turn to educational opportunities between the ages of 16 and 18.","vi":"Bây giờ, tôi muốn chuyển sang các cơ hội giáo dục cho độ tuổi từ 16 đến 18."},{"time":6480,"en":"There are various choices open to pupils of this age.","vi":"Có nhiều lựa chọn khác nhau dành cho học sinh ở độ tuổi này."},{"time":10060,"en":"The first thing to decide is whether to start work or to continue studying full-time.","vi":"Điều đầu tiên cần quyết định là bắt đầu đi làm hay tiếp tục học toàn thời gian."},{"time":15960,"en":"Of course, starting work means going straight into employment, although young people aged between 16 and 18 will still need either to study part-time, as well as doing their job, or to join an apprenticeship or traineeship scheme.","vi":"Tất nhiên, bắt đầu đi làm có nghĩa là đi thẳng vào làm việc, mặc dù những người trẻ tuổi từ 16 đến 18 vẫn cần phải học bán thời gian, cũng như làm công việc của họ, hoặc tham gia một chương trình học nghề hoặc thực tập."},{"time":31460,"en":"For those who want to continue studying full-time, there are two paths: academic and vocational.","vi":"Đối với những người muốn tiếp tục học toàn thời gian, có hai con đường: học thuật và hướng nghiệp."},{"time":38440,"en":"Academic qualifications, mainly Advanced level exams, known as 'A levels', are taken by students aiming for university study.","vi":"Bằng cấp học thuật, chủ yếu là các kỳ thi trình độ nâng cao, được gọi là 'A levels', được thực hiện bởi các sinh viên hướng đến việc học đại học."},{"time":48020,"en":"Vocational qualifications, such as those offered by the Business and Technology Education Council (or 'BTEC' for short), prepare pupils for a specific profession, such as engineering or computing.","vi":"Các bằng cấp hướng nghiệp, chẳng hạn như những bằng cấp do Hội đồng Giáo dục Kinh doanh và Công nghệ (hoặc viết tắt là 'BTEC') cung cấp, chuẩn bị cho học sinh một nghề nghiệp cụ thể, chẳng hạn như kỹ thuật hoặc máy tính."},{"time":62580,"en":"Most of those who wish to continue academic studies will go to the sixth form in their school or a specialist sixth form college.","vi":"Hầu hết những người muốn tiếp tục học tập về mặt học thuật sẽ vào lớp sáu tại trường của họ hoặc một trường cao đẳng chuyên biệt lớp sáu."},{"time":70640,"en":"Alternatively, they can study A levels at a further education college, also known as an 'FE' college.","vi":"Ngoài ra, họ có thể học A levels tại một trường cao đẳng giáo dục thường xuyên, còn được gọi là trường cao đẳng 'FE'."},{"time":78060,"en":"Either of these routes will take students to university.","vi":"Một trong hai con đường này sẽ đưa sinh viên đến trường đại học."},{"time":81880,"en":"On the other hand, those who wish to study a vocational qualification will typically go to a Further Education college and, after qualifying, will be ready for employment.","vi":"Mặt khác, những người muốn học một bằng cấp hướng nghiệp thường sẽ đến một trường Cao đẳng Giáo dục Thường xuyên và sau khi đủ điều kiện, sẽ sẵn sàng cho việc làm."},{"time":92540,"en":"There are other options for those who want to start work at 16. Since 2015, young people","vi":"Có những lựa chọn khác cho những người muốn bắt đầu làm việc ở tuổi 16. Kể từ năm 2015, những người trẻ"},{"time":98980,"en":"between the ages of 16 and 18 must continue to learn in a specified learning environment, in addition to working for an employer.","vi":"trong độ tuổi từ 16 đến 18 phải tiếp tục học tập trong một môi trường học tập cụ thể, ngoài việc làm cho một người chủ."},{"time":108400,"en":"The first option is to work for an employer and study","vi":"Lựa chọn đầu tiên là làm việc cho một người chủ và học tập"},{"time":111760,"en":"part-time for a vocational qualification, such as a National Vocational Qualification (or 'INVQ' for short).","vi":"bán thời gian để có được một bằng cấp nghề, chẳng hạn như Chứng chỉ Nghề Quốc gia (hoặc viết tắt là 'INVQ')."},{"time":120720,"en":"The second is to apply for an apprenticeship or traineeship.","vi":"Thứ hai là đăng ký học nghề hoặc thực tập."},{"time":125260,"en":"With apprenticeships, young people get to work with experienced staff and gain job-related skills.","vi":"Với chương trình học nghề, những người trẻ tuổi được làm việc với các nhân viên giàu kinh nghiệm và có được các kỹ năng liên quan đến công việc."},{"time":132340,"en":"They earn a wage, although this is typically less than a 'regular' employee, and get to continue studying part-time - usually one day a week.","vi":"Họ kiếm được một khoản lương, mặc dù thường thấp hơn một nhân viên 'chính thức', và được tiếp tục học bán thời gian - thường là một ngày một tuần."},{"time":141900,"en":"They study towards a qualification related to the job they are doing and their apprenticeship can last anywhere between one and four years.","vi":"Họ học để đạt được một bằng cấp liên quan đến công việc họ đang làm và chương trình học nghề của họ có thể kéo dài từ một đến bốn năm."},{"time":150960,"en":"Almost always, they are offered a permanent job by the same employer at the end of their apprenticeship.","vi":"Hầu như luôn luôn, họ được nhà tuyển dụng tương tự đề nghị một công việc lâu dài khi kết thúc chương trình học nghề của họ."}],"probUrl":"https://study4.com/problems/120912/?view=embed"}},{"id":"listening_u3_64","title":"Celebrations and Traditions: recording 1","actTitle":"Celebrations and Traditions: recording 1","youtubeId":"","htmlContent":"","problem":{"pType":"listen_passage","probTitle":"Celebrations and Traditions: recording 1","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset2_25.mp3","subs":[{"time":0,"en":"So, first of all, we need to look at the events and see what should be included in next year's festival and what changes should be made.","vi":"Vậy thì, trước hết, chúng ta cần xem xét các sự kiện và xem những gì nên được đưa vào lễ hội năm tới và những thay đổi nào nên được thực hiện."},{"time":8020,"en":"Dr Saunders mentioned that there were issues with the music and crafts.","vi":"Tiến sĩ Saunders đã đề cập rằng có những vấn đề với âm nhạc và đồ thủ công."},{"time":12520,"en":"What are your feelings on those two issues?","vi":"Các bạn có cảm nghĩ gì về hai vấn đề đó?"},{"time":14780,"en":"Do you want to start, Sangita?","vi":"Bạn muốn bắt đầu trước không, Sangita?"},{"time":16900,"en":"Well, as regards the music, I think we need to have another artist in reserve in case the main act can't perform, like in this year's festival.","vi":"Về phần âm nhạc, tôi nghĩ chúng ta cần có một nghệ sĩ dự phòng trong trường hợp nghệ sĩ chính không thể biểu diễn, giống như lễ hội năm nay."},{"time":27140,"en":"It doesn't have to be a well-known band.","vi":"Không nhất thiết phải là một ban nhạc nổi tiếng."},{"time":29660,"en":"It could be a small act, like a student band.","vi":"Đó có thể là một ban nhạc nhỏ, chẳng hạn như một ban nhạc sinh viên."},{"time":33300,"en":"What do you think, Lawrence?","vi":"Bạn nghĩ sao, Lawrence?"},{"time":35720,"en":"You have a point, but I'm not really sure if any artists would be happy to perform only if the main act lets us down.","vi":"Bạn nói có lý, nhưng tôi không chắc liệu có nghệ sĩ nào vui vẻ biểu diễn chỉ khi nghệ sĩ chính bỏ ngang hay không."},{"time":44960,"en":"In any case, how often does that happen?","vi":"Dù sao thì, chuyện đó xảy ra thường xuyên không?"},{"time":48080,"en":"This was the first time, and I don't see it happening again in the future.","vi":"Đây là lần đầu tiên, và tôi không nghĩ nó sẽ xảy ra nữa trong tương lai."},{"time":52020,"en":"I'm not sure we can take that for granted, Lawrence.","vi":"Tôi không chắc chúng ta có thể xem đó là điều hiển nhiên, Lawrence."},{"time":54880,"en":"If you look at what happened, we lost £3,000 as we had to return money to the audience.","vi":"Nếu bạn nhìn vào những gì đã xảy ra, chúng ta đã mất 3.000 bảng vì phải trả lại tiền cho khán giả."},{"time":60600,"en":"I don't think anything bad would have happened, but I think we need to bear in mind that our visitors are the most important aspect of the festival and we have to make sure we keep them happy at all costs.","vi":"Tôi không nghĩ điều gì tồi tệ sẽ xảy ra, nhưng tôi nghĩ chúng ta cần ghi nhớ rằng khách tham quan là khía cạnh quan trọng nhất của lễ hội và chúng ta phải đảm bảo rằng chúng ta giữ cho họ hài lòng bằng mọi giá."},{"time":71700,"en":"How about we arrange the programme so that on one night there isn't a famous headline act but a good local band, so that we can change the programme to make them the main act if anyone else isn't able to perform.","vi":"Chúng ta sắp xếp chương trình sao cho vào một đêm không có nghệ sĩ chính nổi tiếng mà là một ban nhạc địa phương giỏi, để chúng ta có thể thay đổi chương trình để biến họ thành nghệ sĩ chính nếu những người khác không thể biểu diễn thì sao?"},{"time":85460,"en":"We could put them on the last evening, and tell them that they may be needed on the other evenings, just in case.","vi":"Chúng ta có thể để họ biểu diễn vào đêm cuối cùng, và nói với họ rằng họ có thể cần thiết vào những đêm khác, chỉ là trong trường hợp khẩn cấp."},{"time":93260,"en":"That way, we're helping good local talent and making sure that our visitors are happy.","vi":"Bằng cách đó, chúng ta đang giúp đỡ tài năng địa phương tốt và đảm bảo rằng khách tham quan của chúng ta hài lòng."},{"time":99300,"en":"Yes, I can see that working.","vi":"Ừ, tôi thấy điều đó có thể hiệu quả."},{"time":101720,"en":"Then we could use the student band to play the last night if we have to switch the local band from the last night to an earlier night.","vi":"Sau đó, chúng ta có thể sử dụng ban nhạc sinh viên để chơi vào đêm cuối cùng nếu chúng ta phải chuyển ban nhạc địa phương từ đêm cuối cùng sang đêm trước đó."},{"time":109480,"en":"OK ... good ideas.","vi":"Được rồi... ý tưởng hay."},{"time":111380,"en":"I'll make a note so that we can take it back to the organising committee.","vi":"Tôi sẽ ghi chú lại để chúng ta có thể trình bày lại với ban tổ chức."},{"time":115000,"en":"Now, let's move on to the question of crafts.","vi":"Bây giờ, chúng ta hãy chuyển sang vấn đề đồ thủ công."},{"time":117640,"en":"As we heard, the event didn't go very well and lacked visitors.","vi":"Như chúng ta đã nghe, sự kiện diễn ra không tốt lắm và thiếu khách tham quan."},{"time":122200,"en":"What do you think we should do, Sangita?","vi":"Bạn nghĩ chúng ta nên làm gì, Sangita?"},{"time":124440,"en":"Well, I have a personal interest in this.","vi":"Chà, tôi có một sự quan tâm cá nhân đến điều này."},{"time":127500,"en":"I've been creating my own fashion designs and I had some clothes on display mixing Western and Indian themes.","vi":"Tôi đã tạo ra những thiết kế thời trang của riêng mình và tôi đã trưng bày một số quần áo kết hợp các chủ đề phương Tây và Ấn Độ."},{"time":135440,"en":"Actually, I spent some time watching the visitors and I thought they liked the clothes a lot.","vi":"Thực ra, tôi đã dành thời gian quan sát khách tham quan và tôi nghĩ họ rất thích quần áo."},{"time":141720,"en":"I think we have to be careful to distinguish the clothes from the other crafts.","vi":"Tôi nghĩ chúng ta phải cẩn thận để phân biệt quần áo với các đồ thủ công khác."},{"time":147500,"en":"Yes, I noticed that.","vi":"Ừ, tôi đã nhận thấy điều đó."},{"time":149320,"en":"I spent the third day in the craft section helping visitors and I noticed that the clothes exhibition was the most appreciated.","vi":"Tôi đã dành ngày thứ ba ở khu vực thủ công mỹ nghệ để giúp đỡ du khách và tôi nhận thấy rằng triển lãm quần áo được đánh giá cao nhất."},{"time":157420,"en":"I think the glass and ceramic section had hardly any visitors when I was there.","vi":"Tôi nghĩ khu vực thủy tinh và gốm sứ hầu như không có khách tham quan khi tôi ở đó."},{"time":161860,"en":"Perhaps we should just have the clothes on display, maybe even extend that section?","vi":"Có lẽ chúng ta chỉ nên trưng bày quần áo, thậm chí có thể mở rộng khu vực đó?"},{"time":168160,"en":"Yes, that could be a good solution.","vi":"Ừ, đó có thể là một giải pháp tốt."},{"time":171020,"en":"I don't think we should get rid of the glass and pottery altogether, but I certainly think we should promote the clothes section more.","vi":"Tôi không nghĩ chúng ta nên loại bỏ hoàn toàn đồ thủy tinh và gốm sứ, nhưng tôi chắc chắn nghĩ rằng chúng ta nên quảng bá khu vực quần áo nhiều hơn."},{"time":177420,"en":"Well, here's a suggestion: we could even think of turning that into a separate fashion show.","vi":"Chà, đây là một gợi ý: chúng ta thậm chí có thể nghĩ đến việc biến nó thành một buổi trình diễn thời trang riêng biệt."},{"time":183240,"en":"What do you think of that?","vi":"Bạn nghĩ gì về điều đó?"},{"time":184900,"en":"Good idea! I was thinking about that anyway. Can we put that to the committee?","vi":"Ý tưởng hay! Dù sao thì tôi cũng đang nghĩ về điều đó. Chúng ta có thể trình bày điều đó với ủy ban không?"},{"time":190360,"en":"Of course.","vi":"Tất nhiên rồi."},{"time":191220,"en":"I've made a note of it.","vi":"Tôi đã ghi chú lại rồi."},{"time":192680,"en":"Regarding the theatre and poetry, do you think we need to make any changes?","vi":"Về phần sân khấu và thơ ca, bạn có nghĩ chúng ta cần thực hiện bất kỳ thay đổi nào không?"},{"time":196960,"en":"Nothing major, I don't think, but perhaps we should use at least one day to present new plays and poems by our own students.","vi":"Tôi không nghĩ có gì lớn, nhưng có lẽ chúng ta nên dành ít nhất một ngày để giới thiệu các vở kịch và bài thơ mới của sinh viên chúng ta."},{"time":205840,"en":"It's wonderful putting on plays by well-known playwrights and readings of well-known poets, but perhaps we should promote our own talent here in the university.","vi":"Thật tuyệt vời khi dàn dựng các vở kịch của các nhà viết kịch nổi tiếng và đọc thơ của các nhà thơ nổi tiếng, nhưng có lẽ chúng ta nên quảng bá tài năng của chính mình tại trường đại học này."},{"time":215820,"en":"It would certainly help the performing arts students to expand their coursework, and we could have a competition for the best new works.","vi":"Điều đó chắc chắn sẽ giúp các sinh viên nghệ thuật biểu diễn mở rộng các môn học của họ, và chúng ta có thể tổ chức một cuộc thi cho các tác phẩm mới hay nhất."},{"time":224340,"en":"Excellent idea, Lawrence. What do you think, Sangita?","vi":"Ý tưởng tuyệt vời, Lawrence. Bạn nghĩ sao, Sangita?"},{"time":228120,"en":"Yes, but let's not limit it to just English.","vi":"Ừ, nhưng đừng giới hạn nó chỉ ở tiếng Anh."},{"time":231820,"en":"We could also have performances from our international students in their languages.","vi":"Chúng ta cũng có thể có các buổi biểu diễn từ các sinh viên quốc tế của chúng ta bằng ngôn ngữ của họ."},{"time":236780,"en":"I think that would really help promote the festival as an international event.","vi":"Tôi nghĩ điều đó sẽ thực sự giúp quảng bá lễ hội như một sự kiện quốc tế."},{"time":241460,"en":"Fine.","vi":"Tốt thôi."},{"time":242180,"en":"We can propose that as well.","vi":"Chúng ta cũng có thể đề xuất điều đó."},{"time":244160,"en":"And as far as the photography and cinema sections are concerned, they'll keep expanding.","vi":"Và về phần các khu vực nhiếp ảnh và điện ảnh, chúng sẽ tiếp tục mở rộng."},{"time":249140,"en":"Well, personally, I don't think the quality of the photography exhibition was very high.","vi":"Chà, cá nhân tôi không nghĩ rằng chất lượng của triển lãm nhiếp ảnh cao lắm."},{"time":254780,"en":"I think there are issues with digital photography being presented as a printed exhibition.","vi":"Tôi nghĩ có những vấn đề với việc nhiếp ảnh kỹ thuật số được trình bày dưới dạng một triển lãm in."},{"time":259940,"en":"You can never really capture the true meaning of the photograph like that.","vi":"Bạn không bao giờ có thể thực sự nắm bắt được ý nghĩa thực sự của bức ảnh như vậy."},{"time":265260,"en":"I would suggest just having digital displays, you know, tablets that visitors can use to see the photographer's collection.","vi":"Tôi đề nghị chỉ nên có màn hình kỹ thuật số, bạn biết đấy, máy tính bảng mà khách tham quan có thể sử dụng để xem bộ sưu tập của nhiếp ảnh gia."},{"time":273520,"en":"That way, it'll encourage photographers to develop their ideas and think about their exhibits almost as films with a story.","vi":"Bằng cách đó, nó sẽ khuyến khích các nhiếp ảnh gia phát triển ý tưởng của họ và suy nghĩ về các cuộc triển lãm của họ gần như là những bộ phim có câu chuyện."},{"time":282120,"en":"I think that's the way photography is going these days.","vi":"Tôi nghĩ đó là xu hướng của nhiếp ảnh ngày nay."},{"time":285140,"en":"I don't agree.","vi":"Tôi không đồng ý."},{"time":286420,"en":"I think each image should be appreciated in its own way, as the photographer intends.","vi":"Tôi nghĩ mỗi hình ảnh nên được đánh giá theo cách riêng của nó, như ý định của nhiếp ảnh gia."},{"time":292940,"en":"I don't think we should push photographers into one direction.","vi":"Tôi không nghĩ chúng ta nên đẩy các nhiếp ảnh gia vào một hướng duy nhất."},{"time":297120,"en":"That said, I think the idea of having tablets and digital screens is a good idea if we can afford it.","vi":"Điều đó nói lên rằng, tôi nghĩ ý tưởng có máy tính bảng và màn hình kỹ thuật số là một ý tưởng hay nếu chúng ta có đủ khả năng."},{"time":304100,"en":"Perhaps we could have two sections - digital displays and non-digital displays.","vi":"Có lẽ chúng ta có thể có hai khu vực - màn hình kỹ thuật số và màn hình không kỹ thuật số."},{"time":309800,"en":"Sounds good, Sangita.","vi":"Nghe hay đấy, Sangita."},{"time":311180,"en":"I can certainly put thatto the committee and see if they'll consider it.","vi":"Tôi chắc chắn có thể trình bày điều đó với ủy ban và xem họ có xem xét không."},{"time":314980,"en":"So, if that's all about the events themselves, I'd like to discuss the organisation of the festival ...","vi":"Vậy, nếu đó là tất cả về các sự kiện, tôi muốn thảo luận về việc tổ chức lễ hội..."}],"probUrl":"https://study4.com/problems/120913/?view=embed"}},{"id":"listening_u3_65","title":"Celebrations and Traditions: recording 2","actTitle":"Celebrations and Traditions: recording 2","youtubeId":"","htmlContent":"","problem":{"pType":"listen_passage","probTitle":"Celebrations and Traditions: recording 2","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset2_26.mp3","subs":[{"time":0,"en":"Now, the next thing I think we should discuss is the accommodation situation.","vi":"Tiếp theo, tôi nghĩ chúng ta nên thảo luận về vấn đề chỗ ở."},{"time":5080,"en":"It seems clear that the number of visitors is set to grow, so we need to have a suitable plan in place to deal with the increased numbers.","vi":"Rõ ràng là số lượng khách sẽ tăng lên, vì vậy chúng ta cần có một kế hoạch phù hợp để đối phó với số lượng tăng thêm này."},{"time":13540,"en":"We don't want a repeat of this year.","vi":"Chúng ta không muốn lặp lại tình trạng của năm nay."},{"time":15980,"en":"What do you think, Lawrence?","vi":"Bạn nghĩ sao, Lawrence?"},{"time":17460,"en":"Actually, I saw the accommodation that we used at the city college, and it was pretty basic, though it was clean and tidy.","vi":"Thực ra, tôi đã thấy chỗ ở mà chúng ta đã sử dụng ở trường cao đẳng thành phố, nó khá đơn giản, dù sạch sẽ và gọn gàng."},{"time":26220,"en":"There was only a bed and a desk in each room.","vi":"Mỗi phòng chỉ có một giường và một bàn."},{"time":30200,"en":"Another thing the visitors complained about was the lack of Wi-Fi in the rooms, especially as they'd paid for rooms with Wi-Fi.","vi":"Một điều nữa mà khách phàn nàn là thiếu Wi-Fi trong phòng, đặc biệt là khi họ đã trả tiền cho các phòng có Wi-Fi."},{"time":37800,"en":"It certainly wasn't ideal.","vi":"Chắc chắn đó không phải là điều lý tưởng."},{"time":39740,"en":"Do you have anything to add, Sangita?","vi":"Bạn có điều gì muốn nói thêm không, Sangita?"},{"time":41760,"en":"Yeah ... I can understand why they weren't happy. I'd have felt the same in their position.","vi":"Ừ... Tôi hiểu tại sao họ không hài lòng. Tôi cũng sẽ cảm thấy như vậy nếu ở vào vị trí của họ."},{"time":47220,"en":"Well, there's that new holiday development at Elm Park, quite close to the university.","vi":"À, có khu du lịch mới ở Elm Park, khá gần trường đại học."},{"time":52480,"en":"Perhaps we could use their rooms.","vi":"Có lẽ chúng ta có thể sử dụng phòng của họ."},{"time":54560,"en":"After all, it won't be the holiday high season, so there should be plenty of empty rooms that we could use.","vi":"Dù sao thì cũng không phải mùa cao điểm du lịch, vì vậy chắc chắn sẽ có nhiều phòng trống mà chúng ta có thể sử dụng."},{"time":59740,"en":"That's true.","vi":"Đúng vậy."},{"time":61200,"en":"How about taking over some of their rooms and advertising them as accommodation specifically for families with children?","vi":"Hay là chúng ta thuê lại một số phòng của họ và quảng cáo chúng là chỗ ở đặc biệt dành cho các gia đình có trẻ em thì sao?"},{"time":70000,"en":"They're going to have an outdoor and an indoor adventure area for young people.","vi":"Họ sẽ có khu vui chơi mạo hiểm trong nhà và ngoài trời cho giới trẻ."},{"time":75120,"en":"We had quite a few teenagers this year coming with their parents.","vi":"Năm nay chúng ta có khá nhiều thanh thiếu niên đi cùng bố mẹ."},{"time":79240,"en":"If we can attract more by offering them the facilities at the holiday park in a special package, they can go there if they get bored with the festival.","vi":"Nếu chúng ta có thể thu hút thêm khách bằng cách cung cấp cho họ các tiện nghi tại khu du lịch trong một gói đặc biệt, họ có thể đến đó nếu họ cảm thấy chán lễ hội."},{"time":88720,"en":"Excellent idea!","vi":"Ý kiến tuyệt vời!"},{"time":90360,"en":"They'll be around 15 or 16 years old and when they come to the festival, they'll get an idea of what it'd be like to study here.","vi":"Các em ấy sẽ khoảng 15 hoặc 16 tuổi và khi đến lễ hội, họ sẽ hình dung được việc học tập ở đây như thế nào."},{"time":99720,"en":"I'm sure it'll help our future prospects as a university.","vi":"Tôi chắc chắn điều đó sẽ giúp ích cho triển vọng tương lai của trường đại học chúng ta."},{"time":103540,"en":"I agree.","vi":"Tôi đồng ý."},{"time":104680,"en":"I'll be happy to present those ideas to the committee.","vi":"Tôi rất vui được trình bày những ý tưởng đó với ủy ban."},{"time":108040,"en":"Moving on to the catering, it seems clear that the idea of theme days with different kinds of national and regional dishes went down very well.","vi":"Chuyển sang vấn đề ăn uống, rõ ràng là ý tưởng về những ngày chủ đề với các món ăn quốc gia và vùng miền khác nhau đã rất thành công."},{"time":117480,"en":"I'll recommend repeating it next year, but do you have anything else to say about the catering?","vi":"Tôi sẽ đề nghị lặp lại điều đó vào năm tới, nhưng bạn có điều gì khác muốn nói về việc ăn uống không?"},{"time":122320,"en":"Not really ... one thing is that maybe we could tell the students about the festival earlier in the year and invite them to suggest themes and also to volunteer their own cooking skills to help with it.","vi":"Không hẳn... có một điều là có lẽ chúng ta có thể nói với sinh viên về lễ hội sớm hơn trong năm và mời họ đề xuất các chủ đề và tình nguyện sử dụng kỹ năng nấu ăn của mình để giúp đỡ."},{"time":136880,"en":"I think that'll make sure that we vary what we offer from year to year, so that we don't just repeat the same dishes each time.","vi":"Tôi nghĩ điều đó sẽ đảm bảo rằng chúng ta thay đổi những gì chúng ta cung cấp hàng năm, để chúng ta không chỉ lặp lại những món ăn giống nhau mỗi lần."},{"time":144900,"en":"But we should always have fish and chips on the menu!","vi":"Nhưng chúng ta phải luôn có món cá và khoai tây chiên trong thực đơn!"},{"time":147980,"en":"We can't do without that!","vi":"Chúng ta không thể thiếu món đó!"},{"time":151460,"en":"Seriously though, I agree.","vi":"Nói nghiêm túc thì, tôi đồng ý."},{"time":153500,"en":"OK.","vi":"Được rồi."},{"time":154180,"en":"I'll make a note of that as well.","vi":"Tôi cũng sẽ ghi chú điều đó."},{"time":155680,"en":"Moving on to the helpers, you were both directly involved in that.","vi":"Chuyển sang vấn đề người giúp việc, cả hai bạn đều trực tiếp tham gia vào việc đó."},{"time":160520,"en":"Do you think it was a good idea to get professionals for the organising?","vi":"Bạn có nghĩ rằng việc thuê các chuyên gia để tổ chức là một ý kiến hay không?"},{"time":164000,"en":"In a word, no.","vi":"Tóm lại là không."},{"time":165580,"en":"I think the ones that I worked with didn't really know what they were doing.","vi":"Tôi nghĩ những người mà tôi làm việc cùng không thực sự biết họ đang làm gì."},{"time":169840,"en":"We were paying them a lot to do their work, but I don't think they really took it as seriously as they should have.","vi":"Chúng tôi đã trả rất nhiều tiền để họ làm công việc của họ, nhưng tôi không nghĩ họ thực sự coi trọng nó như lẽ ra họ nên làm."},{"time":175700,"en":"They were thinking it was just a student event.","vi":"Họ nghĩ rằng đó chỉ là một sự kiện của sinh viên."},{"time":178680,"en":"On more than one occasion, some of the volunteers had to take charge and make sure that the events went smoothly.","vi":"Trong nhiều trường hợp, một số tình nguyện viên đã phải phụ trách và đảm bảo rằng các sự kiện diễn ra suôn sẻ."},{"time":185660,"en":"Yes, you're right.","vi":"Vâng, bạn nói đúng."},{"time":187140,"en":"That was my experience as well.","vi":"Đó cũng là kinh nghiệm của tôi."},{"time":189300,"en":"We ended up paying them a lot of money for poor service.","vi":"Cuối cùng chúng tôi đã trả cho họ rất nhiều tiền cho dịch vụ kém chất lượng."},{"time":193500,"en":"It was one of the reasons why there were too few volunteers at some events - because the organisation was so poor.","vi":"Đó là một trong những lý do tại sao có quá ít tình nguyện viên tại một số sự kiện - bởi vì tổ chức quá kém."},{"time":201240,"en":"I think the idea of bringing back former students is a good idea.","vi":"Tôi nghĩ ý tưởng đưa cựu sinh viên trở lại là một ý kiến hay."},{"time":205560,"en":"At least then we can be more certain that they know about the university and they'll probably be more committed to doing a good job.","vi":"Ít nhất thì chúng ta có thể chắc chắn hơn rằng họ biết về trường đại học và họ có thể sẽ tận tâm hơn với việc làm tốt công việc."},{"time":213660,"en":"I think you're both right.","vi":"Tôi nghĩ cả hai bạn đều đúng."},{"time":215320,"en":"I was disappointed and I think former students will be a great improvement, so I'll note that as well.","vi":"Tôi đã thất vọng và tôi nghĩ rằng cựu sinh viên sẽ là một cải tiến lớn, vì vậy tôi cũng sẽ ghi chú điều đó."},{"time":222220,"en":"We need to talk about finance, but before that, I just want to mention the issue of security.","vi":"Chúng ta cần nói về tài chính, nhưng trước đó, tôi chỉ muốn đề cập đến vấn đề an ninh."},{"time":227920,"en":"Thinking about the stolen paintings, what do you think we should do about that?","vi":"Nghĩ về những bức tranh bị đánh cắp, bạn nghĩ chúng ta nên làm gì về việc đó?"},{"time":232080,"en":"I'm not really sure.","vi":"Tôi không thực sự chắc chắn."},{"time":233580,"en":"I mean, we had the university security guards on duty the whole time, so I don't think we can really add to that.","vi":"Ý tôi là, chúng ta đã có nhân viên an ninh của trường đại học làm nhiệm vụ suốt thời gian đó, vì vậy tôi không nghĩ chúng ta có thể làm gì thêm."},{"time":241600,"en":"Well, I noticed on more than one occasion that there were windows open in some rooms which made it easy for people to climb in and steal things.","vi":"Chà, tôi đã nhận thấy trong nhiều trường hợp có những cửa sổ mở trong một số phòng, điều này khiến mọi người dễ dàng trèo vào và trộm đồ."},{"time":251500,"en":"I think the main thing is to remind students and volunteers that it's their personal responsibility to be careful and look out for any security issues.","vi":"Tôi nghĩ điều chính là nhắc nhở sinh viên và tình nguyện viên rằng họ có trách nhiệm cá nhân phải cẩn thận và để ý đến bất kỳ vấn đề an ninh nào."},{"time":262120,"en":"So if one of us sees an open window, we should either check with security why it's open, or simply close it.","vi":"Vì vậy, nếu một trong chúng ta thấy một cửa sổ đang mở, chúng ta nên kiểm tra với bộ phận an ninh xem tại sao nó lại mở, hoặc đơn giản là đóng nó lại."},{"time":270260,"en":"You're right, Sangita.","vi":"Bạn nói đúng, Sangita."},{"time":271740,"en":"I'm sure the committee is aware of this, but I'll note it just to show that we've given it some thought.","vi":"Tôi chắc chắn ủy ban đã biết về điều này, nhưng tôi sẽ ghi chú lại chỉ để cho thấy rằng chúng tôi đã suy nghĩ về nó."},{"time":276780,"en":"Now finance - what are your feelings on Dr Saunders' suggestions about sponsorship?","vi":"Bây giờ đến tài chính - bạn cảm thấy thế nào về những gợi ý của Tiến sĩ Saunders về tài trợ?"},{"time":282400,"en":"I don't think that will go down too well with most students.","vi":"Tôi không nghĩ rằng điều đó sẽ được hầu hết sinh viên đón nhận."},{"time":285440,"en":"I mean, personally, I'm not against it, but I think students generally won't be very keen to have businesses involved in what they see as their arts festival.","vi":"Ý tôi là, cá nhân tôi không phản đối điều đó, nhưng tôi nghĩ rằng sinh viên nói chung sẽ không mấy hào hứng với việc các doanh nghiệp tham gia vào những gì họ coi là lễ hội nghệ thuật của họ."},{"time":295860,"en":"I'm sure they'll be happy to take part in more events to raise money throughout the year before the festival, but they won't be happy about big businesses taking over and having their names all over the university.","vi":"Tôi chắc chắn họ sẽ vui vẻ tham gia vào nhiều sự kiện hơn để gây quỹ trong suốt năm trước lễ hội, nhưng họ sẽ không hài lòng về việc các doanh nghiệp lớn tiếp quản và có tên của họ trên khắp trường đại học."},{"time":307520,"en":"Well, I think it's going to happen anyway.","vi":"Chà, tôi nghĩ điều đó dù sao cũng sẽ xảy ra thôi."},{"time":310720,"en":"Everything is commercial to some extent these days.","vi":"Mọi thứ ngày nay đều mang tính thương mại ở một mức độ nào đó."},{"time":314840,"en":"I don't think it's a bad idea, as long as it's done in good taste.","vi":"Tôi không nghĩ đó là một ý tưởng tồi, miễn là nó được thực hiện một cách trang nhã."},{"time":319720,"en":"I think any businesses that do want to sponsor us or advertise should be aware that they need to work closely with us and respect the spirit of the festival.","vi":"Tôi nghĩ bất kỳ doanh nghiệp nào muốn tài trợ cho chúng tôi hoặc quảng cáo nên biết rằng họ cần hợp tác chặt chẽ với chúng tôi và tôn trọng tinh thần của lễ hội."},{"time":330480,"en":"Perhaps we could involve local businesses as well as national ones that don't just put their name on the festival, but can actually sponsor specific events, award prizes, and so on.","vi":"Có lẽ chúng ta có thể mời các doanh nghiệp địa phương cũng như các doanh nghiệp quốc gia không chỉ đặt tên của họ lên lễ hội, mà còn có thể tài trợ cho các sự kiện cụ thể, trao giải thưởng, v.v."},{"time":342680,"en":"So, for example, a local cinema could sponsor the short film event and even send along a representative to judge the films, that sort of thing.","vi":"Ví dụ, một rạp chiếu phim địa phương có thể tài trợ cho sự kiện phim ngắn và thậm chí cử một đại diện đến chấm phim, đại loại thế."},{"time":352400,"en":"Yes, I see what you mean.","vi":"Vâng, tôi hiểu ý của bạn."},{"time":354300,"en":"In that way, they'll be directly involved in the festival, which will encourage them to take an active part and build up their reputations for supporting the arts.","vi":"Bằng cách đó, họ sẽ trực tiếp tham gia vào lễ hội, điều này sẽ khuyến khích họ tham gia tích cực và xây dựng danh tiếng của họ trong việc hỗ trợ nghệ thuật."},{"time":363180,"en":"Well, thank you both.","vi":"Chà, cảm ơn cả hai bạn."},{"time":364880,"en":"We have a lot of useful suggestions to take back to the committee.","vi":"Chúng ta có rất nhiều gợi ý hữu ích để mang về trình bày với ủy ban."}],"probUrl":"https://study4.com/problems/120914/?view=embed"}},{"id":"listening_u3_66","title":"Celebrations and Traditions: recording 3","actTitle":"Celebrations and Traditions: recording 3","youtubeId":"","htmlContent":"","problem":{"pType":"listen_passage","probTitle":"Celebrations and Traditions: recording 3","audioUrl":"https://s4-media1.study4.com/media/mindset_media/Mindset2_27.mp3","subs":[{"time":0,"en":"Hello Dr Saunders.","vi":"Chào bác sĩ Saunders."},{"time":1840,"en":"I just want to tell you about the suggestions that Lawrence and Sangita made during our discussion and see what you think.","vi":"Tôi chỉ muốn nói với bác sĩ về những đề xuất mà Lawrence và Sangita đã đưa ra trong cuộc thảo luận của chúng ta và xem bác sĩ nghĩ gì."},{"time":9320,"en":"Thanks, yes. Please do.","vi":"Cảm ơn, vâng. Mời bạn cứ nói."},{"time":11480,"en":"First of all, regarding the music, they think that it might be a good idea to have a good local band who can replace the main act if it has to let us down at the last minute, which is what happened this year.","vi":"Trước hết, về âm nhạc, họ nghĩ rằng nên có một ban nhạc địa phương giỏi có thể thay thế tiết mục chính nếu có sự cố vào phút cuối, điều đã xảy ra năm nay."},{"time":24080,"en":"The band could be scheduled for later in the week on the understanding that they might have to play on an earlier night.","vi":"Có thể lên lịch cho ban nhạc vào cuối tuần, với điều kiện họ có thể phải chơi vào một đêm sớm hơn."},{"time":30280,"en":"We could also have one evening with a student band.","vi":"Chúng ta cũng có thể có một buổi tối với một ban nhạc sinh viên."},{"time":33260,"en":"Well, it sounds good in theory to plan a rearrangement, but I think it would be too complicated to arrange.","vi":"Về mặt lý thuyết thì việc lên kế hoạch sắp xếp lại nghe có vẻ hay, nhưng tôi nghĩ sẽ rất phức tạp để thực hiện."},{"time":39800,"en":"We would depend too much on all the bands being able to play on any of the nights.","vi":"Chúng ta sẽ phụ thuộc quá nhiều vào việc tất cả các ban nhạc có thể chơi vào bất kỳ đêm nào."},{"time":44420,"en":"I think it's simpler just to give the audience a refund if it happens again.","vi":"Tôi nghĩ đơn giản hơn là chỉ cần hoàn tiền cho khán giả nếu điều đó xảy ra lần nữa."},{"time":48600,"en":"But I'm happy to have one evening supporting local bands and student bands, as that's the main point of the festival - to encourage people to take part.","vi":"Nhưng tôi rất vui khi có một buổi tối ủng hộ các ban nhạc địa phương và ban nhạc sinh viên, vì đó là mục đích chính của lễ hội - khuyến khích mọi người tham gia."},{"time":57080,"en":"The next thing is the crafts.","vi":"Điều tiếp theo là về đồ thủ công."},{"time":58900,"en":"They felt that a fashion show would be a good way of expanding the clothes exhibition, and that perhaps we should reduce or even get rid of the glass and pottery exhibition.","vi":"Họ cảm thấy rằng một buổi trình diễn thời trang sẽ là một cách hay để mở rộng triển lãm quần áo, và có lẽ chúng ta nên giảm bớt hoặc thậm chí loại bỏ triển lãm đồ thủy tinh và gốm sứ."},{"time":68160,"en":"Well, first of all, I think that the fashion show is a good idea as it can help the international students to get involved in more activities and develop their ideas with clothes.","vi":"Trước hết, tôi nghĩ rằng buổi trình diễn thời trang là một ý tưởng hay vì nó có thể giúp sinh viên quốc tế tham gia nhiều hoạt động hơn và phát triển ý tưởng của họ với quần áo."},{"time":78820,"en":"But I'm not keen to get rid of the glass and pottery exhibitions completely, as it's important for the university to be seen to encourage all forms of art and not just the most popular ones, so we should keep that for the time being.","vi":"Nhưng tôi không muốn loại bỏ hoàn toàn các triển lãm đồ thủy tinh và gốm sứ, vì điều quan trọng là trường đại học phải được nhìn nhận là khuyến khích tất cả các hình thức nghệ thuật chứ không chỉ những hình thức phổ biến nhất, vì vậy chúng ta nên giữ lại điều đó trong thời gian này."},{"time":92520,"en":"OK ... now ... regarding theatre and poetry, they felt that it would be good for students to write and perform their own plays and poetry, as well as those by famous playwrights and poets.","vi":"Được rồi... bây giờ... về sân khấu và thơ ca, họ cảm thấy rằng sẽ tốt cho sinh viên nếu tự viết và biểu diễn các vở kịch và thơ của mình, cũng như của các nhà viết kịch và nhà thơ nổi tiếng."},{"time":105160,"en":"That sounds like an excellent idea!","vi":"Nghe có vẻ là một ý tưởng tuyệt vời!"},{"time":107520,"en":"It'd help a lot to raise standards in writing and performance.","vi":"Điều đó sẽ giúp nâng cao tiêu chuẩn trong viết lách và biểu diễn."},{"time":110760,"en":"I'd love to see that taking place.","vi":"Tôi rất muốn thấy điều đó diễn ra."},{"time":112600,"en":"Also on that topic, there was a feeling that works in other languages should be encouraged.","vi":"Cũng về chủ đề đó, có một ý kiến cho rằng nên khuyến khích các tác phẩm bằng các ngôn ngữ khác."},{"time":118240,"en":"Most certainly.","vi":"Chắc chắn rồi."},{"time":119480,"en":"That would help the international students feel far more at home and valued as part of the university.","vi":"Điều đó sẽ giúp các sinh viên quốc tế cảm thấy thoải mái hơn và được coi trọng như một phần của trường đại học."},{"time":124900,"en":"There was one other event we discussed, and that was photography.","vi":"Có một sự kiện khác mà chúng ta đã thảo luận, đó là nhiếp ảnh."},{"time":128800,"en":"It was felt that we should have both digital and non-digital exhibits.","vi":"Mọi người cảm thấy rằng chúng ta nên có cả triển lãm kỹ thuật số và không kỹ thuật số."},{"time":134380,"en":"I don't think we could manage that, at least not yet.","vi":"Tôi không nghĩ chúng ta có thể làm được điều đó, ít nhất là chưa."},{"time":138460,"en":"High-quality tablets and screens would be too expensive, especially with the number we'd have to buy, so it's not an option for next year because of the high cost.","vi":"Máy tính bảng và màn hình chất lượng cao sẽ quá đắt, đặc biệt là với số lượng chúng ta phải mua, vì vậy đó không phải là một lựa chọn cho năm tới vì chi phí cao."},{"time":148180,"en":"OK, as for the accommodation and the catering, they felt that we could use the holiday park that's being built nearby, and we should encourage students to take a greater part in cooking and helping with the catering.","vi":"Được rồi, về chỗ ở và dịch vụ ăn uống, họ cảm thấy rằng chúng ta có thể sử dụng khu nghỉ dưỡng đang được xây dựng gần đó, và chúng ta nên khuyến khích sinh viên tham gia nhiều hơn vào việc nấu ăn và giúp đỡ trong dịch vụ ăn uống."},{"time":162100,"en":"Well, first, I know for a fact that the new holiday park is not likely to be completed by festival time next year as they've run into trouble with the building, but we could certainly think about it in the future.","vi":"Trước hết, tôi biết chắc chắn rằng khu nghỉ dưỡng mới khó có thể hoàn thành vào thời điểm lễ hội năm tới vì họ gặp rắc rối với việc xây dựng, nhưng chúng ta chắc chắn có thể nghĩ về nó trong tương lai."},{"time":174380,"en":"I do like the idea of the students having a greater role in the catering and cooking, as it will clearly be helpful for their all-round development.","vi":"Tôi thích ý tưởng sinh viên đóng vai trò lớn hơn trong dịch vụ ăn uống và nấu nướng, vì điều đó rõ ràng sẽ hữu ích cho sự phát triển toàn diện của họ."},{"time":181940,"en":"OK.","vi":"Được rồi."},{"time":183240,"en":"The next thing is the professional organisers.","vi":"Điều tiếp theo là về các nhà tổ chức chuyên nghiệp."},{"time":186440,"en":"They felt that the standard was quite low and that the volunteers didn't experience good leadership from them.","vi":"Họ cảm thấy rằng tiêu chuẩn khá thấp và các tình nguyện viên không có được sự lãnh đạo tốt từ họ."},{"time":192260,"en":"They think it would be better to ask former students to work as organisers, as they'd be more familiar with the university and more committed, too.","vi":"Họ nghĩ rằng sẽ tốt hơn nếu mời các cựu sinh viên làm người tổ chức, vì họ sẽ quen thuộc hơn với trường đại học và cũng tận tâm hơn."},{"time":200720,"en":"I appreciate that, but unfortunately that wouldn't work.","vi":"Tôi đánh giá cao điều đó, nhưng tiếc là điều đó sẽ không hiệu quả."},{"time":204600,"en":"It'd be too much trouble trying to find them and get them employed.","vi":"Sẽ rất rắc rối khi cố gắng tìm kiếm và thuê họ."},{"time":208300,"en":"However, I think we should review the organisers that we used this year and have a much better selection system in place for the next festival.","vi":"Tuy nhiên, tôi nghĩ chúng ta nên xem xét lại những người tổ chức mà chúng ta đã sử dụng trong năm nay và có một hệ thống lựa chọn tốt hơn nhiều cho lễ hội tiếp theo."},{"time":216820,"en":"Now the last two points are about security and finance.","vi":"Bây giờ hai điểm cuối cùng là về an ninh và tài chính."},{"time":220500,"en":"As far as security goes, they think we should do more to encourage the students to take it seriously.","vi":"Về vấn đề an ninh, họ nghĩ rằng chúng ta nên làm nhiều hơn nữa để khuyến khích sinh viên coi trọng vấn đề này."},{"time":226140,"en":"I agree.","vi":"Tôi đồng ý."},{"time":227320,"en":"If we can encourage students to be more aware of security, not just during the festival, it'd really help to increase trust among all our students because they'll be looking out for each other.","vi":"Nếu chúng ta có thể khuyến khích sinh viên nâng cao ý thức về an ninh, không chỉ trong thời gian lễ hội, điều đó sẽ thực sự giúp tăng cường sự tin tưởng giữa tất cả sinh viên của chúng ta vì họ sẽ để ý đến nhau."},{"time":237980,"en":"As for finance, they thought that, first, we could encourage students to help raise money throughout the year, and, secondly, we could encourage businesses to sponsor the events and advertise more, though it needs to be handled with care.","vi":"Về tài chính, họ nghĩ rằng, thứ nhất, chúng ta có thể khuyến khích sinh viên giúp gây quỹ trong suốt cả năm, và thứ hai, chúng ta có thể khuyến khích các doanh nghiệp tài trợ cho các sự kiện và quảng cáo nhiều hơn, mặc dù cần phải xử lý cẩn thận."},{"time":253000,"en":"Well, regarding sponsorship and advertising, the committee is already looking at the possibilities as it will encourage more interest in the activities that we do and also help our reputation generally.","vi":"Về tài trợ và quảng cáo, ủy ban đã xem xét các khả năng vì nó sẽ khuyến khích sự quan tâm hơn đến các hoạt động mà chúng ta thực hiện và cũng giúp uy tín của chúng ta nói chung."},{"time":264840,"en":"Unfortunately, I don't think asking the students to raise more money during the year is a good idea as we already have a programme in place for that, and if the students are involved any more, they'll spend less time on their studies and I don't want anything to disrupt those.","vi":"Thật không may, tôi không nghĩ rằng việc yêu cầu sinh viên gây quỹ nhiều hơn trong năm là một ý tưởng hay vì chúng ta đã có một chương trình cho việc đó, và nếu sinh viên tham gia nhiều hơn, họ sẽ dành ít thời gian hơn cho việc học và tôi không muốn bất cứ điều gì làm gián đoạn việc đó."}],"probUrl":"https://study4.com/problems/120915/?view=embed"}}]};
